def manoeuvre_ok(mt_id, V_ms, h_agl_m, Vs_ms=None):
    """
    Gate check for manoeuvre mode.
    Returns (bool, reason_str).
    """
    if mt_id not in MANOEUVRE_MODES:
        return False, f"Unknown manoeuvre mode {mt_id}"
    mm = MANOEUVRE_MODES[mt_id]
    if Vs_ms is None:
        Vs_ms = VS_KT / 1.944
    if V_ms < mm['min_V_ms']:
        return False, (f"{mt_id} needs V ≥ {mm['min_V_ms']}m/s "
                       f"(current {V_ms:.1f}m/s)")
    if h_agl_m < MANOEUVRE_MIN_AGL_M:
        return False, f"Manoeuvring needs ≥ {MANOEUVRE_MIN_AGL_M}m AGL"
    # Check stall margin at target bank
    bank = mm['bank_deg']
    Vs_turn = stall_speed_banked(Vs_ms, bank)
    margin  = V_ms - Vs_turn
    if margin < TURN_STALL_MARGIN_MS:
        return False, (f"{mt_id}: stall margin {margin:.1f}m/s at {bank}° bank "
                       f"(need {TURN_STALL_MARGIN_MS}m/s)")
    return True, "ok"


def manoeuvre_sequence(mt_id, turn_direction, V_ms, Vs_ms=None):
    """
    Return the full four-phase manoeuvre sequence for a named mode.
    Returns list of phase dicts:
      [roll_in_commands, banked_turn_commands, roll_out_commands,
       resume_commands]
    """
    if mt_id not in MANOEUVRE_MODES:
        raise ValueError(f"Unknown manoeuvre mode: {mt_id}")
    if Vs_ms is None:
        Vs_ms = VS_KT / 1.944
    mm   = MANOEUVRE_MODES[mt_id]
    bank = mm['bank_deg']

    # Phase 1: roll-in
    roll_sweeps = roll_in_sweeps(turn_direction, bank)
    phase1 = {
        'phase':       'roll_in',
        'freq_hz':     ROLL_FREQ_HZ,
        'sweeps':      roll_sweeps,
        'dihedrals':   {i: ROLL_DIHEDRAL_DEG for i in range(8)},
        'pitch_deg':   ROLL_PITCH_OFFSET_DEG,
        'duration_s':  max(0.5, bank / 40.0),  # ~0.75s for 30°, 1.5s for 60°
    }

    # Phase 2: banked turn (held until heading change complete)
    phase2 = banked_turn_commands(turn_direction, bank, V_ms)
    phase2['phase']    = 'banked_turn'
    phase2['freq_hz']  = mm['freq_hz']

    # Phase 3: roll-out (mirror of roll-in)
    roll_out_sweeps = roll_in_sweeps(
        'right' if turn_direction == 'left' else 'left', bank)
    phase3 = {
        'phase':       'roll_out',
        'freq_hz':     ROLL_FREQ_HZ,
        'sweeps':      roll_out_sweeps,
        'dihedrals':   {i: ROLL_DIHEDRAL_DEG for i in range(8)},
        'pitch_deg':   0.0,
        'duration_s':  phase1['duration_s'],
    }

    # Phase 4: resume normal flight
    phase4 = {
        'phase':       'resume',
        'freq_hz':     0.8,   # cruise frequency
        'sweeps':      {i: 60.0 for i in range(8)},
        'dihedrals':   {i: 0.0  for i in range(8)},
        'pitch_deg':   0.0,
    }

    return [phase1, phase2, phase3, phase4]


def min_turn_radius_m(V_ms, Vs_ms=None):
    """
    Returns the minimum achievable turn radius at current speed,
    limited by the stall speed at bank angle.
    """
    if Vs_ms is None:
        Vs_ms = VS_KT / 1.944
    bank_max = max_safe_bank_deg(V_ms, Vs_ms)
    if bank_max < 5.0:
        return 9999.0
    return turn_radius_m(V_ms, bank_max)


# -----------------------------------------------------------------
# ENERGY STATE DURING MANOEUVRES
# -----------------------------------------------------------------

def manoeuvre_Ps(thrust_N, drag_N, W_N, V_ms, bank_deg):
    """
    Boyd Ps modified for banked turn.
    In a turn, the aircraft must generate more lift (load factor > 1),
    which increases induced drag. The effective drag in the turn is
    higher than in level flight.

    drag_N: total drag in level flight at this speed
    Additional induced drag from bank:
    CD_turn = CL²×(1/cos²(bank)-1) / (π×AR×e)
    """
    bank_rad = _math.radians(abs(bank_deg))
    cos_bank = max(0.10, _math.cos(bank_rad))
    # Load factor penalty on drag
    lf = 1.0 / cos_bank
    drag_turn = drag_N * lf    # approximate: drag scales with load factor
    return specific_excess_power(thrust_N, drag_turn, W_N, V_ms)


