# =================================================================
# ADDENDUM Rev I — UNIFIED FLIGHT LEVER
# 2026-06-07
#
# A single lever maps the complete flight envelope on one axis.
# Full forward = maximum sprint. Mid = hold altitude trim.
# Full aft = maximum airbrake.
#
# ZONES (lever 0% = full forward, 100% = full aft):
#   0–15%   SPRINT       — 2.5–3.0 Hz, 135° sweep, −8° anhedral
#   15–30%  POWERED CRUISE — 1.5–2.5 Hz, 90–135° sweep, 0° dihedral
#   30–45%  STANDARD CRUISE — 0.8–1.5 Hz, 60–90° sweep, 0°
#   45–55%  TRIM DETENT   — 0.2–0.4 Hz, 60°, 0°  (hold altitude)
#   55–65%  CLEAN GLIDE   — 0.0–0.2 Hz, 60°, 0→+8° (GL-0/GL-1)
#   65–75%  APPROACH GLIDE — 0.3 Hz, 60°, +12→+18° (GL-2/GL-3)
#   75–85%  STEEP DESCENT  — 0.3–0.5 Hz, 60–90°, +25→+35° (GL-4/5)
#   85–95%  NEAR-VERTICAL  — 0.8 Hz, 90–120°, +45° (GL-6)
#   95–100% MAX AIRBRAKE   — 1.0 Hz, 135°, +55° (GL-7)
#
# KEY DESIGN RULES:
#   50% = "hold altitude" trim point with 5% hysteresis band.
#   Forward of 50%: thrust zones — aircraft accelerates/climbs.
#   Aft of 50%: glide/brake zones — aircraft decelerates/descends.
#   Freq never drops to 0 until the clean glide zone (>65%).
#   Dihedral is 0° at 50%, transitions smoothly both directions.
#   All transitions use existing Rev H rate limiting.
#
# BIOLOGICAL ANALOGY:
#   Mirrors exactly how a swift or raptor manages its energy:
#   high flap rate + swept wings for sprint;
#   extended wings + no flapping for efficient glide;
#   raised wings (positive dihedral) for steep braking descent.
# =================================================================

# Hysteresis band around the 50% trim detent
LEVER_DETENT_LOW   = 47.5   # % — lower edge of hold-altitude band
LEVER_DETENT_HIGH  = 52.5   # % — upper edge of hold-altitude band

# Zone boundaries
LEVER_SPRINT_END       = 15.0
LEVER_PWR_CRUISE_END   = 30.0
LEVER_STD_CRUISE_END   = 45.0
LEVER_TRIM_END         = 55.0
LEVER_CLEAN_GLIDE_END  = 65.0
LEVER_APPROACH_END     = 75.0
LEVER_STEEP_END        = 85.0
LEVER_NEARVERT_END     = 95.0
# 95–100% = MAX AIRBRAKE

def unified_lever_to_params(lev_pct, V_ms=7.0, h_agl_m=100.0):
    """
    Master wave lever function — 0% to 100%.

    Maps lever position to the highest-ranked available mode,
    respecting speed and altitude gates. When a mode is unavailable
    at current conditions the next-ranked mode in that zone is used.

    0%   = maximum thrust (CF-1 burst if V<10m/s, else fwd-sweep sprint)
    45%  = lower edge of trim detent
    50%  = Ps=0 crossover (trim/hold altitude)
    55%  = upper edge of trim, entering soar/glide
    75%  = glide/brake boundary
    100% = maximum airbrake

    All 26 non-manoeuvre modes from the library are accessible.
    Manoeuvre modes (zoom, stoop, hard bank, spiral, etc.) remain
    on the sticks — they are NOT on this map.

    The optimizer shifts effective mode boundaries over flights as
    measured performance data accumulates in _lever_learning.

    Parameters
    ----------
    lev_pct : float 0..100 — lever position
    V_ms    : float — current airspeed (for speed-gate checks)
    h_agl_m : float — current altitude AGL (for altitude gates)

    Returns
    -------
    dict: freq_hz, sweep_deg, dihedral_deg, pitch_deg,
          zone, mode_id, gs_id, gl_id, lever_pct,
          speed_gated (bool), experimental (bool)
    """
    import math as _lm
    lev = max(0.0, min(100.0, lev_pct))

    def lerp(a, b, t):
        return a + (b - a) * max(0.0, min(1.0, t))

    def zone_t(lo, hi):
        return (lev - lo) / (hi - lo)

    # Speed gate helpers
    Vs = VS_OGE_MS  # 4.85 m/s
    ok_cf1      = V_ms <= CF1_V_MAX_MS                  # V < 10m/s
    ok_v6       = V_ms >= 6.0                           # V > 6m/s
    ok_v7       = V_ms >= 7.0                           # V > 7m/s
    ok_v8       = V_ms >= 8.0                           # V > 8m/s
    ok_v10      = V_ms >= 10.0                          # V > 10m/s
    ok_loiter_v = V_ms >= Vs * 1.3                      # loiter min
    ok_crab_v   = V_ms >= 5.0
    ok_h50      = h_agl_m >= 50.0                       # GL-6/7 altitude
    ok_h30      = h_agl_m >= 30.0                       # ballistic altitude

    # ── THRUST ZONE: 0–45% ───────────────────────────────────────
    # Ten modes ranked by thrust/Ps from max to min.
    # Speed-gated modes fall through to next available.

    if lev <= 5.0:
        # SPRINT-1: CF-1 burst (highest thrust, V<10m/s only)
        if ok_cf1:
            return {
                'freq_hz': FREQ_LIMIT_MAX_HZ, 'sweep_deg': 60.0,
                'dihedral_deg': -8.0, 'pitch_deg': -3.0,
                'zone': 'SPRINT', 'mode_id': 'CF1_BURST',
                'gs_id': 'GS-0', 'gl_id': 'GL-0',
                'lever_pct': round(lev,1),
                'speed_gated': False, 'experimental': False,
            }
        # Fall through to fwd-sweep sprint at high speed
        lev = 10.0   # proxy to SPRINT-3

    if lev <= 10.0:
        # SPRINT-2: CF-1 Standard (V<10m/s) OR
        # SPRINT-3: Forward-sweep sprint (V>8m/s)
        if ok_cf1:
            return {
                'freq_hz': FREQ_LIMIT_MAX_HZ, 'sweep_deg': 60.0,
                'dihedral_deg': -8.0, 'pitch_deg': -2.0,
                'zone': 'SPRINT', 'mode_id': 'CF1_STANDARD',
                'gs_id': 'GS-0', 'gl_id': 'GL-0',
                'lever_pct': round(lev,1),
                'speed_gated': False, 'experimental': False,
            }
        elif ok_v8:
            t = zone_t(5.0, 15.0)
            return {
                'freq_hz': lerp(FREQ_LIMIT_MAX_HZ, 2.5, t),
                'sweep_deg': 30.0,   # X-29 forward sweep
                'dihedral_deg': -8.0, 'pitch_deg': -3.0,
                'zone': 'SPRINT', 'mode_id': 'FWD_SWEEP_SPRINT',
                'gs_id': 'GS-1', 'gl_id': 'GL-0',
                'lever_pct': round(lev,1),
                'speed_gated': False, 'experimental': False,
            }

    if lev <= 15.0:
        # SPRINT-3: Forward-sweep sprint (V>8m/s) or
        # SPRINT-4: Wake-capture sprint (V>6m/s)
        if ok_v8:
            return {
                'freq_hz': 2.5, 'sweep_deg': 30.0,
                'dihedral_deg': -8.0, 'pitch_deg': -3.0,
                'zone': 'SPRINT', 'mode_id': 'FWD_SWEEP_SPRINT',
                'gs_id': 'GS-1', 'gl_id': 'GL-0',
                'lever_pct': round(lev,1),
                'speed_gated': False, 'experimental': False,
            }
        elif ok_v6:
            return {
                'freq_hz': 2.5, 'sweep_deg': 90.0,
                'dihedral_deg': -8.0, 'pitch_deg': -3.0,
                'zone': 'SPRINT', 'mode_id': 'WAKE_CAP_SPRINT',
                'gs_id': 'GS-0', 'gl_id': 'GL-0',
                'lever_pct': round(lev,1),
                'speed_gated': True,  'experimental': False,
            }

    if lev <= 20.0:
        # SPRINT-4: Wake-capture sprint OR standard sprint
        if ok_v6:
            t = zone_t(15.0, 20.0)
            return {
                'freq_hz': lerp(2.5, 2.5, t), 'sweep_deg': 90.0,
                'dihedral_deg': -8.0, 'pitch_deg': -3.0,
                'zone': 'SPRINT', 'mode_id': 'WAKE_CAP_SPRINT',
                'gs_id': 'GS-0', 'gl_id': 'GL-0',
                'lever_pct': round(lev,1),
                'speed_gated': False, 'experimental': False,
            }

    if lev <= 28.0:
        # SPRINT-5: Standard sprint, all wings (always available)
        t = zone_t(20.0, 28.0)
        return {
            'freq_hz': lerp(2.5, 2.0, t), 'sweep_deg': 90.0,
            'dihedral_deg': lerp(-8.0, -4.0, t), 'pitch_deg': -3.0,
            'zone': 'SPRINT', 'mode_id': 'SPRINT_GS0',
            'gs_id': 'GS-0', 'gl_id': 'GL-0',
            'lever_pct': round(lev,1),
            'speed_gated': False, 'experimental': False,
        }

    if lev <= 38.0:
        # CRUISE-1: Boyd-optimised powered cruise (Ps=0 hunt)
        t = zone_t(28.0, 38.0)
        return {
            'freq_hz': lerp(2.0, 1.5, t), 'sweep_deg': lerp(90.0, 60.0, t),
            'dihedral_deg': lerp(-4.0, 0.0, t), 'pitch_deg': 0.0,
            'zone': 'POWERED_CRUISE', 'mode_id': 'BOYD_CRUISE',
            'gs_id': 'GS-0', 'gl_id': 'GL-0',
            'lever_pct': round(lev,1),
            'speed_gated': False, 'experimental': False,
        }

    if lev <= 43.0:
        # CRUISE-2: Loiter (if speed adequate) or standard cruise
        t = zone_t(38.0, 43.0)
        if ok_loiter_v:
            return {
                'freq_hz': lerp(1.5, 1.0, t), 'sweep_deg': 60.0,
                'dihedral_deg': 0.0, 'pitch_deg': 0.0,
                'zone': 'POWERED_CRUISE', 'mode_id': 'LOITER',
                'gs_id': 'GS-0', 'gl_id': 'GL-1',
                'lever_pct': round(lev,1),
                'speed_gated': False, 'experimental': False,
            }
        # Fall through to Boyd cruise
        return {
            'freq_hz': lerp(1.5, 1.2, t), 'sweep_deg': 60.0,
            'dihedral_deg': 0.0, 'pitch_deg': 0.0,
            'zone': 'POWERED_CRUISE', 'mode_id': 'BOYD_CRUISE',
            'gs_id': 'GS-0', 'gl_id': 'GL-0',
            'lever_pct': round(lev,1),
            'speed_gated': True, 'experimental': False,
        }

    if lev <= 45.0:
        # CRUISE-3: Crab / SAR search (if speed adequate)
        if ok_crab_v:
            return {
                'freq_hz': 1.5, 'sweep_deg': 60.0,
                'dihedral_deg': 0.0, 'pitch_deg': 0.0,
                'zone': 'POWERED_CRUISE', 'mode_id': 'CRAB_SEARCH',
                'gs_id': 'GS-0', 'gl_id': 'GL-0',
                'lever_pct': round(lev,1),
                'speed_gated': False, 'experimental': False,
            }
        # Not enough speed for crab — trim
        return {
            'freq_hz': 1.0, 'sweep_deg': 60.0,
            'dihedral_deg': 0.0, 'pitch_deg': 0.0,
            'zone': 'TRIM', 'mode_id': 'TRIM',
            'gs_id': 'GS-0', 'gl_id': 'GL-0',
            'lever_pct': round(lev,1),
            'speed_gated': True, 'experimental': False,
        }

    # ── TRIM DETENT: 45–55% ──────────────────────────────────────
    if lev <= 55.0:
        t = zone_t(45.0, 55.0)
        return {
            'freq_hz': lerp(0.8, 0.2, t), 'sweep_deg': 60.0,
            'dihedral_deg': 0.0, 'pitch_deg': 0.0,
            'zone': 'TRIM', 'mode_id': 'TRIM',
            'gs_id': 'GS-0', 'gl_id': 'GL-1',
            'lever_pct': round(lev,1),
            'speed_gated': False, 'experimental': False,
        }

    # ── SOAR/GLIDE ZONE: 55–75% ──────────────────────────────────
    # 10 glide modes ranked by L/D, highest first.
    # Speed-gated modes fall through to next available.

    if lev <= 58.0:
        # GLIDE-1: GS-2 single pair (L/D=4.5, V>10m/s)
        if ok_v10:
            return {
                'freq_hz': 0.15, 'sweep_deg': 60.0,
                'dihedral_deg': 0.0, 'pitch_deg': -4.0,
                'zone': 'CLEAN_GLIDE', 'mode_id': 'GS2_SINGLE',
                'gs_id': 'GS-2', 'gl_id': 'GL-0',
                'lever_pct': round(lev,1),
                'speed_gated': False, 'experimental': False,
            }
        # Speed gate: fall to GL-9
        lev = 58.5

    if lev <= 61.0:
        # GLIDE-2: GL-9 Eagle scimitar (L/D~4.4 estimated)
        return {
            'freq_hz': 0.1, 'sweep_deg': 90.0,
            'dihedral_deg': 5.0, 'pitch_deg': 2.0,
            'zone': 'CLEAN_GLIDE', 'mode_id': 'GL9_EAGLE_SCIMITAR',
            'gs_id': 'GS-0', 'gl_id': 'GL-9',
            'lever_pct': round(lev,1),
            'speed_gated': False, 'experimental': True,
        }

    if lev <= 64.0:
        # GLIDE-3: GL-8 Eagle primary splay (L/D~4.3 estimated)
        return {
            'freq_hz': 0.1, 'sweep_deg': 90.0,
            'dihedral_deg': 5.0, 'pitch_deg': 2.0,
            'zone': 'CLEAN_GLIDE', 'mode_id': 'GL8_EAGLE_SPLAY',
            'gs_id': 'GS-0', 'gl_id': 'GL-8',
            'lever_pct': round(lev,1),
            'speed_gated': False, 'experimental': True,
        }

    if lev <= 66.0:
        # GLIDE-4: GS-3 gap-wing W1+W4 (L/D=3.9, V>7m/s)
        if ok_v7:
            return {
                'freq_hz': 0.2, 'sweep_deg': 60.0,
                'dihedral_deg': 0.0, 'pitch_deg': 0.0,
                'zone': 'CLEAN_GLIDE', 'mode_id': 'GS3_GAP_WING',
                'gs_id': 'GS-3', 'gl_id': 'GL-0',
                'lever_pct': round(lev,1),
                'speed_gated': False, 'experimental': False,
            }

    if lev <= 68.0:
        # GLIDE-5: GS-4 slot-wing W1+W3 (L/D=3.8, experimental)
        if ok_v7:
            return {
                'freq_hz': 0.2, 'sweep_deg': 60.0,
                'dihedral_deg': 0.0, 'pitch_deg': -1.0,
                'zone': 'CLEAN_GLIDE', 'mode_id': 'GS4_SLOT_WING',
                'gs_id': 'GS-4', 'gl_id': 'GL-0',
                'lever_pct': round(lev,1),
                'speed_gated': False, 'experimental': True,
            }

    if lev <= 70.0:
        # GLIDE-6: GS-1 forward pair W1+W2 (L/D=3.8, V>7m/s)
        if ok_v7:
            return {
                'freq_hz': 0.2, 'sweep_deg': 60.0,
                'dihedral_deg': 0.0, 'pitch_deg': -2.0,
                'zone': 'CLEAN_GLIDE', 'mode_id': 'GS1_FWD_PAIR',
                'gs_id': 'GS-1', 'gl_id': 'GL-0',
                'lever_pct': round(lev,1),
                'speed_gated': False, 'experimental': False,
            }

    if lev <= 72.0:
        # GLIDE-7: GL-1 soaring / thermal (L/D=4.1, always available)
        return {
            'freq_hz': 0.2, 'sweep_deg': 60.0,
            'dihedral_deg': 8.0, 'pitch_deg': 2.0,
            'zone': 'CLEAN_GLIDE', 'mode_id': 'GL1_SOARING',
            'gs_id': 'GS-0', 'gl_id': 'GL-1',
            'lever_pct': round(lev,1),
            'speed_gated': False, 'experimental': False,
        }

    if lev <= 74.0:
        # GLIDE-8: GL-0 best efficiency glide (L/D=3.7, motors off)
        return {
            'freq_hz': 0.0, 'sweep_deg': 60.0,
            'dihedral_deg': -5.0, 'pitch_deg': 0.0,
            'zone': 'CLEAN_GLIDE', 'mode_id': 'GL0_BEST_GLIDE',
            'gs_id': 'GS-0', 'gl_id': 'GL-0',
            'lever_pct': round(lev,1),
            'speed_gated': False, 'experimental': False,
        }

    if lev <= 75.0:
        # GLIDE-9: GL-2 powered approach (L/D=13.1 with thrust)
        return {
            'freq_hz': 0.3, 'sweep_deg': 60.0,
            'dihedral_deg': 12.0, 'pitch_deg': 3.0,
            'zone': 'APPROACH', 'mode_id': 'GL2_PWR_APPROACH',
            'gs_id': 'GS-0', 'gl_id': 'GL-2',
            'lever_pct': round(lev,1),
            'speed_gated': False, 'experimental': False,
        }

    # ── BRAKE ZONE: 75–100% ──────────────────────────────────────

    if lev <= 80.0:
        # BRAKE-1: GL-3 steeper approach (L/D=12.0, sink=0.72m/s)
        t = zone_t(75.0, 80.0)
        return {
            'freq_hz': lerp(0.3, 0.3, t), 'sweep_deg': 60.0,
            'dihedral_deg': lerp(12.0, 18.0, t), 'pitch_deg': 4.0,
            'zone': 'APPROACH', 'mode_id': 'GL3_APPROACH',
            'gs_id': 'GS-0', 'gl_id': 'GL-3',
            'lever_pct': round(lev,1),
            'speed_gated': False, 'experimental': False,
        }

    if lev <= 84.0:
        # BRAKE-2: GL-4 steep descent (L/D=8.1, sink=1.04m/s)
        t = zone_t(80.0, 84.0)
        return {
            'freq_hz': lerp(0.3, 0.3, t), 'sweep_deg': lerp(60.0, 75.0, t),
            'dihedral_deg': lerp(18.0, 25.0, t), 'pitch_deg': 5.0,
            'zone': 'STEEP_DESCENT', 'mode_id': 'GL4_STEEP',
            'gs_id': 'GS-0', 'gl_id': 'GL-4',
            'lever_pct': round(lev,1),
            'speed_gated': False, 'experimental': False,
        }

    if lev <= 87.0:
        # BRAKE-3: GS-5 rear-only descent (experimental)
        return {
            'freq_hz': 0.5, 'sweep_deg': 60.0,
            'dihedral_deg': 0.0, 'pitch_deg': 6.0,
            'zone': 'STEEP_DESCENT', 'mode_id': 'GS5_REAR_ONLY',
            'gs_id': 'GS-5', 'gl_id': 'GL-0',
            'lever_pct': round(lev,1),
            'speed_gated': False, 'experimental': True,
        }

    if lev <= 91.0:
        # BRAKE-4: GL-5 very steep descent (L/D=5.3, sink=1.67m/s)
        t = zone_t(87.0, 91.0)
        return {
            'freq_hz': lerp(0.5, 0.5, t), 'sweep_deg': lerp(75.0, 90.0, t),
            'dihedral_deg': lerp(25.0, 35.0, t), 'pitch_deg': 6.0,
            'zone': 'STEEP_DESCENT', 'mode_id': 'GL5_VERY_STEEP',
            'gs_id': 'GS-0', 'gl_id': 'GL-5',
            'lever_pct': round(lev,1),
            'speed_gated': False, 'experimental': False,
        }

    if lev <= 93.0:
        # BRAKE-5: Ballistic descent (power-off, h>30m)
        if ok_h30:
            return {
                'freq_hz': 0.0, 'sweep_deg': 90.0,
                'dihedral_deg': 35.0, 'pitch_deg': 8.0,
                'zone': 'STEEP_DESCENT', 'mode_id': 'BALLISTIC',
                'gs_id': 'GS-0', 'gl_id': 'GL-5',
                'lever_pct': round(lev,1),
                'speed_gated': False, 'experimental': False,
            }
        # Too low for ballistic — use GL-5 instead
        lev = 91.0

    if lev <= 96.0:
        # BRAKE-6: GL-6 near-vertical (L/D=2.2, sink=4.0m/s, h>50m)
        t = zone_t(93.0, 96.0)
        if ok_h50:
            return {
                'freq_hz': lerp(0.5, 0.8, t), 'sweep_deg': lerp(90.0, 120.0, t),
                'dihedral_deg': lerp(35.0, 45.0, t), 'pitch_deg': 8.0,
                'zone': 'NEAR_VERTICAL', 'mode_id': 'GL6_NEAR_VERT',
                'gs_id': 'GS-0', 'gl_id': 'GL-6',
                'lever_pct': round(lev,1),
                'speed_gated': False, 'experimental': False,
            }

    # BRAKE-7: GL-7 maximum airbrake (L/D=1.7, sink=5.0m/s)
    t = zone_t(96.0, 100.0)
    return {
        'freq_hz': lerp(0.8, 1.0, t), 'sweep_deg': lerp(120.0, 135.0, t),
        'dihedral_deg': lerp(45.0, 55.0, t), 'pitch_deg': lerp(8.0, 10.0, t),
        'zone': 'MAX_AIRBRAKE', 'mode_id': 'GL7_MAX_AIRBRAKE',
        'gs_id': 'GS-0', 'gl_id': 'GL-7',
        'lever_pct': round(lev,1),
        'speed_gated': False, 'experimental': False,
    }


def lever_in_detent(lev_pct):
    """True if lever is in the trim/hold-altitude detent (45-55%)."""
    return LEVER_DETENT_LOW <= lev_pct <= LEVER_DETENT_HIGH


def lever_zone_name(lev_pct):
    """Human-readable zone name for HUD / telemetry."""
    return unified_lever_to_params(lev_pct)['zone']


def lever_mode_id(lev_pct, V_ms=7.0, h_agl_m=100.0):
    """Return the active mode_id for current conditions."""
    return unified_lever_to_params(lev_pct, V_ms, h_agl_m)['mode_id']


def lever_stall_check(lev_pct, V_ms):
    """Safety gate: returns (safe: bool, reason: str)."""
    lp = unified_lever_to_params(lev_pct, V_ms)
    if lp.get('speed_gated') and V_ms < VS_OGE_MS * 1.2:
        return False, f"Mode {lp['mode_id']} needs more airspeed"
    if lev_pct >= 93.0 and V_ms < VS_OGE_MS * 1.3:
        return False, f"High-brake zone: need {VS_OGE_MS*1.3:.1f}m/s (have {V_ms:.1f})"
    return True, 'ok'

