def get_mode_hints(mode_id_or_intent, V_ms=7.0, bank_deg=0.0):
    """
    Retrieve DOF hints for a mode, scaled to current flight condition.

    Parameters
    ----------
    mode_id_or_intent : str — mode name or intent string
    V_ms              : float — airspeed (scales some hints)
    bank_deg          : float — bank angle (scales split_bias)

    Returns
    -------
    dict with all 7 DOF hints + notes
    """
    import math as _mhm

    # Normalise key
    key = mode_id_or_intent.lower().replace('-', '_').replace(' ', '_')
    hints = dict(MODE_HINTS.get(key, MODE_HINTS.get('cruise', {})))

    if not hints:
        hints = {
            'sweep_deg': 60.0, 'dihedral_deg': 0.0,
            'aoa_deg': AOA_PEAK_EFFICIENCY_DEG, 'amp_deg': FLAP_AMP_DEG,
            'phase_deg': CASCADE_PHASE_DEFAULT_DEG,
            'split_bias': 0.0, 'notes': 'default hints',
        }

    # Scale split_bias with bank angle — more bank = more split utility
    bank_abs = abs(bank_deg)
    if bank_abs > 5.0:
        bank_scale = _mhm.sin(_mhm.radians(min(90.0, bank_abs)))
        # Nudge split_bias toward 0.5 at 90° bank regardless of mode default
        hints['split_bias'] = round(
            hints['split_bias'] * (1 - bank_scale * 0.4) +
            0.5 * bank_scale * 0.4, 2)

    # At low airspeed: deployed sweep always beneficial
    if V_ms < VS_OGE_MS * 1.5:
        hints['sweep_deg'] = min(hints['sweep_deg'],
                                  60.0 - (VS_OGE_MS * 1.5 - V_ms) * 3.0)
        hints['sweep_deg'] = round(max(45.0, hints['sweep_deg']), 1)

    return hints


# ── Wire mode hints into the tick layer ──────────────────────────
# After the lever returns a mode, we read its hints and use them
# as soft targets for the DOF that the mode function didn't set.
# Rate-limited via smooth_step — never jumps.

_pre_hints_tick = MCOFlightController.tick

def _tick_mode_hints(self, sensors):
    """Apply mode hints as soft DOF targets for any DOF not set by mode."""
    result = _pre_hints_tick(self, sensors)

    if in_violent_manoeuvre():
        return result

    V_ms     = sensors.get('V_ms',        7.0)
    bank_deg = sensors.get('roll_deg_imu', 0.0)
    lever    = sensors.get('lever_pct',   50.0)
    dt_s     = sensors.get('dt_s',         0.02)

    # Get current mode from lever
    try:
        lp = unified_lever_to_params(lever, V_ms)
        intent = lp.get('intent', 'cruise')
    except Exception:
        intent = 'cruise'

    hints = get_mode_hints(intent, V_ms, bank_deg)

    for wc in result['wing_commands']:
        # Only apply hints to DOF not already explicitly set this tick
        # (identified by checking if value is still at nominal default)
        # Sweep: gentle hint
        curr_sw = wc.get('sweep_deg', 60.0)
        tgt_sw  = hints['sweep_deg']
        if abs(curr_sw - 60.0) < 2.0:   # at nominal — apply hint
            wc['sweep_deg'] = round(smooth_step(
                curr_sw, tgt_sw, SWEEP_RATE_NORM * 0.3, dt_s), 1)

        # Dihedral: very gentle hint — stability preference
        curr_dh = wc.get('dihedral_deg', 0.0)
        tgt_dh  = hints['dihedral_deg']
        if abs(curr_dh) < 1.0:   # near neutral — apply hint
            wc['dihedral_deg'] = round(smooth_step(
                curr_dh, tgt_dh, DIHEDRAL_RATE_NORMAL_DPS * 0.2, dt_s), 1)

    # Post phase hint to Loop 2 as its starting point
    if not _L2_state.get('frozen') and not in_violent_manoeuvre():
        _L2_state['mode_phase_hint'] = hints['phase_deg']

    # Post split_bias to split stroke tick
    _split_state['mode_split_bias'] = hints['split_bias']

    result['mode_hints'] = {
        'intent':     intent,
        'sweep_hint': hints['sweep_deg'],
        'dih_hint':   hints['dihedral_deg'],
        'phase_hint': hints['phase_deg'],
        'split_bias': hints['split_bias'],
        'amp_hint':   hints['amp_deg'],
    }
    return result

MCOFlightController.tick = _tick_mode_hints


# ═════════════════════════════════════════════════════════════════
# HIGH-SPEED FSF SPRINT — DYNAMIC SWEEP COUPLING AT ALL SPEEDS
# ═════════════════════════════════════════════════════════════════
#
# WHAT WAS WRONG:
#   The FSF (Flap-Sweep-Forward) mechanism was gated to V < 6m/s.
#   sprint_params() used sweep=90° (wings pointing laterally).
#   forward_sweep_sprint_params() used fixed 25° sweep.
#   All three are wrong for different reasons.
#
# THE PHYSICS:
#   During a flapping stroke at speed V, each wing section sees a
#   COMBINED velocity vector:
#     V_combined = sqrt(V_freestream² + V_flap²)
#     α_stroke   = arctan(V_flap / V_freestream)
#
#   At V=28m/s, 3Hz: V_flap ≈ 7m/s → α_stroke ≈ 14°
#   At V=7m/s,  2.5Hz: V_flap ≈ 5.8m/s → α_stroke ≈ 40°
#
#   The optimal sweep angle positions the wing chord so that the
#   combined velocity vector meets it at ~18-22° AoA (S1223 peak).
#   This means sweep should track the stroke angle continuously.
#
# THE SOLUTION — HIGH-SPEED FSF:
#   DOWNSTROKE: sweep to optimal_sweep_down(V, freq)
#     Wing sweeps FORWARD so leading edge meets the combined flow
#     at optimal AoA → generates a force with a FORWARD component
#     → direct forward thrust, not just inclined stroke plane tilt
#
#   UPSTROKE:   sweep to optimal_sweep_up(V, freq)
#     Wing sweeps AFT — reduces effective area on recovery stroke
#     Dramatically reduces upstroke drag (like a bird folding its wing)
#
#   TRANSITION: bell-curve profiled between strokes
#     Sweep servo moves during the stroke reversal, not mid-stroke
#     Timing gated to the stroke phase signal from the ODrive
#
# SPEED IMPROVEMENT ESTIMATE:
#   Conservative (15% thrust boost via forward thrust component):
#     → adds ~3-5 m/s to sustained sprint ceiling
#   Moderate (25% boost via LEV attachment on downstroke):
#     → adds ~6-9 m/s to sprint ceiling
#   The discovery system will measure the actual benefit in flight.
#
# CRUISE IMPROVEMENT:
#   The same principle applies at cruise (7-9 m/s).
#   At cruise α_stroke ≈ 40° → optimal_sweep ≈ 30° on downstroke.
#   Currently cruise uses fixed 55-60° sweep (from MODE_HINTS).
#   Dynamic FSF at cruise should reduce drag and improve L/D.
#   Estimated cruise speed increase: 1-3 m/s.
# ═════════════════════════════════════════════════════════════════

import math as _hsfm

# S1223 peak AoA relative to combined flow
AOA_OPT_COMBINED  = 20.0   # degrees — optimal AoA for S1223 in combined flow
AOA_OPT_MIN       = 14.0   # minimum acceptable AoA before stall risk
AOA_OPT_MAX       = 28.0   # maximum before separation

# Sweep limits for high-speed FSF
HSF_SWEEP_MIN_DEG = 20.0   # minimum forward sweep (structural limit)
HSF_SWEEP_MAX_DEG = 85.0   # maximum aft sweep on upstroke

# Speed gate — below this, original FSF (slow-speed) takes over
HSF_V_MIN_MS      = 6.0    # m/s — below this use slow-speed FSF

# Per-pair timing offset for cascade sweep phasing
# Each pair's sweep servo leads the next by this angle of stroke phase
HSF_CASCADE_PHASE_DEG = 22.5   # 90°/4 pairs — quarter cycle between pairs

_hsf_state = {
    'active':          False,
    'sweep_history':   [],   # [(time, V, sweep_down, sweep_up)]
    'best_down_by_V':  {},   # V_bin → best measured sweep_down
    'best_up_by_V':    {},
}


def hsf_optimal_sweeps(V_ms, freq_hz, semi_span_m=0.742):
    """
    Compute the optimal downstroke and upstroke sweep angles
    for high-speed forward flight given current airspeed and frequency.

    The downstroke sweep positions the chord optimally into the
    combined (freestream + flapping) velocity vector.
    The upstroke sweep minimises recovery-stroke drag.

    Parameters
    ----------
    V_ms        : float — forward airspeed
    freq_hz     : float — flapping frequency
    semi_span_m : float — mean semi-span

    Returns
    -------
    dict:
        sweep_down_deg : float — downstroke sweep (forward)
        sweep_up_deg   : float — upstroke sweep (aft/stowed)
        alpha_stroke   : float — stroke velocity angle
        V_combined     : float — combined velocity magnitude
        thrust_factor  : float — estimated thrust improvement factor
    """
    # Flapping velocity at 60% semi-span (effective aerodynamic centre)
    V_flap = 2 * _hsfm.pi * freq_hz * semi_span_m * 0.60

    # Combined velocity vector
    V_comb      = _hsfm.sqrt(V_ms**2 + V_flap**2)
    alpha_stroke = _hsfm.degrees(_hsfm.atan2(V_flap, V_ms))

    # Optimal downstroke sweep: position chord so combined flow
    # meets it at AOA_OPT_COMBINED
    # The chord is perpendicular to the sweep direction.
    # At sweep θ, the chord makes angle (90°-θ) with the fuselage axis.
    # The flow arrives at angle alpha_stroke from horizontal.
    # We want: angle between chord and combined flow = AOA_OPT_COMBINED
    # → sweep_down = 90° - alpha_stroke - AOA_OPT_COMBINED
    sweep_down = 90.0 - alpha_stroke - AOA_OPT_COMBINED
    sweep_down = max(HSF_SWEEP_MIN_DEG,
                     min(HSF_SWEEP_MAX_DEG, sweep_down))

    # Upstroke sweep: stow wings to reduce recovery drag
    # Target: reduce effective area to ~40% of downstroke area
    # Achieved by sweeping aft to ~75-85° depending on speed
    sweep_up = min(HSF_SWEEP_MAX_DEG,
                   70.0 + (V_ms / VNE_MS) * 15.0)

    # Estimated thrust improvement factor vs fixed sweep
    # Comes from: (1) forward thrust component on downstroke
    #             (2) reduced upstroke drag
    # Conservative model: 15% at V=10, 25% at V=20, 35% at V=28
    thrust_factor = 1.0 + 0.35 * (V_ms / VNE_MS)

    return {
        'sweep_down_deg': round(sweep_down, 1),
        'sweep_up_deg':   round(sweep_up, 1),
        'alpha_stroke':   round(alpha_stroke, 1),
        'V_combined':     round(V_comb, 2),
        'thrust_factor':  round(thrust_factor, 3),
        'V_flap':         round(V_flap, 2),
    }


def high_speed_fsf_params(V_ms, Ps_measured, current_freq, dt_s,
                           stroke_phases):
    """
    High-speed FSF sprint configuration.

    Replaces sprint_params() and forward_sweep_sprint_params()
    with a physically correct speed-adaptive dynamic sweep system.

    Parameters
    ----------
    V_ms          : float — current airspeed
    Ps_measured   : float — specific excess power (Boyd input)
    current_freq  : float — current flapping frequency
    dt_s          : float — tick interval
    stroke_phases : list[8] — current stroke phase 0-1 per wing

    Returns
    -------
    dict with freq_hz, sweeps_deg[8], pitches_deg, note
    """
    if V_ms < HSF_V_MIN_MS:
        # Below gate — return to slow-speed FSF
        return {'active': False, 'reason': f'V={V_ms:.1f}<{HSF_V_MIN_MS}m/s'}

    # Boyd frequency command — maximise Ps at sprint
    freq = boyd_freq_command(
        current_freq, Ps_measured,
        PS_TARGET.get('sprint', [0.5])[0], dt_s,
        freq_min=1.5, freq_max=FREQ_LIMIT_MAX_HZ,
    )

    # Body pitch for forward speed: tilt stroke plane forward
    # Optimal nose-down pitch = arctan(D/W) ≈ arctan(0.4) at sprint
    body_pitch_down = min(25.0, 8.0 + (V_ms / VNE_MS) * 17.0)

    # Per-wing sweep based on stroke phase
    sweeps = []
    for i, phase in enumerate(stroke_phases):
        pair_id  = (i // 2) + 1
        # Each pair's phase is offset by HSF_CASCADE_PHASE_DEG
        pair_phase_offset = (pair_id - 1) * HSF_CASCADE_PHASE_DEG / 360.0
        eff_phase = (phase + pair_phase_offset) % 1.0

        # Get optimal sweeps for this speed and frequency
        opt = hsf_optimal_sweeps(V_ms, freq)

        # Downstroke (phase 0.0–0.5): sweep forward for thrust
        # Upstroke (phase 0.5–1.0): sweep aft to reduce drag
        if eff_phase < 0.5:
            # Downstroke — bell-curve within stroke
            t = eff_phase / 0.5   # 0→1 across downstroke
            # Sweep is most forward at mid-downstroke (peak bell)
            sw = opt['sweep_up_deg'] + (opt['sweep_down_deg'] -
                  opt['sweep_up_deg']) * _hsfm.sin(_hsfm.pi * t)
        else:
            # Upstroke — stow
            t  = (eff_phase - 0.5) / 0.5
            sw = opt['sweep_down_deg'] + (opt['sweep_up_deg'] -
                  opt['sweep_down_deg']) * _hsfm.sin(_hsfm.pi * t)

        sweeps.append(round(max(HSF_SWEEP_MIN_DEG,
                                min(HSF_SWEEP_MAX_DEG, sw)), 1))

    # AoA: moderate — speed not lift, but not feathered
    # At sprint, AoA contributes to thrust via inclined stroke plane
    aoa = max(10.0, 20.0 - (V_ms / VNE_MS) * 10.0)

    opt = hsf_optimal_sweeps(V_ms, freq)
    note = (f"HSF-SPRINT: V={V_ms:.1f}m/s f={freq:.2f}Hz "
            f"α_stroke={opt['alpha_stroke']:.0f}° "
            f"sw_down={opt['sweep_down_deg']:.0f}° "
            f"sw_up={opt['sweep_up_deg']:.0f}° "
            f"T×={opt['thrust_factor']:.2f}")

    _hsf_state['active'] = True

    return {
        'active':       True,
        'freq_hz':      round(freq, 2),
        'sweeps_deg':   sweeps,
        'aoa_deg':      round(aoa, 1),
        'body_pitch_down': round(body_pitch_down, 1),
        'thrust_factor':opt['thrust_factor'],
        'zone':         'SPRINT_HSF',
        'mode_id':      'HIGH_SPEED_FSF',
        'note':         note,
    }


