def hsf_sprint_speed_estimate():
    """
    Estimate sprint speed improvement from HSF vs fixed sweep.
    """
    import math
    RHO   = 1.225
    W_N   = 3.448 * 9.81
    S     = 0.979
    AR    = 36.0

    print(f"\n  SPRINT SPEED ESTIMATES")
    print(f"  {'Config':<28}  {'Vmax est':>9}  {'Basis'}")
    print(f"  {'-'*55}")

    configs = [
        ('Current sprint_params (sw=90°)', 1.00, 'lateral wings, stroke plane tilt only'),
        ('forward_sweep_sprint (sw=25°)',   1.00, 'fixed fwd sweep, no dynamic variation'),
        ('HSF conservative (+15%)',         1.15, 'direct thrust component'),
        ('HSF moderate (+25%)',             1.25, 'LEV attachment on downstroke'),
        ('HSF optimistic (+35%)',           1.35, 'full dynamic LEV + reduced upstroke drag'),
    ]

    F_base = W_N * 1.58  # N base thrust at 3Hz

    for name, boost, basis in configs:
        F_avail = F_base * boost
        # Find equilibrium where F_avail × cos(body_pitch) = W
        # and F_avail × sin(body_pitch) = D
        # This is self-consistent iteration
        V_eq = None
        for V in range(5, 60):
            q   = 0.5 * RHO * V**2
            CL  = 2*W_N / (RHO * V**2 * S)
            CD  = 0.030 + CL**2 / (math.pi * AR * 0.82)
            D   = q * S * CD
            # Available forward force component
            F_forward = math.sqrt(max(0, F_avail**2 - W_N**2))
            if D >= F_forward:
                V_eq = V - 1
                break
        if V_eq is None:
            V_eq = '>45'

        V_str = f"{V_eq} m/s ({V_eq*3.6:.0f} km/h)" if isinstance(V_eq, int) else V_eq
        print(f"  {name:<28}  {V_str:>9}  {basis}")


# ═════════════════════════════════════════════════════════════════
# PROGRESSIVE SPEED STOWING
# ═════════════════════════════════════════════════════════════════
# As airspeed increases, rear wing pairs are progressively stowed.
# Stowing reduces wing area, raises wing loading, reduces drag,
# and allows the remaining active pairs to be optimised purely
# for thrust rather than sharing lift duty.
#
# CROSSOVER SPEEDS (estimated — TC-03 will calibrate these):
#   V < 15 m/s:  All 4 pairs active (STOW_THRESHOLD_W4 = 15)
#   V > 15 m/s:  Fold W4 → 3 pairs active. Vs rises: 5.2→6.4 m/s
#   V > 25 m/s:  Fold W3 → 2 pairs active (W1+W2). Vs rises: 9.7 m/s
#   V > 45 m/s:  Fold W2 → 1 pair active (W1). Vs rises: 12.9 m/s
#                (only in dedicated sprint / record mode)
#
# STOWING MECHANISM:
#   The sweep servo drives the wing beyond 90° to ~100-120°.
#   At >90° the chord is pointing AFT of perpendicular.
#   The wing is aerodynamically unloaded (near-zero CL and CD).
#   The stowed wing lies along the fuselage axis — minimal drag.
#   The sector wheel allows this: SECTOR_WHEEL_MECH_LIMIT = 100°.
#
# PAIR-SPECIFIC ROLE AT SPRINT:
#   W1 (front, longest span): primary LIFT pair
#      Forward sweep (25-35°), full AoA, maximum span
#   W2 (second pair):         primary THRUST pair
#      Intermediate sweep (35-50°), inclined AoA
#   W3 (third pair):          secondary THRUST (below W2 crossover)
#   W4 (rear, shortest):      stowed above 15 m/s
#
# This mirrors dragonfly forewing (lift) vs hindwing (thrust) split.
# ═════════════════════════════════════════════════════════════════

# Speed thresholds for progressive stowing (CAL: update after TC-03)
STOW_THRESHOLD_W4_MS  = 15.0   # m/s — fold W4 above this speed
STOW_THRESHOLD_W3_MS  = 25.0   # m/s — fold W3+W4 above this
STOW_THRESHOLD_W2_MS  = 45.0   # m/s — fold W2+W3+W4 (W1 only)

# Stow angle — wing swept beyond perpendicular, lying aft
STOW_ANGLE_DEG        = 100.0  # ° — SECTOR_WHEEL_MECH_LIMIT

# How many pairs to keep when stowing (for each speed regime)
# 4→3→2→1 as speed increases
def active_pairs_for_speed(V_ms):
    """Return number of active (unstowed) wing pairs at airspeed V."""
    if V_ms < STOW_THRESHOLD_W4_MS:
        return 4
    elif V_ms < STOW_THRESHOLD_W3_MS:
        return 3
    elif V_ms < STOW_THRESHOLD_W2_MS:
        return 2
    else:
        return 1

def stall_speed_at_config(n_active, sweep_deg, CL_max=CL_MAX):
    """Stall speed for n_active pairs at sweep_deg."""
    import math as _stm
    theta = _stm.radians(sweep_deg)
    b     = 0.742 * _stm.cos(theta) * 2 * n_active
    S     = b * CHORD_MM / 1000
    if S < 0.001:
        return 99.0
    return _stm.sqrt(2 * MTOW_KG * 9.81 / (1.225 * S * CL_max))


def progressive_stow_for_speed(V_ms, current_freq, Ps_measured,
                                 dt_s, stroke_phases,
                                 allow_w1_only=False):
    """
    Speed-adaptive progressive stowing with pair-specific roles.

    Stows rear pairs as speed increases to reduce drag.
    Active pairs are configured for their specific role
    (W1=lift, W2=thrust, W3=secondary thrust) using HSF
    dynamic sweep on the active wings.

    Parameters
    ----------
    V_ms          : float — current airspeed
    current_freq  : float — current frequency
    Ps_measured   : float — specific excess power
    dt_s          : float — tick interval
    stroke_phases : list[8] — stroke phase 0-1 per wing
    allow_w1_only : bool — allow single-pair mode (sprint only)

    Returns
    -------
    dict:
        active_pairs    : int — how many pairs are active
        sweeps_deg      : list[8] — sweep angle per wing
        pitches_deg     : list[8] — AoA per wing
        amps_deg        : list[8] — amplitude per wing
        freq_hz         : float
        stall_speed     : float — current stall speed
        note            : str
    """
    import math as _psm

    # Determine active pair count
    n_max = 4 if allow_w1_only else 2
    n_active = max(1 if allow_w1_only else 2,
                   active_pairs_for_speed(V_ms))
    n_stowed = 4 - n_active

    # Boyd frequency — maximise Ps with current active wing count
    freq = boyd_freq_command(
        current_freq, Ps_measured,
        PS_TARGET.get('sprint', [0.5])[0], dt_s,
        freq_min=1.5, freq_max=FREQ_LIMIT_MAX_HZ,
    )

    # Get HSF sweep for active pairs
    hsf = hsf_optimal_sweeps(V_ms, freq)

    sweeps = []
    pitches = []
    amps    = []

    for i in range(8):
        pair_id  = (i // 2) + 1    # 1=front, 4=rear
        phase    = stroke_phases[i] if i < len(stroke_phases) else 0.5

        if pair_id > n_active:
            # STOWED — fold aft past perpendicular
            sweeps.append(STOW_ANGLE_DEG)
            pitches.append(0.0)       # feathered
            amps.append(0.0)          # stop flapping (amplitude = 0)
        else:
            # ACTIVE — assign role based on pair position

            # Per-stroke dynamic sweep (HSF)
            if phase < 0.5:
                t  = phase / 0.5
                sw = (hsf['sweep_up_deg'] +
                      (hsf['sweep_down_deg'] - hsf['sweep_up_deg']) *
                      _psm.sin(_psm.pi * t))
            else:
                t  = (phase - 0.5) / 0.5
                sw = (hsf['sweep_down_deg'] +
                      (hsf['sweep_up_deg'] - hsf['sweep_down_deg']) *
                      _psm.sin(_psm.pi * t))

            sweeps.append(round(max(HSF_SWEEP_MIN_DEG,
                                    min(HSF_SWEEP_MAX_DEG, sw)), 1))

            # Pair-specific AoA role
            if pair_id == 1:
                # W1: LIFT pair — highest AoA for low stall speed
                aoa = min(AOA_PEAK_CL_DEG, 28.0)
            elif pair_id == 2:
                # W2: THRUST pair — moderate AoA, inclined stroke plane
                aoa = max(10.0, 20.0 - (V_ms / VNE_MS) * 8.0)
            else:
                # W3: secondary thrust
                aoa = max(8.0, 18.0 - (V_ms / VNE_MS) * 6.0)
            pitches.append(round(aoa, 1))

            # Amplitude: active pairs use full amplitude
            amps.append(FLAP_AMP_DEG)

    # Stall speed with current active count
    sw_mean = (hsf['sweep_down_deg'] + hsf['sweep_up_deg']) / 2
    Vs = stall_speed_at_config(n_active, sw_mean)

    # Safety: if V too close to stall, extend additional pair
    if V_ms < Vs * 1.25 and n_active < 4:
        n_active += 1
        # Re-activate the next pair (simple: restore its sweep)
        pair_to_restore = n_active
        for i in range(8):
            if (i // 2) + 1 == pair_to_restore:
                sweeps[i]  = 60.0
                pitches[i] = AOA_PEAK_CL_DEG
                amps[i]    = FLAP_AMP_DEG

    note = (f"PROG-STOW: V={V_ms:.1f}m/s "
            f"active={n_active}/4 "
            f"stowed=W{n_active+1}..W4 "
            f"Vs={Vs:.1f}m/s "
            f"f={freq:.2f}Hz "
            f"T×={hsf['thrust_factor']:.2f}")

    return {
        'active_pairs':  n_active,
        'stowed_pairs':  n_stowed,
        'sweeps_deg':    sweeps,
        'pitches_deg':   pitches,
        'amps_deg':      amps,
        'freq_hz':       round(freq, 2),
        'stall_speed':   round(Vs, 2),
        'thrust_factor': hsf['thrust_factor'],
        'zone':          'SPRINT_PROG_STOW',
        'mode_id':       f'PROG_STOW_{n_active}P',
        'note':          note,
    }


# Update MODE_HINTS for sprint to reflect progressive stowing
MODE_HINTS['sprint']['notes'] = (
    'Progressive stow: W4 folds at 15m/s, W3 at 25m/s. '
    'HSF dynamic sweep on active pairs. '
    'W1=lift, W2/W3=thrust roles.')


def progressive_stow_status():
    """Print progressive stowing status table."""
    import math
    print(f"\n  PROGRESSIVE SPEED STOWING")
    print(f"  {'Speed':>8}  {'Active':>6}  {'Stowed':>6}  "
          f"{'Vs':>6}  {'Drag@V':>8}  {'Config'}")
    print(f"  {'-'*65}")

    configs_v = [5, 10, 14, 20, 28, 35, 50]
    for V in configs_v:
        n = active_pairs_for_speed(V)
        ns = 4 - n
        sw_mean = 55.0  # approximate mean for stall calc
        Vs = stall_speed_at_config(n, sw_mean)

        # Drag estimate
        theta = math.radians(sw_mean)
        b = 0.742 * math.cos(theta) * 2 * n
        S = b * 0.165
        if S > 0:
            CL = 2 * MTOW_KG * 9.81 / (1.225 * V**2 * S)
            CDi = CL**2 / (math.pi * (b**2/S) * 0.82)
            D_wing = 0.5 * 1.225 * V**2 * S * (0.032 + CDi)
            D_fuse = 0.5 * 1.225 * V**2 * math.pi*(0.075)**2 * 0.08
            D_tot = D_wing + D_fuse
        else:
            D_tot = 0

        stow_str = f"W{n+1}-W4" if ns > 0 else "none"
        safe = "✓" if V > Vs * 1.1 else "⚠ near stall"
        print(f"  {V:>6}m/s  {n:>6}  {stow_str:>6}  "
              f"{Vs:>5.1f}m/s  {D_tot:>7.1f}N  {safe}")

    print()
    print(f"  Crossover speeds (CAL — update from TC-03):")
    print(f"    W4 fold: {STOW_THRESHOLD_W4_MS} m/s")
    print(f"    W3 fold: {STOW_THRESHOLD_W3_MS} m/s")
    print(f"    W2 fold: {STOW_THRESHOLD_W2_MS} m/s (sprint only)")


# ═════════════════════════════════════════════════════════════════
# LEVER MAP — HSF AND PROGRESSIVE STOW INTEGRATION
# ═════════════════════════════════════════════════════════════════
# Patches unified_lever_to_params() to call high_speed_fsf_params()
# and progressive_stow_for_speed() at appropriate lever positions,
# and wires both into the tick stack so the optimizer can observe
# and evolve them.
#
# NEW SPRINT ZONE LAYOUT (0–28% lever):
#
#   0–5%   CF1_BURST      V < 10m/s — clap-fling, maximum thrust
#   0–5%   PROG_STOW_1P   V ≥ 10m/s — single pair (W1), HSF, max speed
#   5–10%  CF1_STANDARD   V < 10m/s
#   5–10%  PROG_STOW_2P   V ≥ 10m/s — 2 pairs (W1+W2), HSF
#  10–15%  FWD_SWEEP_SPRINT V < 15m/s — below stow crossover
#  10–15%  PROG_STOW_3P   V ≥ 15m/s — 3 pairs (W1-W3), HSF
#  15–20%  HSF_ALL_4P     all 4 pairs, HSF dynamic sweep
#  20–28%  HSF_ALL_4P     all 4 pairs, HSF moderate speed
#
# The optimizer (Loop 6) observes Ps at each configuration and
# learns the actual crossover speeds from measured data rather
# than the CAL estimates in the constants.
# ═════════════════════════════════════════════════════════════════

import math as _lwm

# Patch unified_lever_to_params with speed-aware sprint selection


def _tick_hsf(self, sensors):
    """
    Apply HSF and progressive stow commands from lever map
    to wing commands every tick.
    """
    result = _pre_hsf_tick(self, sensors)

    if in_violent_manoeuvre():
        return result

    lever_pct    = sensors.get('lever_pct',    50.0)
    V_ms         = sensors.get('V_ms',          7.0)
    Ps           = sensors.get('Ps_measured',   0.0)
    freq_hz      = result.get('freq_hz',        2.5)
    dt_s         = sensors.get('dt_s',          0.02)
    phases       = sensors.get('flap_phases',  [0.0]*8)

    # Only activate in sprint zone (lever ≤ 28%)
    if lever_pct > 28.0:
        return result

    # Get the extended lever params with stroke phase info
    lp = unified_lever_to_params(
        lever_pct, V_ms, sensors.get('h_agl_m', 100.0),
        stroke_phases=phases, dt_s=dt_s,
        Ps_measured=Ps, current_freq=freq_hz,
    )

    mode_id = lp.get('mode_id', '')

    if mode_id in ('HIGH_SPEED_FSF',) or 'PROG_STOW' in mode_id:
        # Apply per-wing sweep, pitch, and amplitude from the params
        sweeps_all  = lp.get('sweeps_all',  None)
        pitches_all = lp.get('pitches_all', None)
        amps_all    = lp.get('amps_all',    None)

        if sweeps_all:
            for i, wc in enumerate(result['wing_commands']):
                if i < len(sweeps_all):
                    # Rate-limit sweep change
                    curr = wc.get('sweep_deg', 60.0)
                    tgt  = sweeps_all[i]
                    step = min(abs(tgt-curr),
                               SWEEP_RATE_EMERGENCY_DPS * dt_s)
                    wc['sweep_deg'] = round(
                        curr + _lwm.copysign(step, tgt-curr), 1)

                if pitches_all and i < len(pitches_all):
                    wc['pitch_deg'] = round(
                        smooth_step(wc.get('pitch_deg', 20.0),
                                    pitches_all[i],
                                    PITCH_RATE_FAST_DPS, dt_s), 1)

                if amps_all and i < len(amps_all):
                    wc['flap_amp_deg'] = amps_all[i]

        result['freq_hz']       = lp['freq_hz']
        result['hsf_active']    = True
        result['active_pairs']  = lp.get('active_pairs', 4)
        result['thrust_factor'] = lp.get('thrust_factor', 1.0)
        result['stall_speed']   = lp.get('stall_speed', VS_OGE_MS)

        # Safety: if V approaching stall speed in stowed config
        stall_speed = lp.get('stall_speed', VS_OGE_MS)
        if V_ms < stall_speed * 1.15 and lp.get('active_pairs', 4) < 4:
            # Restore all pairs immediately
            result['alert'] = (f'STOW SAFETY: V={V_ms:.1f} near '
                               f'Vs={stall_speed:.1f} — restoring pairs')
            for i, wc in enumerate(result['wing_commands']):
                wc['sweep_deg']    = 60.0
                wc['flap_amp_deg'] = FLAP_AMP_DEG
                wc['pitch_deg']    = AOA_PEAK_CL_DEG

    return result

MCOFlightController.tick = _tick_hsf


