if 'SPRINT' in _lm6_zone_map:
    for new_mode in ['HIGH_SPEED_FSF', 'PROG_STOW_4P',
                      'PROG_STOW_3P', 'PROG_STOW_2P', 'PROG_STOW_1P']:
        if new_mode not in _lm6_zone_map['SPRINT']:
            _lm6_zone_map['SPRINT'].insert(0, new_mode)

