def snap_roll_urgency(roll_stick, dt_s):
    """
    Compute urgency scalar from roll stick velocity.

    Fast stick throw → urgency near 1.0 (fast response)
    Slow deliberate roll → urgency near 0.0 (smooth response)
    Stick returning to neutral → urgency decays

    Returns float 0.0 – 1.0
    """
    st = _snap_state_v2
    raw_rate = (roll_stick - st['roll_prev']) / max(dt_s, 0.001)
    st['roll_rate'] = 0.6 * st['roll_rate'] + 0.4 * abs(raw_rate)
    st['roll_prev'] = roll_stick

    # Normalise: full stick throw in 0.1s = rate of 10/s → urgency ≈ 1.0
    urgency = min(1.0, st['roll_rate'] * SNAP_URGENCY_SCALE_FACTOR)

    # Decay when stick is near neutral
    if abs(roll_stick) < 0.05:
        urgency = urgency * 0.85   # decay toward zero

    st['urgency'] = round(urgency, 3)
    return st['urgency']

SNAP_URGENCY_SCALE_FACTOR = 0.5   # tune: 1/s normalisation


def snap_roll_split_command(roll_stick, urgency, base_amp):
    """
    Convert roll stick position to split stroke amplitudes.

    Returns (port_amp, stbd_amp) in degrees.
    Proportional to stick position — pilot has full authority.
    """
    # Scale: at full stick, differential = base_amp
    # At half stick, differential = base_amp/2
    # This gives proportional roll rate at all stick positions
    split_frac = roll_stick   # -1 to +1
    diff       = split_frac * base_amp * SPLIT_BANK_GAIN

    port_amp = max(0.0, min(FLAP_AMP_DEG, base_amp - diff))
    stbd_amp = max(0.0, min(FLAP_AMP_DEG, base_amp + diff))

    return round(port_amp, 1), round(stbd_amp, 1)


