# ═════════════════════════════════════════════════════════════════
# BACKWARD FLIGHT IN AIR — NOT IMPLEMENTED (physics constraint)
# ═════════════════════════════════════════════════════════════════
# Backward flight in air is not possible on the MCO-1D at its
# current T/W ratio. Three reasons:
#
# 1. REVERSED AoA COLLAPSES LIFT:
#    S1223 inverted: CL_max 0.65 vs normal 2.10 (31% of normal).
#    Lift at reversed AoA with hover freq/amp = 10.5 N.
#    Weight = 33.8 N. Sink acceleration = 6.77 m/s².
#    Aircraft loses 13 metres of altitude in 2 seconds.
#
# 2. THE HOVER GAP:
#    At V_forward = 0 the aircraft needs hover configuration
#    (vertical stroke plane) to stay up AND reverse thrust
#    configuration simultaneously. These are incompatible.
#
# 3. INSUFFICIENT T/W MARGIN:
#    Backward flight requires T/W > 1.25 to simultaneously
#    generate lift AND rearward thrust (like a helicopter
#    tilting its rotor disk). MCO-1D T/W at hover is ~1.0.
#
# WHAT IS POSSIBLE INSTEAD:
#    Smooth deceleration to near-hover: already built.
#    Rearward drift in hover via body tilt: < 0.3 m/s,
#    handled passively by gust/stability system.
#    Backward taxi on the ground: fully implemented.
# ═════════════════════════════════════════════════════════════════


# ═════════════════════════════════════════════════════════════════
# PRE-FLIGHT AND POST-FLIGHT CHECKS — PANEL INTEGRATION
# ═════════════════════════════════════════════════════════════════

import time as _pfc_t

# Pre-flight check state
_preflight_state = {
    'status':    'idle',    # idle|running|pass|fail
    'phase':     None,
    'results':   [],
    'start_t':   None,
    'flight_ok': False,
}

# Post-flight check state
_postflight_state = {
    'status':       'idle',   # idle|running|cooldown|stowing|done
    'start_t':      None,
    'checks_done':  False,
    'cooldown_t':   None,
}


def preflight_check_tick(sensors, pi_handle=None, odrive_axes=None):
    """
    Non-blocking pre-flight check — runs across multiple ticks.
    Called by the panel PRE-FLIGHT button handler.

    Runs all three phases of mco_startup_check() then:
    - Enables autonomous discovery
    - Sets ground_ops_state to 'flight'
    - Returns status for panel display

    Returns dict: status, phase, message, flight_ok
    """
    st  = _preflight_state
    now = _pfc_t.monotonic()

    if st['status'] == 'idle':
        st['status']  = 'running'
        st['start_t'] = now
        st['phase']   = 'phase1'
        st['results'] = []
        st['flight_ok'] = False

    if st['status'] == 'running':
        if st['phase'] == 'phase1':
            p1_ok, p1_res = _phase1_math_checks()
            st['results'].extend(p1_res)
            if p1_ok:
                st['phase'] = 'phase2'
                return {'status': 'running', 'phase': 'phase1',
                        'message': 'Phase 1 passed — checking servos'}
            else:
                st['status'] = 'fail'
                return {'status': 'fail', 'phase': 'phase1',
                        'message': 'PHASE 1 FAILED — check constants'}

        elif st['phase'] == 'phase2':
            if pi_handle is None:
                # No Pi handle — skip phase 2
                st['phase'] = 'phase3'
                return {'status': 'running', 'phase': 'phase2_skip',
                        'message': 'Phase 2 skipped (no pigpio)'}
            p2_ok, p2_res = _phase2_servo_checks(pi_handle)
            st['results'].extend(p2_res)
            st['phase'] = 'phase3' if p2_ok else 'fail_p2'
            msg = 'Phase 2 passed — checking ODrives' if p2_ok \
                  else 'PHASE 2 FAILED — servo issue'
            if not p2_ok:
                st['status'] = 'fail'
            return {'status': st['status'], 'phase': 'phase2', 'message': msg}

        elif st['phase'] == 'phase3':
            h_agl    = sensors.get('h_agl_m', 0.0)
            sink     = sensors.get('sink_rate_ms', 0.0)
            throttle = sensors.get('lever_pct', 0.0) / 100.0
            V_ms     = sensors.get('V_ms', 0.0)

            on_gnd = _ground_confirmed(h_agl, sink, throttle, V_ms)
            if not on_gnd:
                st['status'] = 'fail'
                return {'status': 'fail', 'phase': 'phase3',
                        'message': 'NOT ON GROUND — place on level surface'}

            if odrive_axes is None:
                # Skip ODrive test
                st['phase'] = 'complete'
                return {'status': 'running', 'phase': 'phase3_skip',
                        'message': 'Phase 3 skipped (no ODrives) — arming'}
            else:
                p3_ok, p3_res, _ = _phase3_ground_aware(
                    pi_handle, odrive_axes,
                    rangefinder_m=h_agl, baro_agl_m=h_agl,
                    sink_rate_ms=sink, throttle_frac=throttle,
                    airspeed_ms=V_ms)
                st['results'].extend(p3_res)
                if p3_ok:
                    st['phase'] = 'complete'
                    return {'status': 'running', 'phase': 'phase3',
                            'message': 'Phase 3 passed — arming'}
                else:
                    st['status'] = 'fail'
                    return {'status': 'fail', 'phase': 'phase3',
                            'message': 'PHASE 3 FAILED — ODrive fault'}

        elif st['phase'] == 'complete':
            # All checks passed — arm
            _ground_ops_state['mode'] = 'flight'
            autonomous_discovery_enable()
            _L9_state['active'] = True
            st['status']    = 'pass'
            st['flight_ok'] = True
            return {'status': 'pass', 'phase': 'complete',
                    'message': 'ALL CHECKS PASSED — Armed and ready',
                    'flight_ok': True}

    return {
        'status':   st['status'],
        'phase':    st['phase'],
        'message':  'Ready' if st['flight_ok'] else 'Run pre-flight check',
        'flight_ok':st['flight_ok'],
    }


def postflight_check_sequence(wing_commands, dt_s, sensors):
    """
    Post-flight sequence with integrated checks.
    Called every tick while post-flight is active.

    Stages:
      1. POST-FLIGHT CHECKS (immediate, ~5 seconds):
         - Battery voltage logged
         - Motor temperature warning (if available)
         - Flight log save triggered
         - Wing structure visual prompt
      2. COOLDOWN (8 minutes, in-phase oscillation)
      3. AFT STOW
      4. DISARM

    Returns dict: stage, elapsed, remaining, complete, message
    """
    st  = _postflight_state
    now = _pfc_t.monotonic()

    if st['status'] == 'idle':
        st['status']  = 'running'
        st['start_t'] = now
        return {'stage': 'starting', 'complete': False}

    elapsed = now - st['start_t']

    # ── Stage 1: post-flight checks (~5s) ─────────────────────────
    if st['status'] == 'running' and not st['checks_done']:
        batt   = sensors.get('bus_voltage_v', 0.0)
        V_ms   = sensors.get('V_ms', 0.0)
        issues = []

        if batt < 13.0:
            issues.append(f'LOW BATTERY {batt:.1f}V — charge before next flight')
        if batt < 12.0:
            issues.append(f'CRITICALLY LOW {batt:.1f}V — charge immediately')
        if V_ms > 0.5:
            issues.append(f'Aircraft still moving V={V_ms:.1f}m/s — wait')

        if elapsed > 5.0 and V_ms < 0.5:
            st['checks_done'] = True
            st['cooldown_t']  = now
            st['status']      = 'cooldown'
            _ground_ops_state['mode'] = 'cooldown'
            msg = 'Post-flight checks done — cooling (8 min)'
        else:
            msg = f'Post-flight checks... {"; ".join(issues) if issues else "OK"}'

        return {'stage': 'checks', 'elapsed': elapsed,
                'message': msg, 'complete': False,
                'issues': issues}

    # ── Stage 2: cooldown ──────────────────────────────────────────
    if st['status'] == 'cooldown':
        cd_elapsed  = now - st['cooldown_t']
        cd_remaining= max(0.0, 480.0 - cd_elapsed)
        cd_frac     = min(1.0, cd_elapsed / 480.0)

        # Apply cooldown wing commands
        cd = cooldown_wing_commands(cd_elapsed)
        for wc, cc in zip(wing_commands, cd['wing_commands']):
            for k in ('sweep_deg','dihedral_deg','pitch_deg',
                      'flap_amp_deg','cascade_phase_offset_deg'):
                if k in cc:
                    wc[k] = cc[k]

        if cd['complete']:
            st['status'] = 'stowing'
            _ground_ops_state['mode'] = 'aft_stow'
            return {'stage': 'cooldown_done', 'complete': False,
                    'message': 'Cool — stowing wings'}

        return {
            'stage':     'cooldown',
            'elapsed':   round(cd_elapsed),
            'remaining': round(cd_remaining),
            'frac':      round(cd_frac, 3),
            'message':   (f'Cooling {int(cd_remaining//60)}'
                          f':{int(cd_remaining%60):02d} remaining'),
            'complete':  False,
        }

    # ── Stage 3: aft stow ──────────────────────────────────────────
    if st['status'] == 'stowing':
        if not hasattr(st, '_stow_start_t'):
            st['_stow_start_t'] = now
        stow_elapsed = now - st.get('_stow_start_t', now)

        tr = transition_to_aft_stow(wing_commands, dt_s)
        if tr['settled'] or stow_elapsed > 30.0:
            st['status'] = 'disarming'
            _ground_ops_state['mode'] = 'disarmed'
            return {'stage': 'stow_done', 'complete': False,
                    'message': 'Stowed — disarming ODrives'}

        return {'stage': 'stowing', 'complete': False,
                'message': f'Stowing wings Δ={tr["max_error_deg"]:.0f}°'}

    # ── Stage 4: disarm ───────────────────────────────────────────
    if st['status'] == 'disarming':
        st['status'] = 'done'
        return {'stage': 'done', 'complete': True,
                'message': 'Post-flight complete — safe to handle'}

    if st['status'] == 'done':
        return {'stage': 'done', 'complete': True,
                'message': 'Post-flight complete'}

    return {'stage': st['status'], 'complete': False}


# ── Wire post-flight into tick stack ──────────────────────────────
_pre_postflight_tick = MCOFlightController.tick

def _tick_postflight(self, sensors):
    result = _pre_postflight_tick(self, sensors)

    if _postflight_state['status'] not in ('idle', 'done'):
        dt_s = sensors.get('dt_s', 0.02)
        pf   = postflight_check_sequence(
            result['wing_commands'], dt_s, sensors)
        result['postflight'] = pf
        if pf.get('stage') == 'cooldown':
            result['freq_hz'] = COOLDOWN_FREQ_HZ

    return result

MCOFlightController.tick = _tick_postflight


