# The stopped / idle position on the unified lever
GND_LEVER_IDLE_RAW     = 50.0   # lever at 50% = stopped on ground
GND_LEVER_FWD_MIN_RAW  = 55.0   # lever must be above this for fwd taxi
GND_LEVER_BWD_MAX_RAW  = 45.0   # lever must be below this for backward
GND_LEVER_TAKEOFF_RAW  = 90.0   # lever above this = takeoff intent on ground


def taxi_params_from_raw_lever(raw_lever_pct):
    """
    Convert raw lever position to taxi parameters.
    Forward=power convention — 50% = stopped, 100% = full sprint.

    Returns dict: freq_hz, amp_deg, label, direction, takeoff_armed
    """
    lev = max(0.0, min(100.0, raw_lever_pct))

    # Forward taxi (lever 55-100%)
    if lev >= GND_LEVER_FWD_MIN_RAW:
        fwd_frac = (lev - GND_LEVER_FWD_MIN_RAW) / (100.0 - GND_LEVER_FWD_MIN_RAW)
        fwd_frac = max(0.0, min(1.0, fwd_frac))
        # Smootherstep
        t = fwd_frac
        t = t*t*t*(t*(t*6-15)+10)

        stages = [
            (0.0,  0.05, 0.0,   0.0,  'idle'),
            (0.05, 0.25, 0.8,  18.0,  'crawl'),    # barely cracked
            (0.25, 0.50, 1.2,  30.0,  'walk'),
            (0.50, 0.72, 1.8,  50.0,  'jog'),
            (0.72, 0.90, 2.5,  70.0,  'sprint'),
            (0.90, 1.0,  3.0,  85.0,  'pre-takeoff'),
        ]
        freq, amp, label = 0.0, 0.0, 'idle'
        for lo, hi, f, a, lbl in stages:
            if t >= lo:
                freq, amp, label = f, a, lbl

        return {
            'freq_hz':       round(min(FREQ_LIMIT_MAX_HZ, freq), 2),
            'amp_deg':       round(min(FLAP_AMP_DEG, amp), 1),
            'label':         label,
            'direction':     'forward',
            'takeoff_armed': lev >= GND_LEVER_TAKEOFF_RAW,
        }

    # Idle band (45–55%)
    if lev >= GND_LEVER_BWD_MAX_RAW:
        return {
            'freq_hz':       0.0,
            'amp_deg':       0.0,
            'label':         'idle',
            'direction':     'stopped',
            'takeoff_armed': False,
        }

    # Backward taxi (lever 0–45%)
    bwd_frac = (GND_LEVER_BWD_MAX_RAW - lev) / GND_LEVER_BWD_MAX_RAW
    bwd_frac = max(0.0, min(1.0, bwd_frac))
    bwd_cap  = _gnd_vel_cap_factor(
        _gnd_smooth.get('V_bwd_est', 0.0), GND_BWD_MAX_MS)
    bwd_amp  = round(min(50.0, 50.0 * bwd_frac) * bwd_cap, 1)
    bwd_freq = round(min(1.5, 1.5 * bwd_frac) * bwd_cap, 2)

    return {
        'freq_hz':       bwd_freq,
        'amp_deg':       bwd_amp,
        'label':         'backward',
        'direction':     'backward',
        'takeoff_armed': False,
    }


