# ═════════════════════════════════════════════════════════════════
# FOUR-LAYER EXPLORATION SYSTEM
# ═════════════════════════════════════════════════════════════════
#
# LAYER 1 — Gradient exploitation (existing, always running)
# LAYER 2 — Biomimetic hypothesis injection (12 hypotheses)
# LAYER 3 — Evolutionary search (mutation + crossbreeding)
# LAYER 4 — Random safety-gated search (unconstrained physics)
#
# SCHEDULING: 80% Option B (performance-gated) + 20% Option C
#   (curiosity-driven toward cold lever positions)
#
# Option B: Layers 2/3/4 only activate when Layer 1 has converged
#   at the current lever position (gradient no longer improving).
#   "Converged" = Ps improvement < CONVERGENCE_THRESHOLD over
#   CONVERGENCE_WINDOW_S seconds of continuous Layer 1 operation.
#
# Option C (20% of exploration time): Tracks time since each lever
#   position last produced a novel discovery. Positions cold for
#   longer than CURIOSITY_COLD_S get proportionally more Layer 3/4
#   time regardless of convergence state.
#
# AUTONOMY: The entire system runs perpetually without permission.
#   Pre-flight arm starts it. It never stops.
#   Discoveries crossbreed with discoveries.
#   Successful mutations become parents for further mutations.
#   Random successes (Layer 4) feed into Layer 3 crossbreeding
#   and Layer 1 gradient refinement automatically.
#   The aircraft improves every flight, forever.
#
# SAFETY GATING (all layers):
#   Hard walls:  freq ≤ 3.5Hz novel, amp ≤ 96°, V ≥ 1.3×Vs,
#                h ≥ 15m, turb < 0.15, no stall risk
#   Soft abort:  IMU vibration spike, unexpected current rise,
#                Ps drops sharply, any GR fires, altitude loss
#   Trial caps:  5s duration, 3 trials max per novel config
#   No risk:     Never tries a configuration flagged as understood risk
# ═════════════════════════════════════════════════════════════════

import math   as _elm
import random as _elr
import time   as _elt
import copy   as _elc

# ── Scheduling constants ──────────────────────────────────────────
EXPLORATION_CONVERGENCE_THRESHOLD = 0.02   # Ps improvement below this = converged
EXPLORATION_CONVERGENCE_WINDOW_S  = 120.0  # 2 min of no improvement = converged
EXPLORATION_CURIOSITY_COLD_S      = 600.0  # 10 min without discovery = "cold"
EXPLORATION_OPTION_C_FRAC         = 0.20   # 20% curiosity-driven scheduling
EXPLORATION_TRIAL_S               = 5.0    # trial duration (shorter than standard 8s)
EXPLORATION_TRIAL_MAX             = 3      # max trials per novel config before discard
EXPLORATION_MIN_H_M               = 15.0   # minimum altitude for any exploration
EXPLORATION_MAX_TURB              = 0.15   # maximum turbulence intensity
EXPLORATION_NOVEL_FREQ_MAX        = 3.5    # Hz — extra margin for novel configs
EXPLORATION_MAX_FREQ_DIFF_HZ      = 1.5    # max per-pair frequency differential

# ── Layer scheduling state ────────────────────────────────────────
_exploration_state = {
    'active':              True,
    'layer':               1,         # current active layer (1-4)
    'layer_start_t':       None,
    'convergence_tracker': {},         # lever_pct → (best_Ps, last_improve_t)
    'cold_tracker':        {},         # lever_pct → last_discovery_t
    'trial_active':        False,
    'trial_config':        None,
    'trial_source':        None,       # 'biomimetic'|'evolutionary'|'random'
    'trial_hypothesis':    None,       # H-01 through H-12
    'trial_start_t':       None,
    'trial_Ps':            [],
    'trial_count':         {},         # config_hash → trial count
    'n_trials':            {1:0, 2:0, 3:0, 4:0},
    'n_promoted':          {1:0, 2:0, 3:0, 4:0},
    'n_aborted':           0,
    'session_best':        {},         # lever_pct → best_Ps_this_session
}


def _exploration_safety_ok(sensors, config):
    """
    Check all safety gates before running a novel configuration.
    Returns (safe, reason).
    """
    h    = sensors.get('h_agl_m',           0.0)
    V    = sensors.get('V_ms',              0.0)
    turb = sensors.get('turb_intensity',    0.0)
    stall= sensors.get('stall_risk',       False)
    curr = sensors.get('motor_currents_a',  [0]*8)
    imu  = sensors.get('imu_rms_g',        0.0)

    if h < EXPLORATION_MIN_H_M:
        return False, f'h={h:.0f}m < {EXPLORATION_MIN_H_M}m'
    if V < VS_OGE_MS * 1.3:
        return False, f'V={V:.1f}m/s too slow'
    if turb > EXPLORATION_MAX_TURB:
        return False, f'turb={turb:.2f} > {EXPLORATION_MAX_TURB}'
    if stall:
        return False, 'stall risk'
    if imu > 0.1 * 0.7:
        return False, f'IMU={imu:.3f}g high'
    if any(c > STARTUP_CURRENT_LIMIT_A * 1.5 for c in curr):
        return False, 'current near limit'

    # Config-specific safety
    freq = config.get('freq_hz', 2.5)
    if freq > EXPLORATION_NOVEL_FREQ_MAX:
        return False, f'freq={freq}Hz > novel limit {EXPLORATION_NOVEL_FREQ_MAX}Hz'

    aoa = config.get('global_aoa_deg', 20.0)
    if aoa > AOA_PEAK_CL_DEG:
        return False, f'AoA={aoa}° > stall limit'

    # Per-pair frequency differential
    freqs = [config.get(f'freq_pair_{p}', freq) for p in [1,2,3,4]]
    if max(freqs) - min(freqs) > EXPLORATION_MAX_FREQ_DIFF_HZ:
        return False, 'per-pair freq differential too large'

    return True, 'ok'


def _exploration_abort_check(sensors, Ps_baseline, trial_Ps):
    """
    Check soft-abort conditions during a trial.
    Returns (abort, reason).
    """
    curr    = sensors.get('motor_currents_a', [0]*8)
    imu_rms = sensors.get('imu_rms_g', 0.0)
    h       = sensors.get('h_agl_m',   99.0)
    Ps      = sensors.get('Ps_measured', 0.0)

    # Unexpected current spike (>20% above baseline)
    if any(c > STARTUP_CURRENT_LIMIT_A * 1.4 for c in curr):
        return True, 'current spike'

    # IMU vibration spike
    if imu_rms > 0.1 * 0.85:
        return True, 'IMU spike'

    # Sharp Ps drop (more than 0.3 below baseline)
    if len(trial_Ps) > 10 and Ps < Ps_baseline - 0.30:
        return True, f'Ps={Ps:.2f} dropped sharply'

    # Altitude loss
    return False, 'ok'


# ── LAYER 2: Biomimetic hypothesis library ────────────────────────
# Each hypothesis is a config generator function that returns
# a config dict compatible with _config_to_wing_commands().
# Source references are embedded in the docstrings.

BIOMIMETIC_HYPOTHESES = {}


# RE NOTE: Dragonfly Re ~2,000-10,000. MCO-1D Re ~28,000-89,000.
# Phase switching effect transfers — magnitude may be smaller at higher Re
# because the bound vortex is stronger relative to the shed vortex.
# The optimizer quantifies the actual benefit at MCO-1D Re.
def _h01_dragonfly_phase(phase_deg, base_config=None):
    """
    H-01: Dragonfly adaptive phase.
    Sources: Reavis & Luttges 1988, Zheng et al., AIAA Journal 2019.
    In-phase = maximum force. Antiphase = maximum stability.
    45° = maximum thrust coefficient. 90° hindwing-leads = max efficiency.
    """
    cfg = dict(base_config or {})
    cfg['cascade_phase_deg'] = float(phase_deg)
    cfg['hypothesis'] = 'H-01'
    cfg['bio_source',
    # Inter-pair cascade phase variants (Issue 14 fix)
    {'id':'H-01-p30','pair_phases':[0,30,60,90],'desc':'30° inter-pair'},
    {'id':'H-01-p45','pair_phases':[0,45,90,135],'desc':'45° uniform (baseline)'},
    {'id':'H-01-p60','pair_phases':[0,60,120,180],'desc':'60° inter-pair'},
    {'id':'H-01-p90','pair_phases':[0,90,180,270],'desc':'90° inter-pair'},
    {'id':'H-01-popt','pair_phases':None,'desc':'optimizer-selected phase'}] = 'dragonfly_phase_switching'
    return cfg

def _h02_bat_advance_rotation(advance_deg, base_config=None):
    """
    H-02: Bat advance rotation — AoA starts transitioning before stroke reversal.
    Source: PLOS ONE 2019 (Hipposideros pratti), Biology Open 2012.
    Wing starts pitching up before end of downstroke for 2.5× lift increase.
    """
    cfg = dict(base_config or {})
    cfg['aoa_advance_deg'] = float(advance_deg)   # new dimension
    cfg['hypothesis'] = 'H-02'
    cfg['bio_source'] = 'bat_advance_rotation'
    return cfg

def _h03_manta_spanwise_wave(wave_deg, base_config=None):
    """
    H-03: Manta spanwise wave — phase gradient root-to-tip within each pair.
    Source: MDPI 2022, manta pectoral fin kinematics (89% efficiency).
    Chordwise + spanwise wave → enhanced LEV attachment → improved thrust.
    """
    cfg = dict(base_config or {})
    cfg['spanwise_wave_deg'] = float(wave_deg)    # new dimension
    # Apply as graduated phase offsets: W1 port=0, stbd=wave_deg/4 etc.
    for i, pair in enumerate([1,2,3,4]):
        cfg[f'phase_offset_W{pair}'] = round(i * wave_deg / 4.0, 1)
    cfg['hypothesis'] = 'H-03'
    cfg['bio_source'] = 'manta_spanwise_wave'
    return cfg

def _h04_pterosaur_soar(base_config=None):
    """
    H-04: Pterosaur ultra-low reduced frequency soar.
    Source: PMC 2011 — pterosaur wind tunnel, high CL_max at low Strouhal.
    Wings adapted to low-speed thermal soaring with progressive stall.
    CAUTION: Near-stall AoA. Requires h>30m, stall protection active.
    """
    cfg = dict(base_config or {})
    cfg['freq_hz']         = 0.8
    # RE SCALING CORRECTION:
    # Original pterosaur soar used 32° AoA from PMC 2011 pterosaur
    # wind tunnel tests conducted at pterosaur-scale Re (~1,000,000+).
    # At MCO-1D operating Re (~50,000), S1223 CL_max is at ~18° AoA.
    # 32° at MCO-1D Re is post-stall on the S1223 — the wing would
    # have separated flow, not maximum lift. The stall protection
    # system catches this in flight, but 18° is the correct starting
    # point for the optimizer to work from.
    cfg['global_aoa_deg']  = 18.0    # RE-CORRECTED: S1223 CL_max at Re ~50,000
                                      # (was 32° at pterosaur Re ~1,000,000)
    cfg['global_amp_deg']  = 96.0
    cfg['requires_h_m']    = 30.0    # extra height requirement
    cfg['hypothesis'] = 'H-04'
    cfg['bio_source'] = 'pterosaur_soar'
    return cfg

# RE NOTE: Hawkmoth Re ~5,000-10,000. MCO-1D Re ~28,000-89,000.
# LEVs are proportionally smaller at MCO-1D Re than hawkmoth Re.
# Spanwise amplitude gradient mechanism still relevant but smaller benefit.
# Optimizer discovers whether the gradient helps at MCO-1D scale.
def _h05_hawkmoth_amp_gradient(tip_scale, base_config=None):
    """
    H-05: Hawkmoth/bat spanwise amplitude gradient — tip > root.
    Source: PLOS ONE 2019, Nakata et al. hawkmoth FEM study.
    Spanwise kinematic variation delays LEV breakdown near tip.
    """
    cfg = dict(base_config or {})
    cfg['amp_tip_scale'] = float(tip_scale)   # new dimension
    base_amp = cfg.get('global_amp_deg', 96.0)
    # Port wings (even indices): inner = 80%, outer = 100% of tip_scale
    for pair in [1,2,3,4]:
        cfg[f'amp_scale_W{pair}'] = round(
            0.8 + 0.2 * tip_scale * (pair / 4.0), 3)
    cfg['hypothesis'] = 'H-05'
    cfg['bio_source'] = 'hawkmoth_lev_management'
    return cfg

def _h06_negative_cascade(base_config=None):
    """
    H-06: Negative cascade — rear pair leads, front follows.
    Source: JEB 2004 (Maybury & Lehmann) — hindwing leads forewing
    by 90° extracts maximum energy from forewing downwash.
    Reverses current front-to-rear metachronal wave.
    """
    cfg = dict(base_config or {})
    base_phase = cfg.get('cascade_phase_deg', CASCADE_PHASE_DEFAULT_DEG)
    # Reverse: W4 leads, W1 follows → negate phase offsets
    for pair in [2,3,4]:
        old = cfg.get(f'phase_offset_W{pair}', 0.0)
        cfg[f'phase_offset_W{pair}'] = round(-old, 1)
    cfg['cascade_phase_deg'] = -base_phase % 360
    cfg['hypothesis'] = 'H-06'
    cfg['bio_source'] = 'negative_cascade_hindwing_leads'
    return cfg

def _h07_split_frequency(freq_ratio, base_config=None):
    """
    H-07: Split-frequency inter-pair resonance.
    Source: Dragonfly takeoff — alternating large/small amplitude.
    W1+W2 at freq_base, W3+W4 at freq_base × freq_ratio.
    Beat frequency creates slow amplitude modulation = stability.
    CAUTION: Keep differential < 1.5 Hz.
    """
    cfg = dict(base_config or {})
    base_freq = cfg.get('freq_hz', 2.5)
    cfg['freq_pair_1'] = round(base_freq, 2)
    cfg['freq_pair_2'] = round(base_freq, 2)
    cfg['freq_pair_3'] = round(base_freq * freq_ratio, 2)
    cfg['freq_pair_4'] = round(base_freq * freq_ratio, 2)
    diff = abs(base_freq * freq_ratio - base_freq)
    if diff > EXPLORATION_MAX_FREQ_DIFF_HZ:
        cfg['freq_pair_3'] = round(base_freq + EXPLORATION_MAX_FREQ_DIFF_HZ * 0.8, 2)
        cfg['freq_pair_4'] = cfg['freq_pair_3']
    cfg['hypothesis'] = 'H-07'
    cfg['bio_source'] = 'dragonfly_split_frequency'
    return cfg

def _h08_strouhal_optimised(V_ms, base_config=None):
    """
    H-08: Manta Strouhal optimisation — target St in 0.2–0.4.
    Source: MDPI manta paper — 89% propulsive efficiency at St=0.2–0.4.
    Adjusts freq and amplitude to put Strouhal in biological optimal range.
    """
    cfg = dict(base_config or {})
    ST_TARGET = 0.30   # centre of optimal range
    freq = cfg.get('freq_hz', 2.5)
    amp_deg = cfg.get('global_amp_deg', 96.0)
    # Tip excursion in metres (W1 reference)
    span_m    = SEMI_SPANS_MM[1] / 1000.0
    amp_m     = (amp_deg / 180.0) * _elm.pi * span_m
    St_current= (freq * 2 * amp_m) / max(V_ms, 0.5)
    # Adjust freq to hit target St
    if V_ms > 0.5:
        freq_target = ST_TARGET * V_ms / (2 * amp_m)
        freq_target = max(0.5, min(EXPLORATION_NOVEL_FREQ_MAX, freq_target))
        cfg['freq_hz'] = round(freq_target, 2)
    cfg['strouhal_target'] = ST_TARGET
    cfg['hypothesis'] = 'H-08'
    cfg['bio_source'] = 'manta_strouhal_optimal'
    return cfg

# RE NOTE: Locust Re ~5,000-15,000. MCO-1D Re ~28,000-89,000.
# Reversal burst LEV is smaller relative to bound circulation at MCO-1D Re.
# Mechanism transfers — unsteady vortex capture still occurs.
# Magnitude of benefit uncertain — empirical test required.
def _h12_reversal_burst(burst_frac, base_config=None):
    """
    H-12: Locust stroke reversal burst — faster reversal = stronger vortex.
    Source: Dickinson clap-and-fling, locust unsteady aerodynamics.
    ODrive commanded at vel_limit=150 for last/first burst_frac of stroke.
    """
    cfg = dict(base_config or {})
    cfg['reversal_burst_frac'] = max(0.0, min(0.15, float(burst_frac)))
    cfg['hypothesis'] = 'H-12'
    cfg['bio_source'] = 'locust_reversal_vortex'
    return cfg

# Register all safe hypotheses
BIOMIMETIC_HYPOTHESES = {
    'H-01': [(_h01_dragonfly_phase, p) for p in [0, 45, 90, 135, 180]],
    'H-02': [(_h02_bat_advance_rotation, d) for d in [5, 10, 15, 20, 25]],
    'H-03': [(_h03_manta_spanwise_wave, w) for w in [10, 20, 30]],
    'H-04': [(_h04_pterosaur_soar, None)],
    'H-05': [(_h05_hawkmoth_amp_gradient, s) for s in [0.9, 1.0, 1.1, 1.2]],
    'H-06': [(_h06_negative_cascade, None)],
    'H-07': [(_h07_split_frequency, r) for r in [1.05, 1.10, 1.15]],
    'H-08': 'speed_dependent',   # generated at runtime from V_ms
    'H-12': [(_h12_reversal_burst, f) for f in [0.05, 0.08, 0.12]],
    # H-09, H-10, H-11: pending TC/bench validation
}


# ── LAYER 3: Evolutionary search ─────────────────────────────────

def _evolutionary_mutate(parent_config, rng, boldness=0.15):
    """
    Mutate a successful configuration.
    boldness: fraction of parameter range to deviate (0=timid, 1=wild).
    Applies random mutation to 1-4 parameters simultaneously.
    """
    child = dict(parent_config)
    n_mutations = rng.randint(1, 4)
    mutable = [k for k in _EXPANDED_DISCOVERY_BOUNDS
               if k in child or k in _EXPANDED_DISCOVERY_BOUNDS]

    for _ in range(n_mutations):
        param = rng.choice(mutable)
        lo, hi = _EXPANDED_DISCOVERY_BOUNDS.get(param, (0, 1))
        current = child.get(param, (lo + hi) / 2)
        delta = rng.gauss(0, boldness * (hi - lo))
        child[param] = round(max(lo, min(hi, current + delta)), 3)

    child['source']  = 'evolutionary_mutation'
    child['parent']  = parent_config.get('mode_id', 'unknown')
    child['boldness']= boldness
    return child


def _evolutionary_crossbreed(config_a, config_b, rng):
    """
    Crossbreed two successful configurations.
    Each parameter is taken from A or B with 50% probability,
    with occasional interpolation (blend rather than hard select).
    """
    child = {}
    all_keys = set(config_a) | set(config_b)
    all_keys -= {'mode_id','source','parent','hypothesis','bio_source',
                 'requires_h_m','hypothesis','strouhal_target',
                 'promoted','n_obs','created_at','lever_pct',
                 'zone','V_ms','score','best_score'}

    for key in all_keys:
        if key not in _EXPANDED_DISCOVERY_BOUNDS:
            continue
        a_val = config_a.get(key)
        b_val = config_b.get(key)
        if a_val is None:
            child[key] = b_val
        elif b_val is None:
            child[key] = a_val
        else:
            r = rng.random()
            if r < 0.4:
                child[key] = a_val
            elif r < 0.8:
                child[key] = b_val
            else:
                # Blend
                t = rng.random()
                child[key] = round(a_val + t*(b_val - a_val), 3)

    child['source'] = 'evolutionary_crossbreed'
    child['parent_a'] = config_a.get('mode_id', 'A')
    child['parent_b'] = config_b.get('mode_id', 'B')
    return child


def _get_evolutionary_candidates():
    """
    Return a list of successful DISC configs eligible for mutation/crossbreeding.
    Eligible: promoted=True, n_obs >= 5, score > AUTONOMOUS_MIN_SCORE.
    """
    candidates = []
    for mode_id, entry in _DISC_REGISTRY.items():
        if (entry.get('promoted') and
                entry.get('n_obs', 0) >= 5 and
                entry.get('best_score', 0) > AUTONOMOUS_MIN_SCORE):
            cfg = dict(entry.get('config', {}))
            cfg['mode_id'] = mode_id
            candidates.append(cfg)
    return candidates


# ── LAYER 4: Random safety-gated search ──────────────────────────

def _random_novel_config(rng, V_ms=7.0):
    """
    Generate a completely random configuration within the physical
    safety envelope. No biological inspiration, no parent, no gradient.
    Pure uniform random sampling of the full permissible space.

    This is the layer that discovers what nature hasn't tried.
    Explores combinations that no animal uses and no human would
    think to try — but that physics permits and Ps validates.
    """
    cfg = {}

    # Sample all 32 dimensions uniformly
    for param, (lo, hi) in _EXPANDED_DISCOVERY_BOUNDS.items():
        cfg[param] = round(rng.uniform(lo, hi), 3)

    # Apply safety walls
    cfg['freq_hz'] = round(min(EXPLORATION_NOVEL_FREQ_MAX,
                               cfg['freq_hz']), 2)
    cfg['global_aoa_deg'] = round(min(AOA_PEAK_CL_DEG,
                                       cfg['global_aoa_deg']), 1)
    cfg['global_amp_deg'] = round(min(FLAP_AMP_DEG,
                                       cfg['global_amp_deg']), 1)

    # Apply Strouhal sanity (not a hard wall — but extreme St is
    # a sign the config is unlikely to be efficient)
    if V_ms > 0.5:
        amp_m = (cfg['global_amp_deg']/180.0) * _elm.pi * SEMI_SPANS_MM[1]/1000.0
        St = (cfg['freq_hz'] * 2 * amp_m) / V_ms
        if St > 2.0:
            # Very high Strouhal — reduce frequency to something testable
            cfg['freq_hz'] = round(
                min(cfg['freq_hz'],
                    2.0 * V_ms / (2 * amp_m)), 2)

    # Normalise yaw weights
    yw = (cfg.get('w_crab',0) + cfg.get('w_dart',0) +
          cfg.get('w_split',0) + cfg.get('w_proverse',0))
    if yw > 0.01:
        for k in ('w_crab','w_dart','w_split','w_proverse'):
            cfg[k] = round(cfg[k]/yw, 3)

    cfg['source'] = 'random_layer4'
    return cfg


# ── Scheduling engine ─────────────────────────────────────────────
_exploration_rng = _elr.Random(DISCOVERY_SEED + 9999)



def _next_biomimetic_config(V_ms):
    """Select the next untried biomimetic hypothesis config."""
    st = _exploration_state
    tried = st.get('tried_hypotheses', set())

    for hyp_id, variants in BIOMIMETIC_HYPOTHESES.items():
        if hyp_id == 'H-08':
            # Speed-dependent — generate now
            cfg = _h08_strouhal_optimised(V_ms)
            key = f'{hyp_id}_V{V_ms:.0f}'
            if key not in tried:
                tried.add(key)
                st['tried_hypotheses'] = tried
                return cfg, hyp_id
            continue

        for variant in variants:
            fn, arg = (variant[0], variant[1]) if isinstance(variant, tuple) else (variant, None)
            key = f'{hyp_id}_{arg}'
            if key not in tried:
                tried.add(key)
                st['tried_hypotheses'] = tried
                if arg is None:
                    return fn(), hyp_id
                else:
                    return fn(arg), hyp_id

    # All hypotheses tried — cycle back
    st['tried_hypotheses'] = set()
    return _random_novel_config(_exploration_rng, V_ms), 'H-RANDOM'


def exploration_tick(sensors, lever_pct, dt_s):
    """
    Main exploration tick — runs every sensor packet.
    Manages trial lifecycle for all four layers.
    Integrates with the existing discovery/promotion pipeline.
    """
    st   = _exploration_state
    now  = _elt.monotonic()
    Ps   = sensors.get('Ps_measured',  0.0)
    V_ms = sensors.get('V_ms',         7.0)
    h    = sensors.get('h_agl_m',    100.0)
    turb = sensors.get('turb_intensity',0.0)

    if not st['active']:
        return {'active': False}

    # ── Active trial management ───────────────────────────────────
    if st['trial_active']:
        elapsed = now - st['trial_start_t']

        # Collect Ps
        st['trial_Ps'].append(Ps)

        # Soft abort check
        Ps_baseline = st.get('trial_Ps_baseline', 0.0)
        abort, reason = _exploration_abort_check(sensors, Ps_baseline,
                                                  st['trial_Ps'])
        if abort:
            st['trial_active']   = False
            st['trial_config']   = None
            st['n_aborted']     += 1
            return {
                'active':  True,
                'trial':   False,
                'aborted': True,
                'reason':  reason,
                'layer':   st['layer'],
            }

        if elapsed < EXPLORATION_TRIAL_S:
            return {
                'active':  True,
                'trial':   True,
                'elapsed': round(elapsed, 1),
                'layer':   st['layer'],
                'source':  st['trial_source'],
            }

        # Trial complete — evaluate
        if st['trial_Ps']:
            mean_Ps = sum(st['trial_Ps']) / len(st['trial_Ps'])
        else:
            mean_Ps = 0.0

        st['trial_active'] = False
        trial_cfg          = st['trial_config']
        layer              = st['layer']

        # Compare against existing best at this lever position
        _, existing_cfg, existing_score = _find_discovered_mode_at(
            lever_pct, V_ms, tolerance=3.0)
        existing_score = existing_score or 0.0

        promoted = False
        if mean_Ps > AUTONOMOUS_MIN_SCORE and \
           mean_Ps > existing_score + AUTONOMOUS_PROMOTE_MARGIN:
            # Promote to discovery registry and lever map
            mode_id = register_discovered_mode(
                config    = trial_cfg,
                score     = mean_Ps,
                zone      = 'TRIM',
                V_ms      = V_ms,
                lever_pct = lever_pct,
            )
            promoted = promote_to_lever_map(mode_id, lever_pct, mean_Ps)
            if promoted:
                st['n_promoted'][layer] = st['n_promoted'].get(layer,0) + 1
                st['cold_tracker'][lever_pct] = now   # reset cold timer

        st['n_trials'][layer] = st['n_trials'].get(layer,0) + 1
        st['trial_config']    = None
        st['trial_Ps']        = []

        return {
            'active':    True,
            'trial':     False,
            'trial_done':True,
            'mean_Ps':   round(mean_Ps, 3),
            'promoted':  promoted,
            'layer':     layer,
            'source':    st['trial_source'],
            'hypothesis':st.get('trial_hypothesis'),
        }

    # ── Schedule next trial ───────────────────────────────────────
    # Basic safety before starting anything
    if h < EXPLORATION_MIN_H_M or turb > EXPLORATION_MAX_TURB:
        return {'active': True, 'trial': False, 'waiting': True}

    # Select layer
    layer, rationale = _exploration_schedule(lever_pct, Ps, V_ms, now)
    st['layer'] = layer

    if layer == 1:
        # Layer 1 is the standard discovery system — handled elsewhere
        return {'active': True, 'trial': False, 'layer': 1,
                'rationale': rationale}

    # Generate trial config for layers 2, 3, 4
    trial_cfg   = None
    trial_source= None
    trial_hyp   = None

    if layer == 2:
        trial_cfg, trial_hyp = _next_biomimetic_config(V_ms)
        trial_source = f'biomimetic:{trial_hyp}'

    elif layer == 3:
        candidates = _get_evolutionary_candidates()
        if len(candidates) >= 2:
            a, b = _exploration_rng.sample(candidates, 2)
            if _exploration_rng.random() < 0.6:
                trial_cfg = _evolutionary_mutate(a, _exploration_rng)
            else:
                trial_cfg = _evolutionary_crossbreed(a, b, _exploration_rng)
            trial_source = trial_cfg.get('source', 'evolutionary')
        else:
            # Not enough candidates yet — fall to Layer 4
            trial_cfg    = _random_novel_config(_exploration_rng, V_ms)
            trial_source = 'random_layer4_fallback'
            layer        = 4

    elif layer == 4:
        trial_cfg    = _random_novel_config(_exploration_rng, V_ms)
        trial_source = 'random_layer4'

    if trial_cfg is None:
        return {'active': True, 'trial': False, 'layer': layer}

    # Final safety check
    safe, reason = _exploration_safety_ok(sensors, trial_cfg)
    if not safe:
        return {'active': True, 'trial': False, 'blocked': reason}

    # H-04 pterosaur needs extra height
    if trial_cfg.get('hypothesis') == 'H-04' and h < 30.0:
        return {'active': True, 'trial': False,
                'blocked': f'H-04 needs h>30m, have {h:.0f}m'}

    # Start trial
    st['trial_active']      = True
    st['trial_config']      = trial_cfg
    st['trial_source']      = trial_source
    st['trial_hypothesis']  = trial_hyp
    st['trial_start_t']     = now
    st['trial_Ps']          = []
    st['trial_Ps_baseline'] = Ps

    return {
        'active':     True,
        'trial':      True,
        'layer':      layer,
        'source':     trial_source,
        'hypothesis': trial_hyp,
        'rationale':  rationale,
    }


def exploration_status():
    """Print complete exploration system status."""
    st = _exploration_state
    print(f"\n  FOUR-LAYER EXPLORATION SYSTEM")
    print(f"  ================================")
    print(f"  Active: {st['active']}")
    print(f"  Scheduling: 80% Option B (convergence-gated) + "
          f"20% Option C (curiosity)")
