    print(f"  Cold lever positions: "
          f"{sum(1 for t in st['cold_tracker'].values() if _elt.monotonic()-t > EXPLORATION_CURIOSITY_COLD_S)}")
    print(f"\n  Convergence window: {EXPLORATION_CONVERGENCE_WINDOW_S}s")
    print(f"  Curiosity cold threshold: {EXPLORATION_CURIOSITY_COLD_S/60:.0f} min")
