# ══════════════════════════════════════════════════════════════════════════════
# MORPHING SPEED OPTIMIZER INTEGRATION
# Fixes three gaps so H-33/34/35 are fully explored:
#
#   1. BIOMIMETIC LOOP ADAPTER
#      The existing loop expects (fn, arg) tuples. H-33/34/35 variants are
#      plain dicts. This adapter makes dict variants callable by the loop.
#
#   2. SPEED_AND_GUST PHASE OBJECTIVE
#      Adds 'speed_and_gust' to PHASE_OBJECTIVES and adds its scoring branch
#      to phase_objective_score so the optimizer has a concrete fitness
#      value to maximise during morphing_speed discovery sessions.
#
#   3. MORPHING SPEED EXPLORATION SCHEDULER
#      A dedicated round-robin scheduler that guarantees every H-33/34/35
#      variant is tried at least once per discovery session before any
#      variant is repeated. Prevents the gradient layer from dominating
#      and burying the morphing hypotheses.
#
#   4. SPEED PERFORMANCE REGISTRY
#      Separate from the main knowledge registry. Records best pitot
#      airspeed achieved per configuration variant. Persists across flights.
#      The optimizer compares new trials against this baseline.
#
# ══════════════════════════════════════════════════════════════════════════════

import math  as _math
import time  as _time
import json  as _json
import os    as _os
import random as _random_mod

# ── 1. Biomimetic loop adapter for dict variants ─────────────────────────────

def _morphing_variant_to_config(variant_dict):
    """
    Convert an H-33/34/35 variant dict into an actionable wing config
    that the optimizer can apply via h33_engage / h34_engage / h35_engage.
    Returns a config dict with 'hypothesis', 'variant', and all parameters.
    """
    cfg = dict(variant_dict)
    hyp = cfg.get('hypothesis', 'H-33')

    if hyp == 'H-33':
        # Engage the stow/stop configuration
        cfg['_engage_fn'] = 'h33_engage'
        cfg['_engage_args'] = cfg

    elif hyp == 'H-34':
        # Engage dynamic sweep
        cfg['_engage_fn'] = 'h34_engage'
        cfg['_engage_args'] = {
            'variant_label':    cfg.get('variant'),
            'excursion_deg':    cfg.get('excursion_deg', 20.0),
            'dynamic_pairs':    cfg.get('dynamic_pairs', [1,2,3,4]),
            'stopped_adaptive': cfg.get('stopped_adaptive', False),
            'speed_gate_ms':    cfg.get('speed_gate_ms'),
            'h27_gated':        cfg.get('h27_gated', False),
        }

    elif hyp == 'H-35':
        # Engage thrust/lift separation
        cfg['_engage_fn'] = 'h35_engage'
        cfg['_engage_args'] = {
            'variant_label':  cfg.get('variant'),
            'lift_pairs':     cfg.get('lift_pairs', []),
            'thrust_pairs':   cfg.get('thrust_pairs', [1,2,3,4]),
            'stowed_pairs':   cfg.get('stowed_pairs', []),
            'lift_aoa_mode':  cfg.get('lift_aoa_mode', 'best_lift'),
            'thrust_aoa_deg': cfg.get('thrust_aoa_deg', 8.0),
            'speed_adaptive': cfg.get('speed_adaptive', False),
        }

    return cfg


def _apply_morphing_config(cfg):
    """
    Apply an H-33/34/35 config. Called by the optimizer exploration tick
    when it pulls a morphing variant from the scheduler.
    """
    hyp = cfg.get('hypothesis', 'H-33')
    try:
        if hyp == 'H-33':
            h33_engage(cfg)
        elif hyp == 'H-34':
            args = cfg.get('_engage_args', {})
            h34_engage(**args)
        elif hyp == 'H-35':
            args = cfg.get('_engage_args', {})
            h35_engage(**args)
    except Exception as e:
        print(f"  [morphing] Failed to apply {hyp} {cfg.get('variant')}: {e}")


# Patch the biomimetic loop to handle dict variants
_ORIGINAL_BIOMIMETIC_VARIANTS = {}

def _register_dict_variants_with_loop():
    """
    Wrap all H-33/34/35 dict variants into (callable, key) tuples
    so the existing biomimetic exploration loop can handle them.
    This patches BIOMIMETIC_HYPOTHESES in-place.
    """
    for hyp_id in ('H-33', 'H-34', 'H-35'):
        if hyp_id not in BIOMIMETIC_HYPOTHESES:
            continue
        raw = BIOMIMETIC_HYPOTHESES[hyp_id]
        wrapped = []
        for v in raw:
            if isinstance(v, dict):
                cfg = _morphing_variant_to_config(v)
                # Wrap as (callable, label) tuple the loop can call
                label = v.get('variant') or v.get('h33_variant') or f'{hyp_id}_v{i}'
                fn    = lambda c=cfg: c   # returns config dict when called
                wrapped.append((fn, label))
            else:
                wrapped.append(v)   # already a tuple, leave alone
        BIOMIMETIC_HYPOTHESES[hyp_id] = wrapped
    print("  Morphing variants patched into biomimetic exploration loop ✓")

_register_dict_variants_with_loop()


# ── 2. Speed-and-gust phase objective ────────────────────────────────────────

# Register 'speed_and_gust' as a first-class phase objective
PHASE_OBJECTIVES['morphing_cruise']  = ('speed_and_gust',
                                         'Maximise speed while maintaining gust tolerance')
PHASE_OBJECTIVES['morphing_sprint']  = ('speed_sprint',
                                         'Maximise pitot airspeed — sprint objective')
PHASE_OBJECTIVES['morphing_gust']    = ('gust_resilience_speed',
                                         'Gust rejection primary, speed secondary')


def morphing_speed_score(sensors, result):
    """
    Composite scoring function for morphing speed discovery.
    Called by phase_objective_score when phase == 'morphing_cruise' or sprint.

    PRIMARY:   pitot airspeed achieved (V_ms from msg.airspeed)
    SECONDARY: altitude stability (sigma_h)
    TERTIARY:  gust rejection (sigma_roll, imu_rms)
    PENALTY:   power consumption above efficient cruise baseline

    Returns (score, metric_label, detail_dict)
    Higher score is always better.
    """
    V_ms      = sensors.get('V_ms', 0.0)        # PITOT AIRSPEED
    imu_rms   = sensors.get('imu_rms_g', 0.05)
    roll_rate = abs(sensors.get('roll_rate_dps', 0.0))
    I_A       = sensors.get('motor_I_A', 0.0)
    batt_v    = sensors.get('bus_voltage_v', 14.8)
    sink      = abs(sensors.get('sink_rate_ms', 0.0))

    # Speed component — normalised to VNE
    # 0 at hover (2 m/s), 1.0 at VNE (28 m/s)
    V_floor   = VS_OGE_MS                        # stall speed (~4.85 m/s)
    V_target  = VNE_MS                           # 28 m/s
    v_score   = max(0.0, (V_ms - V_floor) / (V_target - V_floor))

    # Gust rejection — penalise roll disturbance
    # imu_rms of 0.01g = perfect, 0.10g = bad
    gust_score = max(0.0, 1.0 - (imu_rms / 0.10))
    roll_score = max(0.0, 1.0 - (roll_rate / 30.0))

    # Altitude stability — penalise sink
    alt_score  = max(0.0, 1.0 - (sink / 2.0))

    # Power efficiency — penalise excess current
    P_watts   = max(0.01, I_A * batt_v)
    # Efficient cruise ~30W, full power ~120W
    pwr_score = max(0.0, 1.0 - max(0.0, P_watts - 30.0) / 90.0)

    # H-35 lift surplus — bonus when stopped pairs exceed MTOW lift
    lift_surplus_bonus = 0.0
    if result.get('h35_active'):
        lift_N = result.get('h35_lift_N', 0.0)
        MTOW_N = MTOW_KG * 9.81
        if lift_N >= MTOW_N:
            # Thrust pairs fully freed from weight support — bonus
            lift_surplus_bonus = 0.10

    # Weighted composite
    score = (
        0.45 * v_score        +   # speed is the primary objective
        0.20 * gust_score     +   # gust tolerance
        0.15 * roll_score     +   # roll stability
        0.10 * alt_score      +   # altitude stability
        0.10 * pwr_score      +   # power efficiency
        lift_surplus_bonus        # H-35 bonus
    )

    detail = {
        'V_ms_pitot':    round(V_ms, 2),
        'v_score':       round(v_score, 3),
        'gust_score':    round(gust_score, 3),
        'roll_score':    round(roll_score, 3),
        'alt_score':     round(alt_score, 3),
        'pwr_score':     round(pwr_score, 3),
        'lift_surplus':  round(lift_surplus_bonus, 2),
        'total':         round(score, 4),
        'h33_active':    result.get('h33_active', False),
        'h34_active':    result.get('h34_active', False),
        'h35_active':    result.get('h35_active', False),
        'h35_lift_pairs':result.get('h35_lift_pairs', []),
        'h35_thrust_pairs':result.get('h35_thrust_pairs', []),
    }

    return score, 'speed_and_gust', detail


def sprint_score(sensors, result):
    """
    Pure sprint scoring — maximum pitot airspeed, everything else secondary.
    Used for sprint variants (H-35 v13, H-33 v14/v15).
    """
    V_ms     = sensors.get('V_ms', 0.0)   # PITOT AIRSPEED only
    sink     = abs(sensors.get('sink_rate_ms', 0.0))
    imu_rms  = sensors.get('imu_rms_g', 0.05)

    # Hard floor: must maintain level flight (sink < 1 m/s)
    if sink > 1.5:
        return -1.0, 'sprint', {'reason': 'altitude_loss', 'sink_ms': sink}

    v_score   = max(0.0, (V_ms - VS_OGE_MS) / (VNE_MS - VS_OGE_MS))
    stab_pen  = max(0.0, imu_rms / 0.15)
    score     = v_score * (1.0 - 0.20 * stab_pen)

    return score, 'sprint', {
        'V_ms_pitot': round(V_ms, 2),
        'v_score':    round(v_score, 3),
        'stab_pen':   round(stab_pen, 3),
        'total':      round(score, 4),
    }


# ── 3. Morphing exploration scheduler ────────────────────────────────────────

_MORPHING_SCHEDULER = {
    'queue':         [],      # ordered list of (hyp_id, variant_label, config)
    'tried_this_session': set(),
    'current_trial': None,
    'trial_start_t': None,
    'trial_duration_s': 45.0,    # seconds per trial at cruise speed
    'scores':        {},          # variant_label → best score
    'session_count': 0,
    'initialised':   False,
}


def _morphing_scheduler_init():
    """
    Build the ordered exploration queue for all H-33/34/35 variants.
    Ordering strategy:
      1. Safe TC-04 variants first (State B, stopped neutral, single lift wing)
      2. Single-pair stow variants
      3. Two-pair stow / full separation variants
      4. Sprint and composition variants last
    This ensures the optimizer builds knowledge progressively from safe
    to aggressive rather than randomly encountering sprint variants early.
    """
    scheduler = _MORPHING_SCHEDULER
    queue     = []

    priority_order = {
        # H-35 entry variants — safe, three thrust pairs
        'v05_one_lift_W2': 1,
        'v06_one_lift_W3': 1,
        'v07_speed_adaptive_roles': 1,
        # H-34 conservative — 20° excursion
        'v01_dynamic_20deg_all': 1,
        'v04_dynamic_front_only': 1,
        'v05_dynamic_rear_only': 1,
        'v09_stopped_speed_stepped': 1,
        'v10_stopped_continuous_track': 1,
        # H-33 State B (stopped neutral — still generates lift)
        'v09_stop_W1_neutral': 1,
        'v10_stop_W4_neutral': 1,
        'v11_stop_W1W4_neutral': 2,
        # H-35 two-pair separation
        'v01_mid_lift_end_thrust': 2,
        'v02_end_lift_mid_thrust': 2,
        'v03_front_lift_rear_thrust': 2,
        'v04_rear_lift_front_thrust': 2,
        'v09_lift_best_LD': 2,
        'v10_lift_scheduled_aoa': 2,
        'v11_thrust_aggressive_5deg': 2,
        'v12_thrust_moderate_8deg': 2,
        # H-33 single-pair stow
        'v01_stow_W1': 2,
        'v02_stow_W4': 2,
        'v03_stow_W2': 2,
        'v04_stow_W3': 2,
        # H-34 moderate excursion + combined
        'v02_dynamic_30deg_all': 2,
        'v07_cascade_phase_offset': 2,
        'v08_speed_scaled_excursion': 2,
        'v12_combined_dynamic_plus_adaptive': 2,
        'v14_speed_gated_above_5ms': 2,
        'v15_gust_triggered_sweep': 2,
        # H-33 speed variants and two-pair stow
        'v05_stow_W1W4_ends': 3,
        'v06_stow_W2W3_mids': 3,
        'v07_stow_W1W2_front': 3,
        'v08_stow_W3W4_rear': 3,
        'v12_stow_W1_speed': 3,
        'v13_stow_W4_speed': 3,
        # H-35 adaptive + sprint
        'v08_speed_adaptive_with_stow': 3,
        # H-34 + H-33 composition
        'v13_dynamic_plus_stowed_aft': 3,
        # Sprint and maximum speed variants
        'v14_stow_W1W4_maxspeed': 4,
        'v15_stow_W2W3_maxspeed': 4,
        'v13_sprint_2lift_1thrust_1stow': 4,
        'v16_adaptive_stow_W4_6ms': 3,
        'v17_adaptive_stow_W1W4_9ms': 4,
        'v18_gust_adaptive_auto_stow': 3,
        # Full composition variants — last
        'v16_full_morphing_composite': 4,
        'v14_full_composition': 4,
    }

    # Build queue in priority order
    for priority in [1, 2, 3, 4]:
        for hyp_id in ('H-33', 'H-34', 'H-35'):
            variants = BIOMIMETIC_HYPOTHESES.get(hyp_id, [])
            for item in variants:
                # Item is now a (fn, label) tuple after patching
                if isinstance(item, tuple):
                    fn, label = item[0], item[1]
                    p = priority_order.get(label, 3)
                    if p == priority:
                        cfg = fn() if callable(fn) else fn
                        queue.append({
                            'hyp_id':   hyp_id,
                            'label':    label,
                            'config':   cfg,
                            'priority': priority,
                        })

    scheduler['queue']       = queue
    scheduler['initialised'] = True
    scheduler['session_count'] += 1
    scheduler['tried_this_session'] = set()
    print(f"  Morphing scheduler: {len(queue)} variants queued "
          f"({sum(1 for q in queue if q['priority']==1)} safe-first, "
          f"{sum(1 for q in queue if q['priority']==4)} sprint-last)")


def morphing_next_trial(V_ms):
    """
    Return the next morphing trial config to attempt.
    Called by the optimizer when morphing_speed discovery is active.
    V_ms = current pitot airspeed.

    Returns (config, hyp_id, label) or None if queue exhausted.
    Respects TC gate: State C variants skipped below 6 m/s pitot.
    H-27-gated variants skipped until H-27 is complete.
    """
    scheduler = _MORPHING_SCHEDULER
    if not scheduler['initialised']:
        _morphing_scheduler_init()

    tried = scheduler['tried_this_session']
    h27_done = _H35_H27_COMPLETE   # set True after TC-01 step 09 (servo bandwidth)

    for item in scheduler['queue']:
        label = item['label']
        if label in tried:
            continue

        cfg = item['config']

        # Speed gate for State C stow variants — need enough airspeed
        n_stowed = (cfg.get('h33_n_stowed', 0) or
                    len(cfg.get('stowed_pairs', [])))
        if n_stowed >= 2 and V_ms < 6.0:
            continue   # not fast enough yet for multi-pair stow

        # H-27 gate for large-excursion sweep variants
        if cfg.get('h27_gated') and not h27_done:
            continue

        tried.add(label)
        scheduler['current_trial'] = item
        scheduler['trial_start_t'] = _time.monotonic()
        return cfg, item['hyp_id'], label

    # All variants tried — start new session
    print("  Morphing scheduler: all variants tried — starting new session")
    _morphing_scheduler_init()
    return None, None, None


def morphing_record_score(label, score, V_ms, detail):
    """
    Record the score for a completed morphing trial.
    Updates the speed performance registry.
    V_ms = pitot airspeed at which score was achieved.
    """
    scheduler = _MORPHING_SCHEDULER
    prev_best = scheduler['scores'].get(label, {}).get('score', -999)

    if score > prev_best:
        scheduler['scores'][label] = {
            'score':  round(score, 4),
            'V_ms':   round(V_ms, 2),
            'detail': detail,
        }
        print(f"  [morphing] NEW BEST: {label}  "
              f"score={score:.3f}  V={V_ms:.1f}m/s pitot")

    # Persist to knowledge registry
    _persist_morphing_scores()


def _persist_morphing_scores():
    """Save morphing speed registry to knowledge file."""
    path = '/home/pi/knowledge/morphing_speed_registry.json'
    try:
        _os.makedirs(_os.path.dirname(path), exist_ok=True)
        with open(path, 'w') as f:
            _json.dump({
                'scores':        _MORPHING_SCHEDULER['scores'],
                'session_count': _MORPHING_SCHEDULER['session_count'],
                'saved_at':      _time.strftime('%Y-%m-%dT%H:%M:%S'),
            }, f, indent=2)
    except Exception as e:
        print(f"  [morphing] Registry save failed: {e}")


def morphing_speed_report():
    """
    Print the full morphing speed leaderboard.
    Shows all variants sorted by best pitot airspeed achieved.
    """
    scores = _MORPHING_SCHEDULER['scores']
    if not scores:
        print("  No morphing speed data yet — run morphing_speed_start")
        return

    ranked = sorted(scores.items(),
                    key=lambda kv: kv[1].get('V_ms', 0), reverse=True)

    print(f"\n  MORPHING SPEED LEADERBOARD (pitot airspeed)")
    print(f"  {'Rank':<5} {'Variant':<40} {'V_ms':>7} {'Score':>7}")
    print(f"  {'─'*65}")
    for rank, (label, data) in enumerate(ranked, 1):
        V    = data.get('V_ms', 0)
        s    = data.get('score', 0)
        flag = ' ← BEST' if rank == 1 else ''
        print(f"  {rank:<5} {label:<40} {V:>6.1f}m {s:>7.3f}{flag}")

    # Summary
    if ranked:
        best_label, best_data = ranked[0]
        print(f"\n  Best configuration: {best_label}")
        print(f"  Best pitot airspeed: {best_data['V_ms']:.1f} m/s")
        d = best_data.get('detail', {})
        print(f"  H-33 active: {d.get('h33_active', '?')}")
        print(f"  H-34 active: {d.get('h34_active', '?')}")
        print(f"  H-35 active: {d.get('h35_active', '?')}")
        if d.get('h35_lift_pairs'):
            print(f"  Lift wings:  W{d['h35_lift_pairs']}")
            print(f"  Thrust wings:W{d['h35_thrust_pairs']}")


# ── 4. Wire into optimizer exploration tick ──────────────────────────────────

def morphing_exploration_tick(sensors, result):
    """
    Called every tick when morphing_speed discovery is active.
    Manages trial lifecycle:
      - Start a new trial when previous one completes
      - Score the completed trial
      - Apply next configuration
      - Record results

    Integrates with existing exploration_tick framework.
    """
    scheduler = _MORPHING_SCHEDULER
    V_ms      = sensors.get('V_ms', 0.0)   # PITOT AIRSPEED

    # Check if current trial has run long enough
    if scheduler['trial_start_t'] is not None:
        elapsed = _time.monotonic() - scheduler['trial_start_t']
        if elapsed < scheduler['trial_duration_s']:
            # Still running — score accumulation handled by phase_objective_score
            return result

        # Trial complete — score it
        item  = scheduler.get('current_trial')
        if item:
            score, metric, detail = morphing_speed_score(sensors, result)
            morphing_record_score(item['label'], score, V_ms, detail)

        # Disengage current morphing config
        if _h33_state['active']:    h33_disengage()
        if _h34_state['active']:    h34_disengage()
        if _h35_state['active']:    h35_disengage()

    # Get next trial
    cfg, hyp_id, label = morphing_next_trial(V_ms)
    if cfg is None:
        return result   # queue exhausted — scheduler resets

    # Apply the configuration
    _apply_morphing_config(cfg)

    return result


