# Loiter and ferry scoring functions
def h36_loiter_score(sensors, result):
    """Score for SAR loiter: maximum endurance × stability."""
    if not result.get('h36_active'):
        return 0.0, 'h36_loiter', {}
    P_W      = result.get('h36_power_W', 60.0)
    sigma_h  = abs(sensors.get('sink_rate_ms', 0.0))
    roll_rms = abs(sensors.get('roll_rate_dps', 0.0))
    # Endurance score: inversely proportional to power (lower power = higher score)
    # Normalise: 60W = 0.0, 10W = 1.0
    P_score  = max(0.0, (60.0 - P_W) / 50.0)
    # Stability (must stay airborne for endurance to mean anything)
    stab     = max(0.0, 1.0 - sigma_h / 1.0) * max(0.0, 1.0 - roll_rms / 15.0)
    score    = 0.70 * P_score + 0.30 * stab
    return score, 'h36_loiter', {
        'P_W': round(P_W,1), 'P_score': round(P_score,3),
        'stab': round(stab,3), 'total': round(score,4),
        'endurance_est_min': result.get('h36_endurance_est_min',0),
        'V_ms_pitot': result.get('h36_V_ms_pitot',0),
    }


def h36_ferry_score(sensors, result):
    """Score for ferry: maximum km per Wh (pitot airspeed based)."""
    if not result.get('h36_active'):
        return 0.0, 'h36_ferry', {}
    range_km_Wh = result.get('h36_range_km_Wh', 0.0)
    sink        = abs(sensors.get('sink_rate_ms', 0.0))
    # Ferry fails if not maintaining altitude
    if sink > 1.0:
        return -1.0, 'h36_ferry', {'reason': 'altitude_loss', 'sink_ms': sink}
    # Normalise: 0.1 km/Wh = poor, 0.5 km/Wh = excellent
    score = min(1.0, range_km_Wh / 0.5)
    return score, 'h36_ferry', {
        'range_km_Wh': round(range_km_Wh,3),
        'score': round(score,3),
        'V_ms_pitot': result.get('h36_V_ms_pitot',0),
        'power_W': result.get('h36_power_W',0),
    }


