# ── Hypothesis seeder interface ────────────────────────────────────────────────

_hypothesis_queue = []   # ordered list of configs to try before random search
_hypothesis_results = {} # id → {'Ps': float, 'V_ms': float, 'promoted': bool}


def seed_hypotheses(V_ms=9.0, targets=None):
    """
    Inject aerodynamic hypotheses into the discovery queue.
    Called automatically when discovery mode is enabled, or manually
    to pre-load specific performance targets.

    Parameters
    ----------
    V_ms    : float — current airspeed (filters to applicable hypotheses)
    targets : list of str | None — if given, only seed these targets.
              e.g. ['efficiency', 'top_speed']
              Valid: 'efficiency', 'top_speed', 'cruise', 'range',
                     'maneuverability', 'acceleration'

    Returns
    -------
    int — number of hypotheses seeded
    """
    global _hypothesis_queue
    _hypothesis_queue = []

    applicable = [h for h in AERO_HYPOTHESES
                  if h['v_min'] <= V_ms <= h['v_max']]
    if targets:
        applicable = [h for h in applicable if h['target'] in targets]

    # Sort by priority (1 first), then by target for grouping
    applicable.sort(key=lambda h: (h['priority'], h['target']))

    for h in applicable:
        _hypothesis_queue.append({
            'id':     h['id'],
            'label':  h['label'],
            'target': h['target'],
            'config': dict(h['config']),
        })

    print(f"\n  HYPOTHESIS SEEDER: {len(_hypothesis_queue)} hypotheses loaded")
    print(f"  Airspeed: {V_ms:.1f} m/s  "
          f"Targets: {targets or 'all'}")
    print(f"  Evaluation order:")
    for i, h in enumerate(_hypothesis_queue[:8]):
        print(f"    {i+1:2d}. [{h['id']}] {h['label'][:55]}")
    if len(_hypothesis_queue) > 8:
        print(f"    ... and {len(_hypothesis_queue)-8} more")
    print(f"\n  Each hypothesis will be held for {DISCOVERY_DWELL_S:.0f}s "
          f"before Ps evaluation.")
    print(f"  Results stored in hypothesis_results()")

    return len(_hypothesis_queue)


def hypothesis_next():
    """
    Pop the next hypothesis from the queue.
    Called by discovery_tick when a hypothesis queue is available.
    Returns None if queue is empty (switches to random search).
    """
    if not _hypothesis_queue:
        return None
    return _hypothesis_queue.pop(0)


def hypothesis_record(h_id, Ps, V_ms, promoted):
    """Record result of a hypothesis evaluation."""
    _hypothesis_results[h_id] = {
        'Ps':       round(Ps, 4),
        'V_ms':     round(V_ms, 1),
        'promoted': promoted,
    }


def hypothesis_results():
    """Ground station: print hypothesis evaluation results."""
    if not _hypothesis_results:
        print("  No hypotheses evaluated yet.")
        return
    print(f"\n  HYPOTHESIS EVALUATION RESULTS ({len(_hypothesis_results)} completed)")
    print(f"  {'Ref':<8} {'Target':<16} {'Ps (m/s²)':<12} {'V m/s':<8} {'Status'}")
    print(f"  {'─'*60}")
    # Match results to hypotheses for label lookup
    h_map = {h['id']: h for h in AERO_HYPOTHESES}
    for h_id, res in sorted(_hypothesis_results.items()):
        h = h_map.get(h_id, {})
        status = '✓ PROMOTED' if res['promoted'] else '  discarded'
        print(f"  {h_id:<8} {h.get('target','?'):<16} "
              f"{res['Ps']:>+8.4f}     "
              f"{res['V_ms']:>5.1f}   {status}")

    # Group by target
    from collections import defaultdict
    by_target = defaultdict(list)
    for h_id, res in _hypothesis_results.items():
        h = h_map.get(h_id, {})
        by_target[h.get('target','?')].append(res['Ps'])

    print(f"\n  BY PERFORMANCE TARGET:")
    for target, ps_list in sorted(by_target.items()):
        best = max(ps_list)
        avg  = sum(ps_list)/len(ps_list)
        print(f"    {target:<18} best Ps={best:+.4f}  "
              f"avg={avg:+.4f}  n={len(ps_list)}")


def hypothesis_status():
    """Ground station: show queue and results summary."""
    print(f"\n  AERODYNAMIC HYPOTHESIS SEEDER")
    print(f"  ─────────────────────────────────────────")
    print(f"  Total hypotheses: {len(AERO_HYPOTHESES)}")
    print(f"  Queue remaining:  {len(_hypothesis_queue)}")
    print(f"  Evaluated so far: {len(_hypothesis_results)}")
    print(f"  Promoted:         "
          f"{sum(1 for r in _hypothesis_results.values() if r['promoted'])}")
    if _hypothesis_queue:
        print(f"\n  Next up:")
        for h in _hypothesis_queue[:3]:
            print(f"    [{h['id']}] {h['label'][:55]}")
    print(f"\n  GS: hypothesis_results — see full evaluation table")
    print(f"  GS: seed_hypotheses — reload queue at current airspeed")


def hypothesis_strouhal_targets(V_ms):
    """
    Show Strouhal-optimal parameters for the current airspeed.
    Useful for manual tuning reference.
    """
    print(f"\n  STROUHAL NUMBER REFERENCE @ V={V_ms:.1f} m/s")
    print(f"  ─────────────────────────────────────────")
    print(f"  Tip excursion (W1, 96° stroke): {_HS_STROKE_AMP_M:.3f} m")
    for St in [0.20, 0.25, 0.27, 0.30, 0.35]:
        f_opt = _hs_st_freq(V_ms, St)
        f_ok  = f_opt <= FREQ_LIMIT_MAX_HZ
        print(f"    St={St:.2f} → f_optimal = {f_opt:.2f} Hz "
              f"{'✓ achievable' if f_ok else '✗ exceeds 3.0 Hz limit'}")
    f_current = HOVER_FREQ_HZ if V_ms < 3.0 else V_ms * 0.118
    St_current = _HS_STROKE_AMP_M * f_current / V_ms if V_ms > 0 else 0
    print(f"\n  Current operating freq ≈ {f_current:.2f} Hz → "
          f"St ≈ {St_current:.2f}")
    if St_current > 0.40:
        print(f"  ⚠ Above optimal range — consider reducing frequency for cruise")
    elif St_current < 0.20:
        print(f"  ⚠ Below optimal range — consider increasing frequency or amplitude")
    else:
        print(f"  ✓ Within efficient Strouhal range")


# ── Wire seed_hypotheses into discovery_enable ─────────────────────────────────
# Patch: call seed_hypotheses when discovery is enabled so the queue
# is always pre-loaded at the right airspeed.


def discovery_enable(current_h_agl_m, mode='normal'):
    """Enable discovery mode and pre-load aerodynamic hypothesis queue."""
    result = None
    if result.get('enabled'):
        # Seed with current airspeed — V_ms not available here so use 9.0 m/s
        # as a representative cruise start. The tick will re-filter as speed changes.
        seed_hypotheses(V_ms=9.0)
        # Add hypothesis queue check into discovery state
        _discovery_state['_hyp_queue_active'] = True
    return result


# ── Wire hypothesis_next into discovery_tick ───────────────────────────────────
# Patch discovery_tick to check hypothesis queue before random config.


def discovery_tick(Ps_measured, V_ms, h_agl_m, bank_deg,
                    stall_risk, current_time_s):
    """
    Extended discovery_tick that evaluates hypothesis queue first,
    then falls through to random coordinate-descent search.
    """
    # If hypothesis queue is active and a dwell just completed,
    # check if we should record the result and advance the queue.
    st = _discovery_state

    # Check if current config is a hypothesis
    cur_cfg = st.get('current_config')
    if (cur_cfg and '_hyp_id' in cur_cfg and
            st.get('dwell_start_s') is not None):
        elapsed = current_time_s - st['dwell_start_s']
        if elapsed >= DISCOVERY_DWELL_S:
            # Dwell complete — record and advance
            h_id = cur_cfg['_hyp_id']
            promoted = Ps_measured > st.get('best_Ps', -99.0)
            hypothesis_record(h_id, Ps_measured, V_ms, promoted)

    # Try hypothesis queue first
    if (_discovery_state.get('_hyp_queue_active') and
            _hypothesis_queue and
            st.get('dwell_start_s') is None):
        next_h = hypothesis_next()
        if next_h:
            cfg = dict(next_h['config'])
            cfg['_hyp_id'] = next_h['id']
            st['current_config'] = cfg
            st['dwell_start_s']  = current_time_s
            if mode := st.get('_mode', 'normal'):
                pass  # mode already set
            return cfg

    # Fall through to original random discovery
    return None


# Register GS commands
_GS_ALLOWED_CMDS.update({
    'seed_hypotheses',
    'hypothesis_results',
    'hypothesis_status',
    'hypothesis_strouhal_targets',
})


# ══════════════════════════════════════════════════════════════════════════════
# PERSISTENT LEARNING REGISTRY
# Cross-flight, cross-session, cross-lifetime knowledge persistence
# ══════════════════════════════════════════════════════════════════════════════
#
# PHILOSOPHY
# ──────────
# Every flight teaches the aircraft something. Without persistence,
# every power cycle wipes that learning and the aircraft begins again
# from scratch. This system ensures nothing is ever lost:
#
#   WHAT IS SAVED (after every flight, on shutdown):
#     1. Mechanism weights (roll/pitch/yaw) — optimizer's learned rankings
#     2. Loop 5 yaw modality weights — per (V_bin, bank_bin, intent)
#     3. Discovery state — all promoted configurations with their Ps scores
#     4. Hypothesis evaluation results — which of the 17 worked and how well
#     5. Strouhal operating point history — speed vs achieved St per flight
#     6. Target rate schedule — learned optimal °/s per axis from HQ analyser
#     7. Flight counter and cumulative statistics
#
#   WHAT IS LOADED (at startup, before first tick):
#     All of the above, in order. If any file is missing, the system
#     starts fresh for that component without error. On the first ever
#     flight, everything starts at defaults. By the tenth flight, the
#     aircraft is operating from a richly informed starting point.
#
#   HOW LEARNING COMPOUNDS
#     After each flight, the HQ analyser nudges mechanism weights.
#     Those weights are saved. Next flight starts with those weights,
#     so the HQ nudges in the next flight are starting from a better
#     point. Over many flights, the system converges.
#
#     Similarly, the hypothesis seeder re-evaluates at the start of
#     each discovery session, but it also loads the results from
#     previous sessions. If H-PH-2 was promoted on flight 7 and
#     became the best Ps at 9 m/s, flight 8 starts with that as
#     the initial config rather than repeating the 20-second dwell.
#
#   KNOWLEDGE FILES (all in /home/pi/knowledge/)
#     mechanism_weights.json    — MW_ROLL, MW_PITCH, MW_YAW, H26 class
#     l5_learned.json           — L5 yaw modality per flight condition
#     discovery_promoted.json   — all promoted discovery configs with Ps
#     hypothesis_outcomes.json  — H-ST-1 through H-MV-4 results
#     strouhal_log.json         — St vs V_ms per flight
#     target_rates.json         — learned optimal °/s per axis
#     flight_summary.json       — cumulative flight counter and stats
#     learning_log.jsonl        — append-only record of every improvement
#
#   INTEGRITY
#     Every save is atomic: write to .tmp, then rename. A power failure
#     during save leaves the previous version intact.
#     Every load validates the schema version before applying values.
#     A corrupt file is skipped with a warning — the system continues
#     on defaults and overwrites on next shutdown.
#
# ══════════════════════════════════════════════════════════════════════════════

import json   as _plj
import os     as _plo
import time   as _plt
import shutil as _pls

_PL_DIR      = '/home/pi/knowledge'
_PL_VERSION  = 3    # bump when schema changes; old files are skipped

# ── Atomic write helper ────────────────────────────────────────────────────────

def _pl_write(path, data):
    """Atomically write JSON to path (write tmp → rename)."""
    _plo.makedirs(_plo.path.dirname(path), exist_ok=True)
    tmp = path + '.tmp'
    try:
        with open(tmp, 'w') as f:
            _plj.dump(data, f, indent=2, default=str)
        _pls.move(tmp, path)
        return True
    except Exception as e:
        print(f"  [persist] write failed {path}: {e}")
        return False


def _pl_read(path, default=None):
    """Read JSON from path, return default on any error."""
    try:
        with open(path) as f:
            data = _plj.load(f)
        if isinstance(data, dict) and data.get('_version', 0) != _PL_VERSION:
            print(f"  [persist] schema version mismatch {path} — skipping")
            return default
        return data
    except FileNotFoundError:
        return default
    except Exception as e:
        print(f"  [persist] read failed {path}: {e}")
        return default


def _pl_append_log(entry):
    """Append one JSON line to the learning log (append-only record)."""
    path = f'{_PL_DIR}/learning_log.jsonl'
    _plo.makedirs(_PL_DIR, exist_ok=True)
    try:
        with open(path, 'a') as f:
            f.write(_plj.dumps({**entry,
                                 'ts': _plt.strftime('%Y-%m-%dT%H:%M:%S')},
                                default=str) + '\n')
    except Exception:
        pass


# ══════════════════════════════════════════════════════════════════════════════
# SAVE — called from _shutdown() after every flight
# ══════════════════════════════════════════════════════════════════════════════

def persist_save_all(flight_number=None, V_cruise=None, notes=''):
    """
    Save all learned state to disk.
    Called from _shutdown() after every flight.
    Also callable from GS during flight for mid-session checkpoint.

    Parameters
    ----------
    flight_number : int | None — if None, auto-increments
    V_cruise      : float | None — representative cruise speed this flight
    notes         : str — freetext note for the learning log
    """
    saved = []
    ts = _plt.strftime('%Y-%m-%dT%H:%M:%S')

    # ── 1. Mechanism weights ───────────────────────────────────────────────
    mw_path = f'{_PL_DIR}/mechanism_weights.json'
    mw_data = {
        '_version': _PL_VERSION,
        'saved_at': ts,
        'roll':  dict(_MW_ROLL),
        'pitch': dict(_MW_PITCH),
        'yaw':   dict(_MW_YAW),
        'h26':   _H26_CLASSIFICATION,
        'target_rates': dict(_TARGET_RATES),
    }
    if _pl_write(mw_path, mw_data):
        saved.append('mechanism_weights')

    # ── 2. Loop 5 yaw modality weights ────────────────────────────────────
    l5_path = f'{_PL_DIR}/l5_learned.json'
    l5_data = {
        '_version':   _PL_VERSION,
        'saved_at':   ts,
        'n_updates':  _L5_state['n_updates'],
        'learned':    {str(k): v for k, v in _L5_state['learned'].items()},
        'w_crab':     L5_W_CRAB,
        'w_dart':     L5_W_DART,
        'w_split':    L5_W_SPLIT,
        'w_proverse': L5_W_PROVERSE,
    }
    if _pl_write(l5_path, l5_data):
        saved.append('l5_learned')

    # ── 3. Discovery promoted configurations ──────────────────────────────
    disc_path = f'{_PL_DIR}/discovery_promoted.json'
    # Include both _discovery_state discoveries and locked gaits
    all_disc = (list(_discovery_state.get('discoveries', [])) +
                list(_discovery_state.get('locked_gaits', [])))
    disc_data = {
        '_version':       _PL_VERSION,
        'saved_at':       ts,
        'n_configs_tried':_discovery_state['n_configs_tried'],
        'best_Ps':        _discovery_state['best_Ps'],
        'best_config':    _discovery_state.get('best_config'),
        'discoveries':    all_disc,
        'locked_gaits':   list(_discovery_state.get('locked_gaits', [])),
    }
    if _pl_write(disc_path, disc_data):
        saved.append('discovery_promoted')

    # ── 4. Hypothesis evaluation results ──────────────────────────────────
    hyp_path = f'{_PL_DIR}/hypothesis_outcomes.json'
    # Merge new results into any previously saved results
    prev_hyp = _pl_read(hyp_path, {'_version': _PL_VERSION,
                                    'outcomes': {}})
    merged = dict(prev_hyp.get('outcomes', {}))
    merged.update(_hypothesis_results)   # new results overwrite old
    hyp_data = {
        '_version':      _PL_VERSION,
        'saved_at':      ts,
        'total_flights': (prev_hyp.get('total_flights', 0) + 1),
        'outcomes':      merged,
    }
    if _pl_write(hyp_path, hyp_data):
        saved.append('hypothesis_outcomes')

    # ── 5. Strouhal operating point log ───────────────────────────────────
    st_path = f'{_PL_DIR}/strouhal_log.json'
    prev_st = _pl_read(st_path, {'_version': _PL_VERSION, 'log': []})
    if V_cruise and V_cruise > 2.0:
        # Compute achieved Strouhal from current freq (at shutdown lever)
        f_now = getattr(w_globals_ref, 'HOVER_FREQ_HZ', 1.87) if False else 1.87
        St_now = _HS_STROKE_AMP_M * f_now / V_cruise if V_cruise > 0 else 0
        new_entry = {'ts': ts, 'V_ms': V_cruise,
                      'freq_hz': f_now, 'St': round(St_now, 3)}
        prev_st['log'].append(new_entry)
        prev_st['log'] = prev_st['log'][-200:]  # keep last 200 entries
        prev_st['saved_at'] = ts
        if _pl_write(st_path, prev_st):
            saved.append('strouhal_log')

    # ── 6. Target rate schedule ───────────────────────────────────────────
    tr_path = f'{_PL_DIR}/target_rates.json'
    tr_data = {
        '_version': _PL_VERSION,
        'saved_at': ts,
        'rates':    dict(_TARGET_RATES),
    }
    if _pl_write(tr_path, tr_data):
        saved.append('target_rates')

    # ── 7. Flight summary / counter ───────────────────────────────────────
    fs_path = f'{_PL_DIR}/flight_summary.json'
    prev_fs = _pl_read(fs_path, {'_version': _PL_VERSION,
                                   'flights': 0, 'history': []})
    flight_n = (flight_number or prev_fs.get('flights', 0) + 1)
    prev_fs['flights'] = flight_n
    prev_fs['last_flight'] = ts
    prev_fs['last_best_Ps'] = _discovery_state['best_Ps']
    prev_fs['last_V_cruise'] = V_cruise
    prev_fs['history'].append({
        'flight': flight_n,
        'ts':     ts,
        'best_Ps': _discovery_state['best_Ps'],
        'n_disc': len(_discovery_state.get('discoveries', [])),
        'mw_roll_top': max(_MW_ROLL, key=_MW_ROLL.get),
        'mw_pitch_top': max(_MW_PITCH, key=_MW_PITCH.get),
    })
    prev_fs['history'] = prev_fs['history'][-100:]  # keep last 100
    prev_fs['_version'] = _PL_VERSION
    prev_fs['saved_at'] = ts
    if _pl_write(fs_path, prev_fs):
        saved.append('flight_summary')

    # ── 8. Append to learning log ──────────────────────────────────────────
    n_promoted = sum(1 for r in _hypothesis_results.values()
                     if r.get('promoted'))
    _pl_append_log({
        'event':      'flight_end',
        'flight_n':   flight_n,
        'notes':      notes,
        'saved':      saved,
        'best_Ps':    _discovery_state['best_Ps'],
        'n_promoted': n_promoted,
        'mw_roll':    dict(_MW_ROLL),
        'mw_pitch':   dict(_MW_PITCH),
        'mw_yaw':     dict(_MW_YAW),
    })

    print(f"\n  LEARNING PERSISTED (flight {flight_n})")
    print(f"  Saved: {', '.join(saved)}")
    print(f"  Best Ps: {_discovery_state['best_Ps']:.4f}")
    print(f"  Top roll mechanism:  {max(_MW_ROLL, key=_MW_ROLL.get)}")
    print(f"  Top pitch mechanism: {max(_MW_PITCH, key=_MW_PITCH.get)}")
    print(f"  Top yaw mechanism:   {max(_MW_YAW, key=_MW_YAW.get)}")
    print(f"  Hypothesis promotions this flight: {n_promoted}")
    return saved


# ══════════════════════════════════════════════════════════════════════════════
# LOAD — called at startup before first tick
# ══════════════════════════════════════════════════════════════════════════════

def persist_load_all(verbose=True):
    """
    Load all persisted learning state at startup.
    Called from mco_main.py immediately after importing the wave library.
    Safe to call on first flight — all files missing = silent defaults.

    Returns dict of what was loaded.
    """
    loaded = []

    # ── 1. Mechanism weights ───────────────────────────────────────────────
    mw_path = f'{_PL_DIR}/mechanism_weights.json'
    mw = _pl_read(mw_path)
    if mw:
        for k, v in mw.get('roll', {}).items():
            if k in _MW_ROLL: _MW_ROLL[k] = float(v)
        for k, v in mw.get('pitch', {}).items():
            if k in _MW_PITCH: _MW_PITCH[k] = float(v)
        for k, v in mw.get('yaw', {}).items():
            if k in _MW_YAW: _MW_YAW[k] = float(v)
        # Restore target rates
        for k, v in mw.get('target_rates', {}).items():
            if k in _TARGET_RATES: _TARGET_RATES[k] = float(v)
        # H26 classification
        h26 = mw.get('h26')
        if h26 and h26 != 'UNKNOWN':
            try: set_h26_classification(h26)
            except Exception: pass
        loaded.append('mechanism_weights')

    # ── 2. Loop 5 yaw modality ─────────────────────────────────────────────
    l5_path = f'{_PL_DIR}/l5_learned.json'
    l5 = _pl_read(l5_path)
    if l5:
        global L5_W_CRAB, L5_W_DART, L5_W_SPLIT, L5_W_PROVERSE
        L5_W_CRAB     = float(l5.get('w_crab',     L5_W_CRAB))
        L5_W_DART     = float(l5.get('w_dart',     L5_W_DART))
        L5_W_SPLIT    = float(l5.get('w_split',    L5_W_SPLIT))
        L5_W_PROVERSE = float(l5.get('w_proverse', L5_W_PROVERSE))
        _L5_state['n_updates'] = l5.get('n_updates', 0)
        # Restore per-condition learned weights
        for key_str, val in l5.get('learned', {}).items():
            try:
                key = tuple(_plj.loads(key_str.replace('(','[')
                                                .replace(')',']')
                                                .replace("'",'"')))
                _L5_state['learned'][key] = val
            except Exception:
                pass
        loaded.append('l5_learned')

    # ── 3. Discovery promoted configurations ──────────────────────────────
    disc_path = f'{_PL_DIR}/discovery_promoted.json'
    disc = _pl_read(disc_path)
    if disc:
        _discovery_state['discoveries']  = disc.get('discoveries', [])
        _discovery_state['locked_gaits'] = disc.get('locked_gaits', [])
        # Restore best config and best Ps
        best_cfg = disc.get('best_config')
        best_ps  = disc.get('best_Ps', -99.0)
        if best_ps > _discovery_state['best_Ps']:
            _discovery_state['best_Ps'] = best_ps
        if best_cfg is not None:
            _discovery_state['best_config'] = best_cfg
        _discovery_state['n_configs_tried'] = disc.get('n_configs_tried', 0)
        loaded.append('discovery_promoted')

    # ── 4. Hypothesis evaluation results ──────────────────────────────────
    hyp_path = f'{_PL_DIR}/hypothesis_outcomes.json'
    hyp = _pl_read(hyp_path)
    if hyp:
        _hypothesis_results.update(hyp.get('outcomes', {}))
        loaded.append('hypothesis_outcomes')

    # ── 5. Target rates ────────────────────────────────────────────────────
    tr_path = f'{_PL_DIR}/target_rates.json'
    tr = _pl_read(tr_path)
    if tr:
        for k, v in tr.get('rates', {}).items():
            if k in _TARGET_RATES:
                _TARGET_RATES[k] = float(v)
        if 'target_rates' not in loaded:
            loaded.append('target_rates')

    # ── 6. Flight summary ──────────────────────────────────────────────────
    fs_path = f'{_PL_DIR}/flight_summary.json'
    fs = _pl_read(fs_path)
    flight_n = fs.get('flights', 0) if fs else 0

    if verbose:
        print(f"\n  LEARNING RESTORED (flight #{flight_n + 1})")
        if loaded:
            print(f"  Loaded: {', '.join(loaded)}")
            print(f"  Mechanism weights: roll top = "
                  f"{max(_MW_ROLL, key=_MW_ROLL.get)}, "
                  f"pitch top = {max(_MW_PITCH, key=_MW_PITCH.get)}")
            print(f"  L5 yaw: crab={L5_W_CRAB:.2f} dart={L5_W_DART:.2f} "
                  f"split={L5_W_SPLIT:.2f}")
            print(f"  Discoveries loaded: {len(_discovery_state.get('discoveries',[]))}")
            n_hyp = sum(1 for r in _hypothesis_results.values()
                        if r.get('promoted'))
            print(f"  Hypothesis promotions carried: {n_hyp}")
            if _discovery_state['best_Ps'] > -90.0:
                print(f"  Best Ps ever: {_discovery_state['best_Ps']:.4f} m/s²")
        else:
            print(f"  No prior learning found — starting fresh (flight #1)")
    return {'loaded': loaded, 'flight_number': flight_n + 1}


# ══════════════════════════════════════════════════════════════════════════════
# IMPROVEMENT LOGGING — records every time something gets better
# ══════════════════════════════════════════════════════════════════════════════

def log_improvement(dimension, metric_before, metric_after,
                    mechanism, config=None, notes=''):
    """
    Record any measurable improvement to the learning log.
    Call whenever a discovery, hypothesis, or optimizer nudge
    produces a confirmed improvement in any performance metric.

    Parameters
    ----------
    dimension     : str   — 'efficiency'|'top_speed'|'range'|
                            'maneuverability'|'acceleration'|'handling'
    metric_before : float — Ps or other metric before improvement
    metric_after  : float — Ps or other metric after improvement
    mechanism     : str   — what caused the improvement
    config        : dict | None — the winning configuration
    notes         : str   — freetext context
    """
    improvement_pct = ((metric_after - metric_before) /
                        max(abs(metric_before), 0.001) * 100)
    _pl_append_log({
        'event':           'improvement',
        'dimension':       dimension,
        'metric_before':   round(metric_before, 4),
        'metric_after':    round(metric_after, 4),
        'improvement_pct': round(improvement_pct, 1),
        'mechanism':       mechanism,
        'config':          config,
        'notes':           notes,
    })
    print(f"  ✓ IMPROVEMENT: {dimension} +{improvement_pct:.1f}% "
          f"via {mechanism}")


# ══════════════════════════════════════════════════════════════════════════════
# LEARNING HISTORY — cross-flight trend analysis
# ══════════════════════════════════════════════════════════════════════════════

def learning_history(n_flights=20):
    """
    Ground station: show cross-flight learning progress.
    Reads the learning log and flight summary to show trends.
    """
    log_path = f'{_PL_DIR}/learning_log.jsonl'
    fs_path  = f'{_PL_DIR}/flight_summary.json'

    print(f"\n  CROSS-FLIGHT LEARNING HISTORY")
    print(f"  ─────────────────────────────────────────────")

    # Flight summary
    fs = _pl_read(fs_path)
    if fs:
        print(f"  Total flights:     {fs['flights']}")
        print(f"  Last flight:       {fs.get('last_flight','?')}")
        print(f"  Best Ps achieved:  {fs.get('last_best_Ps', 0.0):.4f} m/s²")

        history = fs.get('history', [])[-n_flights:]
        if history:
            print(f"\n  FLIGHT HISTORY (last {len(history)}):")
            print(f"  {'Flt':>4}  {'Best Ps':>9}  {'Discoveries':>12}  "
                  f"{'Top roll':>14}  {'Top pitch':>14}")
            for h in history:
                print(f"  {h['flight']:>4}  {h['best_Ps']:>+9.4f}  "
                      f"{h['n_disc']:>12}  "
                      f"{h.get('mw_roll_top','?'):>14}  "
                      f"{h.get('mw_pitch_top','?'):>14}")

    # Improvements from learning log
    try:
        with open(log_path) as f:
            entries = [_plj.loads(l) for l in f if l.strip()]
        improvements = [e for e in entries if e.get('event') == 'improvement']
        if improvements:
            print(f"\n  CONFIRMED IMPROVEMENTS ({len(improvements)} total):")
            by_dim = {}
            for e in improvements:
                dim = e.get('dimension', '?')
                by_dim.setdefault(dim, []).append(e['improvement_pct'])
            for dim, pcts in sorted(by_dim.items()):
                best = max(pcts)
                print(f"    {dim:<18} n={len(pcts):>3}  "
                      f"best gain={best:>+.1f}%")

        # Hypothesis outcomes across flights
        hyp = _pl_read(f'{_PL_DIR}/hypothesis_outcomes.json')
        if hyp:
            outcomes = hyp.get('outcomes', {})
            promoted = {k: v for k, v in outcomes.items()
                        if v.get('promoted')}
            print(f"\n  HYPOTHESIS PROMOTIONS ACROSS ALL FLIGHTS "
                  f"({len(promoted)}/{len(outcomes)}):")
            for h_id, res in sorted(promoted.items(),
                                     key=lambda x: -x[1].get('Ps',0)):
                print(f"    {h_id:<8}  Ps={res['Ps']:>+.4f}  "
                      f"V={res['V_ms']:.1f} m/s")
    except FileNotFoundError:
        print(f"\n  No learning log yet — starts after first flight.")

    print(f"\n  GS: persist_checkpoint — save mid-flight")
    print(f"  GS: learning_history   — this report")


def persist_checkpoint():
    """Mid-flight checkpoint — save current learning state without shutdown."""
    saved = persist_save_all(notes='mid-flight checkpoint')
    print(f"  Checkpoint saved: {len(saved)} components")


def persist_status():
    """Show what is currently persisted on disk."""
    print(f"\n  PERSISTENCE STATUS")
    print(f"  ─────────────────────────────────────────────")
    files = [
        ('mechanism_weights.json',  'Mechanism weights (roll/pitch/yaw)'),
        ('l5_learned.json',         'Loop 5 yaw modality per condition'),
        ('discovery_promoted.json', 'Promoted discovery configurations'),
        ('hypothesis_outcomes.json','Hypothesis evaluation results'),
        ('strouhal_log.json',       'Strouhal operating point history'),
        ('target_rates.json',       'Target rate schedule (°/s per axis)'),
        ('flight_summary.json',     'Flight counter and history'),
        ('learning_log.jsonl',      'Append-only improvement record'),
    ]
    for fname, desc in files:
        path = f'{_PL_DIR}/{fname}'
        exists = _plo.path.exists(path)
        if exists:
            size = _plo.path.getsize(path)
            mtime = _plt.strftime('%Y-%m-%d %H:%M',
                                   _plt.localtime(_plo.path.getmtime(path)))
            print(f"  ✓ {fname:<32} {size:>7} B  {mtime}")
        else:
            print(f"  ✗ {fname:<32} (not yet created)")
    print(f"\n  Knowledge dir: {_PL_DIR}")


# Register GS commands
_GS_ALLOWED_CMDS.update({
    'persist_save_all',
    'persist_load_all',
    'persist_checkpoint',
    'persist_status',
    'learning_history',
    'log_improvement',
})


# ══════════════════════════════════════════════════════════════════════════════
# FLEET LEARNING SYSTEM
# Bidirectional communication: ideas in, discoveries out, fleet-wide sharing
# ══════════════════════════════════════════════════════════════════════════════
#
# THREE COMMUNICATION CHANNELS
# ─────────────────────────────
#
# CHANNEL 1 — GROUND STATION LIVE INJECTION
#   The operator types a hypothesis, observation, or parameter change
#   into the ground station CLI and it arrives at the aircraft over
#   the existing TCP socket (port 5757) in milliseconds.
#   The aircraft evaluates it during the current flight.
#   No USB stick, no reboot, no file required.
#
#   GS commands:
#     inject_hypothesis name="LEV 37deg" cascade_phase_deg=37 freq_hz=2.1
#     inject_parameter DART_G_LIMIT 2.5
#     inject_note "Wind from north, pilot reports left drift in hover"
#
# CHANNEL 2 — KNOWLEDGE FILE (USB / NETWORK)
#   After any flight, the aircraft exports a self-contained JSON knowledge
#   file. This file contains everything the aircraft has learned in a form
#   that can be imported by any other MCO aircraft — with automatic scaling
#   for different sizes. The file is human-readable and can be reviewed,
#   edited, annotated, or selectively merged before import.
#
#   Export: knowledge_export_now  (GS command — triggers immediate export)
#   Import: knowledge_import /path/to/file.json
#   USB:    place file in /home/pi/knowledge/inbox/ or on USB stick
#           it will be auto-detected at next boot
#
# CHANNEL 3 — FLEET MERGE (multiple drones learning together)
#   When N drones have each accumulated K flights of learning, their
#   knowledge files can be merged into a unified fleet knowledge file.
#   The merge uses a confidence-weighted average: discoveries confirmed
#   by more drones get higher weight. Discoveries unique to one drone
#   are retained with lower confidence, flagged for validation by others.
#
#   The merged file can be pushed back to all drones simultaneously,
#   so each drone begins its next flight with the combined learning of
#   the entire fleet.
#
#   merge_fleet_knowledge file1.json file2.json ... → fleet_merged.json
#   Then: knowledge_import fleet_merged.json on each drone
#
# ══════════════════════════════════════════════════════════════════════════════

import json    as _flj
import os      as _flo
import time    as _flt
import glob    as _flg
import hashlib as _flh

_FL_VERSION = 1
_FL_INBOX   = '/home/pi/knowledge/inbox'
_FL_OUTBOX  = '/home/pi/knowledge/outbox'


# ══════════════════════════════════════════════════════════════════════════════
# CHANNEL 1 — LIVE INJECTION FROM GROUND STATION
# ══════════════════════════════════════════════════════════════════════════════

def gs_inject_hypothesis(name='unnamed', target='efficiency',
                          rationale='', priority=2, **params):
    """
    Inject a hypothesis live from the ground station.

    The operator types this at the GS CLI and it arrives at the aircraft
    over the existing TCP socket with no file, no USB, no reboot.
    The hypothesis is validated, queued, and evaluated during the current
    flight exactly as a built-in hypothesis would be.

    Parameters
    ----------
    name      : str  — human label, e.g. "try 45 deg cascade"
    target    : str  — 'efficiency'|'top_speed'|'range'|'maneuverability'
    rationale : str  — why you think this might work
    priority  : int  — 1=next, 2=normal, 3=low (default 2)
    **params  : any _DISCOVERY_BOUNDS key=value pairs
                e.g. cascade_phase_deg=37, freq_hz=2.1, aoa_deg=22

    Examples
    --------
    GS: gs_inject_hypothesis name="LEV capture" cascade_phase_deg=37
    GS: gs_inject_hypothesis name="anti-phase loiter" cascade_phase_deg=180 freq_hz=1.3
    GS: gs_inject_hypothesis name="max sweep Vne" sweep_deg=88 freq_hz=2.8 target=top_speed
    """
    # Validate params against bounds
    errors = []
    cfg = {}
    for k, v in params.items():
        if k in _DISCOVERY_BOUNDS:
            lo, hi = _DISCOVERY_BOUNDS[k]
            v = float(v)
            if not (lo <= v <= hi):
                errors.append(f"{k}={v} outside [{lo},{hi}]")
            else:
                cfg[k] = round(v, 3)
        else:
            errors.append(f"Unknown param '{k}' — valid: {list(_DISCOVERY_BOUNDS)}")

    if errors:
        print(f"  HYPOTHESIS REJECTED: {'; '.join(errors)}")
        return False

    # Fill missing params from current best config or defaults
    defaults = (_discovery_state.get('best_config') or
                {'sweep_deg':60,'dihedral_deg':0,'aoa_deg':22,
                 'cascade_phase_deg':90,'amp_port_deg':96,'amp_stbd_deg':96,
                 'freq_hz':1.87,'w_crab':0.33,'w_dart':0.33,'w_split':0.34,
                 'port_phase_offset':0,'stbd_phase_offset':0,
                 'proverse_amp_ratio':0,'proverse_sign':1})
    full_cfg = dict(defaults)
    full_cfg.update(cfg)
    # Remove internal keys
    for k in ['_hyp_id', 'dart_left', 'dart_right']:
        full_cfg.pop(k, None)

    # Build hypothesis entry
    hyp_id = f'GS_{_flt.strftime("%H%M%S")}'
    entry  = {
        'id':       hyp_id,
        'label':    name,
        'target':   target,
        'rationale':rationale,
        'config':   full_cfg,
        'v_min':    0.0,
        'v_max':    28.0,
        'priority': priority,
        'source':   'ground_station_live',
        'injected_at': _flt.strftime('%Y-%m-%dT%H:%M:%S'),
    }

    # Inject into front of hypothesis queue (priority 1) or normal position
    if priority == 1:
        _hypothesis_queue.insert(0, {
            'id': hyp_id, 'label': name,
            'target': target, 'config': full_cfg
        })
    else:
        _hypothesis_queue.append({
            'id': hyp_id, 'label': name,
            'target': target, 'config': full_cfg
        })

    # Also save to inbox for persistence
    _flo.makedirs(_FL_INBOX, exist_ok=True)
    inbox_path = f'{_FL_INBOX}/{hyp_id}.json'
    with open(inbox_path, 'w') as f:
        _flj.dump(entry, f, indent=2)

    # Log the injection
    _pl_append_log({
        'event':    'hypothesis_injected',
        'id':       hyp_id,
        'name':     name,
        'target':   target,
        'params':   cfg,
        'rationale':rationale,
    })

    print(f"\n  HYPOTHESIS INJECTED: {hyp_id}")
    print(f"  Name:      {name}")
    print(f"  Target:    {target}")
    print(f"  Params:    {cfg}")
    print(f"  Queue pos: {'NEXT' if priority==1 else len(_hypothesis_queue)}")
    print(f"  Will evaluate for {DISCOVERY_DWELL_S:.0f}s at next opportunity")
    return True


def gs_inject_parameter(param_name, value, rationale=''):
    """
    Override a named parameter value live from the ground station.

    This is for direct parameter changes — not hypothesis testing.
    Use when you know what value you want to try, not when you want
    the system to evaluate it.

    Parameters
    ----------
    param_name : str   — any module-level constant name
    value      : float — new value
    rationale  : str   — why

    Examples
    --------
    GS: gs_inject_parameter DART_G_LIMIT 2.4
    GS: gs_inject_parameter DISCOVERY_DWELL_S 30
    GS: gs_inject_parameter AH_ROLL_KP_OUTER 0.10
    """
    import mco_wave_library as _self
    param_name = str(param_name)

    # Safety: block structural limits and safety ceilings
    BLOCKED = {'FREQ_LIMIT_MAX_HZ', 'PITCH_LIMIT_MAX_DEG', 'PITCH_LIMIT_MIN_DEG',
                'FLAP_AMP_DEG', 'VNE_MS', 'G_LIMIT_HARD', 'SOFT_STOP_ZONE_DEG'}
    if param_name in BLOCKED:
        print(f"  BLOCKED: {param_name} is a structural safety limit. "
              f"Edit source to change.")
        return False

    if not hasattr(_self, param_name):
        print(f"  UNKNOWN parameter: {param_name}")
        print(f"  Tip: use gs_inject_hypothesis for wing kinematics.")
        return False

    old_val = getattr(_self, param_name)
    try:
        new_val = type(old_val)(value)
        setattr(_self, param_name, new_val)
        _pl_append_log({
            'event':     'parameter_injected',
            'param':     param_name,
            'old_value': old_val,
            'new_value': new_val,
            'rationale': rationale,
        })
        print(f"  {param_name}: {old_val} → {new_val}")
        return True
    except Exception as e:
        print(f"  Failed: {e}")
        return False


def gs_inject_note(text):
    """
    Record an operator observation to the learning log.

    Notes are preserved in the knowledge file and can be read by
    anyone who imports that knowledge file. Use for anything you
    observe in flight that isn't captured automatically.

    Examples
    --------
    GS: gs_inject_note "strong thermal south of field, aircraft climbing 0.8m/s unpowered"
    GS: gs_inject_note "dart felt sluggish at 8m/s, mode B seemed absent"
    GS: gs_inject_note "H-PH-2 promoted but wind was gusty, needs calm-day retest"
    """
    _pl_append_log({
        'event':  'operator_note',
        'note':   str(text),
    })
    print(f"  Note recorded: {text}")


def inbox_check():
    """
    Scan inbox and USB for pending hypotheses or knowledge files.
    Called automatically at each ARM. Also callable from GS.
    """
    _flo.makedirs(_FL_INBOX, exist_ok=True)
    results = {'hypotheses': [], 'knowledge_files': []}

    # Scan inbox
    for path in _flg.glob(f'{_FL_INBOX}/*.json'):
        try:
            with open(path) as f:
                data = _flj.load(f)
            if 'config' in data and 'id' in data:
                # It's a hypothesis
                hyp_id = data['id']
                if hyp_id not in _hypothesis_results:
                    _hypothesis_queue.append({
                        'id':     hyp_id,
                        'label':  data.get('label', data.get('name', hyp_id)),
                        'target': data.get('target', 'efficiency'),
                        'config': data['config'],
                    })
                    results['hypotheses'].append(hyp_id)
            elif 'principles' in data:
                # It's a knowledge file
                results['knowledge_files'].append(path)
        except Exception:
            pass

    # Scan USB paths
    for mount in KNOWLEDGE_USB_PATHS:
        for path in _flg.glob(f'{mount}/**/mco_knowledge_*.json',
                               recursive=True):
            results['knowledge_files'].append(path)
        for path in _flg.glob(f'{mount}/**/*.hypothesis.json',
                               recursive=True):
            try:
                with open(path) as f:
                    data = _flj.load(f)
                hyp_id = data.get('id', path)
                if hyp_id not in _hypothesis_results:
                    _hypothesis_queue.append({
                        'id':     hyp_id,
                        'label':  data.get('label', hyp_id),
                        'target': data.get('target', 'efficiency'),
                        'config': data.get('config', {}),
                    })
                    results['hypotheses'].append(hyp_id)
            except Exception:
                pass

    if results['hypotheses']:
        print(f"  Inbox: {len(results['hypotheses'])} hypotheses queued")
    if results['knowledge_files']:
        print(f"  Inbox: {len(results['knowledge_files'])} knowledge files available")
        print(f"  Import: knowledge_import {results['knowledge_files'][0]}")
    return results


# ══════════════════════════════════════════════════════════════════════════════
# CHANNEL 2 — KNOWLEDGE EXPORT / IMPORT (USB / NETWORK)
# ══════════════════════════════════════════════════════════════════════════════

def knowledge_export_now(label=''):
    """
    Export current learning state to the outbox immediately.
    GS command — use any time during or after a flight.

    Creates two files in /home/pi/knowledge/outbox/:
      mco_knowledge_NNN_full.json    — complete state (for same-size drones)
      mco_knowledge_NNN_fleet.json   — scaled principles (for any MCO size)

    Returns the outbox path.
    """
    _flo.makedirs(_FL_OUTBOX, exist_ok=True)

    # Number the export
    existing = sorted(_flg.glob(f'{_FL_OUTBOX}/mco_knowledge_*_full.json'))
    n = len(existing) + 1

    ts = _flt.strftime('%Y-%m-%dT%H:%M:%S')

    # ── Full state export (identical aircraft) ─────────────────────────────
    full_data = {
        '_version':      _FL_VERSION,
        '_type':         'full_state',
        'exported_at':   ts,
        'label':         label,
        'aircraft_id':   'MCO-1D',

        # All persisted learning
        'mechanism_weights': {
            'roll':  dict(_MW_ROLL),
            'pitch': dict(_MW_PITCH),
            'yaw':   dict(_MW_YAW),
        },
        'target_rates': dict(_TARGET_RATES),
        'l5_learned': {
            str(k): v for k, v in _L5_state['learned'].items()
        },
        'l5_global': {
            'w_crab': L5_W_CRAB, 'w_dart': L5_W_DART,
            'w_split': L5_W_SPLIT, 'w_proverse': L5_W_PROVERSE,
        },
        'discovery': {
            'best_Ps':     _discovery_state['best_Ps'],
            'best_config': _discovery_state.get('best_config'),
            'discoveries': _discovery_state.get('discoveries', []),
            'locked_gaits':_discovery_state.get('locked_gaits', []),
        },
        'hypothesis_outcomes': dict(_hypothesis_results),
        'n_configs_tried':     _discovery_state['n_configs_tried'],

        # Geometry reference for scaling
        'geometry': {
            'mtow_kg':       MTOW_KG,
            'span_m':        sum([0.772, 0.749, 0.735, 0.712]) * 2,
            'flap_amp_deg':  FLAP_AMP_DEG,
            'freq_max_hz':   FREQ_LIMIT_MAX_HZ,
            'stroke_amp_m':  _HS_STROKE_AMP_M,
        },
    }
    full_path = f'{_FL_OUTBOX}/mco_knowledge_{n:03d}_full.json'
    with open(full_path, 'w') as f:
        _flj.dump(full_data, f, indent=2, default=str)

    # ── Fleet export (dimensionless — for any MCO size) ────────────────────
    # Discoveries are expressed as dimensionless ratios
    def _dimensionless(cfg):
        if not cfg: return {}
        amp = cfg.get('amp_port_deg', FLAP_AMP_DEG)
        freq = cfg.get('freq_hz', 1.87)
        V_est = 9.0
        return {
            'sweep_frac':       cfg.get('sweep_deg', 60) / 90.0,
            'aoa_frac':         cfg.get('aoa_deg', 22) / AOA_PEAK_CL_DEG,
            'amp_frac':         amp / FLAP_AMP_DEG,
            'cascade_phase_deg':cfg.get('cascade_phase_deg', 90),
            'port_phase_offset':cfg.get('port_phase_offset', 0),
            'stbd_phase_offset':cfg.get('stbd_phase_offset', 0),
            'strouhal_number':  _HS_STROKE_AMP_M * freq / V_est if V_est > 0 else 0,
            'dihedral_deg':     cfg.get('dihedral_deg', 0),
            'proverse_ratio':   cfg.get('proverse_amp_ratio', 0),
            'yaw_blend':        {
                'w_crab':  cfg.get('w_crab', 0.33),
                'w_dart':  cfg.get('w_dart', 0.33),
                'w_split': cfg.get('w_split', 0.34),
            },
        }

    fleet_discoveries = []
    for disc in _discovery_state.get('discoveries', []):
        cfg  = disc.get('config', {})
        ps   = disc.get('Ps', 0)
        if ps > 0.05:   # only meaningful discoveries
            fleet_discoveries.append({
                'dimensionless': _dimensionless(cfg),
                'ps_improvement':round(ps, 4),
                'V_ms':          disc.get('V_ms', 9.0),
                'n_obs':         disc.get('n_obs', 1),
                'confidence':    min(1.0, disc.get('n_obs', 1) / 5.0),
                'target':        disc.get('target', 'efficiency'),
            })

    # Promoted hypotheses
    for h_id, res in _hypothesis_results.items():
        if res.get('promoted') and res.get('Ps', 0) > 0.05:
            # Find original hypothesis for config
            orig = next((h for h in AERO_HYPOTHESES if h['id'] == h_id), None)
            if orig:
                fleet_discoveries.append({
                    'hypothesis_id':  h_id,
                    'hypothesis_label': orig['label'],
                    'dimensionless':  _dimensionless(orig['config']),
                    'ps_improvement': round(res['Ps'], 4),
                    'V_ms':           res.get('V_ms', 9.0),
                    'n_obs':          3,
                    'confidence':     0.6,
                    'target':         orig['target'],
                    'rationale':      orig['rationale'],
                })

    fleet_data = {
        '_version':         _FL_VERSION,
        '_type':            'fleet_knowledge',
        'exported_at':      ts,
        'label':            label,
        'aircraft_id':      'MCO-1D',
        'geometry_ref':     full_data['geometry'],
        'mechanism_top': {
            'roll':  max(_MW_ROLL,  key=_MW_ROLL.get),
            'pitch': max(_MW_PITCH, key=_MW_PITCH.get),
            'yaw':   max(_MW_YAW,   key=_MW_YAW.get),
        },
        'l5_global':        full_data['l5_global'],
        'l5_learned':       full_data['l5_learned'],
        'discoveries':      fleet_discoveries,
        'hypothesis_outcomes': {
            k: v for k, v in _hypothesis_results.items()
            if v.get('promoted')
        },
        'n_configs_tried':  _discovery_state['n_configs_tried'],
        'best_Ps':          _discovery_state['best_Ps'],
        'scaling_formulas': {
            'frequency':   'St_target=0.25, f=St×V/(2×A), A=span×sin(amp/2)',
            'strouhal':    'dimensionless — no scaling needed',
            'phase':       'degrees — no scaling needed',
            'aoa':         'degrees — no scaling needed (Re correction <1m)',
            'amplitude':   'degrees — no scaling needed',
        },
    }
    fleet_path = f'{_FL_OUTBOX}/mco_knowledge_{n:03d}_fleet.json'
    with open(fleet_path, 'w') as f:
        _flj.dump(fleet_data, f, indent=2, default=str)

    print(f"\n  KNOWLEDGE EXPORTED")
    print(f"  Full state:     {full_path}")
    print(f"  Fleet package:  {fleet_path}")
    print(f"  Discoveries:    {len(fleet_discoveries)}")
    print(f"  Best Ps:        {_discovery_state['best_Ps']:.4f}")
    print(f"\n  To share: copy {_FL_OUTBOX}/ to USB or network share")
    print(f"  To import on another drone:")
    print(f"    knowledge_import {fleet_path}")
    return fleet_path


def knowledge_import(filepath, new_mass_kg=None, new_span_m=None):
    """
    Import a knowledge file from another drone or a merged fleet file.
    Automatically detects full_state vs fleet_knowledge type.

    Parameters
    ----------
    filepath    : str   — path to *_full.json or *_fleet.json
    new_mass_kg : float — only needed if importing onto a different-size drone
    new_span_m  : float — only needed if importing onto a different-size drone

    Examples
    --------
    GS: knowledge_import /home/pi/knowledge/inbox/mco_knowledge_007_fleet.json
    GS: knowledge_import /media/usb/DRONE2/mco_knowledge_012_full.json
    """
    try:
        with open(filepath) as f:
            data = _flj.load(f)
    except Exception as e:
        print(f"  Import failed: {e}")
        return False

    kind = data.get('_type', 'unknown')
    src  = data.get('aircraft_id', '?')
    ts   = data.get('exported_at', '?')

    print(f"\n  IMPORTING from {src} ({ts})")
    print(f"  Type: {kind}")

    if kind == 'full_state':
        # Direct restore — same size aircraft
        n_mw = 0
        for axis, weights in data.get('mechanism_weights', {}).items():
            target = {'roll': _MW_ROLL, 'pitch': _MW_PITCH,
                       'yaw': _MW_YAW}.get(axis)
            if target:
                for k, v in weights.items():
                    if k in target:
                        # Blend: 50% import, 50% current (avoid overwriting
                        # local learning entirely)
                        target[k] = round(0.5 * float(v) + 0.5 * target[k], 4)
                        n_mw += 1
        print(f"  Mechanism weights blended: {n_mw} values")

        # L5 global weights (blend)
        l5g = data.get('l5_global', {})
        global L5_W_CRAB, L5_W_DART, L5_W_SPLIT, L5_W_PROVERSE
        L5_W_CRAB     = round(0.5*float(l5g.get('w_crab', L5_W_CRAB))     + 0.5*L5_W_CRAB,     3)
        L5_W_DART     = round(0.5*float(l5g.get('w_dart', L5_W_DART))     + 0.5*L5_W_DART,     3)
        L5_W_SPLIT    = round(0.5*float(l5g.get('w_split', L5_W_SPLIT))   + 0.5*L5_W_SPLIT,    3)
        L5_W_PROVERSE = round(0.5*float(l5g.get('w_proverse', L5_W_PROVERSE)) + 0.5*L5_W_PROVERSE, 3)

        # Discoveries: add if not already known
        n_disc = 0
        for disc in data.get('discovery', {}).get('discoveries', []):
            cfg_hash = _flh.md5(str(sorted(disc.get('config', {}).items()))
                                 .encode()).hexdigest()[:8]
            existing_hashes = [
                _flh.md5(str(sorted(d.get('config', {}).items()))
                          .encode()).hexdigest()[:8]
                for d in _discovery_state.get('discoveries', [])
            ]
            if cfg_hash not in existing_hashes:
                _discovery_state.setdefault('discoveries', []).append(disc)
                n_disc += 1

        # Hypothesis outcomes: merge
        for h_id, res in data.get('hypothesis_outcomes', {}).items():
            if h_id not in _hypothesis_results:
                _hypothesis_results[h_id] = res
        print(f"  Discoveries added: {n_disc}")

    elif kind == 'fleet_knowledge':
        # Scaled import — extract dimensionless discoveries
        geo_ref = data.get('geometry_ref', {})
        ref_amp = geo_ref.get('flap_amp_deg', FLAP_AMP_DEG)
        n_disc  = 0
        for disc in data.get('discoveries', []):
            dim = disc.get('dimensionless', {})
            if not dim:
                continue
            # Reconstruct config in this aircraft's parameter space
            cfg = {
                'sweep_deg':         dim.get('sweep_frac', 0.67) * 90.0,
                'aoa_deg':           dim.get('aoa_frac', 0.55) * AOA_PEAK_CL_DEG,
                'amp_port_deg':      dim.get('amp_frac', 1.0) * FLAP_AMP_DEG,
                'amp_stbd_deg':      dim.get('amp_frac', 1.0) * FLAP_AMP_DEG,
                'cascade_phase_deg': dim.get('cascade_phase_deg', 90),
                'port_phase_offset': dim.get('port_phase_offset', 0),
                'stbd_phase_offset': dim.get('stbd_phase_offset', 0),
                'dihedral_deg':      dim.get('dihedral_deg', 0),
                'proverse_amp_ratio':dim.get('proverse_ratio', 0),
                'w_crab':  dim.get('yaw_blend', {}).get('w_crab', 0.33),
                'w_dart':  dim.get('yaw_blend', {}).get('w_dart', 0.33),
                'w_split': dim.get('yaw_blend', {}).get('w_split', 0.34),
            }
            # Strouhal-correct frequency for this aircraft
            St = dim.get('strouhal_number', 0.27)
            V_ms = disc.get('V_ms', 9.0)
            cfg['freq_hz'] = min(FREQ_LIMIT_MAX_HZ,
                                  round(St * V_ms / _HS_STROKE_AMP_M, 2)
                                  if V_ms > 0 else 1.87)

            # Queue as hypothesis for re-validation
            h_id = f'FLEET_{src}_{n_disc:03d}'
            label = disc.get('hypothesis_label',
                              f'Fleet discovery from {src}')
            _hypothesis_queue.append({
                'id':     h_id,
                'label':  label,
                'target': disc.get('target', 'efficiency'),
                'config': cfg,
                'source': src,
                'fleet_ps': disc.get('ps_improvement', 0),
            })
            n_disc += 1

        print(f"  Fleet discoveries queued for validation: {n_disc}")
        print(f"  Each will be re-evaluated for {DISCOVERY_DWELL_S:.0f}s "
              f"before adoption")

    _pl_append_log({
        'event':    'knowledge_imported',
        'source':   src,
        'type':     kind,
        'filepath': filepath,
    })
    return True


# ══════════════════════════════════════════════════════════════════════════════
# CHANNEL 3 — FLEET MERGE (multiple drones learning together)
# ══════════════════════════════════════════════════════════════════════════════

def merge_fleet_knowledge(*filepaths, output_path=None, min_confidence=0.3):
    """
    Merge knowledge files from multiple drones into one unified file.
    Run this on the ground station or any computer — does not require
    the aircraft to be running.

    Algorithm:
      1. Discoveries confirmed by multiple drones get boosted confidence.
      2. Mechanism weights are averaged, weighted by n_configs_tried.
      3. Discoveries unique to one drone are kept with their base confidence.
      4. Contradicting outcomes (one drone promoted, another discarded) are
         flagged for in-flight re-validation rather than resolved by fiat.

    Parameters
    ----------
    *filepaths     : str — paths to *_fleet.json files from each drone
    output_path    : str — where to write the merged file (default: outbox)
    min_confidence : float — discard discoveries below this confidence

    Example
    -------
    GS: merge_fleet_knowledge /path/drone1_fleet.json /path/drone2_fleet.json
    """
    if len(filepaths) < 2:
        print("  Need at least 2 fleet knowledge files to merge.")
        return None

    all_data = []
    for fp in filepaths:
        try:
            with open(fp) as f:
                d = _flj.load(f)
            if d.get('_type') not in ('fleet_knowledge', 'full_state'):
                print(f"  Skipping {fp} — not a fleet or full_state file")
                continue
            all_data.append((fp, d))
        except Exception as e:
            print(f"  Failed to read {fp}: {e}")

    if len(all_data) < 2:
        print(f"  Only {len(all_data)} valid files — need at least 2")
        return None

    print(f"\n  FLEET MERGE: {len(all_data)} drones")

    # ── Merge mechanism weights (weighted average by n_configs_tried) ──────
    merged_mw = {'roll': {}, 'pitch': {}, 'yaw': {}}
    total_trials = 0
    for _, d in all_data:
        n = d.get('n_configs_tried', 1)
        total_trials += n
        for axis in ('roll', 'pitch', 'yaw'):
            mw = d.get('mechanism_weights', {}).get(axis) or {}
            for mech, w in mw.items():
                if mech not in merged_mw[axis]:
                    merged_mw[axis][mech] = 0.0
                merged_mw[axis][mech] += float(w) * n

    for axis in ('roll', 'pitch', 'yaw'):
        s = sum(merged_mw[axis].values())
        if s > 0:
            for m in merged_mw[axis]:
                merged_mw[axis][m] = round(
                    merged_mw[axis][m] / total_trials, 4)

    # ── Merge L5 weights ───────────────────────────────────────────────────
    l5_counts = {'w_crab':0,'w_dart':0,'w_split':0,'w_proverse':0}
    l5_sums   = {'w_crab':0.0,'w_dart':0.0,'w_split':0.0,'w_proverse':0.0}
    for _, d in all_data:
        l5g = d.get('l5_global', {})
        n   = d.get('n_configs_tried', 1)
        for k in l5_sums:
            l5_sums[k]   += float(l5g.get(k, 0.25)) * n
            l5_counts[k] += n
    merged_l5 = {k: round(l5_sums[k] / max(l5_counts[k], 1), 3)
                  for k in l5_sums}

    # ── Merge discoveries (hash-based deduplication + confidence boost) ────
    disc_map = {}   # hash → {entry, confirming_drones, ps_values}
    for fp, d in all_data:
        drone_id = d.get('aircraft_id', fp[-10:])
        for disc in d.get('discoveries', []):
            dim = disc.get('dimensionless', {})
            if not dim:
                continue
            # Hash on dimensionless parameters (rounded to reduce noise)
            key_str = str({k: round(float(v), 1) if isinstance(v, (int, float))
                           else v
                           for k, v in sorted(dim.items())
                           if not isinstance(v, dict)})
            h = _flh.md5(key_str.encode()).hexdigest()[:12]
            if h not in disc_map:
                disc_map[h] = {
                    'entry':            dict(disc),
                    'confirming_drones':[drone_id],
                    'ps_values':        [disc.get('ps_improvement', 0)],
                    'V_values':         [disc.get('V_ms', 9.0)],
                }
            else:
                disc_map[h]['confirming_drones'].append(drone_id)
                disc_map[h]['ps_values'].append(disc.get('ps_improvement', 0))
                disc_map[h]['V_values'].append(disc.get('V_ms', 9.0))

    # Build merged discovery list
    merged_discoveries = []
    n_confirmed = 0
    for h, entry_data in disc_map.items():
        n_drones   = len(set(entry_data['confirming_drones']))
        ps_mean    = sum(entry_data['ps_values']) / len(entry_data['ps_values'])
        ps_std     = (sum((p - ps_mean)**2 for p in entry_data['ps_values'])
                      / len(entry_data['ps_values'])) ** 0.5
        V_mean     = sum(entry_data['V_values']) / len(entry_data['V_values'])
        base_conf  = entry_data['entry'].get('confidence', 0.5)

        # Confidence boost: each additional confirming drone adds 20%
        conf = min(1.0, base_conf + 0.20 * (n_drones - 1))

        if conf < min_confidence:
            continue

        disc = dict(entry_data['entry'])
        disc.update({
            'fleet_confirmed':   n_drones,
            'fleet_ps_mean':     round(ps_mean, 4),
            'fleet_ps_std':      round(ps_std, 4),
            'fleet_V_ms_mean':   round(V_mean, 1),
            'confidence':        round(conf, 3),
            'confirming_drones': list(set(entry_data['confirming_drones'])),
        })
        merged_discoveries.append(disc)
        if n_drones > 1:
            n_confirmed += 1

    # Sort by fleet_confirmed desc, then ps_mean desc
    merged_discoveries.sort(
        key=lambda d: (-d.get('fleet_confirmed', 1),
                       -d.get('fleet_ps_mean', 0)))

    # ── Merge hypothesis outcomes ──────────────────────────────────────────
    merged_hyp = {}
    for _, d in all_data:
        for h_id, res in d.get('hypothesis_outcomes', {}).items():
            if h_id not in merged_hyp:
                merged_hyp[h_id] = dict(res)
                merged_hyp[h_id]['confirming_drones'] = 1
            else:
                # Average Ps across drones
                n = merged_hyp[h_id]['confirming_drones']
                merged_hyp[h_id]['Ps'] = round(
                    (merged_hyp[h_id]['Ps'] * n + res.get('Ps', 0)) / (n+1), 4)
                merged_hyp[h_id]['promoted'] = (
                    merged_hyp[h_id]['promoted'] or res.get('promoted', False))
                merged_hyp[h_id]['confirming_drones'] = n + 1

    # ── Write merged file ──────────────────────────────────────────────────
    ts = _flt.strftime('%Y-%m-%dT%H:%M:%S')
    if output_path is None:
        _flo.makedirs(_FL_OUTBOX, exist_ok=True)
        output_path = f'{_FL_OUTBOX}/fleet_merged_{ts[:10].replace("-","")}.json'

    merged = {
        '_version':          _FL_VERSION,
        '_type':             'fleet_knowledge',
        'merged_at':         ts,
        'source_drones':     [d.get('aircraft_id', '?')
                               for _, d in all_data],
        'n_drones':          len(all_data),
        'mechanism_weights': merged_mw,
        'l5_global':         merged_l5,
        'discoveries':       merged_discoveries,
        'hypothesis_outcomes': merged_hyp,
        'n_discoveries_total':  len(merged_discoveries),
        'n_multi_confirmed':    n_confirmed,
        'total_configs_tried':  total_trials,
        'scaling_formulas': {
            'frequency':   'St_target=0.25, f=St×V/(2×A), A=span×sin(amp/2)',
            'strouhal':    'dimensionless — no scaling needed',
            'phase':       'degrees — no scaling needed',
        },
        'import_instructions': (
            'Run: knowledge_import <this_file_path> on each drone. '
            'Fleet discoveries will be re-validated in-flight before '
            'adoption. Multi-confirmed discoveries require fewer re-validation '
            'flights (1 vs 3 for single-drone discoveries).'
        ),
    }

    with open(output_path, 'w') as f:
        _flj.dump(merged, f, indent=2, default=str)

    print(f"\n  FLEET MERGE COMPLETE")
    print(f"  Drones merged:       {len(all_data)}")
    print(f"  Discoveries:         {len(merged_discoveries)}")
    print(f"  Multi-confirmed:     {n_confirmed} (seen by >1 drone)")
    print(f"  Total configs tried: {total_trials:,}")
    print(f"  Output:              {output_path}")
    print(f"\n  To push to all drones:")
    print(f"    knowledge_import {output_path}")
    print(f"    (run on each drone, or copy to each inbox/)")
    return output_path


def fleet_status():
    """Show what's in the outbox, ready to share with other drones."""
    print(f"\n  FLEET LEARNING STATUS")
    print(f"  ─────────────────────────────────────────────")

    # Outbox
    print(f"\n  OUTBOX ({_FL_OUTBOX}):")
    for path in sorted(_flg.glob(f'{_FL_OUTBOX}/*.json')):
        size = _flo.path.getsize(path)
        mtime = _flt.strftime('%Y-%m-%d %H:%M',
                               _flt.localtime(_flo.path.getmtime(path)))
        print(f"    {_flo.path.basename(path):<40} "
              f"{size//1024:>4} KB  {mtime}")

    # Inbox
    print(f"\n  INBOX ({_FL_INBOX}):")
    inbox_files = list(_flg.glob(f'{_FL_INBOX}/*.json'))
    if inbox_files:
        for path in sorted(inbox_files):
            print(f"    {_flo.path.basename(path)}")
    else:
        print(f"    (empty — place knowledge or hypothesis files here)")

    # Current learning summary
    print(f"\n  THIS DRONE'S LEARNING:")
    print(f"    Configs tried:     {_discovery_state['n_configs_tried']:,}")
    print(f"    Best Ps:           {_discovery_state['best_Ps']:.4f} m/s²")
    print(f"    Discoveries:       {len(_discovery_state.get('discoveries',[]))}")
    print(f"    Hyp evaluations:   {len(_hypothesis_results)}")
    print(f"    Promotions:        "
          f"{sum(1 for r in _hypothesis_results.values() if r.get('promoted'))}")
    print(f"\n  GS: knowledge_export_now — export to outbox")
    print(f"  GS: merge_fleet_knowledge f1.json f2.json ... — merge files")
    print(f"  GS: knowledge_import <path> — import from another drone")


# Register GS commands
_GS_ALLOWED_CMDS.update({
    'gs_inject_hypothesis',
    'gs_inject_parameter',
    'gs_inject_note',
    'inbox_check',
    'knowledge_export_now',
    'knowledge_import',
    'merge_fleet_knowledge',
    'fleet_status',
})


