# ── Focus management ───────────────────────────────────────────────────────────

def set_mission_focus(name_or_phrase, persist=None, custom_scorer=None):
    """
    Install a mission focus directive.
    Reshapes the discovery scorer and seeds relevant hypotheses.

    Parameters
    ----------
    name_or_phrase : str
        Focus name or any plain English phrase.
        e.g. 'gust_tolerance', 'we are flying in gusty conditions',
             'the aircraft is drifting in turbulence'
    persist : bool | None
        Override the focus's default persist setting.
    custom_scorer : callable | None
        Optional custom scorer function. If provided with a new name,
        creates a custom focus.

    Examples (GS / AI):
        focus gust_tolerance
        focus "holding position in turbulence"
        focus endurance
        focus smooth_flight
        focus  (no argument — shows menu)
    """
    st = _focus_state

    # Match name_or_phrase to a focus
    phrase = name_or_phrase.lower().strip()
    matched = None

    # Exact name match
    all_foci = dict(_FOCUS_REGISTRY)
    all_foci.update(st['custom_foci'])
    if phrase in all_foci:
        matched = phrase
    else:
        # Alias match — prefer longer (more specific) aliases
        best_alias_len = 0
        for fname, fdef in all_foci.items():
            for alias in sorted(fdef.get('aliases', []),
                                key=len, reverse=True):
                if alias in phrase or phrase in alias:
                    if len(alias) > best_alias_len:
                        matched = fname
                        best_alias_len = len(alias)
                    break

        # Substring match on name
        if not matched:
            for fname in all_foci:
                if phrase in fname or fname in phrase:
                    matched = fname
                    break

    if not matched:
        print(f"\n  FOCUS: no match for '{name_or_phrase}'")
        focus_menu()
        return False

    fdef = all_foci[matched]
    st['active']         = matched
    st['set_at']         = _mf_time.strftime('%Y-%m-%dT%H:%M:%S')
    st['session_scores'] = []
    st['best_score']     = None
    st['best_config']    = None
    st['n_evals']        = 0
    st['persist']        = persist if persist is not None else fdef.get('persist', False)

    # Set discovery dwell time for this focus
    global DISCOVERY_DWELL_S
    DISCOVERY_DWELL_S = fdef.get('dwell_s', 20.0)

    # Seed relevant hypotheses
    hyp_ids = fdef.get('hypotheses', [])
    if hyp_ids:
        # Prepend focus-relevant hypotheses to queue
        priority_hyps = []
        for h in AERO_HYPOTHESES:
            if h['id'] in hyp_ids:
                priority_hyps.append({
                    'id': h['id'], 'label': h['label'],
                    'target': h['target'], 'config': dict(h['config']),
                    'focus': matched,
                })
        # Add to front of queue
        global _hypothesis_queue
        _hypothesis_queue = priority_hyps + _hypothesis_queue

    # Log
    _pl_append_log({
        'event':       'focus_set',
        'focus':       matched,
        'description': fdef['description'],
        'persist':     st['persist'],
        'dwell_s':     DISCOVERY_DWELL_S,
        'hypotheses':  hyp_ids,
    })

    # Auto-arm kestrel mode when kestrel_hover focus is activated
    if matched == 'kestrel_hover':
        global KW_ENABLED
        KW_ENABLED = True
        print(f"  Kestrel mode ARMED — will auto-engage when updraft detected")

    print(f"\n  MISSION FOCUS SET: {matched.upper()}")
    print(f"  ─────────────────────────────────────────")
    print(f"  {fdef['description']}")
    print(f"  Dwell time:  {DISCOVERY_DWELL_S:.0f}s per config")
    print(f"  Persist:     {st['persist']}")
    if hyp_ids:
        print(f"  Seeded:      {hyp_ids}")
    print(f"\n  Discovery now scores against: {matched}")
    print(f"  GS: focus_status — check progress")
    print(f"  GS: focus clear  — return to Ps scoring")
    return True


def focus_score_tick(sensors, result):
    """
    Called each tick during a discovery dwell.
    Returns the active focus score, or Ps if no focus active.
    Records score history for the current dwell.
    """
    st = _focus_state
    if not st['active']:
        # No focus — return Ps proxy
        return result.get('Ps', 0.0)

    all_foci = dict(_FOCUS_REGISTRY)
    all_foci.update(st['custom_foci'])
    fdef = all_foci.get(st['active'])
    if not fdef:
        return result.get('Ps', 0.0)

    scorer = fdef.get('scorer')
    if callable(scorer):
        score = scorer(sensors, result, st['session_scores'])
    else:
        score = result.get('Ps', 0.0)

    st['session_scores'].append(score)
    st['session_scores'] = st['session_scores'][-200:]

    if st['best_score'] is None or score > st['best_score']:
        st['best_score']  = score
        st['best_config'] = _discovery_state.get('current_config')
        st['n_evals']    += 1

    return score


def focus_clear():
    """Remove active focus — return to Ps scoring."""
    global DISCOVERY_DWELL_S
    _focus_state['active']         = None
    _focus_state['session_scores'] = []
    _focus_state['best_score']     = None
    DISCOVERY_DWELL_S              = 20.0
    _pl_append_log({'event': 'focus_cleared'})
    print("  Focus cleared — scoring returns to Ps (specific excess power)")


def focus_menu():
    """Show all available foci with descriptions."""
    all_foci = dict(_FOCUS_REGISTRY)
    all_foci.update(_focus_state['custom_foci'])
    print(f"\n  AVAILABLE MISSION FOCI")
    print(f"  ─────────────────────────────────────────")
    for name, fdef in all_foci.items():
        active = '●' if name == _focus_state['active'] else ' '
        print(f"  {active} {name:<22} {fdef['description'][:52]}")
    print(f"\n  GS: focus <name>         — activate a focus")
    print(f"  GS: focus clear          — return to Ps scoring")
    print(f"  GS: focus_status         — progress on current focus")
    print(f"  GS: focus_define ...     — define a new custom focus")
    print(f"\n  Or tell the AI assistant: \"focus on gust tolerance\"")
    print(f"  The AI understands any plain English description.")


def focus_status():
    """Show current focus state and progress."""
    st = _focus_state
    if not st['active']:
        print("  No focus active — scoring against Ps (specific excess power)")
        print("  GS: focus  — show available foci")
        return
    print(f"\n  MISSION FOCUS: {st['active'].upper()}")
    print(f"  ─────────────────────────────────────────")
    fdef = dict(_FOCUS_REGISTRY); fdef.update(st['custom_foci'])
    f = fdef.get(st['active'], {})
    print(f"  {f.get('description','')}")
    print(f"  Set at:      {st['set_at']}")
    print(f"  Persist:     {st['persist']}")
    print(f"  Evaluations: {st['n_evals']}")
    if st['session_scores']:
        recent = st['session_scores'][-10:]
        avg = sum(recent) / len(recent)
        print(f"  Recent score:{avg:.4f}  (best: {st['best_score']:.4f})")
    if st['best_config']:
        print(f"  Best config so far: {st['best_config']}")
    print(f"\n  GS: focus clear — remove focus")


def focus_define(name, description='', metric='imu_rms_g',
                  direction='minimize', persist=False):
    """
    Define a new custom focus on any sensor field.
    No code change required.

    Parameters
    ----------
    name        : str   — identifier for this focus
    description : str   — plain English description
    metric      : str   — any sensor field name
    direction   : str   — 'minimize' or 'maximize'
    persist     : bool

    Examples
    --------
    GS: focus_define name=quiet_hover description="minimise motor noise" metric=imu_rms_g direction=minimize
    GS: focus_define name=max_climb description="maximise climb rate" metric=vel_down_ms direction=minimize
    GS: focus_define name=fastest_dart description="maximise yaw rate" metric=yaw_rate_dps direction=maximize
    """
    import functools
    scorer = functools.partial(_score_sensor_metric,
                                metric, direction)
    _focus_state['custom_foci'][name] = {
        'name':        name,
        'description': description or f'{direction} {metric}',
        'aliases':     [name.replace('_',' '), name],
        'scorer':      scorer,
        'hypotheses':  [],
        'param_bias':  {},
        'persist':     persist,
        'dwell_s':     25.0,
    }
    _pl_append_log({
        'event':     'custom_focus_defined',
        'name':      name,
        'metric':    metric,
        'direction': direction,
    })
    print(f"  Custom focus '{name}' defined: {direction} {metric}")
    print(f"  GS: focus {name}  — activate it")


def focus_save():
    """
    Persist the current focus and its best config to disk.
    Called automatically at shutdown if focus.persist=True.
    """
    st = _focus_state
    if not st['active']:
        return
    path = f'{_PL_DIR}/mission_focus.json'
    data = {
        'active':      st['active'],
        'set_at':      st['set_at'],
        'persist':     st['persist'],
        'best_score':  st['best_score'],
        'best_config': st['best_config'],
        'n_evals':     st['n_evals'],
        'custom_foci': {k: {kk: vv for kk, vv in v.items()
                             if kk != 'scorer'}
                        for k, v in st['custom_foci'].items()},
    }
    _pl_write(path, data)
    print(f"  Focus '{st['active']}' saved to disk")


def focus_load():
    """
    Restore a persisted focus at startup.
    Called from persist_load_all().
    """
    path = f'{_PL_DIR}/mission_focus.json'
    data = _pl_read(path)
    if not data:
        return
    name = data.get('active')
    if name and data.get('persist'):
        print(f"  Restoring persisted focus: {name}")
        set_mission_focus(name, persist=True)
        _focus_state['best_score']  = data.get('best_score')
        _focus_state['best_config'] = data.get('best_config')
        _focus_state['n_evals']     = data.get('n_evals', 0)


# ── Wire into persist_save_all and persist_load_all ───────────────────────────
_orig_persist_save_focus = persist_save_all

def persist_save_all(*args, **kwargs):
    result = _orig_persist_save_focus(*args, **kwargs)
    if _focus_state['active'] and _focus_state['persist']:
        focus_save()
    return result

_orig_persist_load_focus = persist_load_all

def persist_load_all(*args, **kwargs):
    result = _orig_persist_load_focus(*args, **kwargs)
    focus_load()
    return result


# ── Wire focus_score_tick into discovery_tick ─────────────────────────────────
# Patch discovery_tick to use the focus scorer when active.

def discovery_tick(Ps_measured, V_ms, h_agl_m, bank_deg,
                    stall_risk, current_time_s,
                    sensors=None, result=None):
    """Extended discovery tick with focus-aware scoring."""
    # Replace Ps with focus score when a focus is active
    effective_Ps = Ps_measured
    if _focus_state['active'] and sensors is not None and result is not None:
        effective_Ps = focus_score_tick(sensors, result)

    return None


# ── Plain English alias function for GS ───────────────────────────────────────
def focus(name_or_phrase=''):
    """
    Set or show mission focus.
    focus                   — show available foci
    focus gust_tolerance    — activate gust tolerance focus
    focus "windy day"       — plain English — matched automatically
    focus clear             — remove current focus
    """
    if not name_or_phrase or name_or_phrase.strip() == '':
        focus_menu()
        return
    if name_or_phrase.strip().lower() == 'clear':
        focus_clear()
        return
    set_mission_focus(name_or_phrase)


# Register GS commands
_GS_ALLOWED_CMDS.update({
    'focus', 'set_mission_focus', 'focus_status', 'focus_menu',
    'focus_clear', 'focus_define', 'focus_save', 'focus_load',
})


# ══════════════════════════════════════════════════════════════════════════════
# STORM RESILIENCE SYSTEM
# ══════════════════════════════════════════════════════════════════════════════
#
# PHILOSOPHY
# ──────────
# Storm survival for a flapping-wing aircraft is not about being stronger
# than the wind. It is about being more adaptive than any fixed-configuration
# aircraft can be. The MCO-1D changes its fundamental aerodynamic character
# 1.87 times per second across 8 independent wing controllers. No fixed-wing
# or rotary platform can approach this adaptation rate.
#
# The strategy has four layers, drawn directly from seabird storm behaviour:
#
#  1. PASSIVE GUST DAMPING via tandem-wing phase selection
#     March 2026 research (MDPI Drones 10/4/231) confirms tandem-wing
#     phase-dependent wake interaction is a passive disturbance attenuation
#     mechanism. The rear pairs already process the front pairs' disturbed
#     wake — the optimal phase for gust damping may differ from the
#     efficiency-optimal phase. Discovery finds it.
#
#  2. FAST KINEMATIC RESPONSE — within one wingbeat
#     Gust detected by IMU → amplitude asymmetry commanded within 10ms.
#     Upwind wing amplitude reduced, downwind wing increased.
#     Restoring moment generated within the SAME half-stroke as the gust.
#     This is faster than any attitude hold PID can respond.
#
#  3. STROKE PLANE TILTING for headwind penetration
#     AoA + sweep coordinated to shift resultant force vector forward.
#     Allows progress against wind speeds approaching Vne.
#     Draws directly from bird storm-penetration kinematics.
#
#  4. LOAD SHEDDING when structural margins are tight
#     W1 pair (largest, highest moment arm) can be stopped under
#     excessive gust loading. Dramatically reduces root bending moment.
#     Aircraft loses thrust but survives the gust. Equivalent to reefing.
#
# STORM CHARACTERISATION PROTOCOL
# ─────────────────────────────────
# Before attempting storm-level testing, the system must characterise:
#   - Wind speed at which attitude hold saturates
#   - Gust magnitude at which position hold becomes unacceptable
#   - Structural loads approaching design limits
#   - Point at which pilot loses meaningful authority
# This data is collected automatically via storm_char_tick() during
# any windy flight and stored in /home/pi/knowledge/storm_data.json.
#
# SAFETY HIERARCHY IN STORM CONDITIONS
# ──────────────────────────────────────
# 1. Structural limits (G_LIMIT, rope loads) — ALWAYS enforced
# 2. Progressive failure (auto land ≤4 wings) — ALWAYS enforced
# 3. Storm resilience control — adapts within limits 1 and 2
# 4. Pilot authority — always preserved throughout
# ══════════════════════════════════════════════════════════════════════════════

import math as _st_math
import time as _st_time

# ── Storm constants ────────────────────────────────────────────────────────────
STORM_GUST_THRESHOLD_MS   = 10.0  # m/s — gust above this triggers fast response
STORM_ROLL_THRESHOLD_DEG  = 15.0  # deg — roll beyond this triggers correction
STORM_G_WARN_THRESHOLD    =  1.8  # g  — gust load warning level
STORM_LOAD_SHED_G         =  2.0  # g  — g-load that triggers W1 load shedding
STORM_FAST_LEG_GAIN       =  0.8  # 0–1 — authority of fast kinematic response
STORM_PHASE_DAMP_DEG      = 45.0  # deg — cascade phase for gust damping mode
STORM_DIHEDRAL_STORM_DEG  =  8.0  # deg — dihedral boost in storm mode
