_orig_persist_save_storm = persist_save_all

def persist_save_all(*args, **kwargs):
    result = _orig_persist_save_storm(*args, **kwargs)
    # Save storm characterisation data
    if any(v > 0 for v in [
        _storm_char['max_gust_ms'],
        _storm_char['n_gust_events'],
    ]):
        storm_path = f'{_PL_DIR}/storm_data.json'
        prev = _pl_read(storm_path) or {'_version': _PL_VERSION, 'flights': []}
        prev['max_gust_ms_ever']    = max(
            prev.get('max_gust_ms_ever', 0.0), _storm_char['max_gust_ms'])
        prev['total_gust_events']   = (
            prev.get('total_gust_events', 0) + _storm_char['n_gust_events'])
        prev['total_load_shed']     = (
            prev.get('total_load_shed', 0) + _storm_char['load_shed_events'])
        prev['flights'].append({
            'ts':              _st_time.strftime('%Y-%m-%dT%H:%M:%S'),
            'max_wind_ms':     _storm_char['max_gust_ms'],
            'max_roll_deg':    _storm_char['max_roll_deg'],
            'max_accel_g':     _storm_char['max_accel_g'],
            'att_sat_wind_ms': _storm_char['attitude_sat_wind_ms'],
            'pos_fail_wind_ms':_storm_char['pos_hold_fail_ms'],
            'struct_warn_ms':  _storm_char['structural_warn_ms'],
        })
        prev['flights'] = prev['flights'][-50:]
        prev['_version'] = _PL_VERSION
        _pl_write(storm_path, prev)
    return result


