# ── Strategy genome tasks for kestrel mechanisms ───────────────────────────────
# The two kestrel-specific tasks are:
#   'kestrel_hover_hold': body-pitched stopped-wing altitude hold in updraft
#   'kestrel_roll_sweep': differential sweep roll correction (kestrel style)
# These are added to _SG_TASKS so the genome system evaluates them.

_SG_TASKS['kestrel_hover_hold'] = {
    'axis':      'pitch',
    'sensor':    'sink_rate_ms',
    'direction': -1,             # minimise sink rate
    'threshold': 0.1,
}
_SG_TASKS['kestrel_roll_sweep'] = {
    'axis':      'roll',
    'sensor':    'roll_rate_dps',
    'direction': +1,             # roll authority via sweep
    'threshold': 15.0,
}


# ── Cross-pollination into other tasks ────────────────────────────────────────

def kestrel_cross_pollinate():
    """
    Seed kestrel discoveries into related strategy genome tasks.

    Kestrel mode discovers the optimal coupled dihedral-sweep synergy for
    maintaining attitude in wind. This synergy is also optimal for:
      - gust_tolerance (same roll/dih coupling, higher disturbance)
      - storm_resilience (headwind penetration uses same body angle control)
      - hover_hold (low-power hover with stability)

    Called automatically after kestrel promotes a niche champion in MAP-Elites.
    """
    # Find any kestrel niche champions
    kw_champions = [(k, v) for k, v in _me_archive.items()
                    if v is not None and
                    v.get('conditions', {}).get('intent') in ('kestrel', 'sar')]
    if not kw_champions:
        return 0

    n_seeded = 0
    for niche_key, cell in kw_champions:
        cfg  = cell.get('config', {})
        score= cell.get('score', 0.0)

        # Build a genome from the kestrel config
        sweep = cfg.get('sweep_deg', 65.0)
        dih   = cfg.get('dihedral_deg', 6.0)
        aoa   = cfg.get('aoa_deg', 20.0)

        # Translate kestrel sweep/dih ratio into mechanism weights
        # High sweep + high dihedral → roll_sweep and roll_dih dominant
        total = sweep + dih
        sw = sweep / max(total, 1.0)
        dw = dih   / max(total, 1.0)
        rw = 1.0 - sw - dw  # remainder to roll_amp

        kw_genome_weights = {
            'roll_amp':   max(0.0, rw),
            'roll_sweep': sw * 0.8,
            'roll_aoa':   0.0,
            'roll_phase': 0.0,
            'roll_dih':   dw * 0.8 + sw * 0.2,
        }
        # Normalise
        total_w = sum(kw_genome_weights.values())
        if total_w > 0:
            kw_genome_weights = {k: round(v/total_w, 4)
                                 for k, v in kw_genome_weights.items()}

        # Seed into related tasks as operator ideas with kestrel source
        for task in ['hover_hold', 'kestrel_hover_hold']:
            g = _sg_make_genome(
                task,
                roll_w  = kw_genome_weights,
                source  = 'kestrel_xpoll',
            )
            g['score']         = score * 0.85  # discount — different task
            g['operator_note'] = (f'Cross-pollinated from kestrel niche '
                                   f'{_me_niche_label(niche_key)}')
            # Place in archive directly if better than current
            v_idx, w_idx, _ = niche_key
            sg_niche = (task, v_idx, w_idx)
            current  = _sg_archive.get(sg_niche)
            if current is None or g['score'] > current['score']:
                _sg_archive[sg_niche] = g
                n_seeded += 1

    if n_seeded > 0:
        _pl_append_log({
            'event':   'kestrel_cross_pollination',
            'n_seeded': n_seeded,
        })
    return n_seeded


# ── Patch me_promote to trigger cross-pollination ─────────────────────────────

def _me_promote(config, score, niche_key, source='discovery',
                conditions=None, operator_note=''):
    """Patched promote — triggers kestrel cross-pollination on kestrel wins."""
    won = None
    if won and source in ('kestrel_hover', 'operator') and KW_ENABLED:
        try:
            n = kestrel_cross_pollinate()
            if n > 0:
                print(f"  Kestrel cross-pollination: {n} related tasks seeded")
        except Exception:
            pass
    return won


