# ── Gap negotiation state machine ──────────────────────────────────────────────

def gap_set_width(width_m):
    """
    Tell the aircraft how wide the gap is.
    GS: gap_set_width 0.6
    AI: 'the gap is 60 centimetres wide' / 'about half a metre opening'
    """
    w = float(width_m)
    _gap_state['gap_width_m'] = w
    span = ACC_FULL_SPAN_M

    if w < ACC_MIN_BALLISTIC_GAP_M:
        print(f"\n  Gap width: {w:.2f}m — IMPASSABLE")
        print(f"  Minimum body width is {ACC_FUSELAGE_WIDTH_M:.2f}m. This gap is too narrow.")
        return

    ratio = w / span
    if ratio < ACC_TUCK_THRESHOLD:
        mode = 'ballistic'
        desc = f"Ballistic tuck — wings fully swept, body coasts through"
    elif ratio < ACC_SIDEWAYS_THRESHOLD:
        mode = 'sideways'
        desc = f"Sideways passage — body rolls 90°, asymmetric wing sweep"
    else:
        mode = 'flap'
        desc = f"Continuous flapping with upstroke phase management"

    _gap_state['mode'] = mode
    print(f"\n  Gap width: {w:.2f}m  (wingspan ratio: {ratio:.2f}×)")
    print(f"  Strategy: {mode.upper()} — {desc}")
    print(f"  Effective passage span: "
          f"{'body only ~0.15m' if mode=='ballistic' else '~0.45m swept' if mode=='sideways' else '~0.55m upstroke'}")
    print(f"\n  GS: gap_enter — begin gap approach and passage")
    print(f"  GS: gap_abort  — cancel and return to normal flight")


def gap_enter(sensors=None, result=None):
    """
    Begin gap negotiation sequence.
    Must call gap_set_width first.
    GS: gap_enter
    AI: 'go through the gap' / 'enter the building' / 'fly through the opening'
    """
    st = _gap_state
    if st['gap_width_m'] is None:
        print("  Set gap width first: GS: gap_set_width [metres]")
        return
    if st['gap_width_m'] < ACC_MIN_BALLISTIC_GAP_M:
        print("  Gap too narrow — cannot enter.")
        return

    import time as _gt
    st['active']  = True
    st['phase']   = 'approach'
    st['start_t'] = _gt.monotonic()

    mode = st['mode']
    print(f"\n  GAP NEGOTIATION STARTING — mode: {mode.upper()}")
    if mode == 'ballistic':
        print(f"  Sweeping wings fully aft, stopping flapping...")
        print(f"  Aircraft will coast through on current airspeed.")
        print(f"  IMPORTANT: maintain approach speed 6–12 m/s for clearance.")
        _gap_ballistic_enter()
    elif mode == 'sideways':
        print(f"  Rolling body 90°, asymmetric wing sweep...")
        print(f"  Approach speed: 4–8 m/s.")
        _gap_sideways_enter()
    else:
        print(f"  Engaging upstroke phase hold...")
        print(f"  Approach speed: 4–10 m/s. Wings will hold at upstroke.")
        _gap_flap_enter()

    print(f"  GS: gap_status — monitor passage")
    print(f"  GS: gap_abort  — abort and recover")


def _gap_ballistic_enter():
    """Engage H-ACC-4: full sweep, wings stopped."""
    _manoeuvre_state['active'] = 'gap_ballistic'
    _gap_state['stability_mode'] = 'stable_tuck'
    _pl_append_log({'event': 'gap_ballistic_enter',
                     'gap_m': _gap_state['gap_width_m']})


def _gap_sideways_enter():
    """Engage H-ACC-3: body roll + asymmetric sweep."""
    _manoeuvre_state['active'] = 'gap_sideways'
    _gap_state['stability_mode'] = 'stable_tuck'
    _pl_append_log({'event': 'gap_sideways_enter',
                     'gap_m': _gap_state['gap_width_m']})


def _gap_flap_enter():
    """Engage H-ACC-2: upstroke phase hold."""
    _manoeuvre_state['active'] = 'gap_flap'
    _gap_state['stability_mode'] = 'normal'
    _pl_append_log({'event': 'gap_flap_enter',
                     'gap_m': _gap_state['gap_width_m']})


def gap_abort():
    """
    Abort gap negotiation and recover to normal flight.
    GS: gap_abort
    AI: 'abort / stop / come back'
    """
    _gap_state['active']       = False
    _gap_state['phase']        = 'idle'
    _gap_state['stability_mode']= 'normal'
    _manoeuvre_state['active'] = None
    print("  Gap negotiation aborted. Recovering to normal flight.")
    print("  Wings will return to cruise configuration.")


def gap_status():
    """
    GS: gap_status
    Show current gap negotiation state.
    """
    st = _gap_state
    print(f"\n  GAP NEGOTIATION STATUS")
    print(f"  ─────────────────────────────────────────")
    print(f"  Active:        {st['active']}")
    print(f"  Gap width:     {st['gap_width_m']}m")  if st['gap_width_m'] else print(f"  Gap width:     not set")
    print(f"  Mode:          {st['mode'] or 'not set'}")
    print(f"  Phase:         {st['phase']}")
    print(f"  Stability:     {st['stability_mode']}")
    print(f"\n  GAP STRATEGY GUIDE:")
    print(f"  Gap > 0.55m    → Flapping passage (upstroke phase management)")
    print(f"  Gap 0.20–0.55m → Sideways passage (body rolls, wings asymmetric)")
    print(f"  Gap 0.15–0.20m → Ballistic tuck (wings stopped, coasts through)")
    print(f"  Gap < 0.15m    → IMPASSABLE (narrower than body)")
    print(f"\n  GS: gap_set_width [m]  — specify the gap")
    print(f"  GS: gap_enter          — begin passage")
    print(f"  GS: gap_abort          — abort and recover")


# ── Canopy approach ────────────────────────────────────────────────────────────

def canopy_approach(target_lat=None, target_lon=None, target_alt_m=5.0):
    """
    Begin accipiter-style canopy approach to a point in a complex environment.
    Uses flap-flap-glide profile, decelerates to hover above target.
    GS: canopy_approach [lat] [lon] [alt_m]
    AI: 'approach through the trees' / 'fly in under the canopy' /
        'descend to that clearing'
    """
    set_mission_focus('sar_hover')
    seed_hypotheses(V_ms=9.0, phase='approach')
    _pl_append_log({'event': 'canopy_approach_start',
                     'lat': target_lat, 'lon': target_lon,
                     'alt_m': target_alt_m})
    print(f"\n  CANOPY APPROACH ENGAGED")
    print(f"  ─────────────────────────────────────────")
    print(f"  Strategy: accipiter flap-flap-glide profile")
    print(f"  W3+W4 stopped at neutral AoA — fixed-wing lift during glide phases")
    print(f"  Rear pair wing loading absorbed by front two pairs")
    print(f"  Terminal: decelerate to hover {target_alt_m:.0f}m above target")
    print(f"\n  H-ACC-5 (canopy approach) and H-ACC-6 (perch land) seeded")
    print(f"  Discovery learning during approach will refine the profile")
    print(f"\n  GS: perch_land — once overhead target, descend to surface")
    print(f"  GS: gap_enter  — if a gap must be negotiated en route")


def perch_land():
    """
    Descend vertically to a complex surface from hover.
    Uses position hold + vertical descent rate, tolerates slope.
    GS: perch_land
    AI: 'land here' / 'set it down' / 'land on that ledge' /
        'land in the clearing'
    """
    _pl_append_log({'event': 'perch_land_start'})
    print(f"\n  PERCH LANDING SEQUENCE")
    print(f"  ─────────────────────────────────────────")
    print(f"  GPS position hold engaged (horizontal axes)")
    print(f"  Vertical descent: 0.3 m/s (slow — sensor-limited)")
    print(f"  Attitude: levelled to surface via hover trim")
    print(f"  Wing configuration: H-ACC-6 (high dihedral, SAR hover)")
    print(f"\n  The aircraft will descend until contact is sensed")
    print(f"  or until manual stop command.")
    print(f"\n  GS: confined_exit — after landing, to climb out vertically")
    print(f"  GS: abort         — stop descent, hold hover")


def confined_exit(clear_height_m=15.0):
    """
    Pop-up vertical climb from a confined landing position.
    Front wings only (H-ACC-7), minimum span configuration until clear.
    GS: confined_exit [height_m]
    AI: 'get out' / 'climb out' / 'exit the clearing' /
        'take off from here'
    """
    _pl_append_log({'event': 'confined_exit_start', 'clear_m': clear_height_m})
    print(f"\n  CONFINED EXIT — VERTICAL POP-UP")
    print(f"  ─────────────────────────────────────────")
    print(f"  Front wings (W1+W2) at maximum hover power")
    print(f"  Rear wings (W3+W4) stopped — minimum span for clearance")
    print(f"  Effective span during climb: ~0.45m (front pairs only)")
    print(f"  Target clear height: {clear_height_m:.0f}m AGL")
    print(f"  Once clear: rear wings resume, full span restores")
    print(f"\n  This is the H-ACC-7 manoeuvre (confined exit).")
    print(f"  Position hold maintains horizontal station throughout.")


