# ── 5. Phase-aware scorer extension for clap ──────────────────────────────────

def _score_clap_hover(sensors, result):
    """
    Score clap-and-fling hover quality.
    Primary metric: position hold error (lower = better).
    Secondary metric: bonus for validated clap events.
    """
    pos_err  = sensors.get('ph_pos_err_m', 1.0)
    clap_cnt = result.get('wc_clap_count', 0)
    min_sep  = result.get('wc_min_sep_m', 0.5)

    # Position hold quality (main score)
    pos_score = max(0.0, 1.0 - pos_err / 1.0)

    # Clap bonus: reward validated clap events (indicates gate timing correct)
    clap_bonus = min(0.3, clap_cnt * 0.05)

    # Safety penalty: tip separation too close without gate
    if min_sep < 0.010 and not _wc_state.get('clap_gate_open'):
        safety_penalty = 0.5
    else:
        safety_penalty = 0.0

    return round(max(0.0, pos_score + clap_bonus - safety_penalty), 4)


# Patch _phase_score to use clap scorer in hover when gate is open

def _phase_score(sensors, result):
    """Extended phase scorer — uses clap scorer during hover with gate open."""
    if (_wc_state.get('clap_gate_open') and
            _detect_flight_phase(sensors, result) == PHASE_HOVER):
        return _score_clap_hover(sensors, result)
    return None


