def _phase_score(sensors, result):
    """Extended phase scorer — routes sprint and accelerate to top_speed_Ps."""
    phase = _detect_flight_phase(sensors, result)
    V_ms  = sensors.get('V_ms', 0.0)

    # If in sprint/accelerate AND focus is top_speed or fast_cruise,
    # use the speed-biased scorer regardless of clap state
    active_focus = _focus_state.get('active')
    if phase in (PHASE_ACCELERATE,) or V_ms > HS_SPRINT_ENTRY_V:
        if active_focus in ('top_speed', 'sprint', 'fast_cruise'):
            if V_ms > HS_HIGH_SPEED_V:
                return _score_top_speed_Ps(sensors, result)
            else:
                return _score_fast_cruise(sensors, result)

    return None


