# ── Phase scorer: route climb phase to ROC scorer ─────────────────────────────

def _phase_score(sensors, result):
    """Extended phase scorer — climb phase uses ROC or angle scorer."""
    phase        = _detect_flight_phase(sensors, result)
    active_focus = _focus_state.get('active')

    if phase == PHASE_CLIMB:
        if active_focus == 'best_climb_angle':
            return _score_best_angle(sensors, result)
        elif active_focus in ('best_climb_rate', 'sar_hover'):
            return _score_best_ROC(sensors, result)
        else:
            # Default climb scoring: best ROC
            return _score_best_ROC(sensors, result)

    return None


