def strouhal_status():
    """GS: strouhal_status — current Strouhal number and optimal range."""
    import math as _sm
    print(f"\n  STROUHAL NUMBER STATUS")
    print(f"  ─────────────────────────────────────────")
    print(f"  St = f × A / V  (optimal range: 0.20–0.40)")
    print(f"  At current cruise: freq={_lb_state.get('lb_freq_hz',1.87):.2f} Hz")
    # Can't compute without live V_ms; show table
    for V in [7, 9, 12, 15, 18, 22, 28]:
        freq = 1.87; amp_deg = 96.0
        import math
        stroke_m = 2 * 0.772 * math.sin(math.radians(amp_deg/2))
        St = freq * stroke_m / V
        flag = '← optimal' if 0.20 <= St <= 0.40 else ''
        print(f"    V={V:>3} m/s: St={St:.3f}  {flag}")


