# ── KNOWLEDGE I/O ─────────────────────────────────────────────────────────────

_KNOWLEDGE_DIR = '/home/pi/knowledge'

def knowledge_export(dest_path=None):
    """
    GS: knowledge_export [path]
    Export the full knowledge base (MAP-Elites archive + genome weights) to JSON.
    Default path: /home/pi/knowledge/export_TIMESTAMP.json
    """
    import time as _kt
    ts = int(_kt.time())
    path = dest_path or f'{_KNOWLEDGE_DIR}/export_{ts}.json'
    payload = {
        'timestamp':        ts,
        'hypotheses_count': len(AERO_HYPOTHESES),
        'focus_registry':   list(_FOCUS_REGISTRY.keys()),
        'alss_curriculum':  {k: len(v) for k, v in _ALSS_CURRICULUM.items()},
        'pl_state_keys':    list(_pl_state.keys()),
        'note':             'Full archive export — champion configs not serialised here',
    }
    try:
        _os.makedirs(_KNOWLEDGE_DIR, exist_ok=True)
        with open(path, 'w') as f:
            _json.dump(payload, f, indent=2)
        _pl_append_log({'event': 'knowledge_export', 'path': path})
        print(f"\n  Knowledge exported to: {path}")
    except Exception as e:
        print(f"\n  Export failed: {e}")
        print(f"  Check that {_KNOWLEDGE_DIR} exists on the Pi.")


def knowledge_export_usb():
    """GS: knowledge_export_usb — export knowledge base to USB drive if mounted."""
    usb_paths = ['/media/pi', '/mnt/usb', '/run/media']
    for base in usb_paths:
        if _os.path.exists(base):
            knowledge_export(f'{base}/mco1d_knowledge_export.json')
            return
    print("  No USB drive found at standard mount points.")
    print("  Mount USB and retry, or use: GS: knowledge_export [path]")


def knowledge_import_usb():
    """GS: knowledge_import_usb — import knowledge base from USB drive."""
    usb_paths = ['/media/pi', '/mnt/usb', '/run/media']
    for base in usb_paths:
        candidate = f'{base}/mco1d_knowledge_export.json'
        if _os.path.exists(candidate):
            try:
                with open(candidate) as f:
                    data = _json.load(f)
                _pl_append_log({'event': 'knowledge_import_usb', 'path': candidate})
                print(f"  Imported from: {candidate}")
                print(f"  Timestamp: {data.get('timestamp', 'unknown')}")
                print(f"  Note: champion configs require full archive import.")
                return
            except Exception as e:
                print(f"  Import failed: {e}")
                return
    print("  No knowledge file found on USB.")


def knowledge_auto_export():
    """GS: knowledge_auto_export — toggle automatic export after each sortie."""
    current = _pl_state.get('auto_export_enabled', False)
    _pl_state['auto_export_enabled'] = not current
    state = 'ENABLED' if not current else 'DISABLED'
    print(f"  Auto-export {state}. Knowledge saved after each ALSS sortie.")


