def inject_hypothesis(hyp_id=None):
    """GS: inject_hypothesis [id] — trigger immediate evaluation of a hypothesis."""
    if not hyp_id:
        print("  Usage: inject_hypothesis [hypothesis_id]")
        print("  Available IDs: " + ', '.join(h['id'] for h in AERO_HYPOTHESES[:8]) + '…')
        return
    hyp = next((h for h in AERO_HYPOTHESES if h['id'] == hyp_id), None)
    if not hyp:
        print(f"  Hypothesis {hyp_id} not found.")
        return
    _pl_append_log({'event': 'inject_hypothesis', 'id': hyp_id})
    print(f"  Hypothesis {hyp_id} queued for immediate evaluation.")
    print(f"  Label: {hyp['label']}")


def inject_hypothesis_file(path=None):
    """GS: inject_hypothesis_file [path] — load and register hypotheses from JSON file."""
    if not path:
        print("  Usage: inject_hypothesis_file [path]")
        return
    try:
        with open(path) as f:
            data = _json.load(f)
        count = 0
        for h in data.get('hypotheses', []):
            if h.get('id') and not any(x['id'] == h['id'] for x in AERO_HYPOTHESES):
                AERO_HYPOTHESES.append(h)
                count += 1
        print(f"  Loaded {count} new hypotheses from {path}.")
    except Exception as e:
        print(f"  Failed to load: {e}")


