# Stub implementations — full procedures in Commissioning Manual v20
# These must be expanded with actual checklist logic before TC-01 execution

_tc_state = {
    'current_tc': None,
    'phase':      'idle',
    'step':       0,
    'results':    {},
}

def _tc_generic(tc_id, action):
    st = _tc_state
    if action == 'start':
        st['current_tc'] = tc_id
        st['phase']      = 'running'
        st['step']       = 1
        _pl_append_log({'event': f'{tc_id}_start'})
        print(f"\n  TEST CARD {tc_id.upper()} — STARTED")
        print(f"  See Commissioning Manual v20 for full procedure.")
        print(f"  GS: {tc_id}_status — check progress")
        print(f"  GS: {tc_id}_confirm — advance to next step")
        print(f"  GS: {tc_id}_abort   — abort test")
    elif action == 'status':
        print(f"\n  TEST CARD {tc_id.upper()} STATUS")
        print(f"  Current TC: {st.get('current_tc', 'none')}")
        print(f"  Phase:      {st.get('phase', 'idle')}")
        print(f"  Step:       {st.get('step', 0)}")
    elif action in ('confirm', 'continue'):
        st['step'] += 1
        _pl_append_log({'event': f'{tc_id}_step', 'step': st['step']})
        print(f"  Step {st['step']} confirmed. Advancing.")
    elif action == 'abort':
        st['phase'] = 'aborted'
        _pl_append_log({'event': f'{tc_id}_abort'})
        print(f"  TEST CARD {tc_id.upper()} ABORTED.")

def tc01_start():    _tc_generic('tc01', 'start')
def tc01_status():   _tc_generic('tc01', 'status')
def tc01_confirm():  _tc_generic('tc01', 'confirm')
def tc01_abort():    _tc_generic('tc01', 'abort')

