# ── Phase scorer: precision ───────────────────────────────────────────────────

def _phase_score(sensors, result):
    """Phase scorer — uses combined precision scorer when focus is precision."""
    if _focus_state.get('active') == 'precision':
        phase = _detect_flight_phase(sensors, result)
        if phase in (PHASE_CRUISE, PHASE_DESCENT):
            return _score_precision_combined(sensors, result)
    return None


# ── MAP-Elites: precision intent bins ────────────────────────────────────────

def vsi_hold(target_fpm=0.0):
    """
    GS: vsi_hold [fpm]
    Set the VSI hold target in ft/min. 0 = altitude hold.
    Positive = climbing, negative = descending.
    GS: vsi_hold 0       → altitude hold
    GS: vsi_hold -100    → 100 ft/min descent (water approach)
    GS: vsi_hold  200    → 200 ft/min climb
    AI: 'hold this descent rate' / '100 ft/min down' / 'altitude hold'
    """
    target_ms = float(target_fpm) * 0.00508
    _prec['vsi_target_ms'] = target_ms
    _prec['vsi_active']    = True
    _prec['vsi_err_int']   = 0.0
    _pl_append_log({'event': 'vsi_hold', 'target_fpm': target_fpm,
                     'target_ms': target_ms})
    sign = '+' if target_fpm >= 0 else ''
    desc = ('altitude hold' if target_fpm == 0
            else f'{abs(target_fpm):.0f} ft/min '
                 + ('climb' if target_fpm > 0 else 'descent'))
    print(f"\n  VSI HOLD SET: {sign}{target_fpm:.0f} ft/min ({target_ms:+.3f} m/s)")
    print(f"  Mode: {desc}")
    print(f"  Multi-beat averaging: {PREC_AVG_SAMPLES} samples ({PREC_AVG_SAMPLES/50:.1f}s)")


def track_hold():
    """
    GS: track_hold
    Capture the current heading as the track reference.
    Aircraft will maintain this heading hands-off.
    AI: 'hold this heading' / 'track here' / 'maintain heading'
    """
    _prec['hdg_target_deg']   = None   # will capture on next stable tick
    _prec['hdg_stable_ticks'] = 0
    _prec['hdg_active']       = False
    _pl_append_log({'event': 'track_hold_arm'})
    print(f"  Track hold arming. Current heading will be captured after 1 second.")
    print(f"  Keep controls neutral. Hold will engage automatically.")


def precision_status():
    """
    GS: precision_status
    Full precision hold status — VSI, heading, IAS accuracy.
    AI: 'precision status' / 'how accurate is the altitude hold'
        'what is the VSI error' / 'heading accuracy'
    """
    st = _prec
    vsi_fpm = st['vsi_rms_ms'] / 0.00508
    ias_kt  = st['ias_rms_ms'] / 0.514444

    def status_str(rms, limit, unit):
        pct = rms / limit * 100
        flag = '✓ IN SPEC' if rms < limit else '✗ OUTSIDE SPEC'
        return f"{rms:.3f}{unit} ({pct:.0f}% of limit)  {flag}"

    print(f"\n  PRECISION FLIGHT STATUS")
    print(f"  ─────────────────────────────────────────")
    print(f"  VSI hold:     {status_str(st['vsi_rms_ms'], PREC_VSI_LIMIT_MS, 'm/s')}")
    print(f"                = ±{vsi_fpm:.1f} ft/min  (limit: ±{PREC_VSI_LIMIT_MS/0.00508:.0f} ft/min)")
    print(f"  Heading hold: {status_str(st['hdg_rms_deg'], PREC_HDG_LIMIT_DEG, '°')}")
    print(f"  IAS hold:     {status_str(st['ias_rms_ms'], PREC_IAS_LIMIT_MS, 'm/s')}")
    print(f"                = ±{ias_kt:.2f} kt  (limit: ±{PREC_IAS_LIMIT_MS/0.514444:.1f} kt)")
    print(f"\n  HOLD STATES:")
    print(f"  VSI:     {'active — target ' + str(round(st['vsi_target_ms']/0.00508,0)) + ' ft/min' if st['vsi_active'] else 'inactive (pilot flying VSI)'}")
    print(f"  Heading: {'active — target ' + str(round(st['hdg_target_deg'],1)) + '°' if st['hdg_active'] and st['hdg_target_deg'] else 'inactive'}")
    print(f"  IAS:     {'active — target ' + str(round(st['ias_target_ms']/0.514444,1)) + ' kt' if st['ias_active'] and st['ias_target_ms'] else 'inactive'}")
    print(f"  Track:   {'active' if st['track_active'] else 'inactive'}")
    print(f"\n  OVERALL: {'✓ ALL IN SPEC' if st['vsi_rms_ms'] < PREC_VSI_LIMIT_MS and st['hdg_rms_deg'] < PREC_HDG_LIMIT_DEG and st['ias_rms_ms'] < PREC_IAS_LIMIT_MS else '✗ ONE OR MORE AXES OUTSIDE SPEC'}")
    print(f"\n  Water approach: {'ARMED' if st['water_approach'] else 'not armed'}")
    print(f"\n  GS: vsi_hold [fpm]  — set VSI target")
    print(f"  GS: track_hold      — capture current heading")
    print(f"  GS: water_approach_arm — arm seaplane approach mode")


def water_approach_arm():
    """
    GS: water_approach_arm
    Arm the seaplane water approach mode.
    Tightens VSI PID gain below 50m AGL.
    Sets VSI target to -100 ft/min (0.508 m/s descent).
    AI: 'water approach' / 'seaplane approach' / 'fly the approach'
    """
    _prec['water_approach'] = True
    vsi_hold(-100.0)   # 100 ft/min descent
    set_mission_focus('precision')
    _pl_append_log({'event': 'water_approach_arm'})
    print(f"\n  WATER APPROACH ARMED")
    print(f"  VSI target: -100 ft/min (-0.508 m/s)")
    print(f"  PID gain tightens automatically below 50m AGL")
    print(f"  Precision focus engaged")
    print(f"  GS: precision_status — monitor VSI accuracy on approach")


def water_approach_abort():
    """
    GS: water_approach_abort
    Abort water approach, return to normal flight.
    """
    _prec['water_approach'] = False
    _prec['vsi_target_ms']  = 0.0   # altitude hold
    focus_clear()
    _pl_append_log({'event': 'water_approach_abort'})
    print(f"  Water approach aborted. Altitude hold restored.")


_GS_ALLOWED_CMDS.update({
    'vsi_hold', 'track_hold', 'precision_status',
    'water_approach_arm', 'water_approach_abort',
})


# ══════════════════════════════════════════════════════════════════════════════
# PRECISION FLIGHT — CORRECTION
#
# The previous precision_hold_tick implemented three PIDs that actively
# corrected VSI, heading, and IAS to compensate for disturbances.
# This is autopilot behaviour. It is wrong for this aircraft at this stage.
#
# WHAT WAS WRONG AND WHY
# ────────────────────────
# The PIDs fought environmental disturbances — gusts, thermals, wind shear.
# These are exactly what the pilot is supposed to feel and correct.
# Taking that authority from the pilot makes the aircraft harder to fly
# in the conditions that matter, not easier.
#
# The seaplane approach gain tightening was additionally wrong in reasoning:
# more aggressive correction near the water produces oscillation in turbulence,
# not stability. A conventional approach philosophy reduces correction authority
# near the surface and lets the pilot fly it.
#
# WHAT IS CORRECT
# ─────────────────
# Think of a fixed-pitch propeller at constant throttle and mixture:
#   - In calm air: consistent thrust → consistent climb/descent/cruise
#   - In a gust: thrust unchanged, aircraft pitches/rolls → pilot corrects
#   - The engine does not sense the gust and compensate — the pilot does
#
# The flapping wing's equivalent problem is the stroke pulsation at 3.74 Hz.
# This is internal variation — not environmental. A 5-beat rolling average
# cancels it completely, leaving the pilot a smooth, readable instrument.
# That is the ONLY thing the software should do automatically.
#
# WHAT THIS SYSTEM DOES INSTEAD
# ───────────────────────────────
# 1. STROKE SMOOTHING: rolling average over 5 wingbeats for VSI and IAS.
#    Displayed to pilot. Not acted on by software.
#
# 2. TRIM CHARACTERISATION: measures the residual VSI, heading drift, and
#    IAS variation at neutral controls in calm conditions. This becomes the
#    precision scorer — low residual variation = good trim = high score.
#    The genome learns what wing configuration minimises residual variation.
#
# 3. STROKE SYMMETRY ENFORCEMENT: port and starboard amplitudes are held
#    equal at the commanded value. A 0.1° asymmetry produces measurable
#    yaw torque at 1.87 Hz. This is trim, not autopilot — it is correcting
#    an internal asymmetry, not an external disturbance.
#
# 4. DISPLAY OUTPUTS: smooth VSI in ft/min, smooth IAS in knots, heading,
#    roll, pitch — all displayed to pilot. The pilot acts on these.
#
# SEAPLANE APPROACH
# ──────────────────
# The aircraft produces a consistent sink rate for a given lever + AoA,
# identical to a conventional aircraft at constant power and attitude.
# The pilot sets the rate they want and monitors the (smooth) VSI.
# No special gain tightening. Same behaviour as cruise. The pilot flies it.
#
# PRECISION SCORING
# ──────────────────
# The precision focus now scores LOW RESIDUAL VARIATION in trim conditions.
# The genome learns the configuration that is easiest to fly precisely —
# not the configuration that makes precision look good via hidden correction.
# ══════════════════════════════════════════════════════════════════════════════

import collections as _psm_collections
import math as _psm_math

# ── Stroke-smoothing state ─────────────────────────────────────────────────────
# Rolling buffers — display only, not acted on by software

_PSM_BEATS       = 5        # wingbeats to average over
_PSM_SAMPLE_HZ   = 50.0    # control loop rate
_PSM_BEAT_HZ     = 1.87    # nominal flap frequency
_PSM_SAMPLES     = int(_PSM_SAMPLE_HZ / _PSM_BEAT_HZ * _PSM_BEATS)  # ~134 samples

_psm = {
    'vsi_buf':     _psm_collections.deque(maxlen=_PSM_SAMPLES),
    'ias_buf':     _psm_collections.deque(maxlen=_PSM_SAMPLES),
    'roll_buf':    _psm_collections.deque(maxlen=_PSM_SAMPLES),
    'heading_buf': _psm_collections.deque(maxlen=_PSM_SAMPLES),

    # Smoothed display values (what the instruments show)
    'vsi_smooth_ms':   0.0,
    'vsi_smooth_fpm':  0.0,
    'ias_smooth_ms':   0.0,
    'ias_smooth_kt':   0.0,
    'roll_smooth_deg': 0.0,

    # Trim quality — residual variation at neutral controls (calm air)
    # Measured as RMS over the smoothing window
    'vsi_rms_ms':      0.0,   # how much VSI varies around its mean
    'ias_rms_ms':      0.0,
    'roll_rms_deg':    0.0,

    # Whether controls are currently neutral (trim measurement valid)
    'controls_neutral': False,
    'neutral_ticks':    0,
}

# How long controls must be neutral before trim is measured
_PSM_NEUTRAL_TICKS = int(_PSM_SAMPLE_HZ * 3.0)   # 3 seconds


def _enforce_stroke_symmetry(result):
    """
    Enforce port = starboard amplitude on each wing pair.
    Corrects internal hardware asymmetry (manufacturing tolerance,
    servo calibration drift). Does not compensate for external forces.
    Called from within wing_guard_tick — runs before ODrive output.
    """
    wc = result.get('wing_commands', [{}] * 8)
    for pair in range(4):
        port_idx = 2 * pair
        stbd_idx = 2 * pair + 1
        if port_idx >= len(wc) or stbd_idx >= len(wc):
            continue
        port_amp = wc[port_idx].get('flap_amp_deg', 96.0)
        stbd_amp = wc[stbd_idx].get('flap_amp_deg', 96.0)
        # Mean of commanded amplitudes — both get the mean
        # (If the pilot commanded different amplitudes for a manoeuvre,
        # the MIC/CIC has already set them. This only equalises residual
        # hardware drift, measured as systematic asymmetry over >3 seconds.)
        if st := _psm:
            if not st['controls_neutral']:
                continue   # only enforce symmetry in trim — not during manoeuvre
        mean_amp = (port_amp + stbd_amp) / 2.0
        wc[port_idx]['flap_amp_deg'] = mean_amp
        wc[stbd_idx]['flap_amp_deg'] = mean_amp
    result['wing_commands'] = wc


# ── Replace precision_hold_tick with stroke_smoothing_tick ────────────────────
# The old precision_hold_tick (autopilot PIDs) is replaced.
# position_hold_tick already wraps _orig_position_hold_tick_prec.
# We need to rewire it to call stroke_smoothing_tick instead.


def _score_vsi_precision(sensors, result, history=None):
    """
    VSI precision score — how little the VSI varies in trim.
    Measured as RMS of the smoothed VSI around its mean.
    A well-trimmed aircraft has low variation.
    A poorly trimmed aircraft oscillates even in calm air.
    """
    rms = _psm.get('vsi_rms_ms', PREC_VSI_LIMIT_MS)
    if not _psm.get('controls_neutral', False):
        return 0.0   # only score when trimmed / hands-off
    return round(max(0.0, 1.0 - rms / PREC_VSI_LIMIT_MS), 4)


def _score_heading_precision(sensors, result, history=None):
    """
    Heading precision score — how little roll varies in trim.
    Roll variation at neutral controls indicates yaw-roll coupling
    from cascade asymmetry. The genome tunes this out.
    """
    rms = _psm.get('roll_rms_deg', PREC_ROLL_LIMIT_DEG)
    if not _psm.get('controls_neutral', False):
        return 0.0
    return round(max(0.0, 1.0 - rms / PREC_ROLL_LIMIT_DEG), 4)


def _score_ias_precision(sensors, result, history=None):
    """
    IAS precision score — how little airspeed varies at constant lever.
    Driven by power-smoothing cascade (H-30) — staggered peak forces
    produce more constant thrust than all-at-once peaks.
    """
    rms = _psm.get('ias_rms_ms', PREC_IAS_LIMIT_MS)
    if not _psm.get('controls_neutral', False):
        return 0.0
    return round(max(0.0, 1.0 - rms / PREC_IAS_LIMIT_MS), 4)


def _score_trim_quality(sensors, result, history=None):
    """Combined trim quality — geometric mean of all three axes in trim."""
    if not _psm.get('controls_neutral', False):
        return 0.0
    vsi_s = _score_vsi_precision(sensors, result)
    hdg_s = _score_heading_precision(sensors, result)
    ias_s = _score_ias_precision(sensors, result)
    return round((vsi_s * hdg_s * ias_s) ** (1.0/3.0), 4)


def _score_precision_combined(sensors, result, history=None):
    """Combined precision score. Only valid during hands-off trim."""
    return _score_trim_quality(sensors, result, history)


def _score_water_approach(sensors, result, history=None):
    """
    Water approach score — same as VSI precision.
    No special tightening. Same behaviour as cruise.
    The pilot flies the rate. The aircraft holds trim.
    """
    return _score_vsi_precision(sensors, result, history)


# ── Revised precision_status ──────────────────────────────────────────────────

def precision_status():
    """
    GS: precision_status
    Display stroke-smoothed instruments and trim quality.
    """
    st = _psm
    vsi_fpm  = st['vsi_smooth_fpm']
    ias_kt   = st['ias_smooth_kt']
    roll_deg = st['roll_smooth_deg']

    def within(rms, limit):
        return '✓' if rms < limit else '✗'

    print(f"\n  PRECISION INSTRUMENTS (5-beat average)")
    print(f"  ─────────────────────────────────────────")
    print(f"  VSI:     {vsi_fpm:+.1f} ft/min  ({st['vsi_smooth_ms']:+.3f} m/s)")
    print(f"  IAS:     {ias_kt:.1f} kt  ({st['ias_smooth_ms']:.2f} m/s)")
    print(f"  Roll:    {roll_deg:+.2f}°")
    print(f"\n  TRIM QUALITY (measured hands-off in calm air)")
    print(f"  Controls neutral: {st['controls_neutral']}")
    if st['controls_neutral']:
        vrms = st['vsi_rms_ms']; vrms_fpm = vrms / 0.00508
        rrms = st['ias_rms_ms']; rrms_kt  = rrms / 0.514444
        lrms = st['roll_rms_deg']
        print(f"  VSI variation:  {within(vrms, PREC_VSI_LIMIT_MS)}  "
              f"±{vrms_fpm:.1f} ft/min  (limit ±{PREC_VSI_LIMIT_MS/0.00508:.0f})")
        print(f"  IAS variation:  {within(rrms, PREC_IAS_LIMIT_MS)}  "
              f"±{rrms_kt:.2f} kt  (limit ±{PREC_IAS_LIMIT_MS/0.514444:.1f})")
        print(f"  Roll variation: {within(lrms, PREC_ROLL_LIMIT_DEG)}  "
              f"±{lrms:.2f}°  (limit ±{PREC_ROLL_LIMIT_DEG:.1f}°)")
    else:
        print(f"  Not yet measured — hold controls neutral for "
              f"{_PSM_NEUTRAL_TICKS/50:.0f}s in calm air.")
    print(f"\n  HOW TO USE")
    print(f"  The instrument readings above are what you see on the VSI and ASI.")
    print(f"  The stroke pulsation at {_PSM_BEAT_HZ*2:.2f} Hz is filtered out.")
    print(f"  What remains is the true mean rate — read it and fly it.")
    print(f"  The aircraft does not compensate for gusts or wind shifts.")
    print(f"  You do that, as you would in any conventional aircraft.")
    print(f"\n  GS: precision_status — this report")
    print(f"  GS: vsi_hold [fpm]  — display only: label a target rate")


# ── Revised vsi_hold — display annotation only, no PID ───────────────────────

def vsi_hold(target_fpm=0.0):
    """
    GS: vsi_hold [fpm]
    Set a VSI target annotation on the display.
    This is a reference marker — the aircraft does NOT hold this rate.
    The pilot holds the rate. The annotation helps them monitor it.
    AI: 'target descent rate 100 ft/min' / 'show me 100 down on the VSI'
    """
    target_ms = float(target_fpm) * 0.00508
    _prec['vsi_target_ms'] = target_ms
    # Disable any active PID correction
    _prec['vsi_active'] = False
    _prec['vsi_err_int'] = 0.0
    _pl_append_log({'event': 'vsi_target_set', 'target_fpm': target_fpm})
    sign = '+' if target_fpm >= 0 else ''
    print(f"\n  VSI TARGET: {sign}{target_fpm:.0f} ft/min ({target_ms:+.3f} m/s)")
    print(f"  This is a reference marker on the display.")
    print(f"  The aircraft does not hold this rate — you do.")
    print(f"  Watch the smooth VSI and adjust pitch/power as needed.")


def track_hold():
    """
    GS: track_hold
    Capture and display the current heading as a reference.
    The aircraft does NOT hold this heading — the pilot does.
    AI: 'remember this heading' / 'set heading reference'
    """
    _prec['hdg_target_deg'] = None
    _prec['hdg_active']     = False
    _pl_append_log({'event': 'track_reference_set'})
    print(f"  Track reference captured. Displayed on heading indicator.")
    print(f"  The aircraft does not hold this heading — you do.")


def water_approach_arm():
    """
    GS: water_approach_arm
    Arm the water approach display mode.
    Shows VSI target of -100 ft/min on instruments.
    Engages precision focus for learning.
    Does NOT tighten any gains. Behaviour identical to normal cruise.
    AI: 'water approach' / 'seaplane approach' / 'fly the approach'
    """
    _prec['water_approach'] = True
    vsi_hold(-100.0)      # display annotation only
    set_mission_focus('precision')
    _pl_append_log({'event': 'water_approach_arm'})
    print(f"\n  WATER APPROACH DISPLAY MODE")
    print(f"  VSI reference: -100 ft/min (-0.508 m/s) shown on display")
    print(f"  Set your lever and pitch for approximately this rate.")
    print(f"  Monitor the smooth VSI. Correct as you would in any aircraft.")
    print(f"  The aircraft behaviour is identical to normal cruise.")
    print(f"  No automatic gain change. You are flying it.")


# ══════════════════════════════════════════════════════════════════════════════
# VSI REFERENCE MARKER — PERMANENT, UNIVERSAL
#
# The VSI reference marker is now always present and always displayed.
# It is not associated with water approach or any particular mode.
# It is a universal pilot aid — like the index bug on an airspeed indicator
# or the CDI on a VOR: always there, set to whatever the pilot needs.
#
# DEFAULT: 0 ft/min (level flight) on power-up
# RANGE:   -2000 to +2000 ft/min (±10.16 m/s)
# SET BY:  pilot saying the rate they want, or by GS: vsi_ref [fpm]
#          The old vsi_hold command is an alias for vsi_ref
#
# DISPLAYED ON:
#   - VSI gauge: reference bug / triangle marker at the target rate
#   - Telemetry key: vsi_ref_fpm (always present in result dict)
#   - precision_status: always shown alongside smooth VSI
#
# WATER APPROACH:
#   water_approach_arm simply calls vsi_ref(-100) plus precision focus.
#   No special behaviour. The water approach protocol IS the standard.
# ══════════════════════════════════════════════════════════════════════════════

# ── VSI reference marker state — lives here, always ──────────────────────────
_VSI_REF_FPM = 0.0      # current reference — default level flight
_VSI_REF_MS  = 0.0      # same in m/s
_VSI_REF_MIN = -2000.0  # ft/min — minimum settable
_VSI_REF_MAX = +2000.0  # ft/min — maximum settable


def vsi_ref(target_fpm=0.0):
    """
    GS: vsi_ref [fpm]
    Set the VSI reference marker — always displayed on the VSI gauge.
    This is a permanent pilot aid, active in all flight phases.

    Positive = climb, negative = descent. Zero = level flight.
    Default on power-up: 0 ft/min (level).

    The aircraft does NOT hold this rate. The pilot holds it.
    The marker shows where the needle should be; the pilot puts it there.

    Examples:
      vsi_ref 0       → level flight (default)
      vsi_ref -100    → 100 ft/min descent
      vsi_ref -500    → 500 ft/min descent
      vsi_ref  200    → 200 ft/min climb

    AI: 'target rate 100 ft/min down' / 'set VSI bug to 500 down'
        'I want to descend at 100 ft/min' / 'reference 200 up'
        'set descent rate' / 'target descent 100'
    """
    global _VSI_REF_FPM, _VSI_REF_MS

    target_fpm = max(_VSI_REF_MIN, min(_VSI_REF_MAX, float(target_fpm)))
    _VSI_REF_FPM = target_fpm
    _VSI_REF_MS  = target_fpm * 0.00508

    # Keep _prec in sync (used by scorers)
    _prec['vsi_target_ms'] = _VSI_REF_MS

    _pl_append_log({'event': 'vsi_ref_set',
                     'target_fpm': target_fpm,
                     'target_ms':  _VSI_REF_MS})

    sign = '+' if target_fpm >= 0 else ''
    if target_fpm == 0.0:
        desc = 'level flight'
    elif target_fpm < 0:
        desc = f'{abs(target_fpm):.0f} ft/min descent'
    else:
        desc = f'{target_fpm:.0f} ft/min climb'

    print(f"\n  VSI REFERENCE: {sign}{target_fpm:.0f} ft/min  ({_VSI_REF_MS:+.3f} m/s)")
    print(f"  Description: {desc}")
    print(f"  The marker is now shown on the VSI gauge.")
    print(f"  Set your power and pitch until the needle meets the bug.")

# Alias — vsi_hold is the old name, now redirects here
vsi_hold = vsi_ref


def vsi_ref_clear():
    """
    GS: vsi_ref_clear
    Remove the VSI reference marker (return to zero / level).
    AI: 'clear the VSI bug' / 'remove the reference'
    """
    vsi_ref(0.0)
    print(f"  VSI reference cleared — marker at zero (level flight).")


# ── Patch stroke_smoothing_tick to always emit the reference ──────────────────

def water_approach_arm():
    """
    GS: water_approach_arm
    Set VSI reference to -100 ft/min and engage precision focus.
    Behaviour is identical to setting vsi_ref -100 and focus precision.
    No special modes, no gain changes. The water approach protocol
    is the standard protocol — this is a convenience command.
    AI: 'water approach' / 'seaplane approach' / 'fly the approach'
        'set up for the approach' / 'approach to land'
    """
    _prec['water_approach'] = True
    vsi_ref(-100.0)
    set_mission_focus('precision')
    _pl_append_log({'event': 'water_approach_arm'})
    print(f"\n  WATER APPROACH")
    print(f"  VSI reference set to -100 ft/min. Marker shown on gauge.")
    print(f"  Precision focus engaged — learning optimises for stable trim.")
    print(f"  Fly it as you would any approach: set power and pitch,")
    print(f"  put the needle on the bug, monitor and correct.")


def water_approach_abort():
    """
    GS: water_approach_abort
    Clear water approach mode, return VSI reference to zero.
    AI: 'abort approach' / 'go around' / 'cancel the approach'
    """
    _prec['water_approach'] = False
    vsi_ref(0.0)
    focus_clear()
    _pl_append_log({'event': 'water_approach_abort'})
    print(f"  Approach aborted. VSI reference returned to level.")


# ── Update precision_status to always show reference ─────────────────────────
def precision_status():
    """
    GS: precision_status
    Precision instruments status — VSI reference, smooth readings, trim quality.
    AI: 'precision status' / 'VSI accuracy' / 'how is the trim'
    """
    st = _psm

    vsi_now  = st['vsi_smooth_fpm']
    vsi_ref_ = _VSI_REF_FPM
    vsi_err  = vsi_now - vsi_ref_
    ias_kt   = st['ias_smooth_kt']

    in_spec = lambda rms, lim: '✓' if rms < lim else '✗'
    arrow   = lambda e: '↑' if e > 5 else '↓' if e < -5 else '='

    print(f"\n  PRECISION INSTRUMENTS")
    print(f"  ─────────────────────────────────────────")
    print(f"  VSI  (smooth 5-beat): {vsi_now:+6.1f} ft/min")
    print(f"  VSI  reference bug:   {vsi_ref_:+6.1f} ft/min")
    print(f"  VSI  error:           {vsi_err:+6.1f} ft/min  {arrow(vsi_err)}")
    print(f"  IAS  (smooth 5-beat): {ias_kt:>6.1f} kt")
    print(f"  Roll (smooth 5-beat): {st['roll_smooth_deg']:>+6.2f}°")

    print(f"\n  TRIM QUALITY  (measured hands-off, calm air)")
    if st['controls_neutral']:
        vr = st['vsi_rms_ms'];  vr_fpm = vr / 0.00508
        ir = st['ias_rms_ms'];  ir_kt  = ir / 0.514444
        rr = st['roll_rms_deg']
        print(f"  {in_spec(vr, PREC_VSI_LIMIT_MS)}  VSI  variation: ±{vr_fpm:.1f} ft/min"
              f"  (limit ±{PREC_VSI_LIMIT_MS/0.00508:.0f})")
        print(f"  {in_spec(ir, PREC_IAS_LIMIT_MS)}  IAS  variation: ±{ir_kt:.2f} kt"
              f"  (limit ±{PREC_IAS_LIMIT_MS/0.514444:.1f})")
        print(f"  {in_spec(rr, PREC_ROLL_LIMIT_DEG)}  Roll variation: ±{rr:.2f}°"
              f"  (limit ±{PREC_ROLL_LIMIT_DEG:.1f}°)")
    else:
        ticks_needed = max(0, _PSM_NEUTRAL_TICKS - st['neutral_ticks'])
        print(f"  Hold all controls neutral for {ticks_needed/50:.0f}s in calm air to measure.")

    print(f"\n  HOW TO USE THE VSI BUG")
    print(f"  Set your target rate with: GS: vsi_ref [fpm]")
    print(f"  Examples: vsi_ref -100  (100 ft/min descent)")
    print(f"            vsi_ref 0     (level flight)")
    print(f"            vsi_ref 200   (200 ft/min climb)")
    print(f"  The bug is always displayed. Set it, fly to it, monitor it.")
    print(f"\n  Water approach: {'ARMED (-100 ft/min)' if _prec.get('water_approach') else 'not set'}")


# ── Update GS system prompt to know about universal VSI reference ─────────────
