def _route_hypothesis_to_scorer(hyp):
    """
    Map a hypothesis to its scoring function and evaluation phase.
    Returns (scorer_name, eval_phase, min_duration_s).
    """
    target  = hyp.get('target', 'efficiency')
    h_id    = hyp.get('id', '')
    phases  = hyp.get('eval_phases', ['cruise'])

    # New hypothesis families get appropriate routing
    if h_id.startswith('H-DIH-') or h_id.startswith('H-PDW-'):
        return 'trim_quality', 'stability', 30.0
    if h_id.startswith('H-SOR-1') or h_id.startswith('H-SOR-2'):
        return 'glide_ratio', 'glide', 30.0
    if h_id.startswith('H-SOR-3'):
        return 'netto_per_watt', 'glide', 30.0
    if h_id.startswith('H-SOR-4'):
        return 'thermal_climb_rate', 'thermal', 25.0
    if h_id.startswith('H-SOR-5'):
        return 'glide_ratio', 'glide', 40.0
    if h_id.startswith('H-SOR-6'):
        return 'trim_quality', 'cruise', 30.0
    if h_id.startswith('H-DA-'):
        return 'hover_hold', 'density_alt', 25.0
    if h_id.startswith('H-LB-'):
        return 'brake', 'level_body', 15.0
    if h_id.startswith('H-TR-'):
        return 'high_cruise_eff', 'transition', 30.0
    if h_id.startswith('H-AQ-'):
        return 'high_cruise_eff', 'acoustic', 30.0
    if h_id.startswith('H-SP-'):
        return 'hover_hold', 'sensor_point', 20.0
    if h_id.startswith('H-TX-'):
        return 'trim_quality', 'transition', 25.0

    # Fall through to target-based routing
    scorer = _TARGET_SCORER_MAP.get(target, '_score_endurance')
    phase  = phases[0] if phases else 'cruise'
    return scorer, phase, 20.0


