# ── 1. Patch MAP-Elites niche label to include manoeuvre bins ─────────────────



def _obs_analyse_turn_genome(result):
    """
    Analyse turn genome for convergence patterns.
    Returns a proposal dict or None.
    Looks for dominant mechanisms and underperforming ones.
    """
    st = _OBS
    total = max(sum(_MW_TURN.values()), 0.001)

    # Need enough evaluations before proposing
    hb_evals = sum(
        _hypothesis_results.get(h, {}).get('n_evaluations', 0)
        for h in ['H-HB-1','H-HB-2','H-HB-3','H-HB-4','H-HB-5'])
    if hb_evals < 3:
        return None

    dominant_mech = max(_MW_TURN, key=_MW_TURN.get)
    dominant_pct  = _MW_TURN[dominant_mech] / total

    # If one mechanism is clearly winning, propose reinforcing it
    if dominant_pct > 0.40:
        mech_to_hyp = {
            'stroke_plane_tilt': 'H-HB-1',
            'inner_outer_asymm': 'H-HB-2',
            'lev_drag_precision': 'H-HB-3',
            'inertial_damping':   'H-HB-4',
            'per_stroke_vector':  'H-HB-5',
        }
        winning_hyp = mech_to_hyp.get(dominant_mech, 'H-HB-1')
        nice_names = {
            'stroke_plane_tilt': 'cascade-tilt stroke-plane vectoring',
            'inner_outer_asymm': 'inner/outer wing differentiation',
            'lev_drag_precision': 'LEV drag precision',
            'inertial_damping':  'inertial wing damping',
            'per_stroke_vector': 'per-stroke force vectoring',
        }
        return {
            'category': 'genome',
            'text':     (f"The turn genome has converged: "
                         f"'{nice_names.get(dominant_mech, dominant_mech)}' "
                         f"carries {dominant_pct*100:.0f}% of turn quality weight "
                         f"across {hb_evals} hummingbird evaluations. "
                         f"Shall I run a focused trial on {winning_hyp} "
                         f"to refine this mechanism further?"),
            'cmd':      f'_obs_apply_hb_focus {winning_hyp}',
            'rationale':(f"_MW_TURN dominant: {dominant_mech} "
                          f"at {dominant_pct*100:.0f}%"),
            'sgtask':   'hummingbird_turn',
            'priority': 3,
        }
    return None

