def _me_niche_label_safe(sensors_or_speed, result_or_wind=None, intent=None):
    """
    Safe wrapper for _me_niche_label — handles both call conventions:
      (speed_bin, wind_bin, intent)  — legacy integer form
      (sensors_dict, result_dict, intent)  — new dict form
    """
    # Detect call convention
