# ── TC-05 GS commands ─────────────────────────────────────────────────────────
def tc05_start():
    """
    GS: tc05_start
    Begin TC-05 Heavy Lift Assessment.
    AI: 'start TC-05' / 'heavy lift test' / 'cargo test'
    """
    print(f"\n  TC-05 HEAVY LIFT ASSESSMENT — STARTED")
    print(f"  Prerequisites: TC-04 passed, ≥3 free flight sessions")
    print(f"  Test masses: 0.5 / 1.0 / 2.0 / 5.0 kg on 0.3m sling")
    print(f"  FM target: > {HL_FM_TARGET:.3f} N/W")
    print(f"  DARPA 4:1 payload: {HL_PAYLOAD_4X_KG:.1f} kg equivalent")
    print(f"  See MCO-1D_Test_Cards_v25.pdf for complete procedure")
    _pl_append_log({'event': 'tc05_started'})

def tc05_confirm():
    """
    GS: tc05_confirm
    Mark TC-05 complete and export results.
    AI: 'TC-05 complete' / 'heavy lift test complete'
    """
    print(f"\n  TC-05 COMPLETE — exporting test record")
    _pl_append_log({'event': 'tc05_complete'})

def payload_declare(mass_kg=0.0):
    """
    GS: payload_declare [mass_kg]
    Declare attached payload mass to the flight system.
    The system updates thrust requirements and selects the
    appropriate payload-adaptive genome champion.
    AI: 'payload is 1 kg' / 'cargo mass 2kg' / 'no payload' / 'empty'
    """
    try:
        mass = float(mass_kg)
    except (TypeError, ValueError):
        mass = 0.0

    _flight_state['payload_kg'] = mass

    # Select genome band
    if mass < 0.3:
        band = 'empty'
    elif mass < 2.0:
        band = 'light'
    else:
        band = 'heavy'
    _flight_state['payload_band'] = band

    print(f"\n  PAYLOAD DECLARED: {mass:.2f} kg ({band})")
    total = 4.1 + mass
    print(f"  Total aircraft mass: {total:.2f} kg")
    print(f"  Required thrust to hover: {total*9.81:.0f} N")
    print(f"  Estimated power needed: {(total*9.81)**1.5 / (0.060 * (2*1.225*0.741)**0.5):.0f} W")
    if band != 'empty':
        print(f"  Payload-adaptive genome champion: loading {band} configuration")
        print(f"  GS: pendulum_damp enable recommended for payload > 0.3 kg")
    _pl_append_log({'event': 'payload_declared', 'mass_kg': mass, 'band': band})

def pendulum_damp(state='enable'):
    """
    GS: pendulum_damp [enable|disable]
    Enable or disable cargo pendulum suppression (H-HL-3).
    AI: 'pendulum damping on/off' / 'sling load stabilise' / 'stop the swing'
    """
    enabled = state.lower() in ('enable','on','yes','1','true')
    _flight_state['pendulum_damp_active'] = enabled
    print(f"\n  Pendulum suppression: {'ENABLED' if enabled else 'DISABLED'}")
    if enabled:
        print(f"  Anti-phase cascade differential active.")
        print(f"  Target: damp 5° swing to < 1° in < 5 seconds.")
    _pl_append_log({'event': 'pendulum_damp', 'enabled': enabled})

def figure_of_merit_run(variant='all'):
    """
    GS: figure_of_merit_run [variant|all]
    Run figure of merit measurement (H-HL-1).
    variant: baseline | high_amp | high_freq | clap | combined | all
    AI: 'measure figure of merit' / 'FM test' / 'hover efficiency test'
        'how efficient is the hover' / 'run all FM variants'
    """
    variants = {
        'baseline':  {'freq': 1.87, 'amp': 96.0,  'clap': False},
        'high_amp':  {'freq': 1.87, 'amp': 115.0, 'clap': False},
        'high_freq': {'freq': 2.50, 'amp': 96.0,  'clap': False},
        'clap':      {'freq': 1.87, 'amp': 108.0, 'clap': True},
        'combined':  {'freq': 2.20, 'amp': 108.0, 'clap': True},
    }
    to_run = variants if variant == 'all' else {variant: variants[variant]}

    print(f"\n  FIGURE OF MERIT MEASUREMENT")
    print(f"  Each variant: 60 seconds hold. Record motor_I_A, bus_V, accel_z_g.")
    print(f"  FM = (accel_z_g × 4.1) / (bus_V × motor_I_A)")
    print(f"  Target: FM > {HL_FM_TARGET:.3f} N/W | Minimum: FM > {HL_FM_BASELINE:.3f} N/W")
    print()
    for name, cfg in to_run.items():
        print(f"  {name:<12} freq={cfg['freq']:.2f}Hz  amp={cfg['amp']:.0f}°  "
              f"clap={'ON' if cfg['clap'] else 'off'}  → run 60s → record FM")
    _pl_append_log({'event': 'fm_run', 'variant': variant})

_GS_ALLOWED_CMDS.update({'tc05_start','tc05_confirm','payload_declare',
                           'pendulum_damp','figure_of_merit_run'})

