# H-HL FULL INTEGRATION PATCH
# Fixes 6 gaps identified by audit:
#   1. _MW_CARGO genome axis — 4 mechanisms
#   2. _update_genome_from_trial — route H-HL to _MW_CARGO
#   3. observer_report — show _MW_CARGO
#   4. _obs_analyse_cargo — convergence detection + FM trend
#   5. ai_observer_tick — run cargo genome analysis
#   6. mechanism_weight_report — show _MW_CARGO
#   7. discovery_hypothesis_select — heavy_lift focus routes to H-HL
# ══════════════════════════════════════════════════════════════════════════════

# ── 1. _MW_CARGO genome axis ──────────────────────────────────────────────────
CARGO_MECHANISMS = [
    'max_thrust_fm',     # H-HL-1: figure of merit — which config yields most N/W
    'payload_trim',      # H-HL-2: cascade/dihedral optimisation for loaded mass
    'pendulum_damp',     # H-HL-3: anti-phase cascade differential damps swing
    'ballistic_climb',   # H-HL-4: kinetic→potential energy conversion profile
]
_MW_CARGO = {m: 1.0/len(CARGO_MECHANISMS) for m in CARGO_MECHANISMS}

# Also track the best measured FM value — updated by H-HL-1 evaluations
_CARGO_STATE = {
    'best_fm_N_per_W':    0.0,
    'best_fm_variant':    None,
    'best_fm_config':     None,
    'payload_kg':         0.0,    # mirrors _flight_state['payload_kg']
    'payload_band':       'empty',
    'fm_history':         [],     # list of (timestamp, variant, fm_value)
    'payload_ratio_est':  0.0,    # updated after each FM measurement
    'pendulum_active':    False,
}


# ── 2. genome_update routing — H-HL → _MW_CARGO ──────────────────────────────


def _obs_analyse_cargo_genome(result):
    """
    Analyse cargo genome for convergence and FM trend.
    Returns proposal or None.
    Fires when:
      (a) One mechanism dominates with > 45% weight across 3+ evaluations
      (b) FM measurements suggest a clear winning configuration
      (c) Payload ratio has been measured and gaps are known
    """
    st  = _CARGO_STATE
    total = max(sum(_MW_CARGO.values()), 0.001)

    # Need some H-HL evaluations first
    hl_evals = sum(
        _hypothesis_results.get(h, {}).get('n_evaluations', 0)
        for h in ['H-HL-1','H-HL-2','H-HL-3','H-HL-4'])
    if hl_evals < 2:
        return None

    dominant = max(_MW_CARGO, key=_MW_CARGO.get)
    dominant_pct = _MW_CARGO[dominant] / total

    # FM-based proposal — if best FM is known, focus on improving it
    if st['best_fm_N_per_W'] > 0:
        if st['best_fm_N_per_W'] < HL_FM_BASELINE:
            return {
                'category': 'cargo',
                'text':     (f"Figure of merit is {st['best_fm_N_per_W']:.4f} N/W "
                             f"— below the minimum target of {HL_FM_BASELINE:.3f} N/W. "
                             f"This limits payload ratio to less than 2.5:1. "
                             f"Shall I run a focused H-HL-1 trial with maximum "
                             f"amplitude and clap to improve it?"),
                'cmd':      '_obs_apply_cargo_focus H-HL-1',
                'priority': 1,
            }
        elif st['best_fm_N_per_W'] < HL_FM_TARGET and hl_evals >= 3:
            return {
                'category': 'cargo',
                'text':     (f"Figure of merit is {st['best_fm_N_per_W']:.4f} N/W. "
                             f"Above minimum but below the {HL_FM_TARGET:.3f} N/W target. "
                             f"Best variant so far: {st['best_fm_variant']}. "
                             f"Shall I run a refined trial to push toward the target?"),
                'cmd':      '_obs_apply_cargo_focus H-HL-1',
                'priority': 2,
            }

    # Genome convergence proposal
    if dominant_pct > 0.45 and hl_evals >= 3:
        nice = {
            'max_thrust_fm':  'maximum thrust / figure of merit (H-HL-1)',
            'payload_trim':   'payload-adaptive trim (H-HL-2)',
            'pendulum_damp':  'pendulum suppression (H-HL-3)',
            'ballistic_climb':'ballistic zoom climb (H-HL-4)',
        }
        return {
            'category': 'cargo',
            'text':     (f"Cargo genome converging: "
                         f"'{nice.get(dominant, dominant)}' carries "
                         f"{dominant_pct*100:.0f}% of weight. "
                         f"Shall I run a focused refinement trial?"),
            'cmd':      f'_obs_apply_cargo_focus {dominant}',
            'priority': 3,
        }
    return None



# ── 5. Patch ai_observer_tick to include cargo analysis ───────────────────────



def heavy_lift_status():
    """
    GS: heavy_lift_status
    Complete heavy lift and cargo status: FM measurements, payload ratio,
    genome weights, DARPA target progress, pendulum state.
    AI: 'cargo status' / 'heavy lift status' / 'payload ratio' /
        'how much can it carry' / 'what is the figure of merit' /
        'DARPA challenge status' / 'are we at 4:1'
    """
    st = _CARGO_STATE
    print(f"\n  HEAVY LIFT STATUS")
    print(f"  ─────────────────────────────────────────")
    print(f"  Payload declared:     {st['payload_kg']:.2f} kg ({st['payload_band']})")
    print(f"  Pendulum suppression: {'ACTIVE' if st['pendulum_active'] else 'off'}")

    print(f"\n  FIGURE OF MERIT:")
    if st['best_fm_N_per_W'] > 0:
        print(f"  Best measured FM:     {st['best_fm_N_per_W']:.4f} N/W")
        print(f"  Best variant:         {st['best_fm_variant']}")
        print(f"  Payload ratio (est):  {st['payload_ratio_est']:.2f}:1")
        print(f"  Payload at 4.1kg:     {st['payload_ratio_est']*4.1:.1f} kg")
        print(f"\n  DARPA 4:1 PROGRESS:")
        if st['payload_ratio_est'] >= HL_PAYLOAD_RATIO_4X:
            print(f"  ✓ TARGET ACHIEVED ({st['payload_ratio_est']:.2f}:1 ≥ 4.0:1)")
        else:
            pct = st['payload_ratio_est'] / HL_PAYLOAD_RATIO_4X * 100
            print(f"  Progress: {pct:.0f}% of 4:1 target")
            print(f"  Gap: {HL_PAYLOAD_RATIO_4X - st['payload_ratio_est']:.2f} ratio points")
        print(f"  FM target: {HL_FM_TARGET:.3f} N/W | "
              f"Minimum: {HL_FM_BASELINE:.3f} N/W | "
              f"Measured: {st['best_fm_N_per_W']:.4f} N/W")
    else:
        print(f"  FM not yet measured.")
        print(f"  → Run TC-02 Step 10: figure_of_merit_run all")
        print(f"  → Or: GS: figure_of_merit_run combined")

    print(f"\n  CARGO GENOME (_MW_CARGO):")
    total = max(sum(_MW_CARGO.values()), 0.001)
    for mech, w_val in sorted(_MW_CARGO.items(), key=lambda x: -x[1]):
        pct = w_val / total * 100
        bar = '█' * int(pct / 5)
        print(f"    {mech:<20} {pct:>5.1f}%  {bar}")

    print(f"\n  REFERENCE:")
    print(f"  Disk loading:         {HL_DISK_LOADING_N_M2:.1f} N/m² = 1.13 lb/ft²")
    print(f"  4:1 payload at 4.1kg: {HL_PAYLOAD_4X_KG:.1f} kg")
    print(f"  Disk area:            {HL_DISK_AREA_M2:.3f} m² (all 8 wings)")

_GS_ALLOWED_CMDS.add('heavy_lift_status')


