# ══════════════════════════════════════════════════════════════════════════════
# CARGO AUTO-DETECTION SYSTEM
#
# The aircraft automatically detects when payload is attached,
# estimates its mass from sensor fusion, and silently adopts the
# appropriate flight characteristics. The pilot neither declares
# nor is aware of this process — the aircraft simply flies correctly.
#
# THREE-STAGE PROCESS:
#
# Stage 1 — EVENT DETECTION (instant, <100ms)
#   Watches for the signature of a mass being attached:
#   (a) Sudden motor current increase (more thrust needed to hold altitude)
#   (b) VSI going negative (aircraft sinking from added weight)
#   (c) IMU pitch/roll shift (CG displacement from offset attachment)
#   Any two of three triggers a mass estimation sequence.
#   Also fires on arming if power at arm is above empty-hover baseline.
#
# Stage 2 — MASS ESTIMATION (passive, 3-8 seconds of stable hover)
#   Uses power balance method (Method 3):
#     P_hover_measured = bus_V × motor_I_A
#     P_hover_theoretical = (m_total × g)^1.5 / (FM × sqrt(2ρA))
#     Solve for m_total → m_cargo = m_total - M_AIRFRAME_KG
#   FM is taken from _CARGO_STATE['best_fm_N_per_W'] if measured,
#   or from HL_FM_BASELINE (0.055) as prior.
#   Requires 3 seconds of h_agl stable (< ±0.3m) and V < 2 m/s.
#   Updates estimate continuously while conditions hold.
#   Converges when standard deviation < 0.15 kg over 10 samples.
#
# Stage 3 — SILENT ADAPTATION (immediate on estimate)
#   Selects the matching payload-band genome champion.
#   Arms pendulum damping if mass > 0.3 kg.
#   Updates discovery routing to prefer H-HL-2/3.
#   Adjusts flight monitor thresholds for new MTOW.
#   No cockpit notification — invisible to pilot.
#   Pilot can always query: 'cargo status' / 'what am I carrying'
# ══════════════════════════════════════════════════════════════════════════════

import collections as _cad_col
import math as _cad_math

# ── Airframe mass constant ────────────────────────────────────────────────────
M_AIRFRAME_KG = 4.189  # kg — confirmed AUW: 16×A27CHR + 8×1.0m wings (110g ea)

# ── Auto-detect state ─────────────────────────────────────────────────────────
_CAD = {
    # Detection
    'armed':               False,   # detection system armed (requires FM baseline)
    'event_detected':      False,   # cargo event signature seen
    'event_t':             0.0,     # time of event
    # Estimation
    'estimating':          False,
    'estimate_samples':    _cad_col.deque(maxlen=50),   # 1s at 50Hz
    'estimate_kg':         0.0,     # current estimate
    'estimate_std_kg':     99.0,    # standard deviation — high until converged
    'estimate_converged':  False,
    'stable_hover_t':      0.0,     # how long hover has been stable
    # Baseline (empty aircraft at hover)
    'baseline_P_W':        0.0,     # power at hover, empty, calibrated
    'baseline_I_A':        0.0,     # current at hover, empty
    'baseline_set':        False,
    # State
    'last_payload_kg':     0.0,     # last committed estimate
    'cargo_present':       False,
    # Thresholds
    'event_P_threshold':   0.08,    # 8% power increase triggers detection
    'event_vsi_threshold': -60.0,   # ft/min sudden drop triggers detection
    'converge_std_kg':     0.15,    # kg std dev for convergence
    'converge_n':          10,      # samples needed
    'stable_hover_req_s':  3.0,     # seconds of stable hover for estimation
}

# ── Hover stability check ─────────────────────────────────────────────────────
def _hover_stable(sensors):
    """Returns True if aircraft is in stable hover suitable for mass estimation."""
    V_ms   = sensors.get('V_ms', 9.0)
    h_agl  = sensors.get('h_agl_m', 0.0)
    vsi    = sensors.get('vsi_smooth_ms', 0.0)
    lever  = sensors.get('lever_pct', 50.0)
    return (V_ms < 2.0           # slow — hovering
            and h_agl > 0.3      # airborne
            and abs(vsi) < 0.3   # stable altitude (0.3 m/s = 60 fpm)
            and lever > 10.0)    # motor running


# ── Mass estimator from power balance ─────────────────────────────────────────
def _estimate_mass_from_power(P_hover_W, FM=None):
    """
    Given measured hover power, estimate total mass.
    P_hover = (m × g)^1.5 / (FM × sqrt(2 × rho × A))
    → m = (P_hover × FM × sqrt(2ρA))^(2/3) / g
    """
    fm = FM or _CARGO_STATE.get('best_fm_N_per_W') or HL_FM_BASELINE
    rho_A = 2.0 * 1.225 * HL_DISK_AREA_M2
    try:
        m_total = (P_hover_W * fm * _cad_math.sqrt(rho_A)) ** (2.0/3.0) / 9.81
        return max(0.0, m_total)
    except Exception:
        return M_AIRFRAME_KG


# ── Main cargo auto-detect tick — runs inside position_hold_tick at 1Hz ───────
def _cargo_autodetect_tick(sensors, result):
    """
    Cargo auto-detection tick. Runs at 1 Hz.
    Invisible to pilot. Updates _CARGO_STATE and _flight_state silently.
    """
    st  = _CAD
    cst = _CARGO_STATE
    now = __import__('time').monotonic()

    # Require FM baseline to operate (from H-HL-1 or HL_FM_BASELINE)
    fm = cst.get('best_fm_N_per_W') or HL_FM_BASELINE
    if fm <= 0:
        result['cad_status'] = 'no_fm_baseline'
        return result

    # Current power measurement
    I_A  = sensors.get('motor_I_A', 0.0)
    V_b  = sensors.get('bus_voltage', 24.0)
    P_W  = I_A * V_b

    # ── Establish empty-aircraft baseline ─────────────────────────────────────
    # Done once: in stable hover after arm, when cargo_present=False
    if not st['baseline_set'] and _hover_stable(sensors):
        if not cst['payload_kg'] and not st['cargo_present']:
            st['baseline_P_W'] = P_W
            st['baseline_I_A'] = I_A
            st['baseline_set'] = True
            result['cad_baseline_set'] = True

    # ── Event detection ───────────────────────────────────────────────────────
    if st['baseline_set'] and not st['event_detected']:
        # Detect sudden power increase (cargo attached during hover)
        if st['baseline_P_W'] > 10.0:
            P_ratio = (P_W - st['baseline_P_W']) / st['baseline_P_W']
        else:
            P_ratio = 0.0
        vsi_fpm = result.get('vsi_smooth_fpm', 0.0)

        event_P   = P_ratio > st['event_P_threshold']
        event_vsi = vsi_fpm < st['event_vsi_threshold']

        if event_P or event_vsi:
            st['event_detected'] = True
            st['event_t']        = now
            st['estimating']     = True
            st['estimate_samples'].clear()
            result['cad_event'] = True

        # Also detect cargo removal (power drop back to baseline)
        if st['cargo_present'] and P_ratio < -st['event_P_threshold']:
            # Cargo removed
            st['event_detected'] = False
            st['estimating']     = False
            st['cargo_present']  = False
            st['estimate_converged'] = False
            st['estimate_kg']    = 0.0
            _flight_state['payload_kg']  = 0.0
            _flight_state['payload_band']= 'empty'
            cst['payload_kg']    = 0.0
            cst['payload_band']  = 'empty'
            _CARGO_STATE['pendulum_active'] = False
            result['cad_cargo_removed'] = True

    # ── Mass estimation ───────────────────────────────────────────────────────
    if st['estimating'] and _hover_stable(sensors):
        st['stable_hover_t'] += 1.0   # 1Hz tick

        if st['stable_hover_t'] >= st['stable_hover_req_s']:
            # Accumulate samples
            m_est = _estimate_mass_from_power(P_W, fm)
            st['estimate_samples'].append(m_est)

            if len(st['estimate_samples']) >= st['converge_n']:
                samples = list(st['estimate_samples'])
                mean = sum(samples) / len(samples)
                std  = (_cad_math.sqrt(sum((x-mean)**2
                        for x in samples) / len(samples)))
                st['estimate_kg']     = mean
                st['estimate_std_kg'] = std

                # Converge when std is small enough
                if std < st['converge_std_kg']:
                    st['estimate_converged'] = True
                    m_cargo = max(0.0, mean - M_AIRFRAME_KG)

                    # Only commit if meaningfully different from last
                    if abs(m_cargo - st['last_payload_kg']) > 0.15:
                        _silent_payload_apply(m_cargo, std)
                        st['last_payload_kg'] = m_cargo
                        st['cargo_present']   = True

    elif st['estimating']:
        # Not in stable hover — reset stable timer
        st['stable_hover_t'] = 0.0

    # Write telemetry
    result['cad_cargo_present']  = st['cargo_present']
    result['cad_estimate_kg']    = round(st['estimate_kg'] - M_AIRFRAME_KG, 2) \
                                    if st['estimate_kg'] > M_AIRFRAME_KG else 0.0
    result['cad_estimate_std']   = round(st['estimate_std_kg'], 3)
    result['cad_converged']      = st['estimate_converged']
    return result


def _silent_payload_apply(m_cargo_kg, std_kg):
    """
    Silently apply detected cargo mass to all relevant systems.
    No cockpit notification. No pilot action required.
    """
    # Round to nearest 0.1 kg for band selection
    m_rounded = round(m_cargo_kg, 1)

    # Select band
    if m_rounded < 0.3:
        band = 'empty'
    elif m_rounded < 2.0:
        band = 'light'
    else:
        band = 'heavy'

    # Update all state that uses payload mass
    _flight_state['payload_kg']   = m_rounded
    _flight_state['payload_band'] = band
    _CARGO_STATE['payload_kg']    = m_rounded
    _CARGO_STATE['payload_band']  = band

    # Arm pendulum damping silently if mass significant
    if m_rounded >= 0.3:
        _flight_state['pendulum_damp_active']  = True
        _CARGO_STATE['pendulum_active']        = True

    # Update flight monitor thresholds for new MTOW
    # Battery warn/crit stay the same; power thresholds scale with mass
    m_total = M_AIRFRAME_KG + m_rounded
    scale   = m_total / M_AIRFRAME_KG
    # Record for monitor — it reads from _flight_state
    _flight_state['mtow_kg']      = m_total
    _flight_state['mass_scale']   = scale

    # Update discovery routing preference
    _CAD['cargo_present'] = True

    # Log the detection (not shown to pilot unless queried)
    _pl_append_log({
        'event':     'cargo_autodetected',
        'mass_kg':   m_rounded,
        'std_kg':    round(std_kg, 3),
        'band':      band,
        'pendulum':  m_rounded >= 0.3,
    })


# ── Wire into position_hold_tick ──────────────────────────────────────────────

def cargo_status():
    """
    GS: cargo_status
    Current cargo auto-detection state and mass estimate.
    AI: 'cargo status' / 'what am I carrying' / 'is there cargo attached' /
        'how much does the cargo weigh' / 'payload weight' / 'auto cargo'
    """
    st  = _CAD
    cst = _CARGO_STATE
    fs  = _flight_state

    print(f"\n  CARGO AUTO-DETECTION STATUS")
    print(f"  ─────────────────────────────────────────")
    print(f"  Baseline established:  {'✓' if st['baseline_set'] else '✗ (need stable hover first)'}")
    print(f"  Cargo present:         {'YES' if st['cargo_present'] else 'no'}")

    if st['cargo_present'] or st['estimating']:
        m_cargo = max(0.0, st['estimate_kg'] - M_AIRFRAME_KG)
        print(f"\n  MASS ESTIMATE:")
        print(f"  Cargo mass:          {m_cargo:.2f} ± {st['estimate_std_kg']:.2f} kg")
        print(f"  Total aircraft mass: {st['estimate_kg']:.2f} kg")
        print(f"  Payload band:        {fs.get('payload_band','?')}")
        print(f"  Estimate converged:  {'✓' if st['estimate_converged'] else 'still refining...'}")
        print(f"  Pendulum damping:    {'ACTIVE' if fs.get('pendulum_damp_active') else 'off'}")
        if cst.get('best_fm_N_per_W',0) > 0:
            T_est = cst['best_fm_N_per_W'] * 3500.0
            W_total = st['estimate_kg'] * 9.81
            headroom = T_est - W_total
            print(f"  Thrust headroom:     {headroom:.0f} N ({headroom/9.81:.1f} kg additional lift available)")
    else:
        print(f"  No cargo detected.")

    print(f"\n  FM USED FOR ESTIMATION: "
          f"{cst.get('best_fm_N_per_W') or HL_FM_BASELINE:.4f} N/W "
          f"({'measured' if cst.get('best_fm_N_per_W') else 'prior estimate'})")

def cargo_baseline_reset():
    """
    GS: cargo_baseline_reset
    Reset the empty-aircraft hover baseline.
    Run when aircraft is definitely empty and in stable hover.
    AI: 'reset cargo baseline' / 'recalibrate empty hover'
    """
    _CAD['baseline_set']    = False
    _CAD['event_detected']  = False
    _CAD['estimating']      = False
    _CAD['cargo_present']   = False
    _CAD['estimate_converged'] = False
    _CAD['stable_hover_t']  = 0.0
    _CAD['estimate_samples'].clear()
    print(f"  Cargo baseline reset. Hover stably to re-establish.")
    _pl_append_log({'event': 'cargo_baseline_reset'})

_GS_ALLOWED_CMDS.update({'cargo_status', 'cargo_baseline_reset'})

