# ── 2. Complete genome update routing ─────────────────────────────────────────




def _obs_analyse_competition_genome(result):
    """Detect competition genome convergence."""
    total = max(sum(_MW_COMPETITION.values()), 0.001)
    cr_evals = sum(
        _hypothesis_results.get(h,{}).get('n_evaluations',0)
        for h in ['H-CR-1','H-CR-2','H-CR-3','H-CR-4','H-CR-5'])
    if cr_evals < 2:
        return None
    dominant = max(_MW_COMPETITION, key=_MW_COMPETITION.get)
    pct = _MW_COMPETITION[dominant] / total
    if pct > 0.45:
        nice = {
            'gps_denied_drift': 'GPS-denied drift minimisation (H-CR-1)',
            'release_smooth':   'payload release smoothness (H-CR-2)',
            'cargo_range':      'cargo cruise efficiency (H-CR-3)',
            'alt_loiter':       'high-altitude loiter endurance (H-CR-4)',
            'link_resilience':  'link-degraded stability (H-CR-5)',
        }
        return {
            'category': 'competition',
            'text':     (f"Competition genome converging: "
                         f"'{nice.get(dominant, dominant)}' leads "
                         f"at {pct*100:.0f}% across {cr_evals} evaluations. "
                         f"Shall I run a focused refinement trial?"),
            'priority': 3,
        }
    return None

