def _hq_level(bandwidth, phase_delay):
    """MIL-STD-1797B Level classification."""
    if bandwidth >= EVTOL_BANDWIDTH_L1_RAD_S and phase_delay <= EVTOL_PHASE_DELAY_L1_S:
        return 1
    if bandwidth >= 1.0 and phase_delay <= 0.20:
        return 2
    return 3


