def evtol_status():
    """
    GS: evtol_status
    eVTOL certification metrics: handling qualities and acoustic signature.
    AI: 'eVTOL status' / 'certification metrics' / 'handling qualities' /
        'what level are the handling qualities' / 'how loud is it' /
        'acoustic signature' / 'noise level' / 'MIL-STD'
    """
    hq = _HQ_STATE
    ac = _AC_STATE
    print(f"\n  eVTOL CERTIFICATION STATUS")
    print(f"  ─────────────────────────────────────────")

    print(f"\n  HANDLING QUALITIES (MIL-STD-1797B):")
    print(f"  Level 1 thresholds: BW ≥ {EVTOL_BANDWIDTH_L1_RAD_S:.1f} rad/s  "
          f"τ_p ≤ {EVTOL_PHASE_DELAY_L1_S:.2f}s  Q ≥ {EVTOL_QUICKNESS_L1:.1f}")
    for regime, bw_key, pd_key, q_key, lv_key in [
        ('Hover', 'bandwidth_hover_rad_s', 'phase_delay_hover_s',
         'quickness_hover', 'level_hover'),
        ('Blend zone', 'bandwidth_blend_rad_s', 'phase_delay_blend_s',
         'quickness_blend', 'level_blend'),
        ('Cruise', 'bandwidth_cruise_rad_s', None, None, 'level_cruise'),
    ]:
        bw = hq.get(bw_key)
        lv = hq.get(lv_key)
        if bw is not None:
            pd_str = (f"τ_p={hq[pd_key]:.3f}s"
                      if pd_key and hq.get(pd_key) else "")
            q_str  = (f"Q={hq[q_key]:.2f}"
                      if q_key and hq.get(q_key) else "")
            lv_str = (f"Level {lv}" if lv else "?")
            ok = lv == 1
            print(f"  {'✓' if ok else '✗'} {regime:<12} "
                  f"BW={bw:.2f} rad/s  {pd_str}  {q_str}  → {lv_str}")
        else:
            print(f"  — {regime:<12} not yet measured — run H-EV-1")

    print(f"\n  ACOUSTIC SIGNATURE (eVTOL 65 dB target at 76m):")
    if ac.get('spl_db_hover') is not None:
        spl = ac['spl_db_hover']
        margin = EVTOL_NOISE_LIMIT_DB - spl
        ok = spl < EVTOL_NOISE_LIMIT_DB
        print(f"  {'✓' if ok else '✗'} Hover SPL: {spl:.1f} dB  "
              f"(margin: {margin:+.1f} dB vs {EVTOL_NOISE_LIMIT_DB:.0f} dB limit)")
        print(f"    Config: {ac.get('freq_hz_meas'):.2f} Hz, "
              f"{ac.get('amp_deg_meas'):.0f}° amplitude")
        if ok:
            print(f"    ✓ BELOW eVTOL certification threshold")
        else:
            print(f"    ✗ EXCEEDS limit — use lower freq or amplitude")
    else:
        print(f"  — Not yet measured — run H-EV-2 or figure_of_merit_run")

    print(f"\n  REFERENCE:")
    print(f"  eVTOL target:    {EVTOL_NOISE_LIMIT_DB:.0f} dB(A) at {EVTOL_OBSERVER_DIST_M:.0f}m")
    print(f"  Small helicopter: ~77 dB at same distance")
    print(f"  Joby S4:          <65 dB overflight")
    print(f"  Archer Midnight:  <45 dB approach")

def handling_qualities_run():
    """
    GS: handling_qualities_run
    Run MIL-STD-1797B frequency sweep (H-EV-1 protocol).
    Aircraft must be in stable hover or cruise for each regime.
    AI: 'run handling qualities' / 'MIL-STD test' / 'bandwidth test' /
        'measure handling qualities' / 'frequency sweep'
    """
    print(f"\n  MIL-STD-1797B HANDLING QUALITIES TEST")
    print(f"  Protocol:")
    print(f"    1. Hover — apply sinusoidal pitch stick at 6 frequencies")
    print(f"       Frequencies: 0.1, 0.5, 1.0, 2.0, 3.0, 4.0 Hz")
    print(f"       Duration: 5 cycles per frequency")
    print(f"       Record: pitch_deg_imu response amplitude and phase lag")
    print(f"    2. Compute bandwidth (45° lag point) by interpolation")
    print(f"    3. Compute phase delay at 2×bandwidth")
    print(f"    4. Small step input → compute quickness")
    print(f"    5. Repeat at blend zone (4 m/s) and cruise (9 m/s)")
    print(f"  Level 1 targets:")
    print(f"    Bandwidth:   ≥ {EVTOL_BANDWIDTH_L1_RAD_S:.1f} rad/s")
    print(f"    Phase delay: ≤ {EVTOL_PHASE_DELAY_L1_S:.2f} s")
    print(f"    Quickness:   ≥ {EVTOL_QUICKNESS_L1:.1f} deg/s per deg")
    print(f"  Note: requires piloted frequency sweeps — not autonomous")
    _pl_append_log({'event': 'handling_qualities_run_requested'})

def acoustic_run():
    """
    GS: acoustic_run
    Compute acoustic SPL estimate from current hover telemetry (H-EV-2).
    No microphone required — uses Gutin model + IMU + ODrive data.
    AI: 'acoustic test' / 'noise level' / 'how loud' / 'SPL' /
        'measure noise' / 'certification noise' / 'acoustic signature'
    """
    # Compute from current state if available
    freq  = _flight_state.get('freq_hz_actual', 1.87)
    amp   = 96.0   # nominal — would read from actual config
    span  = 0.772
    V_tip = _tip_velocity_ms(freq, amp, span)
    # Thrust estimate from flight state
    m_total = M_AIRFRAME_KG + _flight_state.get('payload_kg', 0.0)
    T_est   = m_total * 9.81   # hover: thrust ≈ weight
    spl     = _gutin_spl_db(T_est, V_tip, 8, EVTOL_OBSERVER_DIST_M)
    margin  = EVTOL_NOISE_LIMIT_DB - spl
    ok      = spl < EVTOL_NOISE_LIMIT_DB

    _AC_STATE['spl_db_hover']  = spl
    _AC_STATE['freq_hz_meas']  = freq
    _AC_STATE['amp_deg_meas']  = amp
    _AC_STATE['margin_db']     = margin
    _AC_STATE['passes_65db']   = ok
    _AC_STATE['measurements'].append({'freq': freq, 'amp': amp,
                                       'spl': spl, 'margin': margin})

    print(f"\n  ACOUSTIC ESTIMATE (Gutin tonal model):")
    print(f"  Frequency:      {freq:.2f} Hz")
    print(f"  Amplitude:      {amp:.0f}°")
    print(f"  Tip velocity:   {V_tip:.2f} m/s")
    print(f"  Thrust:         {T_est:.1f} N")
    print(f"  SPL at {EVTOL_OBSERVER_DIST_M:.0f}m:   {spl:.1f} dB")
    print(f"  Limit:          {EVTOL_NOISE_LIMIT_DB:.0f} dB")
    print(f"  Margin:         {margin:+.1f} dB")
    print(f"  Result:         {'✓ PASSES eVTOL certification' if ok else '✗ EXCEEDS limit'}")
    if ok:
        print(f"\n  The MCO-1D is {margin:.0f} dB quieter than the eVTOL limit.")
        print(f"  This reflects the low tip velocity ({V_tip:.1f} m/s) "
              f"vs multirotor (~80 m/s).")
    _pl_append_log({'event': 'acoustic_run', 'spl_db': spl, 'margin_db': margin})

_GS_ALLOWED_CMDS.update({'evtol_status', 'handling_qualities_run', 'acoustic_run'})


