def _obs_analyse_evtol_cert(result):
    """
    Watch eVTOL certification metrics and propose action when data exists.
    Fires when:
      (a) HQ measurements show Level 2 or 3 — propose cascade refinement
      (b) Acoustic margin is below target — propose frequency reduction
      (c) Both Level 1 achieved — note the certification milestone
    """
    hq = _HQ_STATE
    ac = _AC_STATE

    # Check HQ status
    level_h = hq.get('level_hover')
    level_b = hq.get('level_blend')
    if level_h is not None and level_h >= 2:
        bw = hq.get('bandwidth_hover_rad_s', 0)
        return {
            'category': 'evtol_cert',
            'text':     (f"Handling qualities in hover: Level {level_h} "
                         f"(bandwidth={bw:.2f} rad/s, need ≥ 2.0 for Level 1). "
                         f"Shall I run a focused H-EV-1 trial to find a higher-"
                         f"bandwidth cascade configuration?"),
            'priority': 2,
        }

    # Check acoustic
    if ac.get('passes_65db') is False:
        return {
            'category': 'evtol_cert',
            'text':     (f"Acoustic SPL {ac['spl_db_hover']:.1f} dB exceeds "
                         f"the {EVTOL_NOISE_LIMIT_DB:.0f} dB eVTOL target. "
                         f"Lower frequency or amplitude will reduce tip velocity "
                         f"and improve acoustic margin. Shall I trial H-EV-2?"),
            'priority': 2,
        }

    # Celebrate Level 1
    if level_h == 1 and level_b == 1 and ac.get('passes_65db'):
        return {
            'category': 'evtol_cert',
            'text':     (f"eVTOL certification metrics: Level 1 handling qualities "
                         f"in hover and blend zone. Acoustic margin "
                         f"{ac.get('margin_db', 0):+.1f} dB below limit. "
                         f"The aircraft meets MIL-STD-1797B Level 1 and EASA "
                         f"65 dB noise standard with current configuration."),
            'priority': 4,
        }
    return None

