def mechanism_weight_report():
    """
    GS: mechanism_weight_report
    Show all 10 genome axes with current mechanism weights.
    AI: 'mechanism weights' / 'genome status' / 'what mechanisms dominate' /
        'show genome' / 'genome report' / 'weight report'
    """
    print(f"\n  GENOME MECHANISM WEIGHTS")
    print(f"  ─────────────────────────────────────────")
    axes = [
        ('Roll',         _MW_ROLL),
        ('Pitch',        _MW_PITCH),
        ('Yaw',          _MW_YAW),
        ('Stability',    _MW_STABILITY),
        ('Soaring',      _MW_SOARING),
        ('Glide',        _MW_GLIDE),
        ('Turn',         _MW_TURN),
        ('Water',        _MW_WATER),
        ('Cargo',        _MW_CARGO),
        ('Competition',  _MW_COMPETITION),
    ]
    for name, axis in axes:
        total = max(sum(axis.values()), 0.001)
        dominant = max(axis, key=axis.get)
        print(f"\n  {name} axis:")
        for mech, wt in sorted(axis.items(), key=lambda x: -x[1]):
            pct = wt / total * 100
            bar = '█' * int(pct / 5)
            flag = ' ←' if mech == dominant and pct > 30 else ''
            print(f"    {mech:<24} {pct:>5.1f}%  {bar}{flag}")

_GS_ALLOWED_CMDS.add('mechanism_weight_report')


