# ── Lever-aware pigeon descent tick ───────────────────────────────────────────



def _obs_analyse_pigeon_descent(result):
    """
    Detect pigeon descent mode convergence in the glide genome.
    Fires when drag_minimise (H-FD-1) or geom_dihedral (H-FD-2/3)
    dominate in their respective contexts.
    """
    fd_evals = sum(
        _hypothesis_results.get(h, {}).get('n_evaluations', 0)
        for h in ['H-FD-1', 'H-FD-2', 'H-FD-3'])
    if fd_evals < 2:
        return None

    glide_total = max(sum(_MW_GLIDE.values()), 0.001)
    drag_wt = _MW_GLIDE.get('drag_minimise', 0) / glide_total
    stab_total = max(sum(_MW_STABILITY.values()), 0.001)
    dih_wt = _MW_STABILITY.get('geom_dihedral', 0) / stab_total
    roll_total = max(sum(_MW_ROLL.values()), 0.001)
    dih_roll_wt = _MW_ROLL.get('roll_dih', 0) / roll_total

    if drag_wt > 0.40 and fd_evals >= 3:
        return {
            'category': 'pigeon_descent',
            'text':     (f"Pigeon descent genome converging: drag_minimise "
                         f"at {drag_wt*100:.0f}% of glide axis — high-dihedral "
                         f"braking is proving effective. "
                         f"Shall I run a focused H-FD-1 trial at lever 7%?"),
            'priority': 3,
        }
    if dih_roll_wt > 0.35 and fd_evals >= 3:
        return {
            'category': 'pigeon_descent',
            'text':     (f"Differential dihedral steering (roll_dih) "
                         f"at {dih_roll_wt*100:.0f}% of roll axis — "
                         f"H-FD-3 is proving effective for precision track. "
                         f"Shall I run a focused refinement at lever 3%?"),
            'priority': 3,
        }
    return None

