    print(f"  Roll stick controls lateral track (steep zone only).")
    print(f"  {'Zone':<12} {'Lever':<12} {'VSI':<14} {'Dihedral':<12} Hypothesis")
    print(f"  {'─'*12} {'─'*12} {'─'*14} {'─'*12} {'─'*20}")
    for band, info in _PIGEON_LEVER_MAP.items():
        vsi_str = f"{info['vsi_fpm']:.0f} fpm"
