HARD_BRAKE_LEVER_HI    =  3.0   # 0-3%: hard brake (new — no pitch, no alt loss)
PD_LEVER_STEEP_LO_NEW  =  3.0   # 3-7%: pigeon steep (was 0-5%)
PD_LEVER_STEEP_HI_NEW  =  7.0
PD_LEVER_MOD_LO_NEW    =  7.0   # 7-12%: pigeon moderate (was 5-10%)
PD_LEVER_MOD_HI_NEW    = 12.0
PD_LEVER_SHALLOW_LO_NEW= 12.0   # 12-15%: pigeon shallow (was 10-15%)
PD_LEVER_SHALLOW_HI_NEW= 15.0   # unchanged top

# Update the PIGEON_LEVER_MAP in place
_PIGEON_LEVER_MAP['steep']['lever_lo']  = PD_LEVER_STEEP_LO_NEW
_PIGEON_LEVER_MAP['steep']['lever_hi']  = PD_LEVER_STEEP_HI_NEW
_PIGEON_LEVER_MAP['moderate']['lever_lo']= PD_LEVER_MOD_LO_NEW
_PIGEON_LEVER_MAP['moderate']['lever_hi']= PD_LEVER_MOD_HI_NEW
_PIGEON_LEVER_MAP['shallow']['lever_lo'] = PD_LEVER_SHALLOW_LO_NEW
_PIGEON_LEVER_MAP['shallow']['lever_hi'] = PD_LEVER_SHALLOW_HI_NEW

# Gesture thresholds — matched to existing GestureDetector vocabulary
RC_BANK_TURN_TIGHT_DEG    = 45.0  # bank above this enables turn tightening
RC_PITCH_TURN_TIGHT_THR   =  0.70  # aft pitch past this in steep bank = tighten
RC_REVERSE_PITCH_THR      =  0.50  # aft pitch beyond 0.5 = rearward flight zone
RC_PEDAL_BOTH_THR         =  0.15  # both pedals must be above this value
RC_PEDAL_DIFF_DEAD        =  0.08  # pedal differential below this = straight
RC_NOSE_PITCH_FWD_THR     =  0.10  # forward pitch above this = nose-down intent
RC_NOSE_PITCH_AFT_THR     =  0.10  # aft pitch 0.1-0.5 + both pedals = nose up
RC_HARD_BRAKE_PITCH_DEAD  =  0.20  # pitch must be within ±0.2 for hard brake
RC_MIN_RESPONSE_S         =  0.05  # 50ms — target max control lag for evasive manoeuvres

# State for new gesture modes
_RC_STATE = {
    # Turn tightening
    'turn_tight_active':     False,
    'turn_tight_t':          0.0,
    'turn_tight_bank_deg':   0.0,
    # Rearward flight
    'reverse_active':        False,
    'reverse_speed_ms':      0.0,
    'reverse_arc_dir':       0.0,   # -1=left, +1=right, 0=straight
    'reverse_arc_rate':      0.0,   # proportional to pedal differential
    # Nose attitude
    'nose_mode_active':      False,
    'nose_target_deg':       0.0,
    # Hard brake
    'hard_brake_active':     False,
    'hard_brake_intensity':  0.0,
}

# ── Gesture detection extensions ──────────────────────────────────────────────
def _rc_detect_gestures(sensors, result):
    """
    Detect the four new RC-series gestures from control inputs.
    Runs at 50 Hz inside stroke_smoothing_tick.
    Updates _RC_STATE in place.
    Returns dict of active gestures.
    """
    st = _RC_STATE
    now = _rc_time.monotonic()

    pitch_st = sensors.get('pitch_stick', 0.0)
    roll_st  = sensors.get('roll_stick',  0.0)
    ped_l    = sensors.get('pedal_left',  0.0)
    ped_r    = sensors.get('pedal_right', 0.0)
    lever    = sensors.get('lever_pct',  50.0)
    bank_deg = abs(sensors.get('roll_deg_imu', 0.0))
    h_agl    = sensors.get('h_agl_m', 100.0)
    V_ms     = sensors.get('V_ms', 0.0)

    both_pedals = (ped_l > RC_PEDAL_BOTH_THR and ped_r > RC_PEDAL_BOTH_THR)
    ped_diff    = ped_l - ped_r           # positive = left dominant
    ped_sum     = (ped_l + ped_r) / 2.0

    active = {}

    # ── 1. HIGH-BANK TURN TIGHTENING ─────────────────────────────────────────
    # Trigger: bank > 45° AND aft pitch > 0.7
    # Intensity: proportional to how far past 0.7 the aft pitch goes
    turn_tight = (bank_deg > RC_BANK_TURN_TIGHT_DEG and
                  pitch_st > RC_PITCH_TURN_TIGHT_THR and
                  V_ms > 4.0)   # needs forward speed
    if turn_tight:
        intensity = min(1.0, (pitch_st - RC_PITCH_TURN_TIGHT_THR) /
                             (1.0 - RC_PITCH_TURN_TIGHT_THR))
        # Direction from roll stick sign
        direction = 1.0 if roll_st > 0 else -1.0
        st['turn_tight_active']   = True
        st['turn_tight_bank_deg'] = bank_deg
        active['turn_tight'] = {
            'intensity':  intensity,
            'direction':  direction,
            'bank_deg':   bank_deg,
        }
    else:
        st['turn_tight_active'] = False

    # ── 2. REARWARD FLIGHT WITH ARC STEERING ─────────────────────────────────
    # Trigger: aft pitch > 0.5 AND both pedals > threshold
    # Speed: proportional to pitch deflection past 0.5
    # Arc: pedal differential sets direction and tightness
    reverse = (pitch_st > RC_REVERSE_PITCH_THR and
               both_pedals and h_agl > 0.3)
    if reverse:
        speed_factor = min(1.0, (pitch_st - RC_REVERSE_PITCH_THR) /
                                (1.0 - RC_REVERSE_PITCH_THR))
        # Pedal differential → arc steering
        if abs(ped_diff) < RC_PEDAL_DIFF_DEAD:
            arc_dir  = 0.0    # straight back
            arc_rate = 0.0
        else:
            arc_dir  = -1.0 if ped_diff > 0 else 1.0  # left pedal dom → left arc
            arc_rate = min(1.0, abs(ped_diff) / 0.5)   # tightness
        st['reverse_active']    = True
        st['reverse_speed_ms']  = speed_factor * 3.0   # max 3 m/s reverse
        st['reverse_arc_dir']   = arc_dir
        st['reverse_arc_rate']  = arc_rate
        active['reverse'] = {
            'speed_ms':  st['reverse_speed_ms'],
            'arc_dir':   arc_dir,
            'arc_rate':  arc_rate,
            'ped_sum':   ped_sum,
        }
    else:
        if st['reverse_active']:
            st['reverse_active'] = False  # exit → return to hover
        active['reverse'] = None

    # ── 3. HARD BRAKE — lever 0-3%, pitch neutral ────────────────────────────
    hard_brake = (lever <= HARD_BRAKE_LEVER_HI and
                  abs(pitch_st) <= RC_HARD_BRAKE_PITCH_DEAD and
                  h_agl > 0.3 and V_ms > 0.5)
    if hard_brake:
        # Intensity: proportional to how far lever is from 3%
        intensity = 1.0 - (lever / HARD_BRAKE_LEVER_HI)
        intensity = max(0.1, min(1.0, intensity))
        st['hard_brake_active']    = True
        st['hard_brake_intensity'] = intensity
        active['hard_brake'] = {'intensity': intensity}
    else:
        st['hard_brake_active']    = False
        st['hard_brake_intensity'] = 0.0
        active['hard_brake'] = None

    # ── 4. NOSE ATTITUDE CONTROL — both pedals + pitch stick ─────────────────
    # Forward pitch + both pedals = nose down (no drift)
    # Aft pitch 0.1-0.5 + both pedals = nose up (no drift)
    # Aft pitch 0.5-1.0 + both pedals = rearward flight (handled above)
    nose_mode = (both_pedals and not reverse and
                 (pitch_st > RC_NOSE_PITCH_FWD_THR or
                  (RC_NOSE_PITCH_AFT_THR < -pitch_st <= RC_REVERSE_PITCH_THR)))
    if nose_mode:
        if pitch_st > 0:
            # Forward pitch → nose down
            target_deg = -pitch_st * 20.0   # max -20° nose down
        else:
            # Gentle aft pitch → nose up
            target_deg = -pitch_st * 15.0   # max +15° nose up
        st['nose_mode_active']  = True
        st['nose_target_deg']   = target_deg
        active['nose_mode'] = {
            'target_deg':  target_deg,
            'direction':   'down' if pitch_st > 0 else 'up',
        }
    else:
        st['nose_mode_active'] = False
        active['nose_mode'] = None

    result['rc_gestures'] = active
    return result


# ── Wing kinematics for each mode ─────────────────────────────────────────────

def _rc_turn_tight_params(intensity, direction, bank_deg, base_config):
    """
    H-RC-1: High-bank turn tightening.
    Uses cascade braking (H-LB-1 mechanism) while maintaining the roll.
    Intensity 0-1: how aggressively to brake.
    Direction ±1: which way the bank is (determines cascade asymmetry).
    Body flat — no pitch change. Braking is horizontal only.
    """
    brake_cascade = 60.0 + intensity * 60.0    # 60°-120° cascade reversal
    amp_boost     = 1.0 + intensity * 0.10     # slight amp increase for G
    return {
        'freq_hz':           2.2,
        'aoa_deg':           13.0,
        'sweep_deg':         50.0,
        'amp_port_deg':      min(_PHYS_AMP_MAX, base_config.get('amp_port_deg', 96.0) * amp_boost),
        'amp_stbd_deg':      min(_PHYS_AMP_MAX, base_config.get('amp_stbd_deg', 96.0) * amp_boost),
        'cascade_phase_deg': brake_cascade,
        'dihedral_deg':      7.0,
        '_rc_turn_tight':    True,
        '_intensity':        intensity,
        '_direction':        direction,
    }


def _rc_reverse_params(speed_ms, arc_dir, arc_rate, base_config):
    """
    H-RC-2: Rearward flight.
    Front pairs reverse stroke plane → rearward thrust.
    Rear pairs maintain lift.
    Arc steering: differential cascade between port and stbd.
    Body flat. Lever controls altitude as hover.
    """
    # Speed factor 0-1 maps to cascade reversal magnitude
    reversal_cascade = 90.0 + (speed_ms / 3.0) * 45.0   # 90°→135° at max speed
    # Arc steering: differential amplitude between port and stbd
    diff_amp = arc_rate * 12.0   # ±12° differential at full pedal diff
    port_amp = min(_PHYS_AMP_MAX, 96.0 + arc_dir * diff_amp)
    stbd_amp = min(_PHYS_AMP_MAX, 96.0 - arc_dir * diff_amp)
    return {
        'freq_hz':           2.0,
        'aoa_deg':           14.0,
        'sweep_deg':         48.0,
        'amp_port_deg':      port_amp,
        'amp_stbd_deg':      stbd_amp,
        'cascade_phase_deg': reversal_cascade,
        'dihedral_deg':      6.0,
        '_rc_reverse':       True,
        '_speed_ms':         speed_ms,
        '_arc_dir':          arc_dir,
        '_arc_rate':         arc_rate,
    }


def _rc_hard_brake_params(intensity, base_config):
    """
    H-RC-3: Hard brake — no pitch, no altitude loss.
    Uses maximum symmetric cascade reversal for drag without attitude change.
    Competes with shuttle brake and pigeon steep in the discovery arena.
    Intensity 0-1 maps to braking severity.
    """
    cascade = 90.0 + intensity * 90.0     # 90°→180° full reversal at max
    amp     = min(_PHYS_AMP_MAX, 96.0 + intensity * 19.0)  # 96°→115°
    freq    = 1.87 + intensity * 0.5      # slightly higher freq for quicker action
    return {
        'freq_hz':           freq,
        'aoa_deg':           12.0,         # body flat
        'sweep_deg':         50.0,
        'amp_port_deg':      amp,
        'amp_stbd_deg':      amp,
        'cascade_phase_deg': cascade,
        'dihedral_deg':      0.0,          # no dihedral braking (that's pigeon)
        '_rc_hard_brake':    True,
        '_intensity':        intensity,
    }


def _rc_nose_params(target_deg, base_config):
    """
    H-RC-4: Nose attitude control — both pedals depressed.
    Adjusts stroke plane tilt for attitude change without drift.
    Rear pairs compensate for the pitch moment to prevent forward drift.
    Body stays at target attitude; position holds.
    """
    # Stroke plane tilt via cascade — front/rear differential
    cascade_offset = target_deg * 0.8   # deg of cascade per deg of pitch target
    cascade = max(0.0, min(_PHYS_CASCADE_MAX, 28.0 + cascade_offset))
    return {
        'freq_hz':           1.87,
        'aoa_deg':           max(_PHYS_AOA_MIN, min(_PHYS_AOA_MAX,
                                 13.0 + target_deg * 0.3)),
        'sweep_deg':         50.0,
        'amp_port_deg':      96.0,
        'amp_stbd_deg':      96.0,
        'cascade_phase_deg': cascade,
        'dihedral_deg':      7.0,
        '_rc_nose_mode':     True,
        '_target_deg':       target_deg,
    }


# ── Main RC tick — wired into stroke_smoothing_tick ───────────────────────────




def _obs_analyse_rc_manoeuvres(result):
    """Detect RC-series genome convergence and propose refinements."""
    rc_evals = sum(_hypothesis_results.get(h,{}).get('n_evaluations',0)
                   for h in ['H-RC-1','H-RC-2','H-RC-3','H-RC-4'])
    if rc_evals < 2:
        return None
    turn_wt  = _MW_TURN.get('lev_drag_precision',0)
    glide_wt = _MW_GLIDE.get('drag_minimise',0)
    if turn_wt > 0.35 and rc_evals >= 3:
        return {
            'category': 'raider_manoeuvres',
            'text':     (f"Turn tightening genome converging: lev_drag_precision "
                         f"at {turn_wt*100:.0f}% of turn axis — "
                         f"cascade braking is proving effective for radius compression. "
                         f"Shall I run a focused H-RC-1 trial?"),
            'priority': 3,
        }
    if glide_wt > 0.40 and rc_evals >= 3:
        return {
            'category': 'raider_manoeuvres',
            'text':     (f"Hard brake genome converging: drag_minimise "
                         f"at {glide_wt*100:.0f}% of glide axis — "
                         f"cascade maximum drag is proving the dominant braking mode. "
                         f"Shall I run a focused H-RC-3 trial at lever 1%?"),
            'priority': 3,
        }
    return None


def rc_manoeuvre_status():
    """
    GS: rc_manoeuvre_status
    Status of Raider/Cheyenne-inspired manoeuvres.
    AI: 'raider status' / 'evasive manoeuvres' / 'hard brake status' /
        'reverse flight status' / 'turn tightening' / 'nose attitude'
    """
    st = _RC_STATE
    print(f"\n  RAIDER/CHEYENNE MANOEUVRE STATUS")
    print(f"  ─────────────────────────────────────────")
    print(f"  Turn tightening:  {'ACTIVE' if st['turn_tight_active'] else 'standby'}"
          f"  (trigger: bank>45°, aft pitch>0.7)")
    print(f"  Reverse flight:   {'ACTIVE' if st['reverse_active'] else 'standby'}"
          f"  speed={st['reverse_speed_ms']:.1f}m/s  arc={st['reverse_arc_dir']:+.1f}")
    print(f"  Hard brake:       {'ACTIVE' if st['hard_brake_active'] else 'standby'}"
          f"  intensity={st['hard_brake_intensity']:.2f}")
    print(f"  Nose attitude:    {'ACTIVE' if st['nose_mode_active'] else 'standby'}"
          f"  target={st['nose_target_deg']:+.1f}°")
    print(f"\n  CONTROL MAPPING:")
    print(f"  H-RC-1 Turn tight: bank>45° + aft pitch>0.7")
    print(f"  H-RC-2 Reverse:    aft pitch>0.5 + both pedals")
    print(f"                     pedal diff → arc direction/tightness")
    print(f"  H-RC-3 Hard brake: lever 0-{HARD_BRAKE_LEVER_HI:.0f}% + pitch neutral")
    print(f"  H-RC-4 Nose:       both pedals + fwd pitch → nose down")
    print(f"                     both pedals + aft 0-0.5 → nose up")
    print(f"                     both pedals + aft 0.5-1.0 → reverse (H-RC-2)")
    print(f"\n  LEVER MAP (descent region):")
    print(f"    0-{HARD_BRAKE_LEVER_HI:.0f}%:   Hard brake (H-RC-3)")
    for band, info in _PIGEON_LEVER_MAP.items():
        print(f"    {info['lever_lo']:.0f}-{info['lever_hi']:.0f}%: "
              f"Pigeon {band} ({info['hyp_id']})  dih≈{info['dih_deg']:.0f}°")

_GS_ALLOWED_CMDS.add('rc_manoeuvre_status')


