# ── 1. GestureDetector — update class-level thresholds ────────────────────────
# Zoom: pilot asking for MAX thrust (lever ≥ 80%) + hard pull back
# Stoop: pilot reducing to approach/glide (lever ≤ 38%) + push forward
STOOP_AUTO_LEVER_THRESHOLD = LV_APPROACH_LO   # 38% — entering low-power
ZOOM_LEVER_MAX             = LV_SPRINT_LO     # 88% — must be in sprint zone
ZOOM_LEVER_MIN_RAW         = LV_SPRINT_LO     # same
STOOP_AUTO_LEVER_MAX_RAW   = LV_APPROACH_LO   # 38%

# ── 2. Lever sprint / trim end — used by GestureDetector for not_thrust_zone ──
# "Not thrust zone" now means lever < cruise (68%)
# "Trim end" means below detent hi (55%)
LEVER_SPRINT_END = LV_CRUISE_LO     # 68% — below this not sprint
LEVER_TRIM_END   = LV_DETENT_HI     # 55% — below this below trim

# ── 3. Soaring auto-activation — below trim detent (< 45%) ───────────────────
_SOR_LEVER_THRESHOLD = LV_DETENT_LO   # 45% — correct: pilot below neutral

# Patch soaring tick to use new threshold

def soaring_tick(sensors, result):
    """Soaring tick — updated lever threshold: active below detent (< 45%)."""
    # Temporarily redirect the threshold the tick reads
    result = None
    # Override soar_active based on new threshold
    lever = sensors.get('lever_pct', 50.0) if isinstance(sensors, dict) else 50.0
    if 'sor_active' in result:
        result['sor_active'] = lever < _SOR_LEVER_THRESHOLD
    return result


# ── 4. Pigeon descent tick — relocated to descent zone (16–28%) ───────────────
# New pigeon lever positions within the DESCENT zone (28–16%)
PD_NEW_SHALLOW_HI = LV_GLIDE_LO      # 28% — top of descent zone
PD_NEW_SHALLOW_LO = 22.0             # 22–28%: shallow pigeon (dih 25°)
PD_NEW_MODERATE_HI = 22.0            # 22%
PD_NEW_MODERATE_LO = 18.0            # 18–22%: moderate pigeon (dih 45°)
PD_NEW_STEEP_HI    = 18.0            # 18%
PD_NEW_STEEP_LO    = LV_DESCENT_LO   # 16–18%: steep/max (dih 60°)

# Update PIGEON_LEVER_MAP
_PIGEON_LEVER_MAP['shallow']['lever_lo']  = PD_NEW_SHALLOW_LO
_PIGEON_LEVER_MAP['shallow']['lever_hi']  = PD_NEW_SHALLOW_HI
_PIGEON_LEVER_MAP['moderate']['lever_lo'] = PD_NEW_MODERATE_LO
_PIGEON_LEVER_MAP['moderate']['lever_hi'] = PD_NEW_MODERATE_HI
_PIGEON_LEVER_MAP['steep']['lever_lo']    = PD_NEW_STEEP_LO
_PIGEON_LEVER_MAP['steep']['lever_hi']    = PD_NEW_STEEP_HI

# Hard brake now lives in ACTIVE_BRAKE zone (6–16%)
HARD_BRAKE_LEVER_HI = LV_DESCENT_LO    # 16% — top of active brake zone
HARD_BRAKE_LEVER_LO = LV_BRAKE_LO      # 6%  — bottom of active brake zone

# Patch pigeon descent tick

def _pigeon_descent_tick(sensors, result):
    """Pigeon descent tick — relocated to new descent zone (28–16%)."""
    lever  = sensors.get('lever_pct', 50.0) if isinstance(sensors, dict) else 50.0
    h_agl  = sensors.get('h_agl_m', 100.0) if isinstance(sensors, dict) else 100.0

    if lever > PD_NEW_SHALLOW_HI or h_agl < 0.5:
        result['pigeon_active'] = False
        return result

    result['pigeon_active'] = True
    roll_st = sensors.get('roll_stick', 0.0) if isinstance(sensors, dict) else 0.0

    if lever >= PD_NEW_SHALLOW_LO:
        t   = (PD_NEW_SHALLOW_HI - lever) / max(0.001, PD_NEW_SHALLOW_HI - PD_NEW_SHALLOW_LO)
        dih_sym  = t * 25.0
        dih_diff = 0.0
        mode = 'shallow_H-FD-2'
    elif lever >= PD_NEW_MODERATE_LO:
        t   = (PD_NEW_MODERATE_HI - lever) / max(0.001, PD_NEW_MODERATE_HI - PD_NEW_MODERATE_LO)
        dih_sym  = 25.0 + t * 20.0
        dih_diff = roll_st * 10.0
        mode = 'moderate_H-FD-1'
    else:
        t   = (PD_NEW_STEEP_HI - lever) / max(0.001, PD_NEW_STEEP_HI - PD_NEW_STEEP_LO + 0.001)
        dih_sym  = 45.0 + t * 35.0    # 45° → 80°
        dih_diff = roll_st * 20.0
        mode = 'steep_H-FD-3'

    dih_port = round(max(0.0, min(85.0, dih_sym + dih_diff)), 1)
    dih_stbd = round(max(0.0, min(85.0, dih_sym - dih_diff)), 1)

    result['pigeon_mode']     = mode
    result['pigeon_dih_sym']  = round(dih_sym, 1)
    result['pigeon_dih_port'] = dih_port
    result['pigeon_dih_stbd'] = dih_stbd
    result['pigeon_dih_diff'] = round(dih_diff, 1)
    result['pigeon_lever']    = round(lever, 1)
    return result


# ── 5. Brake tick — invert to low-lever ───────────────────────────────────────
# Old brake tick fired at HIGH lever (87-100%)
# New: fires at LOW lever (0-16%)

def lever_brake_tick(sensors, result):
    """
    Lever brake tick — inverted for new convention.
    Fires at LOW lever (0–16%) not high lever.
    0–6%:  Emergency stop — H-LB-3 maximum cascade reversal
    6–10%: Cascade brake — H-RC-3 hard brake
    10–16%: Lift dump / pigeon steep transition
    """
    lever  = sensors.get('lever_pct', 50.0) if isinstance(sensors, dict) else 50.0
    h_agl  = sensors.get('h_agl_m', 100.0) if isinstance(sensors, dict) else 100.0
    pitch  = sensors.get('pitch_stick', 0.0) if isinstance(sensors, dict) else 0.0

    if lever > LV_DESCENT_LO:   # above 16% — no braking
        result['brake_mode'] = 'none'
        result['brake_intensity'] = 0.0
        return result

    if lever <= LV_BRAKE_LO:    # 0–6%: emergency stop
        intensity = 1.0 - (lever / LV_BRAKE_LO)
        intensity = max(0.3, min(1.0, intensity))
        result['brake_mode']      = 'emergency_stop'
        result['brake_intensity'] = intensity
        result['brake_hyp']       = 'H-LB-3'

    elif lever <= HARD_BRAKE_LEVER_LO + 4.0:   # 6–10%: cascade brake
        intensity = 1.0 - ((lever - LV_BRAKE_LO) /
                           (HARD_BRAKE_LEVER_LO + 4.0 - LV_BRAKE_LO))
        if abs(pitch) <= RC_HARD_BRAKE_PITCH_DEAD:
            result['brake_mode']      = 'hard_brake'
            result['brake_intensity'] = max(0.2, intensity)
            result['brake_hyp']       = 'H-RC-3'
        else:
            result['brake_mode']      = 'pigeon_brake'
            result['brake_intensity'] = max(0.2, intensity)
            result['brake_hyp']       = 'H-FD-4'

    else:   # 10–16%: active brake / descent entry
        intensity = 1.0 - ((lever - (HARD_BRAKE_LEVER_LO + 4.0)) /
                           (LV_DESCENT_LO - (HARD_BRAKE_LEVER_LO + 4.0)))
        result['brake_mode']      = 'active_descent'
        result['brake_intensity'] = max(0.1, intensity)
        result['brake_hyp']       = 'H-FD-3'

    return result


