# ── Continuous performance scorer — runs at 1 Hz ──────────────────────────────
def _performance_scorer_tick(sensors, result):
    """
    Continuous performance scoring tick at 1 Hz.
    Updates _PERF_STATE and _MW_PERFORMANCE weights.
    Invisible to pilot. The genome improves without discrete hypothesis trials.
    """
    st  = _PERF_STATE
    ref = _PERF_REFERENCE
    now = __import__('time').monotonic()

    V_ms  = sensors.get('V_ms', 0.0) if isinstance(sensors, dict) else 0.0
    I_A   = sensors.get('motor_I_A', 0.0) if isinstance(sensors, dict) else 0.0
    V_b   = sensors.get('bus_voltage', 24.0) if isinstance(sensors, dict) else 24.0
    vsi   = sensors.get('vsi_smooth_ms', 0.0) if isinstance(sensors, dict) else 0.0
    pitch = sensors.get('pitch_stick', 0.0) if isinstance(sensors, dict) else 0.0
    h_agl = sensors.get('h_agl_m', 0.0) if isinstance(sensors, dict) else 0.0
    lever = sensors.get('lever_pct', 50.0) if isinstance(sensors, dict) else 50.0

    P_W = I_A * V_b

    # ── Top speed ─────────────────────────────────────────────────────────────
    if V_ms > st['v_max_ms']:
        st['v_max_ms'] = V_ms
    st['v_recent_max_ms'] = max(st['v_recent_max_ms'] * 0.99, V_ms)  # decay
    result['perf_v_max_ms'] = st['v_max_ms']

    # ── Cruise efficiency (only in cruise zone, moving, powered) ──────────────
    if (LV_DETENT_HI <= lever <= LV_CRUISE_LO and
            V_ms > 4.0 and P_W > 10.0):
        wh_per_km = (P_W / 3600.0) / max(V_ms * 0.001, 0.001)  # Wh/km
        st['wh_per_km_history'].append(wh_per_km)
        if len(st['wh_per_km_history']) >= 5:
            st['wh_per_km_current'] = sum(st['wh_per_km_history'][-10:]) / min(10, len(st['wh_per_km_history']))
            if st['wh_per_km_current'] < st['wh_per_km_best']:
                st['wh_per_km_best'] = st['wh_per_km_current']
                _MW_PERFORMANCE['cruise_efficiency'] = min(
                    0.5, _MW_PERFORMANCE['cruise_efficiency'] + 0.01)
        result['perf_wh_per_km'] = round(st['wh_per_km_current'], 2)

    # ── Hover efficiency (only hovering, powered) ─────────────────────────────
    if (V_ms < 2.0 and h_agl > 0.3 and P_W > 20.0):
        # FM = Thrust / Power, Thrust ≈ weight in steady hover
        m_total = _M_AIRFRAME_KG if hasattr(w,'_M_AIRFRAME_KG') else (
                   M_AIRFRAME_KG if hasattr(w,'M_AIRFRAME_KG') else 4.1)
        m_total += _flight_state.get('payload_kg', 0.0)
        T_est = m_total * 9.81
        fm = T_est / max(P_W, 1.0)
        st['n_per_w_history'].append(fm)
        if len(st['n_per_w_history']) >= 5:
            st['n_per_w_current'] = sum(st['n_per_w_history'][-10:]) / min(10, len(st['n_per_w_history']))
            if st['n_per_w_current'] > st['n_per_w_best']:
                st['n_per_w_best'] = st['n_per_w_current']
                _MW_PERFORMANCE['hover_efficiency'] = min(
                    0.5, _MW_PERFORMANCE['hover_efficiency'] + 0.01)
                # Also update cargo FM state
                if st['n_per_w_current'] > _CARGO_STATE.get('best_fm_N_per_W', 0):
                    _CARGO_STATE['best_fm_N_per_W'] = st['n_per_w_current']
        result['perf_n_per_w'] = round(st['n_per_w_current'], 4)

    # ── Intent latency ────────────────────────────────────────────────────────
    stick_now = abs(pitch)
    stick_prev = abs(st['_last_stick'])
    if abs(stick_now - stick_prev) > 0.05:
        st['_stick_change_t'] = now
    st['_last_stick'] = pitch

    # If we recorded a stick change and VSI has responded
    if (st['_stick_change_t'] > 0 and
            abs(vsi) > 0.1 and
            now - st['_stick_change_t'] < 2.0):
        latency_ms = (now - st['_stick_change_t']) * 1000.0
        if latency_ms > 10.0:   # filter noise
            st['latency_ms_history'].append(latency_ms)
            if len(st['latency_ms_history']) >= 5:
                st['latency_ms_current'] = sum(st['latency_ms_history'][-10:]) / min(10, len(st['latency_ms_history']))
                if st['latency_ms_current'] < st['latency_ms_best']:
                    st['latency_ms_best'] = st['latency_ms_current']
                    _MW_PERFORMANCE['intent_latency'] = min(
                        0.5, _MW_PERFORMANCE['intent_latency'] + 0.01)
            st['_stick_change_t'] = 0.0   # reset
        result['perf_latency_ms'] = round(st['latency_ms_current'], 0)

    # ── Precision hold ────────────────────────────────────────────────────────
    # Only score when in trim detent (pilot expecting altitude hold)
    if LV_DETENT_LO <= lever <= LV_DETENT_HI and h_agl > 1.0:
        rms_err = abs(vsi)   # simple: VSI should be ~0 in trim
        st['precision_rms_history'].append(rms_err)
        if len(st['precision_rms_history']) >= 10:
            prms = sum(st['precision_rms_history']) / len(st['precision_rms_history'])
            st['precision_rms_current'] = prms
            if prms < st['precision_rms_best']:
                st['precision_rms_best'] = prms
                _MW_PERFORMANCE['precision_hold'] = min(
                    0.5, _MW_PERFORMANCE['precision_hold'] + 0.01)
        result['perf_precision_rms'] = round(st['precision_rms_current'], 3)

    # ── Top speed genome update ───────────────────────────────────────────────
    if V_ms > ref['v_max_target_ms'] * 0.90:
        # Aircraft is achieving ≥90% of target speed
        _MW_PERFORMANCE['top_speed'] = min(
            0.5, _MW_PERFORMANCE['top_speed'] + 0.005)

    # ── Composite score ───────────────────────────────────────────────────────
    # Normalise each metric 0-1 (1=perfect, 0=worst)
    v_score    = min(1.0, V_ms / ref['v_max_target_ms'])
    eff_score  = max(0.0, 1.0 - st['wh_per_km_current'] / ref['wh_per_km_target']) \
                 if st['wh_per_km_current'] > 0 else 0.5
    fm_score   = min(1.0, st['n_per_w_current'] / ref['n_per_w_target']) \
                 if st['n_per_w_current'] > 0 else 0.5
    lat_score  = max(0.0, 1.0 - st['latency_ms_current'] / ref['latency_ms_target']) \
                 if st['latency_ms_current'] > 0 else 0.5
    prec_score = max(0.0, 1.0 - st['precision_rms_current'] / ref['precision_rms_target']) \
                 if st['precision_rms_current'] > 0 else 0.5

    composite = (v_score + eff_score + fm_score + lat_score + prec_score) / 5.0
    st['composite_score'] = composite
    st['composite_history'].append(composite)
    result['perf_composite'] = round(composite, 3)

    # If composite is improving, note it
    if len(st['composite_history']) >= 60:
        recent_mean  = sum(list(st['composite_history'])[-30:]) / 30.0
        earlier_mean = sum(list(st['composite_history'])[:30]) / 30.0
        if recent_mean > earlier_mean + 0.01:
            st['sessions_improving'] += 1
        st['sessions_total'] += 1

    # Renormalise _MW_PERFORMANCE
    total = sum(_MW_PERFORMANCE.values())
    if total > 0:
        for k in _MW_PERFORMANCE:
            _MW_PERFORMANCE[k] /= total

    return result


# ── Wire into position_hold_tick ──────────────────────────────────────────────

def position_hold_tick(sensors, result):
    """Position hold tick — extended with continuous performance scoring at 1Hz."""
    result = None
    tick = _flight_state.get('_perf_tick', 0) + 1
    _flight_state['_perf_tick'] = tick
    if tick % 50 == 0:   # 1 Hz at 50 Hz
        try:
            _performance_scorer_tick(sensors, result)
        except Exception as _e:
            _tick_error_log('performance_scorer', _e)
    return result



# ── Genome update routing for H-PERF ─────────────────────────────────────────

def _obs_analyse_performance(result):
    """
    Watch the composite performance trend.
    Propose action when the aircraft is measurably improving or stalling.
    """
    st = _PERF_STATE
    if len(st['composite_history']) < 60:
        return None   # not enough data
    recent  = sum(list(st['composite_history'])[-30:]) / 30.0
    earlier = sum(list(st['composite_history'])[-60:-30]) / 30.0
    delta   = recent - earlier

    # Identify which metric is weakest
    scores = {
        'top_speed':       min(1.0, st['v_max_ms'] / _PERF_REFERENCE['v_max_target_ms']),
        'efficiency':      max(0.0, 1.0 - st['wh_per_km_current'] / _PERF_REFERENCE['wh_per_km_target'])
                           if st['wh_per_km_current'] > 0 else 0.0,
        'hover_fm':        min(1.0, st['n_per_w_current'] / _PERF_REFERENCE['n_per_w_target'])
                           if st['n_per_w_current'] > 0 else 0.0,
        'intent_latency':  max(0.0, 1.0 - st['latency_ms_current'] / _PERF_REFERENCE['latency_ms_target'])
                           if st['latency_ms_current'] > 0 else 0.0,
        'precision':       max(0.0, 1.0 - st['precision_rms_current'] / _PERF_REFERENCE['precision_rms_target'])
                           if st['precision_rms_current'] > 0 else 0.0,
    }
    weakest = min(scores, key=scores.get)
    weakest_score = scores[weakest]

    if weakest_score < 0.4:
        focus_map = {
            'top_speed':      ('H-PERF-1', 'top speed — maximum airspeed'),
            'efficiency':     ('H-PERF-2', 'cruise efficiency — Wh/km'),
            'hover_fm':       ('H-PERF-3', 'hover figure of merit'),
            'intent_latency': ('H-PERF-4', 'intent latency — response time'),
            'precision':      ('H-PERF-5', 'precision hold — trim stability'),
        }
        hid, desc = focus_map[weakest]
        return {
            'category': 'performance',
            'text':     (f"Performance composite: {recent:.2f}. "
                         f"Weakest dimension: {desc} at {weakest_score*100:.0f}% of target. "
                         f"Shall I run a focused {hid} trial to improve it?"),
            'priority': 2,
        }
    if delta > 0.05:
        return {
            'category': 'performance',
            'text':     (f"Aircraft is improving: composite {earlier:.2f}→{recent:.2f} "
                         f"over last 60 seconds. Continuing current genome direction."),
            'priority': 4,
        }
    return None

# Patch ai_observer_tick

def performance_status():
    """
    GS: performance_status
    Current performance metrics across all four dimensions.
    AI: 'performance status' / 'how fast is it' / 'how efficient' /
        'is it improving' / 'composite performance' / 'response time' /
        'intent latency' / 'top speed' / 'cruise efficiency'
    """
    st  = _PERF_STATE
    ref = _PERF_REFERENCE

    print(f"\n  AIRCRAFT PERFORMANCE STATUS")
    print(f"  ─────────────────────────────────────────")
    print(f"  Composite score:    {st['composite_score']:.3f} / 1.000")
    if st['sessions_total'] > 0:
        pct = st['sessions_improving'] / st['sessions_total'] * 100
        print(f"  Improving:          {pct:.0f}% of recent windows")

    print(f"\n  TOP SPEED:")
    print(f"    All-time max:     {st['v_max_ms']:.2f} m/s  "
          f"({st['v_max_ms']*3.6:.1f} km/h)")
    print(f"    Target:           {ref['v_max_target_ms']:.1f} m/s  "
          f"({ref['v_max_target_ms']*3.6:.1f} km/h)")
    print(f"    Attainment:       {min(100,st['v_max_ms']/ref['v_max_target_ms']*100):.0f}%")

    print(f"\n  CRUISE EFFICIENCY:")
    if st['wh_per_km_current'] > 0:
        print(f"    Current:          {st['wh_per_km_current']:.2f} Wh/km")
        print(f"    Best:             {st['wh_per_km_best']:.2f} Wh/km")
        print(f"    Target:           {ref['wh_per_km_target']:.1f} Wh/km")
    else:
        print(f"    Not yet measured — fly in cruise zone (68–55%)")

    print(f"\n  HOVER EFFICIENCY (Figure of Merit):")
    if st['n_per_w_current'] > 0:
        print(f"    Current:          {st['n_per_w_current']:.4f} N/W")
        print(f"    Best:             {st['n_per_w_best']:.4f} N/W")
        print(f"    Target:           {ref['n_per_w_target']:.3f} N/W")
    else:
        print(f"    Not yet measured — hover in trim detent")

    print(f"\n  INTENT LATENCY (stick→response):")
    if st['latency_ms_current'] > 0:
        print(f"    Current:          {st['latency_ms_current']:.0f} ms")
        print(f"    Best:             {st['latency_ms_best']:.0f} ms")
        print(f"    Target:           < {ref['latency_ms_target']:.0f} ms")
    else:
        print(f"    Not yet measured — make stick inputs in flight")

    print(f"\n  PRECISION HOLD:")
    if st['precision_rms_current'] > 0:
        print(f"    Current RMS:      {st['precision_rms_current']:.3f} m/s")
        print(f"    Best RMS:         {st['precision_rms_best']:.3f} m/s")
        print(f"    Target:           < {ref['precision_rms_target']:.2f} m/s")
    else:
        print(f"    Not yet measured — hold trim detent in stable air")

    print(f"\n  PERFORMANCE GENOME (_MW_PERFORMANCE):")
    total = max(sum(_MW_PERFORMANCE.values()), 0.001)
    for mech, wt in sorted(_MW_PERFORMANCE.items(), key=lambda x: -x[1]):
        pct = wt / total * 100
        bar = '█' * int(pct / 5)
        print(f"    {mech:<20} {pct:>5.1f}%  {bar}")

