def _obs_analyse_stoop_family(result):
    """Watch gust suppression and stoop family for convergence."""
    stoop_evals = sum(_hypothesis_results.get(h,{}).get('n_evaluations',0)
                      for h in ['H-GS-1','H-STOOP-1','H-PULL-1'])
    if stoop_evals < 2:
        return None

    # Check gust suppression body RMS
    gs_state = _GS_STATE
    stoop_state = _STOOP_STATE
    pull_state = _PULL_STATE

    if gs_state['suppression_events'] > 20:
        drag_wt = _MW_STABILITY.get('stroke_dihedral', 0)
        if drag_wt > 0.35:
            return {
                'category': 'stoop_family',
                'text':     (f"Gust suppression genome converging: "
                             f"{gs_state['suppression_events']} events logged. "
                             f"stroke_dihedral at {drag_wt*100:.0f}% of stability axis. "
                             f"Shall I run a focused H-GS-1 trial in turbulent conditions?"),
                'priority': 3,
            }

    if stoop_state['peak_V_ms'] > STOOP_V_CRUISE * 1.5:
        return {
            'category': 'stoop_family',
            'text':     (f"Peak dive speed recorded: {stoop_state['peak_V_ms']:.1f} m/s "
                         f"({stoop_state['peak_V_ms']/STOOP_V_CRUISE:.1f}× cruise). "
                         f"Safe dihedral at that speed: {stoop_state['safe_dih_deg']:.0f}°. "
                         f"Shall I run H-STOOP-1 to optimise the dart profile?"),
            'priority': 3,
        }

    return None


