# WHISPER MODE
#
# A pilot-commanded acoustic reduction mode that applies the whisper
# principle (lower frequency, higher amplitude, maintained Strouhal number)
# across the entire wave lever map.
#
# ACTIVATION: Pilot tells the AI client in plain language.
#   "Enable whisper mode" / "go quiet" / "whisper on" / "acoustic stealth"
#   "silence mode" / "quiet mode" / "reduce noise" / etc.
#
# DEACTIVATION: Pilot tells the AI client to disable.
#   "Disable whisper mode" / "whisper off" / "normal mode" / etc.
#
# DESIGN INTENT:
#   - Not used routinely — only when acoustic signature matters
#   - Applied across all lever zones with zone-appropriate freq/amp swaps
#   - The genome and optimizer track whisper vs nominal performance
#     and over time discover configurations that are quieter with
#     less efficiency penalty — the mode gets better without being redesigned
#   - Performance penalty is acknowledged and accepted when activated
#   - The pilot is informed of the approximate acoustic and efficiency trade
#
# ACOUSTIC REDUCTIONS (computed, Gutin model at 76m):
#   Emergency stop:   -6.2 dB tonal, -7.8 dB broadband
#   Active brake:     -4.3 dB tonal, -5.4 dB broadband
#   Descent:          -3.1 dB tonal, -3.9 dB broadband
#   Glide/Soar:       already near-silent, no change
#   Approach:         -2.5 dB tonal, -3.2 dB broadband
#   Trim/Hover:       -3.1 dB tonal, -3.9 dB broadband
#   Cruise:           -3.1 dB tonal, -3.9 dB broadband
#   Powered climb:    -3.1 dB tonal, -3.9 dB broadband (free — efficiency improves)
#   High thrust:      -5.2 dB tonal, -6.5 dB broadband
#   Max thrust:       -8.1 dB tonal,-10.0 dB broadband
#   Average:          -4.3 dB tonal, -5.4 dB broadband
#
# Perceptual equivalent: aircraft sounds roughly half as loud across
# all powered phases. At cruise, equivalent to moving observer 30-40%
# farther away.
# ══════════════════════════════════════════════════════════════════════════════

import math as _wm_math
import time as _wm_time

# ── Whisper mode state ────────────────────────────────────────────────────────
_WHISPER_STATE = {
    'active':           False,
    'activated_t':      0.0,       # monotonic time of activation
    'activated_by':     None,      # 'pilot' always (never auto)
    'n_activations':    0,
    # Performance tracking while in whisper mode
    'whisper_sessions': [],        # list of {duration_s, zones_visited, spl_est}
    'current_session_t': 0.0,
    # Genome improvement tracking
    'best_spl_per_zone':   {},     # zone_id → lowest SPL achieved in whisper
    'best_config_per_zone':{},     # zone_id → config that achieved it
    'efficiency_log':      [],     # (lever_pct, Wh_per_km_whisper, Wh_per_km_nom)
}

# Whisper frequency/amplitude map by lever zone
# Each entry: (whisper_freq_hz, whisper_amp_deg)
# Designed to maintain approximately Strouhal 0.27–0.32 where possible
# and minimise tip velocity (the primary acoustic driver) elsewhere
_WHISPER_ZONE_MAP = {
    'MAX_THRUST':    (2.2, 115.0),  # -8.1 dB tonal; 32% St penalty; brief use only
    'HIGH_THRUST':   (2.0, 112.0),  # -5.2 dB tonal; 29% St penalty
    'POWERED_CLIMB': (1.7, 108.0),  # -3.1 dB tonal; 1%  St penalty — free
    'CRUISE':        (1.5, 100.0),  # -3.1 dB tonal; 34% St penalty
    'TRIM_DETENT':   (1.5, 100.0),  # -3.1 dB tonal; hover — efficiency cost moderate
    'APPROACH':      (1.2, 108.0),  # -2.5 dB tonal; 29% St penalty
    'GLIDE_SOAR':    (0.0,   0.0),  # motors off — already silent, no change
    'DESCENT':       (1.5, 100.0),  # -3.1 dB tonal; 16% St penalty
    'ACTIVE_BRAKE':  (1.8, 105.0),  # -4.3 dB tonal; 8%  St penalty — acceptable
    'EMERGENCY_STOP':(2.2,  96.0),  # -6.2 dB tonal; 40% St penalty; cascade does braking
}

# Efficiency penalty by zone (Strouhal deviation from optimal)
_WHISPER_EFFICIENCY_PENALTY = {
    'MAX_THRUST':    0.32,   # 32% — use briefly
    'HIGH_THRUST':   0.29,
    'POWERED_CLIMB': 0.01,   # 1%  — essentially free
    'CRUISE':        0.34,
    'TRIM_DETENT':   0.30,
    'APPROACH':      0.29,
    'GLIDE_SOAR':    0.00,
    'DESCENT':       0.16,
    'ACTIVE_BRAKE':  0.08,
    'EMERGENCY_STOP':0.40,   # 40% — cascade dominates, Strouhal irrelevant
}

# Acoustic reductions (tonal dB, broadband dB)
_WHISPER_REDUCTIONS = {
    'MAX_THRUST':    (-8.1, -10.0),
    'HIGH_THRUST':   (-5.2,  -6.5),
    'POWERED_CLIMB': (-3.1,  -3.9),
    'CRUISE':        (-3.1,  -3.9),
    'TRIM_DETENT':   (-3.1,  -3.9),
    'APPROACH':      (-2.5,  -3.2),
    'GLIDE_SOAR':    ( 0.0,   0.0),
    'DESCENT':       (-3.1,  -3.9),
    'ACTIVE_BRAKE':  (-4.3,  -5.4),
    'EMERGENCY_STOP':(-6.2,  -7.8),
}


# ── Whisper lever override ────────────────────────────────────────────────────
def _whisper_apply_to_params(zone, params):
    """
    Apply whisper frequency/amplitude to a params dict returned by
    unified_lever_to_params. Called after the normal lever lookup
    when whisper mode is active. Returns modified params.
    Preserves all other parameters (cascade, dihedral, mode_id etc).
    GLIDE_SOAR zone is unchanged — already silent.
    """
    if zone not in _WHISPER_ZONE_MAP:
        return params
    wf, wa = _WHISPER_ZONE_MAP[zone]
    if wf == 0.0:
        return params   # glide — no change
    params = dict(params)   # copy
    params['freq_hz']       = wf
    params['amp_port_deg']  = wa
    params['amp_stbd_deg']  = wa
    params['whisper']       = True
    return params


def whisper_lever_params(lev_pct, V_ms=7.0, h_agl_m=100.0):
    """
    Whisper-mode version of unified_lever_to_params.
    Returns acoustic-reduced params when whisper mode is active.
    Falls through to normal params when inactive.
    """
    p = unified_lever_to_params(lev_pct, V_ms, h_agl_m)
    if not _WHISPER_STATE['active']:
        return p
    zone = p.get('zone', 'CRUISE')
    return _whisper_apply_to_params(zone, p)


# ── Whisper tick — runs in stroke_smoothing_tick ──────────────────────────────
def _whisper_tick(sensors, result):
    """
    Whisper mode management tick at 50 Hz.
    When active: applies whisper kinematics, tracks acoustic improvement.
    """
    st = _WHISPER_STATE
    if not st['active']:
        result['whisper_active'] = False
        return result

    result['whisper_active'] = True
    lever = sensors.get('lever_pct', 50.0) if isinstance(sensors,dict) else 50.0
    V_ms  = sensors.get('V_ms', 7.0) if isinstance(sensors,dict) else 7.0
    I_A   = sensors.get('motor_I_A', 0.0) if isinstance(sensors,dict) else 0.0
    V_b   = sensors.get('bus_voltage', 24.0) if isinstance(sensors,dict) else 24.0

    # Get whisper params for current lever
    wp = whisper_lever_params(lever, V_ms)
    zone = wp.get('zone', 'CRUISE')
    freq = wp.get('freq_hz', 1.87)
    amp  = wp.get('amp_port_deg', 96.0)

    # Estimate current SPL via Gutin model
    span = 0.772; n_wings = 8; S_wing = span * 0.12
    T_est = 4.1 * 9.81 + _flight_state.get('payload_kg', 0.0) * 9.81
    amp_r = _wm_math.radians(amp)
    v_tip = 2 * _wm_math.pi * freq * span * amp_r if amp > 0 else 0.0
    rho = 1.225; c = 343.0; obs = 76.2; p_ref = 2e-5
    A = n_wings * S_wing
    if v_tip > 0 and T_est > 0:
        W = (T_est**2 * v_tip**4 /
             (4 * _wm_math.pi * obs**2 * rho**2 * c**4 * A**2))
        spl_est = max(0.0, 10 * _wm_math.log10(W / p_ref**2 + 1e-30))
    else:
        spl_est = 0.0

    result['whisper_zone']    = zone
    result['whisper_freq_hz'] = freq
    result['whisper_amp_deg'] = amp
    result['whisper_spl_db']  = round(spl_est, 1)

    # Track best SPL per zone — genome improvement signal
    prev_best = st['best_spl_per_zone'].get(zone, 999.0)
    if 0 < spl_est < prev_best:
        st['best_spl_per_zone'][zone] = spl_est
        st['best_config_per_zone'][zone] = {
            'freq_hz': freq, 'amp_deg': amp, 'V_ms': V_ms,
        }
        # Boost genome
        _MW_PERFORMANCE['precision_hold'] = min(
            0.5, _MW_PERFORMANCE['precision_hold'] + 0.002)
        total = sum(_MW_PERFORMANCE.values())
        for k in _MW_PERFORMANCE: _MW_PERFORMANCE[k] /= total

    # Track efficiency (cruise zone only — meaningful comparison)
    P_W = I_A * V_b
    if zone == 'CRUISE' and V_ms > 4.0 and P_W > 10.0:
        wh_per_km = (P_W / 3600.0) / max(V_ms * 0.001, 0.001)
        st['efficiency_log'].append({
            'lever': round(lever, 1),
            'V_ms': round(V_ms, 1),
            'wh_per_km': round(wh_per_km, 2),
            'mode': 'whisper',
        })

    return result


# Wire into stroke_smoothing_tick

def stroke_smoothing_tick(sensors, result):
    """Stroke smoothing — extended with whisper mode management."""
    result = None
    try:
        _whisper_tick(sensors, result)
    except Exception as _e:
        _tick_error_log('whisper_tick', _e)
    return result



# ── Genome update for whisper ─────────────────────────────────────────────────

def _obs_analyse_whisper(result):
    """
    Watch whisper mode acoustic improvement over sessions.
    Fires when whisper mode has meaningful data and improvement is detectable.
    """
    st = _WHISPER_STATE
    if not st['best_spl_per_zone']:
        return None
    if st['n_activations'] < 2:
        return None

    # Check if any zone has improved since first activation
    improved = {z: spl for z,spl in st['best_spl_per_zone'].items() if spl < 20.0}
    if improved:
        best_z = min(improved, key=improved.get)
        return {
            'category': 'whisper',
            'text':     (f"Whisper mode improvement detected: "
                         f"{best_z} zone now achieving {improved[best_z]:.1f} dB "
                         f"at 76m. "
                         f"The genome has improved whisper performance through "
                         f"{st['n_activations']} activation sessions. "
                         f"Shall I run a focused H-AQ trial to push further?"),
            'priority': 4,
        }
    return None


def whisper_on():
    """
    GS: whisper_on
    Enable whisper mode — acoustic reduction across all lever zones.
    Pilot activates explicitly. Never auto-enabled.
    AI: 'whisper mode on' / 'go quiet' / 'enable whisper' / 'acoustic stealth' /
        'quiet mode' / 'silence mode' / 'reduce noise' / 'stealth mode' /
        'activate whisper' / 'whisper please' / 'make it quieter' /
        'reduce acoustic signature' / 'whisper flight'
    """
    st = _WHISPER_STATE
    if st['active']:
        print(f"\n  Whisper mode is already active.")
        print(f"  Activated {int(_wm_time.monotonic()-st['activated_t'])}s ago.")
        return

    st['active']          = True
    st['activated_t']     = _wm_time.monotonic()
    st['activated_by']    = 'pilot'
    st['current_session_t'] = _wm_time.monotonic()
    st['n_activations']  += 1

    print(f"\n  ◉ WHISPER MODE ACTIVE")
    print(f"  ─────────────────────────────────────────────")
    print(f"  Acoustic reduction applied across all lever zones.")
    print(f"  Average reduction: ~4.3 dB tonal, ~5.4 dB broadband.")
    print(f"  Perceived loudness approximately halved.")
    print(f"\n  Zone-by-zone acoustic reduction:")
    for zone, (dt, db) in _WHISPER_REDUCTIONS.items():
        if dt == 0.0:
            print(f"    {zone:<18} already silent (glide/soar)")
            continue
        wf, wa = _WHISPER_ZONE_MAP[zone]
        pen = _WHISPER_EFFICIENCY_PENALTY[zone]
        note = '← free' if pen < 0.05 else (f'~{pen*100:.0f}% efficiency cost' if pen > 0.20 else '')
        print(f"    {zone:<18} {dt:+.1f} dB tonal   {note}")
    print(f"\n  Performance note:")
    print(f"    Powered climb zone: efficiency IMPROVES (Strouhal moves toward optimum)")
    print(f"    Cruise/trim zones:  ~30% efficiency cost — range reduced")
    print(f"    Max thrust zone:    8 dB quieter but 32% less thrust efficiency")
    print(f"    Emergency stop:     quieter, braking unchanged (cascade-dominated)")
    print(f"\n  Say 'whisper off' or 'disable whisper' to return to normal.")
    print(f"\n  The genome will improve whisper performance over time.")
    print(f"  Current session: #{st['n_activations']}")

    _pl_append_log({'event': 'whisper_mode_on', 'session': st['n_activations']})


def whisper_off():
    """
    GS: whisper_off
    Disable whisper mode — return to normal kinematic optimisation.
    AI: 'whisper off' / 'disable whisper' / 'normal mode' / 'full power' /
        'turn off quiet mode' / 'deactivate whisper' / 'whisper mode off' /
        'back to normal' / 'standard mode' / 'performance mode'
    """
    st = _WHISPER_STATE
    if not st['active']:
        print(f"\n  Whisper mode is not currently active.")
        return

    duration_s = _wm_time.monotonic() - st['current_session_t']
    st['active']      = False
    st['activated_by']= None

    # Log the session
    st['whisper_sessions'].append({
        'duration_s': round(duration_s, 1),
        'best_spl':   min(st['best_spl_per_zone'].values())
                      if st['best_spl_per_zone'] else 0.0,
    })

    print(f"\n  ○ WHISPER MODE DISABLED")
    print(f"  Session duration: {int(duration_s)}s")
    print(f"  Total sessions:   {st['n_activations']}")
    if st['best_spl_per_zone']:
        best_z = min(st['best_spl_per_zone'], key=st['best_spl_per_zone'].get)
        print(f"  Best SPL achieved: {st['best_spl_per_zone'][best_z]:.1f} dB "
              f"in {best_z} zone")
    print(f"  Returning to normal performance-optimised kinematics.")

    _pl_append_log({'event': 'whisper_mode_off', 'duration_s': round(duration_s,1)})


def whisper_status():
    """
    GS: whisper_status
    Current whisper mode state and acoustic performance.
    AI: 'whisper status' / 'how quiet is it' / 'acoustic status' /
        'current noise level' / 'is whisper on' / 'whisper mode status'
    """
    st = _WHISPER_STATE
    print(f"\n  WHISPER MODE STATUS")
    print(f"  ─────────────────────────────────────────")
    status = '◉ ACTIVE' if st['active'] else '○ inactive'
    print(f"  State:           {status}")
    if st['active']:
        t = int(_wm_time.monotonic() - st['activated_t'])
        print(f"  Active for:      {t}s")
    print(f"  Total sessions:  {st['n_activations']}")

    if st['best_spl_per_zone']:
        print(f"\n  Best SPL per zone (genome improvement):")
        for zone, spl in sorted(st['best_spl_per_zone'].items(),
                                 key=lambda x: x[1]):
            cfg = st['best_config_per_zone'].get(zone, {})
            print(f"    {zone:<18} {spl:.1f} dB  "
                  f"@ {cfg.get('freq_hz',0):.2f}Hz / {cfg.get('amp_deg',0):.0f}°")
    else:
        print(f"\n  No whisper data yet — activate whisper mode in flight.")

    if not st['active']:
        print(f"\n  Say 'whisper on' or 'go quiet' to activate.")

    print(f"\n  EXPECTED REDUCTIONS (computed, Gutin model at 76m):")
    for zone, (dt, db) in _WHISPER_REDUCTIONS.items():
        if dt == 0.0:
            print(f"    {zone:<18} already silent")
        else:
            print(f"    {zone:<18} {dt:>+5.1f} dB tonal   {db:>+5.1f} dB broadband")

_GS_ALLOWED_CMDS.update({'whisper_on', 'whisper_off', 'whisper_status'})


