_CMTS_CHAMPIONS = {
    'cruise_efficiency':  {'config': None, 'wh_per_km': 999.0,
                           'spl_db': 999.0, 'n_per_w': 0.0,
                           'source_hyp': None, 'n_obs': 0},
    'hover_efficiency':   {'config': None, 'n_per_w': 0.0,
                           'spl_db': 999.0, 'trim_rms': 999.0,
                           'source_hyp': None, 'n_obs': 0},
    'acoustic':           {'config': None, 'spl_db': 999.0,
                           'wh_per_km': 999.0, 'n_per_w': 0.0,
                           'source_hyp': None, 'n_obs': 0},
    'precision':          {'config': None, 'trim_rms': 999.0,
                           'latency_ms': 999.0, 'spl_db': 999.0,
                           'source_hyp': None, 'n_obs': 0},
    'top_speed':          {'config': None, 'v_max_ms': 0.0,
                           'spl_db': 999.0, 'wh_per_km': 999.0,
                           'source_hyp': None, 'n_obs': 0},
    'climb_rate':         {'config': None, 'vsi_ms': 0.0,
                           'wh_per_km': 999.0, 'spl_db': 999.0,
                           'source_hyp': None, 'n_obs': 0},
    'intent_response':    {'config': None, 'latency_ms': 999.0,
                           'trim_rms': 999.0, 'spl_db': 999.0,
                           'source_hyp': None, 'n_obs': 0},
}

# History of pending and confirmed transfers
_CMTS_TRANSFERS = {
    'pending':    [],   # [{source_hyp, target_context, metric, delta, config}]
    'confirmed':  [],   # same + confirmed_t
    'rejected':   [],   # same + rejected_t
    'silent':     [],   # auto-promoted (no tradeoff)
}

# Minimum observations before a cross-mode beat is considered credible
_CMTS_MIN_OBS         = 3
# Improvement threshold: must beat champion by at least this fraction
_CMTS_BEAT_THRESHOLD  = 0.05   # 5% improvement required
# Tradeoff threshold: this much degradation on secondary metric = needs pilot
_CMTS_TRADEOFF_THRESH = 0.03   # 3% degradation = tradeoff exists


def _cmts_score_config(config, sensors, result, hyp_id):
    """
    Score a wing configuration against ALL five standard metrics.
    Called after every hypothesis evaluation with live sensor/result data.
    Returns a dict of metric values.

    Metrics that can be directly measured from sensors/result:
      spl_db       — from Gutin model (freq, amp, thrust)
      wh_per_km    — from motor power and airspeed
      n_per_w      — from thrust estimate and motor power
      latency_ms   — from intent latency state
      trim_rms     — from VSI stability over last 10s
    """
    freq    = config.get('freq_hz', 1.87)
    amp     = config.get('amp_port_deg', 96.0)
    V_ms    = sensors.get('V_ms', 7.0) if isinstance(sensors, dict) else 7.0
    I_A     = sensors.get('motor_I_A', 0.0) if isinstance(sensors, dict) else 0.0
    V_b     = sensors.get('bus_voltage', 24.0) if isinstance(sensors, dict) else 24.0
    vsi     = sensors.get('vsi_smooth_ms', 0.0) if isinstance(sensors, dict) else 0.0

    P_W   = max(I_A * V_b, 0.001)
    T_est = (M_AIRFRAME_KG + _flight_state.get('payload_kg', 0.0)) * 9.81

    # ── Acoustic (Gutin) ──────────────────────────────────────────────────────
    span = 0.772; n_wings = 8; S_wing = span * 0.12
    amp_r = math.radians(amp)
    v_tip = 2 * math.pi * freq * span * amp_r if amp > 0 else 0.0
    rho = 1.225; c = 343.0; obs = 76.2; p_ref = 2e-5
    A = n_wings * S_wing
    if v_tip > 0 and T_est > 0:
        try:
            W = (T_est**2 * v_tip**4 /
                 (4 * math.pi * obs**2 * rho**2 * c**4 * A**2))
            spl_db = max(0.0, 10 * math.log10(W / p_ref**2 + 1e-30))
        except Exception:
            spl_db = 999.0
    else:
        spl_db = 0.0  # motors off / glide — silent

    # ── Cruise efficiency ─────────────────────────────────────────────────────
    if V_ms > 2.0:
        wh_per_km = (P_W / 3600.0) / max(V_ms * 0.001, 0.001)
    else:
        wh_per_km = 999.0  # hover — not meaningful for cruise metric

    # ── Hover figure of merit ─────────────────────────────────────────────────
    if V_ms < 2.0 and P_W > 5.0:
        n_per_w = T_est / P_W
    else:
        n_per_w = _PERF_STATE.get('n_per_w_current', 0.0)

    # ── Intent latency ────────────────────────────────────────────────────────
    latency_ms = _PERF_STATE.get('latency_ms_current', 999.0)

    # ── Trim RMS (VSI stability) ──────────────────────────────────────────────
    trim_rms = _PERF_STATE.get('precision_rms_current', 999.0)

    # ── VSI (climb rate — for climb_rate context) ─────────────────────────────
    vsi_ms = result.get('vsi_smooth_ms', vsi) if isinstance(result, dict) else vsi

    # ── Top speed ─────────────────────────────────────────────────────────────
    v_max_ms = max(V_ms, _PERF_STATE.get('v_recent_max_ms', 0.0))

    return {
        'spl_db':     round(spl_db, 2),
        'wh_per_km':  round(wh_per_km, 3),
        'n_per_w':    round(n_per_w, 5),
        'latency_ms': round(latency_ms, 1),
        'trim_rms':   round(trim_rms, 4),
        'vsi_ms':     round(vsi_ms, 3),
        'v_max_ms':   round(v_max_ms, 2),
    }


def _cmts_update_champions(hyp_id, config, scores):
    """
    Compare this configuration's scores against all context champions.
    Update champions and queue transfer proposals where appropriate.
    """
    transfers_queued = []

    # Context definitions: (primary_metric, direction, secondary_metrics)
    # direction: -1 = lower is better, +1 = higher is better
    contexts = {
        'cruise_efficiency': ('wh_per_km', -1, ['spl_db', 'n_per_w']),
        'hover_efficiency':  ('n_per_w',   +1, ['spl_db', 'trim_rms']),
        'acoustic':          ('spl_db',    -1, ['wh_per_km', 'n_per_w']),
        'precision':         ('trim_rms',  -1, ['latency_ms', 'spl_db']),
        'top_speed':         ('v_max_ms',  +1, ['spl_db', 'wh_per_km']),
        'climb_rate':        ('vsi_ms',    +1, ['wh_per_km', 'spl_db']),
        'intent_response':   ('latency_ms',-1, ['trim_rms', 'spl_db']),
    }

    for ctx_name, (primary, direction, secondaries) in contexts.items():
        champion = _CMTS_CHAMPIONS[ctx_name]
        new_val  = scores.get(primary)
        old_val  = champion.get(primary)

        if new_val is None or old_val is None:
            continue
        # Skip invalid values
        if new_val in (0.0, 999.0) and direction == -1:
            continue
        if new_val == 0.0 and direction == +1:
            continue
        if old_val in (0.0, 999.0) and direction == -1:
            # No valid champion yet — install immediately
            champion.update({
                'config':     dict(config),
                primary:      new_val,
                'source_hyp': hyp_id,
                'n_obs':      1,
            })
            for s in secondaries:
                if s in scores: champion[s] = scores[s]
            continue

        # Compute improvement
        if direction == -1:
            improvement = (old_val - new_val) / max(abs(old_val), 0.001)
        else:
            improvement = (new_val - old_val) / max(abs(old_val), 0.001)

        if improvement <= 0:
            continue   # not better

        # Increment observation count
        champion['n_obs'] = champion.get('n_obs', 0) + 1

        if improvement < _CMTS_BEAT_THRESHOLD:
            continue   # beats champion but below significance threshold

        if champion['n_obs'] < _CMTS_MIN_OBS:
            continue   # not enough observations to be credible

        # Check secondary metrics for tradeoffs
        has_tradeoff = False
        tradeoff_info = []
        for sec in secondaries:
            new_sec = scores.get(sec)
            old_sec = champion.get(sec)
            if new_sec is None or old_sec is None:
                continue
            # Determine if secondary is better-when-lower or better-when-higher
            sec_dir = -1 if sec in ('spl_db','wh_per_km','trim_rms','latency_ms') else +1
            if sec_dir == -1:
                sec_delta = (new_sec - old_sec) / max(abs(old_sec), 0.001)
            else:
                sec_delta = (old_sec - new_sec) / max(abs(old_sec), 0.001)
            if sec_delta > _CMTS_TRADEOFF_THRESH:
                has_tradeoff = True
                tradeoff_info.append({
                    'metric':     sec,
                    'degradation':round(sec_delta * 100, 1),
                    'old_val':    old_sec,
                    'new_val':    new_sec,
                })

        transfer_record = {
            'source_hyp':    hyp_id,
            'target_context':ctx_name,
            'primary_metric':primary,
            'improvement':   round(improvement * 100, 1),
            'old_val':       old_val,
            'new_val':       new_val,
            'config':        dict(config),
            'scores':        dict(scores),
            'has_tradeoff':  has_tradeoff,
            'tradeoff_info': tradeoff_info,
            'queued_t':      _cmts_time.monotonic(),
        }

        if not has_tradeoff:
            # Unambiguous improvement — silent promotion
            champion.update({
                'config':     dict(config),
                primary:      new_val,
                'source_hyp': hyp_id,
            })
            for s in secondaries:
                if s in scores: champion[s] = scores[s]
            transfer_record['promoted'] = True
            _CMTS_TRANSFERS['silent'].append(transfer_record)
            _pl_append_log({'event': 'cmts_silent_promotion',
                            'ctx':   ctx_name, 'hyp': hyp_id,
                            'gain':  round(improvement*100,1)})
            # Boost lever zone weight for this configuration
            _cmts_boost_lever_weight(ctx_name, config, improvement)
        else:
            # Tradeoff — queue for pilot review
            # Avoid re-queuing if already pending
            already_pending = any(
                p['source_hyp']==hyp_id and p['target_context']==ctx_name
                for p in _CMTS_TRANSFERS['pending'])
            if not already_pending:
                _CMTS_TRANSFERS['pending'].append(transfer_record)
                transfers_queued.append(transfer_record)

    return transfers_queued


def _cmts_boost_lever_weight(ctx_name, config, improvement):
    """
    Boost the lever mode weight for a promoted configuration.
    Maps context to lever zone and increments the relevant weight.
    """
    ctx_to_zone = {
        'cruise_efficiency': 'CRUISE',
        'hover_efficiency':  'TRIM_DETENT',
        'acoustic':          'APPROACH',
        'precision':         'CRUISE',
        'top_speed':         'MAX_THRUST',
        'climb_rate':        'POWERED_CLIMB',
        'intent_response':   'CRUISE',
    }
    zone = ctx_to_zone.get(ctx_name)
    if not zone or zone not in _lever_mode_weights:
        return
    # Create a mode_id from the source config's mode_id if available
    mode_id = config.get('mode_id', f'CMTS_{ctx_name.upper()[:6]}')
    boost   = min(0.3, improvement * 0.5)
    _lever_mode_weights[zone][mode_id] = min(
        3.0, _lever_mode_weights[zone].get(mode_id, 1.0) + boost)


def _cmts_evaluate(hyp_id, config, sensors, result, score_delta):
    """
    Main CMTS entry point — called after every hypothesis evaluation.
    Scores the configuration, updates champions, queues transfers.
    Returns list of pending transfer records (may be empty).
    """
    if score_delta <= 0 and not _WHISPER_STATE['active']:
        return []   # skip failed evaluations unless in whisper (always score)
    scores = _cmts_score_config(config, sensors, result, hyp_id)
    return _cmts_update_champions(hyp_id, config, scores)


# ── Observer analysis — cross-mode transfer proposals ─────────────────────────
def _obs_analyse_cmts(result):
    """
    Surface the highest-priority pending transfer to the pilot.
    Picks the transfer with the largest improvement percentage.
    """
    pending = _CMTS_TRANSFERS['pending']
    if not pending:
        return None

    # Find highest-priority pending transfer
    best = max(pending, key=lambda t: t['improvement'])

    src  = best['source_hyp']
    ctx  = best['target_context']
    pct  = best['improvement']
    met  = best['primary_metric']
    old  = best['old_val']
    new  = best['new_val']

    # Format tradeoff info
    tradeoff_str = ''
    for td in best.get('tradeoff_info', []):
        tradeoff_str += (f" Note: {td['metric']} degrades "
                         f"{td['degradation']:.1f}%.")

    direction_word = 'lower' if met in ('wh_per_km','spl_db',
                                         'trim_rms','latency_ms') else 'higher'
    return {
        'category': 'cross_mode_transfer',
        'text':     (f"Cross-mode transfer opportunity: "
                     f"a configuration from {src} outperforms the current "
                     f"{ctx} champion by {pct:.1f}% on {met} "
                     f"({old:.3g} → {new:.3g}, {direction_word} is better)."
                     f"{tradeoff_str} "
                     f"Shall I promote it to the {ctx} standard?"),
        'priority': 3,
        'transfer': best,
    }


def ai_observer_tick(sensors, result):
    """AI observer — extended with cross-mode transfer proposals."""
    msgs = msgs
    if msgs: return msgs
    st  = _OBS
    now = _cmts_time.monotonic()
    if (now - st['last_analysis_t'] < st['analysis_interval_s']
            or st['pending_proposal']
            or now - st['last_proposal_t'] < st['proposal_cooldown_s']):
        return msgs
    try:
        proposal = _obs_analyse_cmts(result)
        if proposal:
            st['pending_proposal'] = proposal
            st['last_proposal_t']  = now
            msgs.append(proposal['text'])
    except Exception:
        pass
    return msgs


# ── Pilot confirmation/rejection of pending transfers ─────────────────────────
def cmts_confirm():
    """
    GS: cmts_confirm
    Confirm the most recent cross-mode transfer proposal.
    Promotes the configuration to the target context champion.
    AI: 'confirm transfer' / 'yes promote it' / 'approve transfer' /
        'confirm cross mode' / 'accept transfer' / 'promote it' /
        'yes do it' / 'transfer confirmed' / 'go ahead with transfer'
    """
    pending = _CMTS_TRANSFERS['pending']
    if not pending:
        print(f"\n  No pending cross-mode transfer to confirm.")
        return

    transfer = max(pending, key=lambda t: t['improvement'])
    ctx      = transfer['target_context']
    config   = transfer['config']
    scores   = transfer['scores']
    primary  = transfer['primary_metric']
    src      = transfer['source_hyp']

    # Promote to champion
    champion = _CMTS_CHAMPIONS[ctx]
    champion.update({
        'config':     dict(config),
        primary:      scores.get(primary),
        'source_hyp': src,
    })
    for k, v in scores.items():
        if k in champion:
            champion[k] = v

    # Boost lever weight
    _cmts_boost_lever_weight(ctx, config, transfer['improvement'] / 100.0)

    # Move to confirmed
    transfer['confirmed_t'] = _cmts_time.monotonic()
    _CMTS_TRANSFERS['confirmed'].append(transfer)
    pending.remove(transfer)

    print(f"\n  ✓ CROSS-MODE TRANSFER CONFIRMED")
    print(f"  Source:  {src}")
    print(f"  Target:  {ctx} context champion updated")
    print(f"  Gain:    {transfer['improvement']:.1f}% on {primary}")
    if transfer.get('tradeoff_info'):
        for td in transfer['tradeoff_info']:
            print(f"  Trade:   {td['metric']} degrades {td['degradation']:.1f}%")
    print(f"  Lever weight for {ctx} zone boosted.")
    print(f"  The genome will prefer this configuration going forward.")

    _pl_append_log({'event': 'cmts_confirmed', 'ctx': ctx,
                    'src': src, 'gain': transfer['improvement']})


def cmts_reject():
    """
    GS: cmts_reject
    Reject the most recent cross-mode transfer proposal.
    Configuration is not promoted. Genome notes the preference.
    AI: 'reject transfer' / 'no keep current' / 'decline transfer' /
        'reject cross mode' / 'no do not transfer' / 'keep what we have' /
        'transfer rejected' / 'ignore that' / 'no thanks'
    """
    pending = _CMTS_TRANSFERS['pending']
    if not pending:
        print(f"\n  No pending cross-mode transfer to reject.")
        return

    transfer = max(pending, key=lambda t: t['improvement'])
    ctx      = transfer['target_context']
    src      = transfer['source_hyp']

    transfer['rejected_t'] = _cmts_time.monotonic()
    _CMTS_TRANSFERS['rejected'].append(transfer)
    pending.remove(transfer)

    print(f"\n  ✗ CROSS-MODE TRANSFER REJECTED")
    print(f"  Source: {src} → Target: {ctx}")
    print(f"  Current champion retained.")
    print(f"  Preference noted — genome will not re-propose this "
          f"specific configuration for this context.")

    _pl_append_log({'event': 'cmts_rejected', 'ctx': ctx, 'src': src})


def cmts_status():
    """
    GS: cmts_status
    Full cross-mode transfer system status — champions, pending, history.
    AI: 'cross mode status' / 'transfer status' / 'cmts status' /
        'show champions' / 'what has been transferred' /
        'cross mode champions' / 'performance champions'
    """
    print(f"\n  CROSS-MODE TRANSFER SYSTEM")
    print(f"  ─────────────────────────────────────────────")
    print(f"  Silent promotions:  {len(_CMTS_TRANSFERS['silent'])}")
    print(f"  Pilot confirmed:    {len(_CMTS_TRANSFERS['confirmed'])}")
    print(f"  Pilot rejected:     {len(_CMTS_TRANSFERS['rejected'])}")
    print(f"  Pending:            {len(_CMTS_TRANSFERS['pending'])}")

    print(f"\n  PER-CONTEXT CHAMPIONS:")
    for ctx, champ in _CMTS_CHAMPIONS.items():
        cfg = champ.get('config')
        src = champ.get('source_hyp','none')
        n   = champ.get('n_obs', 0)
        if cfg:
            freq = cfg.get('freq_hz',0)
            amp  = cfg.get('amp_port_deg',0)
            # Primary metric
            pmap = {
                'cruise_efficiency':'wh_per_km','hover_efficiency':'n_per_w',
                'acoustic':'spl_db','precision':'trim_rms',
                'top_speed':'v_max_ms','climb_rate':'vsi_ms',
                'intent_response':'latency_ms',
            }
            pm  = pmap.get(ctx,'?')
            val = champ.get(pm,'?')
            print(f"\n    {ctx}:")
            print(f"      Champion from:  {src}  ({n} obs)")
            print(f"      Config:         {freq:.2f}Hz / {amp:.0f}°")
            print(f"      {pm}: {val}")
        else:
            print(f"\n    {ctx}: no champion yet — needs flight data")

    if _CMTS_TRANSFERS['pending']:
        print(f"\n  PENDING TRANSFER:")
        best = max(_CMTS_TRANSFERS['pending'], key=lambda t: t['improvement'])
        print(f"    {best['source_hyp']} → {best['target_context']}")
        print(f"    {best['improvement']:.1f}% gain on {best['primary_metric']}")
        if best['has_tradeoff']:
            print(f"    Tradeoffs: {[t['metric'] for t in best['tradeoff_info']]}")
        print(f"    Say 'confirm transfer' or 'reject transfer' to decide.")

    if _CMTS_TRANSFERS['silent']:
        print(f"\n  RECENT SILENT PROMOTIONS (no tradeoff — auto):")
        for t in _CMTS_TRANSFERS['silent'][-5:]:
            print(f"    {t['source_hyp']} → {t['target_context']}  "
                  f"+{t['improvement']:.1f}% {t['primary_metric']}")


_GS_ALLOWED_CMDS.update({'cmts_confirm','cmts_reject','cmts_status'})


