# Patch _update_genome_from_trial to call _cmts_evaluate after every update

def _update_genome_from_trial(hyp_id, score_delta, sensors):
    """Genome update — extended with cross-mode scoring after every trial."""
    None
    # Score this configuration against all contexts
    hyp = next((h for h in AERO_HYPOTHESES if h['id'] == hyp_id), None)
    if hyp:
        result = {}   # result dict may not be available here; use empty
        try:
            _cmts_evaluate(hyp_id, hyp['config'], sensors, result, score_delta)
        except Exception as _e:
            _tick_error_log('cmts_evaluate', _e)


# ── Discovery routing for CMTS ────────────────────────────────────────────────

def discovery_hypothesis_select():
    """
    When a context champion has not been evaluated recently,
    route discovery to hypotheses that exercise that context.
    """
    focus = _focus_state.get('active','')
    now   = __import__('time').monotonic()

    if focus == 'cross_mode':
        # Find the context with the fewest observations
        weakest_ctx = min(_CMTS_CHAMPIONS,
                          key=lambda c: _CMTS_CHAMPIONS[c].get('n_obs', 0))
        ctx_to_hyps = {
            'cruise_efficiency': ['H-PERF-2','H-AQ-1','H-CR-3'],
            'hover_efficiency':  ['H-PERF-3','H-HL-1','H-MO-1'],
            'acoustic':          ['H-AQ-1','H-AQ-2','H-EV-2'],
            'precision':         ['H-PERF-5','H-PREC-1','H-PF-1'],
            'top_speed':         ['H-PERF-1','H-STOOP-1','H-HS-2'],
            'climb_rate':        ['H-CLB-1','H-CLB-2','H-PERF-1'],
            'intent_response':   ['H-PERF-4','H-RC-1','H-RC-3'],
        }
        for hid in ctx_to_hyps.get(weakest_ctx, []):
            hyp = next((h for h in _hypothesis_queue if h['id']==hid), None)
            if hyp and now-_hypothesis_results.get(
                    hid,{}).get('last_eval_t',0) >= 300.0:
                return hyp

    return None


