def _me_niche_label(sensors, result, intent=None):
    """Adds cross_mode niche for transfer-sourced configurations."""
    speed_bin, wind_bin, base = speed_bin, wind_bin, base
    if intent == 'cross_mode':
        return speed_bin, wind_bin, 'cross_mode_eval'
    return speed_bin, wind_bin, base


# ── Initial champion seeding from existing knowledge ─────────────────────────
# Pre-populate champions from PERF_STATE best values so far
# (avoids waiting for first flight to see any data)
def _cmts_seed_from_perf():
    """Seed cross-mode champions from existing performance state."""
    ps = _PERF_STATE
    if ps.get('v_max_ms', 0) > 0:
        _CMTS_CHAMPIONS['top_speed']['v_max_ms'] = ps['v_max_ms']
    if ps.get('wh_per_km_best', 999) < 999:
        _CMTS_CHAMPIONS['cruise_efficiency']['wh_per_km'] = ps['wh_per_km_best']
    if ps.get('n_per_w_best', 0) > 0:
        _CMTS_CHAMPIONS['hover_efficiency']['n_per_w'] = ps['n_per_w_best']
    if ps.get('latency_ms_best', 999) < 999:
        _CMTS_CHAMPIONS['intent_response']['latency_ms'] = ps['latency_ms_best']
        _CMTS_CHAMPIONS['precision']['latency_ms'] = ps['latency_ms_best']
    if ps.get('precision_rms_best', 999) < 999:
        _CMTS_CHAMPIONS['precision']['trim_rms'] = ps['precision_rms_best']
    # Acoustic: seed from Gutin model at nominal hover config
    import math as _sm; span=0.772; nw=8; Sw=span*0.12
    vt = 2*_sm.pi*1.87*span*_sm.radians(96)
    T=4.1*9.81; rho=1.225; c=343; obs=76.2; pr=2e-5; A=nw*Sw
    W = T**2*vt**4/(4*_sm.pi*obs**2*rho**2*c**4*A**2)
    spl = max(0, 10*_sm.log10(W/pr**2+1e-30))
    _CMTS_CHAMPIONS['acoustic']['spl_db'] = round(spl, 1)

_cmts_seed_from_perf()


