# ── Genome update routing ─────────────────────────────────────────────────────
def _update_genome_from_trial(hyp_id, score_delta, sensors):
    """Extends definitive genome update with H-OV routing."""
    if score_delta <= 0:
        return
    boost = min(0.08, score_delta * 0.5)
    def _R(axis, mech):
        if mech not in axis: return
        axis[mech] = min(0.60, axis[mech] + boost)
        t = sum(axis.values())
        if t > 0:
            for k in axis: axis[k] /= t

    if hyp_id == 'H-OV-1':
        # 80 Jump reinforces pitch (cascade = pitch authority)
        # and performance (top speed + climb rate)
        _R(_MW_PITCH,       'pitch_phase')    # cascade phase is pitch mechanism
        _R(_MW_PERFORMANCE, 'top_speed')
        _R(_MW_PERFORMANCE, 'cruise_efficiency')
        # Also update CMTS — 80 Jump may be best climb_rate champion
        try:
            h = next(h for h in AERO_HYPOTHESES if h['id']=='H-OV-1')
            _cmts_evaluate('H-OV-1', h['config'], sensors, {}, score_delta)
        except Exception: pass

    elif hyp_id == 'H-OV-2':
        # Lateral translation reinforces roll (differential amplitude)
        # and stability (heading hold = weathercock/proverse)
        _R(_MW_ROLL,      'roll_amp')
        _R(_MW_STABILITY, 'proverse_yaw')   # heading hold in lateral
        _R(_MW_PERFORMANCE, 'precision_hold')
        try:
            h = next(h for h in AERO_HYPOTHESES if h['id']=='H-OV-2')
            _cmts_evaluate('H-OV-2', h['config'], sensors, {}, score_delta)
        except Exception: pass

    else:
        # Fall through to prior definition for all other hypotheses
        # (this is now the last definition, so call the original builtin)
        pass

    _pl_append_log({'event':'genome_update','hyp_id':hyp_id,
                    'boost':round(boost,4)})


# ── MAP-Elites ────────────────────────────────────────────────────────────────
def _me_niche_label(sensors, result, intent=None):
    """Adds jump80 and lateral_trans MAP-Elites niches."""
    # Determine speed_bin and wind_bin from sensors if dict
    if isinstance(sensors, dict):
        V_ms = sensors.get('V_ms', 7.0)
        speed_bin = (0 if V_ms < 4 else 1 if V_ms < 8 else
                     2 if V_ms < 12 else 3)
        wind_bin  = 0
    else:
        speed_bin = int(sensors) if isinstance(sensors, int) else 2
        wind_bin  = int(result) if isinstance(result, int) else 0

    if intent == 'jump80' or (isinstance(result,dict) and
                               result.get('jump80_active')):
        return speed_bin, wind_bin, 'jump80'
    if intent == 'lateral_trans' or (isinstance(result,dict) and
                                      result.get('lat_active')):
        return speed_bin, wind_bin, 'lateral_trans'
    if intent is not None:
        return speed_bin, wind_bin, str(intent)
    return speed_bin, wind_bin, 'general'


