# ── Genome update ─────────────────────────────────────────────────────────────
def _update_genome_from_trial(hyp_id, score_delta, sensors):
    """Extends genome update with H-OV-3 routing."""
    if score_delta <= 0:
        return
    boost = min(0.08, score_delta * 0.5)
    def _R(axis, mech):
        if mech not in axis: return
        axis[mech] = min(0.60, axis[mech] + boost)
        t = sum(axis.values())
        if t > 0:
            for k in axis: axis[k] /= t

    if hyp_id == 'H-OV-3':
        # Combined translation = turn mechanism + roll differential + stability
        _R(_MW_TURN,      'stroke_plane_tilt')   # cascade reversal for reverse
        _R(_MW_ROLL,      'roll_amp')             # amplitude differential for lateral
        _R(_MW_STABILITY, 'proverse_yaw')         # heading hold during both
        _R(_MW_PERFORMANCE, 'precision_hold')     # flat body throughout
        # Feed CMTS — may improve H-RC-2 or H-OV-2 champions
        try:
            _cmts_evaluate('H-OV-3', _h_ov3['config'], sensors, {}, score_delta)
        except Exception: pass
    # All other hypotheses handled by passing — this is last in chain


# ── MAP-Elites ────────────────────────────────────────────────────────────────
def _me_niche_label(sensors, result, intent=None):
    """Adds diagonal, arced_lat, full_envelope MAP-Elites niches."""
    if isinstance(sensors, dict):
        V_ms = sensors.get('V_ms', 7.0)
        speed_bin = 0 if V_ms<4 else 1 if V_ms<8 else 2 if V_ms<12 else 3
        wind_bin  = 0
    else:
        speed_bin = int(sensors) if isinstance(sensors,int) else 2
        wind_bin  = int(result)  if isinstance(result,int)  else 0

    if isinstance(result, dict):
        mode = result.get('ov3_mode','')
        if result.get('ov3_active') and mode:
            return speed_bin, wind_bin, mode
        if result.get('jump80_active'):
            return speed_bin, wind_bin, 'jump80'
        if result.get('lat_active'):
            return speed_bin, wind_bin, 'lateral_trans'

    if intent in ('diagonal','arced_lat','full_envelope',
                  'combined_translation','jump80','lateral_trans'):
        return speed_bin, wind_bin, str(intent)
    return speed_bin, wind_bin, 'general'


