# ── Discovery routing ─────────────────────────────────────────────────────────
def discovery_hypothesis_select():
    """
    Authoritative discovery — all hypotheses including H-OV-3.
    Replaces previous definition completely.
    """
    focus  = _focus_state.get('active','')
    now    = _ov3_time.monotonic()
    lever  = _flight_state.get('lever_pct', 50.0)
    h_agl  = _flight_state.get('h_agl_m',  100.0)
    V_ms   = _flight_state.get('V_ms',       7.0)
    pitch  = _flight_state.get('pitch_stick', 0.0)
    payload= _flight_state.get('payload_kg',  0.0)

    def _ready(hid):
        hyp = next((h for h in _hypothesis_queue if h['id']==hid), None)
        return (hyp if hyp and
                now-_hypothesis_results.get(hid,{}).get('last_eval_t',0)>=300
                else None)
    def _first(ids):
        for hid in ids:
            h = _ready(hid)
            if h: return h
        return None

    # ── OV-3 auto-route: ov3 tick active ───────────────────────────────────
    if _OV3_STATE.get('active') and h_agl > 0.3:
        h = _ready('H-OV-3')
        if h: return h

    # ── OV-1: auto-route in HIGH_THRUST climb ──────────────────────────────
    if LV_CLIMB_LO <= lever <= LV_SPRINT_LO and V_ms > 3.0:
        h = _ready('H-OV-1')
        if h: return h

    # ── OV-2: auto-route when lateral tick active ──────────────────────────
    if _OV_STATE.get('lat_active') and h_agl > 0.3:
        h = _ready('H-OV-2')
        if h: return h

    FOCUS = {
        # OV series
        'jump80':           ['H-OV-1'],
        'osprey':           ['H-OV-1','H-OV-2','H-OV-3'],
        'lateral':          ['H-OV-2','H-OV-3'],
        'sideward':         ['H-OV-2','H-OV-3'],
        'sideways':         ['H-OV-2','H-OV-3'],
        'crab':             ['H-OV-2','H-OV-3'],
        'diagonal':         ['H-OV-3'],
        'omnidirectional':  ['H-OV-3'],
        'combined':         ['H-OV-3'],
        # eVTOL / cert
        'evtol':            ['H-EV-1','H-EV-2'],
        'certification':    ['H-EV-1','H-EV-2'],
        'handling_qualities':['H-EV-1'],
        'acoustic':         ['H-EV-2','H-AQ-1'],
        # Heavy lift / cargo
        'heavy_lift':       ['H-HL-1','H-HL-2','H-HL-3','H-HL-4'],
        'cargo':            ['H-HL-1','H-HL-2','H-HL-3','H-CR-2','H-CR-3'],
        # Aerobatics / agility
        'aerobatics':       ['H-HB-1','H-HB-2','H-HB-3','H-HB-4','H-HB-5'],
        'agility':          ['H-PULL-1','H-RC-1','H-HB-1','H-OV-3'],
        # Stability
        'stability':        ['H-PDW-1','H-PDW-2','H-PDW-3',
                             'H-DIH-1','H-DIH-2','H-DIH-3'],
        'smooth_flight':    ['H-PDW-1','H-DIH-1','H-TX-1','H-PF-3'],
        # Soaring / endurance
        'soaring':          ['H-SOR-1','H-SOR-2','H-SOR-3',
                             'H-SOR-4','H-SOR-5','H-SOR-6'],
        'endurance':        ['H-SOR-3','H-CR-3','H-CR-4','H-HL-3'],
        # Water
        'water':            ['H-WD-1','H-WD-2','H-WD-3'],
        # Competition
        'competition':      ['H-CR-1','H-CR-2','H-CR-3','H-CR-4','H-CR-5'],
        'gps_denied':       ['H-CR-1','H-CR-5'],
        # Terrain
        'bush':             ['H-BS-1','H-BS-4','H-BS-5'],
        'noe':              ['H-BS-5'],
        # Pigeon descent
        'pigeon':           ['H-FD-1','H-FD-2','H-FD-3','H-FD-4'],
        'flat_descent':     ['H-FD-1','H-FD-2','H-FD-3','H-FD-4'],
        'steep_descent':    ['H-FD-4','H-FD-3','H-FD-1'],
        # SAR / pilot feel
        'sar':              ['H-SP-1','H-SP-2','H-PF-5','H-PF-6',
                             'H-SOR-6','H-BS-5'],
        'pilot_feel':       ['H-PF-1','H-PF-2','H-PF-3',
                             'H-PF-4','H-PF-5','H-PF-6'],
        # Raider manoeuvres
        'raider':           ['H-RC-1','H-RC-2','H-RC-3','H-RC-4'],
        'reverse':          ['H-RC-2','H-OV-3'],
        'backwards':        ['H-RC-2','H-OV-3'],
        'hard_brake':       ['H-RC-3'],
        'nose_attitude':    ['H-RC-4'],
        'evasive':          ['H-RC-1','H-RC-2','H-RC-3','H-RC-4','H-OV-3'],
        # Stoop / gust
        'stoop':            ['H-STOOP-1','H-PULL-1'],
        'dart':             ['H-STOOP-1'],
        'pullout':          ['H-PULL-1'],
        'knife_edge':       ['H-PULL-1'],
        'gust':             ['H-GS-1'],
        'turbulence':       ['H-GS-1'],
        'comfort':          ['H-GS-1'],
        'high_speed':       ['H-STOOP-1','H-PERF-1','H-OV-1'],
        # Performance
        'performance':      ['H-PERF-1','H-PERF-2','H-PERF-3',
                             'H-PERF-4','H-PERF-5'],
        'efficiency':       ['H-PERF-2','H-PERF-3'],
        'speed':            ['H-PERF-1','H-STOOP-1','H-OV-1'],
        'top_speed':        ['H-PERF-1','H-STOOP-1','H-OV-1'],
        'climb':            ['H-OV-1','H-CLB-1','H-CLB-2','H-CLB-3'],
        'hover':            ['H-PERF-3','H-OV-2','H-OV-3','H-SP-1'],
        'transition':       ['H-TX-1','H-TR-2','H-PF-3'],
        # Whisper
        'whisper':          ['H-AQ-1','H-AQ-2','H-PERF-2','H-EV-2'],
        # Density alt
        'density_alt':      ['H-DA-1','H-DA-2','H-DA-3',
                             'H-DA-4','H-DA-5','H-DA-6','H-DA-7'],
        'precision':        ['H-PF-1','H-PF-2','H-CR-1','H-PREC-1'],
    }

    if focus in FOCUS:
        h = _first(FOCUS[focus])
        if h: return h

    # ── Automatic state routing ─────────────────────────────────────────────
    if LV_DESCENT_LO <= lever <= LV_GLIDE_LO and h_agl > 0.5:
        for (lo,hi),hid in [
            ((PD_NEW_SHALLOW_LO, PD_NEW_SHALLOW_HI),  'H-FD-2'),
            ((PD_NEW_MODERATE_LO,PD_NEW_MODERATE_HI), 'H-FD-1'),
            ((PD_NEW_STEEP_LO,   PD_NEW_STEEP_HI),    'H-FD-3'),
        ]:
            if lo <= lever <= hi:
                h = _ready(hid)
                if h: return h
                break

    if LV_BRAKE_LO <= lever <= LV_DESCENT_LO:
        h = _ready('H-RC-3' if abs(pitch) <= RC_HARD_BRAKE_PITCH_DEAD
                   else 'H-FD-4')
        if h: return h

    if lever < LV_BRAKE_LO:
        h = _ready('H-LB-3')
        if h: return h

    if lever >= LV_SPRINT_LO:
        h = _first(['H-CLB-3','H-HL-4','H-STOOP-1','H-OV-1'])
        if h: return h

    if payload > 0.3:
        h = _first(['H-HL-2','H-HL-3','H-CR-2'])
        if h: return h

    if _water_phase_state.get('phase','') in ('water_planing','water_departure') \
            or surface_is_water():
        h = _first(['H-WD-1','H-WD-2','H-WD-3'])
        if h: return h

    # Route to weakest H-PERF
    st  = _PERF_STATE
    ref = _PERF_REFERENCE
    scores = {
        'H-PERF-1': min(1.0, st['v_max_ms']/ref['v_max_target_ms']),
        'H-PERF-2': max(0.0, 1.0-st['wh_per_km_current']/ref['wh_per_km_target'])
                    if st['wh_per_km_current']>0 else 0.0,
        'H-PERF-3': min(1.0, st['n_per_w_current']/ref['n_per_w_target'])
                    if st['n_per_w_current']>0 else 0.0,
        'H-PERF-4': max(0.0, 1.0-st['latency_ms_current']/ref['latency_ms_target'])
                    if st['latency_ms_current']>0 else 0.0,
        'H-PERF-5': max(0.0, 1.0-st['precision_rms_current']/ref['precision_rms_target'])
                    if st['precision_rms_current']>0 else 0.0,
    }
    weakest = min(scores, key=scores.get)
    h = _ready(weakest)
    if h: return h

    for hyp in _hypothesis_queue:
        if now-_hypothesis_results.get(hyp['id'],{}).get('last_eval_t',0)>=300.0:
            return hyp
    return _hypothesis_queue[0] if _hypothesis_queue else None


# ── Observer analysis ─────────────────────────────────────────────────────────
def _obs_analyse_ov3(result):
    """Watch H-OV-3 for cross-mode improvements and convergence."""
    st = _OV3_STATE
    if st['sessions'] < 2:
        return None
    if st['best_diagonal_v'] > 2.0:
        return {
            'category': 'combined_translation',
            'text':     (f"Combined translation converging: best resultant "
                         f"speed {st['best_diagonal_v']:.1f} m/s. "
                         f"This configuration may also improve pure lateral "
                         f"(H-OV-2) or rearward (H-RC-2) — CMTS monitoring "
                         f"for cross-mode transfer opportunities."),
            'priority': 3,
        }
    return None

_orig_ai_obs_ov3 = ai_observer_tick

def ai_observer_tick(sensors, result):
    """AI observer — extended with combined translation analysis."""
    msgs = _orig_ai_obs_ov3(sensors, result)
    if msgs: return msgs
    st  = _OBS
    now = _ov3_time.monotonic()
    if (now - st['last_analysis_t'] < st['analysis_interval_s']
            or st['pending_proposal']
            or now - st['last_proposal_t'] < st['proposal_cooldown_s']):
        return msgs
    try:
        proposal = _obs_analyse_ov3(result)
        if proposal:
            st['pending_proposal'] = proposal
            st['last_proposal_t']  = now
            msgs.append(proposal['text'])
    except Exception:
        pass
    return msgs


# ── GS status ─────────────────────────────────────────────────────────────────
def combined_translation_status():
    """
    GS: combined_translation_status
    Status of the combined rearward+lateral translation system.
    AI: 'combined translation status' / 'diagonal flight status' /
        'omnidirectional hover' / 'diagonal mode' / 'combined mode' /
        'ov3 status'
    """
    st  = _OV3_STATE
    ov2 = _OV_STATE
    rc2 = _RC_STATE
    print(f"\n  COMBINED TRANSLATION STATUS (H-OV-3)")
    print(f"  ─────────────────────────────────────────────")
    print(f"  Mode:         {st['mode'] or 'inactive'}")
    if st['active']:
        print(f"  Reverse V:    {st['reverse_v_ms']:.2f} m/s")
        print(f"  Lateral V:    {st['lateral_v_ms']:.2f} m/s")
        print(f"  Arc rate:     {st['arc_rate']:.1f} deg/s")
        print(f"  Cascade:      {st['cascade_deg']:.0f}°")
        print(f"  Port amp:     {st['port_amp_deg']:.0f}°")
        print(f"  Stbd amp:     {st['stbd_amp_deg']:.0f}°")
        r = _ov3_math.sqrt(st['reverse_v_ms']**2 + st['lateral_v_ms']**2)
        print(f"  Resultant V:  {r:.2f} m/s")
    print(f"  Best resultant: {st['best_diagonal_v']:.2f} m/s")
    print(f"  Sessions:       {st['sessions']}")
    print(f"\n  CONTROL MAPPING:")
    print(f"  Mode A Diagonal:  aft pitch >0.5 + roll + both pedals")
    print(f"  Mode B Arc-lat:   roll + both pedals + pedal differential")
    print(f"  Mode C Full:      aft pitch >0.5 + roll + both pedals + diff")
    print(f"\n  PURE MODES:")
    print(f"  H-OV-2 Lateral:   {ov2.get('lat_best_v_ms',0):.2f} m/s best")
    print(f"  H-RC-2 Reverse:   {rc2.get('reverse_speed_ms',0):.2f} m/s current")
    print(f"\n  CMTS monitoring for cross-mode improvements to H-OV-2/H-RC-2.")

_GS_ALLOWED_CMDS.add('combined_translation_status')

# ── Genome normalisation ──────────────────────────────────────────────────────
for _ax in [_MW_ROLL, _MW_PITCH, _MW_YAW, _MW_STABILITY, _MW_SOARING,
            _MW_GLIDE, _MW_TURN, _MW_WATER, _MW_CARGO,
            _MW_COMPETITION, _MW_PERFORMANCE]:
    _t = sum(_ax.values())
    if _t > 0 and abs(_t-1.0) > 0.001:
        for _k in _ax: _ax[_k] /= _t

# ── Verify ────────────────────────────────────────────────────────────────────
_ov3h = next((h for h in AERO_HYPOTHESES if h['id']=='H-OV-3'), None)
_boot_log.append(f"  H-OV-3 COMPLETE: {'registered' if _ov3h else 'MISSING'}")
_boot_log.append(f"  Modes: diagonal, arced_lat, full_envelope")
_boot_log.append(f"  Ticks: _ov3_tick wired into stroke_smoothing_tick")
_boot_log.append(f"  GS: combined_translation_status")
_boot_log.append(f"  CMTS: combined_translation context added")
_boot_log.append(f"  Total hypotheses: {len(AERO_HYPOTHESES)}")


