# SESSION A — ENERGY STATE TRANSITIONS (H-EN-1/2/3)
# ══════════════════════════════════════════════════════════════════════════════

_EN_STATE = {
    # H-EN-1: sprint-to-hover
    'sprint_stop_active':    False,
    'sprint_stop_entry_V':   0.0,
    'sprint_stop_dist_m':    0.0,
    'sprint_stop_best_dist': 999.0,
    'sprint_stop_best_prof': None,
    # H-EN-2: stoop-to-lateral
    'stoop_lat_active':      False,
    'stoop_lat_entry_V':     0.0,
    'stoop_lat_exit_V_lat':  0.0,
    'stoop_lat_best_conv':   0.0,
    # H-EN-3: direction reversal
    'reversal_active':       False,
    'reversal_phase':        'none',  # 'reversing'|'zero_cross'|'sprinting'
    'reversal_V_at_cross':   0.0,
    'reversal_best_time_s':  999.0,
}

def _en_tick(sensors, result):
    """Energy transition tick — tracks all three transition modes."""
    st   = _EN_STATE
    now  = _bg_time.monotonic()
    V_ms = sensors.get('V_ms', 0.0) if isinstance(sensors,dict) else 0.0
    vsi  = sensors.get('vsi_smooth_ms',0.0) if isinstance(sensors,dict) else 0.0
    lever= sensors.get('lever_pct',50.0) if isinstance(sensors,dict) else 50.0
    pitch= sensors.get('pitch_stick',0.0) if isinstance(sensors,dict) else 0.0

    # H-EN-1: Sprint-to-hover — lever drops from sprint to brake zone quickly
    if lever >= LV_SPRINT_LO and not st['sprint_stop_active']:
        st['sprint_stop_entry_V'] = V_ms
        st['sprint_stop_dist_m']  = 0.0
    if st['sprint_stop_entry_V'] > 8.0 and lever <= LV_DESCENT_LO:
        st['sprint_stop_active'] = True
    if st['sprint_stop_active']:
        st['sprint_stop_dist_m'] += V_ms * 0.02   # integrate at 50Hz
        if V_ms < 1.0:
            dist = st['sprint_stop_dist_m']
            if dist < st['sprint_stop_best_dist']:
                st['sprint_stop_best_dist'] = dist
            st['sprint_stop_active'] = False
            result['en1_stop_dist_m'] = round(dist, 1)

    # H-EN-3: Direction reversal — rearward V becomes forward V
    if _RC_STATE.get('reverse_active') and V_ms < 0.5:
        st['reversal_active'] = True
        st['reversal_phase']  = 'zero_cross'
    if st['reversal_active'] and st['reversal_phase'] == 'zero_cross':
        if lever >= LV_SPRINT_LO:
            st['reversal_phase']   = 'sprinting'
            st['reversal_V_at_cross'] = V_ms
    result['en_state'] = st['reversal_phase']
    return result


# Wire EN tick
_orig_stroke_sm_en = stroke_smoothing_tick

def stroke_smoothing_tick(sensors, result):
    result = _orig_stroke_sm_en(sensors, result)
    try:
        _en_tick(sensors, result)
    except Exception as _e:
        _tick_error_log('en_tick', _e)
    return result


