# ── Genome update routing for all new hypotheses ──────────────────────────────
def _update_genome_from_trial(hyp_id, score_delta, sensors):
    """Extends genome update with Session A/B/C hypotheses + new axes."""
    if score_delta <= 0:
        return
    boost = min(0.08, score_delta * 0.5)
    def _R(axis, mech):
        if mech not in axis: return
        axis[mech] = min(0.60, axis[mech] + boost)
        t = sum(axis.values())
        if t > 0:
            for k in axis: axis[k] /= t

    # Session A — Energy transitions
    if   hyp_id == 'H-EN-1':
        _R(_MW_PITCH,      'pitch_freq')        # fast response during stop
        _R(_MW_PERFORMANCE,'precision_hold')
        _R(_MW_TRANSITION, 'altitude_hold')     # new axis
    elif hyp_id == 'H-EN-2':
        _R(_MW_ROLL,  'roll_amp')               # lateral energy redirect
        _R(_MW_TURN,  'stroke_plane_tilt')
        _R(_MW_TRANSITION, 'speed_accuracy')    # new axis
    elif hyp_id == 'H-EN-3':
        _R(_MW_PITCH, 'pitch_phase')            # cascade sweep
        _R(_MW_STABILITY,'proverse_yaw')        # heading through zero V
        _R(_MW_TRANSITION,'blend_smoothness')   # new axis

    # Session B — Resilience
    elif hyp_id == 'H-RES-1':
        _R(_MW_STABILITY,'proverse_yaw')        # distributes control
        _R(_MW_RESILIENCE,'single_pair_loss')   # new axis
    elif hyp_id == 'H-RES-2':
        _R(_MW_STABILITY,'proverse_yaw')
        _R(_MW_RESILIENCE,'pair_pair_loss')     # new axis
        _R(_MW_RESILIENCE,'proverse_redundancy')
    elif hyp_id == 'H-RES-3':
        _R(_MW_PERFORMANCE,'intent_latency')    # fast detection
        _R(_MW_RESILIENCE,'fault_detect_speed') # new axis

    # Session C — Combinations
    elif hyp_id == 'H-AQ-3':
        _R(_MW_GLIDE, 'drag_minimise')          # dihedral drag replaces cascade
        _R(_MW_SAR,   'acoustic_minimum')       # new axis
    elif hyp_id == 'H-FD-5':
        _R(_MW_ROLL,  'roll_dih')               # differential dihedral
        _R(_MW_ROLL,  'roll_amp')               # amplitude differential
        _R(_MW_SAR,   'precision_hover')        # new axis
    elif hyp_id == 'H-HL-5':
        _R(_MW_CARGO, 'pendulum_damp')
        _R(_MW_ROLL,  'roll_amp')               # active lateral damping
        _R(_MW_SAR,   'payload_delivery')       # new axis

    # CMTS evaluation for all new hypotheses
    try:
        h = next((h for h in AERO_HYPOTHESES if h['id']==hyp_id), None)
        if h:
            _cmts_evaluate(hyp_id, h['config'], sensors, {}, score_delta)
    except Exception:
        pass


# ── Discovery routing ─────────────────────────────────────────────────────────
def discovery_hypothesis_select():
    """Authoritative discovery — all hypotheses including Session A/B/C."""
    focus  = _focus_state.get('active','')
    now    = _bg_time.monotonic()
    lever  = _flight_state.get('lever_pct', 50.0)
    h_agl  = _flight_state.get('h_agl_m',  100.0)
    V_ms   = _flight_state.get('V_ms',       7.0)
    pitch  = _flight_state.get('pitch_stick', 0.0)
    payload= _flight_state.get('payload_kg',  0.0)

    def _ready(hid):
        hyp = next((h for h in _hypothesis_queue if h['id']==hid), None)
        return (hyp if hyp and
                now-_hypothesis_results.get(hid,{}).get('last_eval_t',0)>=300
                else None)
    def _first(ids):
        for hid in ids:
            h = _ready(hid)
            if h: return h
        return None

    # Auto-route: resilience always runs in background
    if _RES_STATE.get('degraded_mode'):
        n_lost = len(_RES_STATE.get('failed_pairs',[]))
        hid = 'H-RES-1' if n_lost == 1 else 'H-RES-2'
        h = _ready(hid)
        if h: return h

    # Auto-route: whisper pigeon when whisper active + descent zone
    if (_WHISPER_STATE.get('active') and
            LV_DESCENT_LO <= lever <= LV_GLIDE_LO):
        h = _ready('H-AQ-3')
        if h: return h

    # Auto-route: cargo lateral when payload + lateral active
    if (payload > 0.3 and _OV_STATE.get('lat_active')):
        h = _ready('H-HL-5')
        if h: return h

    # OV-3 auto-route
    if _OV3_STATE.get('active') and h_agl > 0.3:
        h = _ready('H-OV-3')
        if h: return h

    # OV-1: climb zone
    if LV_CLIMB_LO <= lever <= LV_SPRINT_LO and V_ms > 3.0:
        h = _ready('H-OV-1')
        if h: return h

    # OV-2: lateral
    if _OV_STATE.get('lat_active') and h_agl > 0.3:
        h = _ready('H-OV-2')
        if h: return h

    FOCUS = {
        # Energy transitions
        'energy_transition': ['H-EN-1','H-EN-2','H-EN-3'],
        'sprint_stop':       ['H-EN-1'],
        'stoop_lateral':     ['H-EN-2'],
        'direction_reversal':['H-EN-3'],
        'cheyenne':          ['H-EN-3'],
        # Resilience
        'resilience':        ['H-RES-1','H-RES-2','H-RES-3'],
        'fault_tolerance':   ['H-RES-1','H-RES-2','H-RES-3'],
        'single_pair_loss':  ['H-RES-1'],
        'two_pair_loss':     ['H-RES-2'],
        'fault_detection':   ['H-RES-3'],
        # Whisper pigeon
        'whisper_pigeon':    ['H-AQ-3'],
        'quiet_approach':    ['H-AQ-3','H-AQ-1'],
        # 3D approach
        '3d_approach':       ['H-FD-5'],
        'pigeon_lateral':    ['H-FD-5'],
        # Cargo lateral
        'cargo_lateral':     ['H-HL-5'],
        'cargo_precision':   ['H-HL-5','H-HL-2'],
        # OV series
        'jump80':            ['H-OV-1'],
        'osprey':            ['H-OV-1','H-OV-2','H-OV-3'],
        'lateral':           ['H-OV-2','H-OV-3','H-FD-5'],
        'sideward':          ['H-OV-2','H-OV-3'],
        'diagonal':          ['H-OV-3'],
        'combined':          ['H-OV-3'],
        # eVTOL
        'evtol':             ['H-EV-1','H-EV-2'],
        'certification':     ['H-EV-1','H-EV-2'],
        'acoustic':          ['H-EV-2','H-AQ-1','H-AQ-3'],
        # Heavy lift
        'heavy_lift':        ['H-HL-1','H-HL-2','H-HL-3','H-HL-4','H-HL-5'],
        'cargo':             ['H-HL-1','H-HL-2','H-HL-3','H-CR-2','H-HL-5'],
        # Aerobatics
        'aerobatics':        ['H-HB-1','H-HB-2','H-HB-3','H-HB-4','H-HB-5'],
        'agility':           ['H-PULL-1','H-RC-1','H-HB-1','H-OV-3'],
        # Stability
        'stability':         ['H-PDW-1','H-PDW-2','H-PDW-3',
                              'H-DIH-1','H-DIH-2','H-DIH-3'],
        'smooth_flight':     ['H-PDW-1','H-DIH-1','H-TX-1','H-PF-3'],
        # Soaring
        'soaring':           ['H-SOR-1','H-SOR-2','H-SOR-3',
                              'H-SOR-4','H-SOR-5','H-SOR-6'],
        'thermal':           ['H-SOR-4','H-SOR-6'],
        'endurance':         ['H-SOR-3','H-CR-3','H-CR-4','H-HL-3'],
        # Water
        'water':             ['H-WD-1','H-WD-2','H-WD-3'],
        # Competition
        'competition':       ['H-CR-1','H-CR-2','H-CR-3','H-CR-4','H-CR-5'],
        'gps_denied':        ['H-CR-1','H-CR-5'],
        # Terrain
        'bush':              ['H-BS-1','H-BS-4','H-BS-5'],
        'noe':               ['H-BS-5'],
        # Pigeon
        'pigeon':            ['H-FD-1','H-FD-2','H-FD-3','H-FD-4','H-FD-5'],
        'flat_descent':      ['H-FD-1','H-FD-2','H-FD-3','H-FD-5'],
        'steep_descent':     ['H-FD-4','H-AQ-3','H-FD-3'],
        # SAR
        'sar':               ['H-SP-1','H-SP-2','H-PF-5','H-PF-6',
                              'H-SOR-6','H-BS-5','H-FD-5'],
        'pilot_feel':        ['H-PF-1','H-PF-2','H-PF-3',
                              'H-PF-4','H-PF-5','H-PF-6'],
        # Raider
        'raider':            ['H-RC-1','H-RC-2','H-RC-3','H-RC-4'],
        'reverse':           ['H-RC-2','H-OV-3','H-EN-3'],
        'backwards':         ['H-RC-2','H-OV-3','H-EN-3'],
        'hard_brake':        ['H-RC-3','H-EN-1'],
        'nose_attitude':     ['H-RC-4'],
        'evasive':           ['H-RC-1','H-RC-2','H-RC-3','H-RC-4','H-OV-3'],
        # Stoop
        'stoop':             ['H-STOOP-1','H-PULL-1','H-EN-2'],
        'dart':              ['H-STOOP-1'],
        'pullout':           ['H-PULL-1'],
        'knife_edge':        ['H-PULL-1'],
        # Gust
        'gust':              ['H-GS-1'],
        'turbulence':        ['H-GS-1'],
        'comfort':           ['H-GS-1'],
        # Performance
        'performance':       ['H-PERF-1','H-PERF-2','H-PERF-3',
                              'H-PERF-4','H-PERF-5'],
        'efficiency':        ['H-PERF-2','H-PERF-3'],
        'speed':             ['H-PERF-1','H-STOOP-1','H-OV-1'],
        'top_speed':         ['H-PERF-1','H-STOOP-1','H-OV-1'],
        'climb':             ['H-OV-1','H-CLB-1','H-CLB-2','H-CLB-3'],
        'hover':             ['H-PERF-3','H-OV-2','H-OV-3','H-SP-1'],
        'transition':        ['H-TX-1','H-TR-2','H-PF-3','H-EN-1'],
        'whisper':           ['H-AQ-1','H-AQ-2','H-AQ-3','H-EV-2'],
        'density_alt':       ['H-DA-1','H-DA-2','H-DA-3',
                              'H-DA-4','H-DA-5','H-DA-6','H-DA-7'],
        'precision':         ['H-PF-1','H-PF-2','H-CR-1',
                              'H-PREC-1','H-FD-5','H-EN-1'],
    }

    if focus in FOCUS:
        h = _first(FOCUS[focus])
        if h: return h

    # State routing
    if LV_DESCENT_LO <= lever <= LV_GLIDE_LO and h_agl > 0.5:
        for (lo,hi),hid in [
            ((PD_NEW_SHALLOW_LO,PD_NEW_SHALLOW_HI), 'H-FD-2'),
            ((PD_NEW_MODERATE_LO,PD_NEW_MODERATE_HI),'H-FD-1'),
            ((PD_NEW_STEEP_LO, PD_NEW_STEEP_HI),   'H-FD-3'),
        ]:
            if lo <= lever <= hi:
                h = _ready(hid)
                if h: return h
                break

    if LV_BRAKE_LO <= lever <= LV_DESCENT_LO:
        h = _ready('H-RC-3' if abs(pitch)<=RC_HARD_BRAKE_PITCH_DEAD else 'H-FD-4')
        if h: return h

    if lever < LV_BRAKE_LO:
        h = _ready('H-LB-3')
        if h: return h

    if lever >= LV_SPRINT_LO:
        h = _first(['H-CLB-3','H-HL-4','H-STOOP-1','H-OV-1'])
        if h: return h

    if payload > 0.3:
        h = _first(['H-HL-2','H-HL-3','H-HL-5','H-CR-2'])
        if h: return h

    if _water_phase_state.get('phase','') in ('water_planing','water_departure') \
            or surface_is_water():
        h = _first(['H-WD-1','H-WD-2','H-WD-3'])
        if h: return h

    # Weakest H-PERF
    st  = _PERF_STATE; ref = _PERF_REFERENCE
    perf_scores = {
        'H-PERF-1': min(1.0,st['v_max_ms']/ref['v_max_target_ms']),
        'H-PERF-2': max(0.0,1.0-st['wh_per_km_current']/ref['wh_per_km_target'])
                    if st['wh_per_km_current']>0 else 0.0,
        'H-PERF-3': min(1.0,st['n_per_w_current']/ref['n_per_w_target'])
                    if st['n_per_w_current']>0 else 0.0,
        'H-PERF-4': max(0.0,1.0-st['latency_ms_current']/ref['latency_ms_target'])
                    if st['latency_ms_current']>0 else 0.0,
        'H-PERF-5': max(0.0,1.0-st['precision_rms_current']/ref['precision_rms_target'])
                    if st['precision_rms_current']>0 else 0.0,
    }
    h = _ready(min(perf_scores, key=perf_scores.get))
    if h: return h

    for hyp in _hypothesis_queue:
        if now-_hypothesis_results.get(hyp['id'],{}).get('last_eval_t',0)>=300.0:
            return hyp
    return _hypothesis_queue[0] if _hypothesis_queue else None


# ── MAP-Elites ────────────────────────────────────────────────────────────────
def _me_niche_label(sensors, result, intent=None):
    """Adds all new niches."""
    if isinstance(sensors, dict):
        V_ms = sensors.get('V_ms', 7.0)
        speed_bin = 0 if V_ms<4 else 1 if V_ms<8 else 2 if V_ms<12 else 3
        wind_bin  = 0
    else:
        speed_bin = int(sensors) if isinstance(sensors,int) else 2
        wind_bin  = int(result)  if isinstance(result,int)  else 0

    if isinstance(result, dict):
        if result.get('ov3_active'):
            return speed_bin, wind_bin, result.get('ov3_mode','combined')
        if result.get('jump80_active'):
            return speed_bin, wind_bin, 'jump80'
        if result.get('lat_active'):
            return speed_bin, wind_bin, 'lateral_trans'
        if result.get('res_degraded'):
            return speed_bin, wind_bin, 'degraded_resilience'
        if result.get('thermal_detected'):
            return speed_bin, wind_bin, 'thermal_detected'

    intent_map = {
        'sprint_stop': 'sprint_stop', 'stoop_lateral': 'stoop_lateral',
        'direction_reversal': 'direction_reversal',
        'whisper_pigeon': 'whisper_pigeon', '3d_approach': '3d_approach',
        'cargo_lateral': 'cargo_lateral',
        'diagonal': 'diagonal', 'arced_lat': 'arced_lat',
        'full_envelope': 'full_envelope', 'jump80': 'jump80',
        'lateral_trans': 'lateral_trans',
    }
    if intent in intent_map:
        return speed_bin, wind_bin, intent_map[intent]
    return speed_bin, wind_bin, 'general'


# ── Observer analysis for new families ───────────────────────────────────────
def _obs_analyse_background(result):
    """
    Watch for convergence across Session A/B/C hypotheses.
    Issues one proposal at a time, highest priority first.
    """
    # Resilience convergence
    res = _RES_STATE
    if res.get('fault_events', 0) >= 2:
        res_evals = sum(_hypothesis_results.get(h,{}).get('n_evaluations',0)
                        for h in ['H-RES-1','H-RES-2','H-RES-3'])
        if res_evals >= 2:
            return {
                'category': 'resilience',
                'text':     (f"Resilience genome has {res_evals} evaluations. "
                             f"Best single-pair loss adaptation: "
                             f"proverse_yaw at "
                             f"{_MW_RESILIENCE.get('single_pair_loss',0)*100:.0f}%. "
                             f"Shall I run a focused fault-tolerance trial?"),
                'priority': 2,
            }

    # Sprint-stop improvement
    en = _EN_STATE
    if en.get('sprint_stop_best_dist', 999) < 20.0:
        return {
            'category': 'energy_transition',
            'text':     (f"Sprint-to-hover best stopping distance: "
                         f"{en['sprint_stop_best_dist']:.1f}m. "
                         f"Shall I run H-EN-1 to refine the cascade profile?"),
            'priority': 3,
        }

    # Thermal advisory accuracy
    th = _THERMAL_ADVISORY_STATE
    if th['n_advisories'] >= 3:
        return {
            'category': 'thermal',
            'text':     (f"Thermal detection has issued {th['n_advisories']} advisories. "
                         f"H-SOR-6 advisory system active — "
                         f"detection based on netto variometer + wing-load asymmetry. "
                         f"All decisions remain with the pilot."),
            'priority': 4,
        }
    return None

_orig_ai_obs_bg = ai_observer_tick

def ai_observer_tick(sensors, result):
    """AI observer — extended with background hypothesis analysis."""
    msgs = _orig_ai_obs_bg(sensors, result)
    if msgs: return msgs
    st  = _OBS
    now = _bg_time.monotonic()
    if (now - st['last_analysis_t'] < st['analysis_interval_s']
            or st['pending_proposal']
            or now - st['last_proposal_t'] < st['proposal_cooldown_s']):
        return msgs
    try:
        proposal = _obs_analyse_background(result)
        if proposal:
            st['pending_proposal'] = proposal
            st['last_proposal_t']  = now
            msgs.append(proposal['text'])
    except Exception:
        pass
    return msgs


# ── GS commands ───────────────────────────────────────────────────────────────
def resilience_status():
    """
    GS: resilience_status
    Wing pair fault status and resilience genome state.
    AI: 'resilience status' / 'fault tolerance' / 'wing pair fault' /
        'how many pairs active' / 'fault status' / 'degraded mode'
    """
    st = _RES_STATE
    print(f"\n  RESILIENCE STATUS")
    print(f"  ─────────────────────────────────────────────")
    print(f"  Mode:          {'DEGRADED' if st['degraded_mode'] else 'NOMINAL'}")
    print(f"  Active pairs:  {len(st['active_pairs'])}/8 "
          f"({', '.join(str(i+1) for i in st['active_pairs'])})")
    if st['failed_pairs']:
        print(f"  Failed pairs:  {', '.join(str(i+1) for i in st['failed_pairs'])}")
    print(f"  Fault events:  {st['fault_events']}")
    print(f"\n  RESILIENCE GENOME (_MW_RESILIENCE):")
    total = max(sum(_MW_RESILIENCE.values()), 0.001)
    for mech, wt in sorted(_MW_RESILIENCE.items(), key=lambda x:-x[1]):
        bar = '█' * int(wt/total*20)
        print(f"    {mech:<25} {wt/total*100:>5.1f}%  {bar}")


def thermal_advisory_status():
    """
    GS: thermal_advisory_status
    Current thermal detection and advisory state.
    AI: 'thermal status' / 'is there a thermal' / 'thermal advisory' /
        'thermal detected' / 'lift detected' / 'soaring advisory'
    """
    st = _THERMAL_ADVISORY_STATE
    print(f"\n  THERMAL ADVISORY STATUS (H-SOR-6)")
    print(f"  ─────────────────────────────────────────────")
    print(f"  Thermal active:  {'YES' if st['thermal_detected'] else 'no'}")
    if st['thermal_detected']:
        print(f"  Strength:        {st['thermal_strength_ms']:.2f} m/s above polar")
        print(f"  Est. bearing:    {st['thermal_bearing_deg']}°")
        print(f"  Est. radius:     {st['thermal_radius_m']}m")
    print(f"  Advisories:      {st['n_advisories']}")
    print(f"  Detections:      {st['n_detections']}")
    print(f"\n  PILOT CONTROL: All turning decisions remain with the pilot.")
    print(f"  The system detects and advises. It never turns autonomously.")
    print(f"  Thermal circling, if chosen, is flown by the pilot.")


def autopilot_deferred_status():
    """
    GS: autopilot_deferred_status
    List of autopilot functions deferred to post-first-flight development.
    AI: 'autopilot deferred' / 'what is deferred' / 'autopilot list' /
        'what is post flight' / 'autopilot functions' / 'future autopilot'
    """
    print(f"\n  AUTOPILOT DEFERRED — POST FIRST FLIGHT")
    print(f"  ─────────────────────────────────────────────")
    print(f"  These functions require flight-tested foundations before")
    print(f"  implementation. None are active in the current software.")
    print()
    for key, desc in _AUTOPILOT_DEFERRED.items():
        print(f"  {key:<20} {desc}")
    print(f"\n  Total deferred: {len(_AUTOPILOT_DEFERRED)}")
    print(f"  Development order (planned):")
    print(f"    1. Position hold (GPS + vision)")
    print(f"    2. Altitude hold (barometric)")
    print(f"    3. Course hold (heading + wind correction)")
    print(f"    4. Return to launch")
    print(f"    5. SAR search patterns")
    print(f"    6. Thermal exploitation (H-SOR-7)")


_GS_ALLOWED_CMDS.update({
    'resilience_status',
    'thermal_advisory_status',
    'autopilot_deferred_status',
})

# ── Final normalisation ───────────────────────────────────────────────────────
for _ax in _ALL_MW_AXES:
    _t = sum(_ax.values())
    if _t > 0 and abs(_t-1.0) > 0.001:
        for _k in _ax: _ax[_k] /= _t

# ── Verify ────────────────────────────────────────────────────────────────────
_new_ids = ['H-EN-1','H-EN-2','H-EN-3',
            'H-RES-1','H-RES-2','H-RES-3',
            'H-AQ-3','H-FD-5','H-HL-5']
_reg  = [h for h in AERO_HYPOTHESES if h['id'] in _new_ids]
_qued = [h for h in _hypothesis_queue if h['id'] in _new_ids]
_boot_log.append(f"\n  BACKGROUND KINEMATICS EXPANSION COMPLETE:")
_boot_log.append(f"  New hypotheses: {len(_reg)}/9 registered, "
                 f"{len(_qued)}/9 queued")
_boot_log.append(f"  Session A (energy transitions): H-EN-1/2/3")
_boot_log.append(f"  Session B (resilience):         H-RES-1/2/3")
_boot_log.append(f"  Session C (combinations):       H-AQ-3, H-FD-5, H-HL-5")
_boot_log.append(f"  Session D (genome axes):        _MW_ENDURANCE, _MW_TRANSITION,")
_boot_log.append(f"                                  _MW_SAR, _MW_RESILIENCE")
_boot_log.append(f"  H-SOR-6: advisory mode — suggests thermal turns to pilot")
_boot_log.append(f"  Autopilot deferred: {len(_AUTOPILOT_DEFERRED)} items logged")
_boot_log.append(f"  Total hypotheses: {len(AERO_HYPOTHESES)}")
_boot_log.append(f"  Total genome axes: {len(_ALL_MW_AXES)}")


