# ══════════════════════════════════════════════════════════════════════════════
# ADAPTIVE LEARNING COORDINATOR (ALC)
#
# The ALC is a coordinator, not a replacement. All five existing learning
# systems (AI observer, discovery selector, ALSS optimizer, genome, CMTS)
# continue operating independently. The ALC sits alongside them, reads from
# their state, writes to a shared state structure all five can read, and
# coordinates their activity toward continuous improvement across every metric.
#
# If the ALC fails or throws any exception, the five subsystems continue
# exactly as before. The ALC is additive, never foundational.
#
# STERILE COCKPIT PROTOCOL (based on FAA FAR 121.542 / CRM model):
#   Pre-flight:        full briefing — alc_preflight_brief
#   Launch prep:       STERILE — no ALC communication
#   Takeoff/climb:     STERILE — tier 3 safety only
#   Established cruise: brief operational observations (co-pilot style)
#   Active manoeuvre:  STERILE — tier 2/3 only
#   Approach/landing:  STERILE — tier 3 only
#   Post-flight:       full debrief — alc_debrief
#
# CRM THREE-TIER ESCALATION:
#   Tier 1 (concern):  cruise only, stated once, not repeated unless worsens
#   Tier 2 (advisory): any phase, stated once, logged
#   Tier 3 (unsafe):   any phase, repeated until acknowledged
#
# EXTENSIBLE MODALITY INTERFACE:
#   Any new learning modality implements four methods:
#     observe(sensors, result) → dict of findings
#     learn(findings)          → updates modality state
#     share()                  → dict written to _ALC_SHARED
#     explain()                → plain-language string for debrief
#   Register with: _alc_register_modality(name, modality_instance)
# ══════════════════════════════════════════════════════════════════════════════

import time        as _alc_time
import math        as _alc_math
import collections as _alc_col

# ── Flight phase definitions (workload-based, not altitude-based) ─────────────
# For a drone always below 10,000 ft, phase replaces altitude as the threshold
_ALC_PHASE_STERILE  = frozenset(['launch_prep','takeoff','climb',
                                  'manoeuvre','approach','landing','recovery'])
_ALC_PHASE_CRUISE   = frozenset(['cruise','hover_patrol','transit'])
_ALC_PHASE_GROUND   = frozenset(['pre_flight','post_flight','shutdown'])

# ── Shared state — all five subsystems can read from this dict ────────────────
_ALC_SHARED = {
    # Phase and workload
    'flight_phase':         'pre_flight',
    'phase_set_at':         0.0,
    'workload':             'low',          # 'low'|'medium'|'high'
    # Priority queue (observer → discovery link)
    'priority_hyp_queue':   [],             # [{'hyp_id':..,'reason':..,'t':..}]
    # Burst evaluation requests (CMTS → discovery link)
    'burst_eval_queue':     [],             # [{'config':..,'contexts':[..],'t':..}]
    # Improvement velocity (per genome axis, rolling)
    'axis_velocity':        {},             # axis_name → deque of recent score deltas
    'axis_velocity_alert':  {},             # axis_name → True if velocity below threshold
    # Degradation tracking
    'metric_bests':         {},             # metric → best value seen
    'metric_degraded':      {},             # metric → True if currently degraded
    # Session memory (persists across flights)
    'session_log':          [],             # [{flight_n, hyp_id, score, t, phase}]
    'exhausted_regions':    {},             # hyp_family → {'cascade_range':...}
    'flight_number':        0,
    'total_evaluations':    0,
    # Pilot satisfaction signal
    'pilot_rating_log':     [],             # [{t, rating, hyp_id, config_snapshot}]
    'last_pilot_rating':    None,
    # In-flight alert log
    'alert_log':            [],             # [{tier, text, t, ack}]
    'pending_tier3':        None,           # text of unacknowledged tier 3 alert
    # Modality registry
    'modalities':           {},             # name → instance dict
    # Cruise observation cooldown (co-pilot discipline)
    'last_cruise_obs_t':    0.0,
    'cruise_obs_cooldown_s': 45.0,
}

# Rolling window for velocity tracking
_ALC_VELOCITY_WINDOW = 8    # evaluations
_ALC_VELOCITY_MIN    = 0.005 # below this → search radius expands
_ALC_DEGRADATION_THR = 0.05  # 5% degradation from recent best → alert
_ALC_DEGRADATION_N   = 2     # consecutive evaluations degraded before alert


# ── Modality registry ─────────────────────────────────────────────────────────
def _alc_register_modality(name, observe_fn, learn_fn, share_fn, explain_fn):
    """
    Register a new learning modality with the ALC.
    observe_fn(sensors, result) → dict
    learn_fn(findings)          → None
    share_fn()                  → dict
    explain_fn()                → str
    """
    _ALC_SHARED['modalities'][name] = {
        'observe':  observe_fn,
        'learn':    learn_fn,
        'share':    share_fn,
        'explain':  explain_fn,
        'healthy':  True,
        'last_run': 0.0,
    }


# ── Flight phase management ───────────────────────────────────────────────────
def alc_set_phase(phase):
    """
    Set the current flight phase. Called by the flight controller
    at phase transitions. Phase determines ALC communication discipline.
    Valid: pre_flight, launch_prep, takeoff, climb, cruise, hover_patrol,
           transit, manoeuvre, approach, landing, recovery, post_flight
    """
    _ALC_SHARED['flight_phase'] = phase
    _ALC_SHARED['phase_set_at'] = _alc_time.monotonic()
    _pl_append_log({'event': 'alc_phase', 'phase': phase})


def _alc_is_sterile():
    """True when ALC must be silent (safety tier 3 excepted)."""
    return _ALC_SHARED['flight_phase'] in _ALC_PHASE_STERILE

def _alc_is_cruise():
    """True when brief operational observations are permitted."""
    return _ALC_SHARED['flight_phase'] in _ALC_PHASE_CRUISE

def _alc_is_ground():
    """True during pre/post flight — full conversation permitted."""
    return _ALC_SHARED['flight_phase'] in _ALC_PHASE_GROUND


# ── CRM three-tier alert system ───────────────────────────────────────────────
def _alc_alert(tier, text, metric=None, value=None):
    """
    Surface a CRM-tiered alert.
    Tier 1: cruise only, logged, stated once
    Tier 2: any phase, logged, stated once
    Tier 3: any phase, logged, repeated until acknowledged via alc_ack_alert()
    """
    st = _ALC_SHARED
    now = _alc_time.monotonic()

    if tier == 1 and not _alc_is_cruise():
        # Tier 1 must wait for cruise — log it for when phase changes
        st['alert_log'].append({
            'tier': tier, 'text': text, 'metric': metric,
            'value': value, 't': now, 'ack': False, 'deferred': True
        })
        return None

    entry = {'tier': tier, 'text': text, 'metric': metric,
             'value': value, 't': now, 'ack': False, 'deferred': False}
    st['alert_log'].append(entry)

    if tier == 3:
        st['pending_tier3'] = text

    _pl_append_log({'event': 'alc_alert', 'tier': tier, 'text': text[:80]})
    return text


def alc_ack_alert():
    """
    GS: alc_ack_alert
    Acknowledge a pending tier-3 safety alert.
    AI: 'acknowledge alert' / 'ack alert' / 'I see it' / 'noted' /
        'alert acknowledged' / 'understood'
    """
    st = _ALC_SHARED
    if st['pending_tier3']:
        for entry in reversed(st['alert_log']):
            if entry['tier'] == 3 and not entry['ack']:
                entry['ack'] = True
                break
        alert_text = st['pending_tier3']
        st['pending_tier3'] = None
        print(f"\n  ✓ Alert acknowledged: {alert_text[:80]}")
    else:
        print(f"\n  No pending tier-3 alert.")

_GS_ALLOWED_CMDS.add('alc_ack_alert')


# ── Improvement velocity tracking ─────────────────────────────────────────────
def _alc_update_velocity(hyp_id, score_delta):
    """
    Track improvement velocity per genome axis family.
    When velocity drops below threshold, widen discovery search radius.
    """
    st = _ALC_SHARED
    # Map hypothesis to its primary genome axis
    _HYP_AXIS_MAP = {
        'H-ROLL': '_MW_ROLL', 'H-MV': '_MW_ROLL', 'H-HS': '_MW_ROLL',
        'H-PITCH': '_MW_PITCH', 'H-PF': '_MW_PITCH', 'H-LB': '_MW_PITCH',
        'H-YAW': '_MW_YAW', 'H-PDW': '_MW_YAW',
        'H-DIH': '_MW_STABILITY', 'H-STORM': '_MW_STABILITY',
        'H-SOR': '_MW_SOARING', 'H-MO': '_MW_SOARING',
        'H-CE': '_MW_GLIDE', 'H-KW': '_MW_GLIDE',
        'H-HB': '_MW_TURN', 'H-RC': '_MW_TURN',
        'H-WD': '_MW_WATER',
        'H-HL': '_MW_CARGO', 'H-CR': '_MW_CARGO',
        'H-PERF': '_MW_PERFORMANCE', 'H-EV': '_MW_COMPETITION',
        'H-EN': '_MW_TRANSITION', 'H-TX': '_MW_TRANSITION',
        'H-RES': '_MW_RESILIENCE', 'H-GS': '_MW_RESILIENCE',
        'H-AQ': '_MW_SAR', 'H-FD': '_MW_SAR', 'H-SP': '_MW_SAR',
        'H-DA': '_MW_ENDURANCE', 'H-OV': '_MW_PERFORMANCE',
    }
    # Find axis from hyp_id prefix
    axis = None
    for prefix, ax in _HYP_AXIS_MAP.items():
        if hyp_id.startswith(prefix):
            axis = ax
            break
    if axis is None:
        return

    if axis not in st['axis_velocity']:
        st['axis_velocity'][axis] = _alc_col.deque(maxlen=_ALC_VELOCITY_WINDOW)
    st['axis_velocity'][axis].append(score_delta)

    # Compute rolling mean
    window = st['axis_velocity'][axis]
    if len(window) >= 4:
        mean_v = sum(window) / len(window)
        was_low = st['axis_velocity_alert'].get(axis, False)
        is_low  = mean_v < _ALC_VELOCITY_MIN

        if is_low and not was_low:
            # Velocity just dropped — widen search radius for this axis
            st['axis_velocity_alert'][axis] = True
            # Signal discovery: expand exploration for this axis
            _ALC_SHARED['priority_hyp_queue'].append({
                'reason':     f'velocity_low_{axis}',
                'hyp_family': axis.replace('_MW_','').lower(),
                'expand':     True,
                't':          _alc_time.monotonic(),
            })
        elif not is_low and was_low:
            st['axis_velocity_alert'][axis] = False


# ── Degradation detection ─────────────────────────────────────────────────────
_ALC_DEGRAD_COUNTS = {}  # metric → consecutive degradation count

def _alc_check_degradation(sensors):
    """
    Compare current metric values against recent bests.
    Alert if any metric degrades >5% in two consecutive evaluations.
    """
    st   = _ALC_SHARED
    ps   = _PERF_STATE
    now  = _alc_time.monotonic()

    metrics = {
        'v_max_ms':      (ps.get('v_max_ms', 0),          +1),
        'wh_per_km':     (ps.get('wh_per_km_current', 999), -1),
        'n_per_w':       (ps.get('n_per_w_current', 0),    +1),
        'latency_ms':    (ps.get('latency_ms_current', 999),-1),
        'precision_rms': (ps.get('precision_rms_current',999),-1),
    }

    for metric, (current, direction) in metrics.items():
        if current in (0, 999, None):
            continue

        # Update best
        best = st['metric_bests'].get(metric)
        if best is None:
            st['metric_bests'][metric] = current
            continue

        if direction == +1 and current > best:
            st['metric_bests'][metric] = current
            _ALC_DEGRAD_COUNTS[metric] = 0
            continue
        elif direction == -1 and current < best:
            st['metric_bests'][metric] = current
            _ALC_DEGRAD_COUNTS[metric] = 0
            continue

        # Check degradation from best
        if best != 0:
            deg = abs(current - best) / abs(best)
        else:
            continue

        if deg > _ALC_DEGRADATION_THR:
            _ALC_DEGRAD_COUNTS[metric] = _ALC_DEGRAD_COUNTS.get(metric, 0) + 1
            if _ALC_DEGRAD_COUNTS[metric] >= _ALC_DEGRADATION_N:
                pct  = deg * 100
                tier = 2 if pct < 15 else 3
                txt  = (f"{metric} degraded {pct:.0f}% from best "
                        f"({best:.3g} → {current:.3g}). "
                        f"{'Recommend investigation.' if tier==2 else 'RECOMMEND LANDING.'}")
                _alc_alert(tier, txt, metric=metric, value=current)
                st['metric_degraded'][metric] = True
        else:
            _ALC_DEGRAD_COUNTS[metric] = 0
            st['metric_degraded'][metric] = False


# ── Session memory ────────────────────────────────────────────────────────────
def _alc_log_evaluation(hyp_id, score_delta, sensors):
    """
    Log every hypothesis evaluation to the persistent session memory.
    Tracks which parameter regions have been explored and their results.
    """
    st  = _ALC_SHARED
    now = _alc_time.monotonic()
    h   = next((h for h in AERO_HYPOTHESES if h['id'] == hyp_id), None)
    if not h: return

    cfg = h.get('config', {})
    entry = {
        'flight':    st['flight_number'],
        'hyp_id':    hyp_id,
        'score':     round(score_delta, 4),
        'freq_hz':   cfg.get('freq_hz', 0),
        'cascade':   cfg.get('cascade_phase_deg', 0),
        'amp':       cfg.get('amp_port_deg', 0),
        'dih':       cfg.get('dihedral_deg', 0),
        'phase':     st['flight_phase'],
        't':         round(now, 1),
    }
    st['session_log'].append(entry)
    st['total_evaluations'] += 1

    # Track exhausted regions: if a hyp family scores poorly 3+ times
    # in the same parameter bucket, mark that region as exhausted
    fam = '-'.join(hyp_id.split('-')[:2])
    fam_history = [e for e in st['session_log']
                   if e['hyp_id'].startswith(fam) and e['score'] <= 0]
    if len(fam_history) >= 3:
        # Check if they cluster in the same cascade/amp bucket
        cascades = [e['cascade'] for e in fam_history[-3:]]
        if max(cascades) - min(cascades) < 20:
            bucket = f"{fam}_cascade_{int(cascades[-1]//20)*20}"
            if bucket not in st['exhausted_regions']:
                st['exhausted_regions'][bucket] = {
                    'cascade_centre': sum(cascades)/len(cascades),
                    'n_poor':         len(fam_history),
                    'last_t':         now,
                }


# ── Observer → Discovery reactive dispatch ────────────────────────────────────
def _alc_obs_to_discovery(obs_finding, hyp_ids):
    """
    When the observer detects an anomaly, immediately queue the
    relevant hypothesis for the next discovery selection cycle.
    This is the primary cross-talk link that did not exist before.
    The discovery selector checks _ALC_SHARED['priority_hyp_queue']
    before its normal selection logic.
    """
    now = _alc_time.monotonic()
    for hid in hyp_ids:
        # Check not already in queue
        already = any(e.get('hyp_id') == hid
                      for e in _ALC_SHARED['priority_hyp_queue'])
        if not already:
            _ALC_SHARED['priority_hyp_queue'].append({
                'hyp_id': hid,
                'reason': obs_finding[:60],
                't':      now,
                'ttl':    now + 600.0,  # 10-minute time-to-live
            })


# ── CMTS → Discovery burst evaluation ────────────────────────────────────────
def _alc_cmts_burst(source_hyp, config, contexts):
    """
    When CMTS finds a cross-mode winner, queue the same configuration
    for evaluation in all related contexts as a burst.
    """
    now = _alc_time.monotonic()
    _ALC_SHARED['burst_eval_queue'].append({
        'source_hyp': source_hyp,
        'config':     dict(config),
        'contexts':   contexts,
        't':          now,
        'ttl':        now + 1800.0,  # 30-minute TTL
    })


# ── Genome → Observer (significant axis shifts) ───────────────────────────────
def _alc_genome_shift_check():
    """
    Detect when any genome axis has shifted significantly.
    Records the shift for inclusion in the post-flight debrief.
    Does not interrupt flight — purely a logging function.
    """
    shifts = {}
    for ax_name in ['_MW_ROLL','_MW_PITCH','_MW_YAW','_MW_STABILITY',
                    '_MW_SOARING','_MW_GLIDE','_MW_TURN','_MW_WATER',
                    '_MW_CARGO','_MW_COMPETITION','_MW_PERFORMANCE',
                    '_MW_ENDURANCE','_MW_TRANSITION','_MW_SAR','_MW_RESILIENCE']:
        ax = globals().get(ax_name)
        if ax is None: continue
        top_mech = max(ax, key=ax.get)
        top_wt   = ax[top_mech]
        prev_key = f'_prev_{ax_name}'
        prev     = _ALC_SHARED.get(prev_key)
        if prev and prev != top_mech:
            shifts[ax_name] = {'from': prev, 'to': top_mech,
                               'weight': round(top_wt, 3)}
        _ALC_SHARED[prev_key] = top_mech
    return shifts


# ── Pilot satisfaction signal ─────────────────────────────────────────────────
def learning_rate(rating='neutral'):
    """
    GS: learning_rate
    Pilot satisfaction signal — directly influences genome weighting.
    Rating: 'good' | 'neutral' | 'poor'
    AI: 'learning rate good' / 'that felt good' / 'great improvement' /
        'learning rate poor' / 'that felt worse' / 'not better' /
        'learning rate neutral' / 'about the same'
    Can be called any time — during flight or post-flight.
    """
    st  = _ALC_SHARED
    now = _alc_time.monotonic()
    rating = rating.lower().strip()
    if rating not in ('good','neutral','poor'):
        # Try to infer
        if any(w in rating for w in ['good','great','better','yes','smooth','nice']):
            rating = 'good'
        elif any(w in rating for w in ['poor','bad','worse','no','rough','sloppy']):
            rating = 'poor'
        else:
            rating = 'neutral'

    # Identify what configuration was active at this moment
    lever  = _flight_state.get('lever_pct', 50.0)
    active_hyp = None
    # Find most recently evaluated hypothesis
    if st['session_log']:
        recent = sorted(st['session_log'], key=lambda e: e['t'])[-1]
        active_hyp = recent.get('hyp_id')

    entry = {
        't':       round(now, 1),
        'rating':  rating,
        'hyp_id':  active_hyp,
        'lever':   round(lever, 1),
        'phase':   st['flight_phase'],
    }
    st['pilot_rating_log'].append(entry)
    st['last_pilot_rating'] = entry

    # Apply genome signal
    boost_map = {'good': +0.04, 'neutral': 0.0, 'poor': -0.03}
    boost = boost_map[rating]

    if active_hyp and boost != 0:
        try:
            _update_genome_from_trial(active_hyp,
                                      max(0.001, boost) if boost > 0
                                      else 0,  # negative handled below
                                      {})
            if boost < 0:
                # Mild negative reinforcement: reduce current config weight
                zone = _flight_state.get('lever_zone','CRUISE')
                if zone in _lever_mode_weights:
                    for mid, wt in _lever_mode_weights[zone].items():
                        _lever_mode_weights[zone][mid] = max(0.1, wt * 0.95)
        except Exception:
            pass

    feedback = {'good': 'Positive feedback noted. Genome reinforced.',
                'neutral': 'Neutral feedback noted. No genome change.',
                'poor': 'Negative feedback noted. Genome weight reduced for current config.'}
    print(f"\n  Pilot rating: {rating.upper()} — {feedback[rating]}")
    if active_hyp:
        print(f"  Applied to:   {active_hyp}")

_GS_ALLOWED_CMDS.add('learning_rate')


# ── ALC main tick — runs in stroke_smoothing_tick at reduced rate ─────────────
_ALC_TICK_INTERVAL = 2.0   # ALC coordination runs every 2 seconds
_ALC_LAST_TICK     = 0.0

def _alc_tick(sensors, result):
    """
    ALC coordination tick.
    Runs at reduced rate (every 2s) — coordination overhead, not flight control.
    During flight: monitors, logs, checks degradation, runs modalities silently.
    Surfaces alerts only per CRM tier protocol.
    """
    global _ALC_LAST_TICK
    now = _alc_time.monotonic()
    if now - _ALC_LAST_TICK < _ALC_TICK_INTERVAL:
        return result
    _ALC_LAST_TICK = now

    st = _ALC_SHARED

    # Auto-detect flight phase from sensor state
    lever = sensors.get('lever_pct', 50.0) if isinstance(sensors,dict) else 50.0
    V_ms  = sensors.get('V_ms', 0.0) if isinstance(sensors,dict) else 0.0
    if st['flight_phase'] == 'pre_flight' and lever > 20 and V_ms > 1.0:
        alc_set_phase('cruise')   # auto-transition to cruise on takeoff

    # Run all registered modalities silently
    for name, mod in st['modalities'].items():
        try:
            findings = mod['observe'](sensors, result)
            mod['learn'](findings)
            shared   = mod['share']()
            st.update({f'mod_{name}_{k}': v for k,v in shared.items()})
            mod['last_run'] = now
        except Exception as _me:
            mod['healthy'] = False
            _tick_error_log(f'alc_mod_{name}', _me)

    # Degradation check
    try:
        _alc_check_degradation(sensors)
    except Exception:
        pass

    # Genome shift check (silent, for debrief)
    try:
        shifts = _alc_genome_shift_check()
        if shifts:
            st['_genome_shifts_this_session'] = st.get(
                '_genome_shifts_this_session', [])
            st['_genome_shifts_this_session'].append(
                {'t': now, 'shifts': shifts})
    except Exception:
        pass

    # Expire stale priority queue entries
    st['priority_hyp_queue'] = [
        e for e in st['priority_hyp_queue']
        if e.get('ttl', now+1) > now
    ]

    # Cruise observation — deferred tier-1 alerts
    if _alc_is_cruise():
        if now - st['last_cruise_obs_t'] >= st['cruise_obs_cooldown_s']:
            deferred = [e for e in st['alert_log']
                        if e.get('deferred') and not e['ack']]
            if deferred:
                oldest = sorted(deferred, key=lambda e: e['t'])[0]
                oldest['deferred'] = False
                result['alc_cruise_obs'] = oldest['text']
                st['last_cruise_obs_t'] = now

    # Pending tier-3 re-surface
    if st.get('pending_tier3') and not _alc_is_ground():
        result['alc_tier3_pending'] = st['pending_tier3']

    return result


# Wire ALC tick into stroke_smoothing_tick
_orig_stroke_sm_alc = stroke_smoothing_tick

def stroke_smoothing_tick(sensors, result):
    """Stroke smoothing — extended with ALC coordination tick."""
    result = _orig_stroke_sm_alc(sensors, result)
    try:
        _alc_tick(sensors, result)
    except Exception as _e:
        _tick_error_log('alc_tick', _e)
    return result


# ── Discovery selector — ALC priority queue integration ───────────────────────
def discovery_hypothesis_select():
    """
    DEFINITIVE discovery routing — ALC priority queue checked first.
    All 153 hypotheses, all families. ALC-coordinated when queue non-empty.
    """
    st     = _ALC_SHARED
    focus  = _focus_state.get('active','')
    now    = _alc_time.monotonic()
    lever  = _flight_state.get('lever_pct', 50.0)
    h_agl  = _flight_state.get('h_agl_m',  100.0)
    V_ms   = _flight_state.get('V_ms',       7.0)
    pitch  = _flight_state.get('pitch_stick', 0.0)
    payload= _flight_state.get('payload_kg',  0.0)

    def _ready(hid):
        hyp = next((h for h in _hypothesis_queue if h['id']==hid), None)
        # Also respect exhausted regions
        if hyp:
            fam = '-'.join(hid.split('-')[:2])
            cfg = hyp.get('config',{})
            casc = cfg.get('cascade_phase_deg', 28.0)
            bucket = f"{fam}_cascade_{int(casc//20)*20}"
            if bucket in st['exhausted_regions']:
                return None  # skip exhausted region
            last_eval = _hypothesis_results.get(hid,{}).get('last_eval_t',0)
            if now - last_eval >= 300:
                return hyp
        return None

    def _first(ids):
        for hid in ids:
            h = _ready(hid)
            if h: return h
        return None

    # ── ALC priority queue (observer → discovery link) ────────────────────────
    if st['priority_hyp_queue']:
        entry = st['priority_hyp_queue'][0]
        hid   = entry.get('hyp_id')
        if hid:
            h = _ready(hid)
            if h:
                st['priority_hyp_queue'].pop(0)
                return h
        elif entry.get('expand'):
            # Velocity low — expand search: use fallback below
            st['priority_hyp_queue'].pop(0)

    # ── Auto state routing ────────────────────────────────────────────────────
    if _RES_STATE.get('degraded_mode'):
        h = _first(['H-RES-1','H-RES-2'] if
                   len(_RES_STATE.get('failed_pairs',[]))>=2 else ['H-RES-1'])
        if h: return h

    if _WHISPER_STATE.get('active') and LV_DESCENT_LO<=lever<=LV_GLIDE_LO:
        h = _ready('H-AQ-3')
        if h: return h

    if payload > 0.3 and _OV_STATE.get('lat_active'):
        h = _ready('H-HL-5')
        if h: return h

    if _OV3_STATE.get('active') and h_agl > 0.3:
        h = _ready('H-OV-3')
        if h: return h

    if LV_CLIMB_LO <= lever <= LV_SPRINT_LO and V_ms > 3.0:
        h = _ready('H-OV-1')
        if h: return h

    if _OV_STATE.get('lat_active') and h_agl > 0.3:
        h = _ready('H-OV-2')
        if h: return h

    # ── Focus keyword routing (complete — same as definitive version) ─────────
    FOCUS = {
        'acceleration':['H-ACC-1','H-ACC-2','H-ACC-3','H-ACC-7'],
        'sprint':['H-HS-1','H-HS-2','H-ACC-7','H-TR-1'],
        'acoustic':['H-EV-2','H-AQ-1','H-AQ-2','H-AQ-3'],
        'whisper':['H-AQ-1','H-AQ-2','H-AQ-3','H-EV-2'],
        'quiet_approach':['H-AQ-3','H-AQ-1','H-FD-4'],
        'whisper_pigeon':['H-AQ-3'],
        'aerobatics':['H-HB-1','H-HB-2','H-HB-3','H-HB-4','H-HB-5'],
        'agility':['H-PULL-1','H-RC-1','H-HB-1','H-OV-3','H-VIFF-1'],
        'viff':['H-VIFF-1','H-VIFF-2','H-VIFF-3'],
        'brake':['H-RC-3','H-EN-1','H-LB-3'],
        'hard_brake':['H-RC-3','H-EN-1','H-LB-3'],
        'emergency_stop':['H-LB-3','H-AM-1'],
        'sprint_stop':['H-EN-1'],
        'bush':['H-BS-1','H-BS-4','H-BS-5'],
        'crosswind':['H-BS-4','H-DIH-3'],
        'cargo':['H-HL-1','H-HL-2','H-HL-3','H-HL-5','H-CR-2','H-CR-3'],
        'heavy_lift':['H-HL-1','H-HL-2','H-HL-3','H-HL-4','H-HL-5'],
        'cargo_lateral':['H-HL-5'],
        'evtol':['H-EV-1','H-EV-2'],
        'certification':['H-EV-1','H-EV-2'],
        'climb':['H-OV-1','H-CLB-1','H-CLB-2','H-CLB-3','H-CLB-4'],
        'combined':['H-OV-3'],
        'diagonal':['H-OV-3'],
        'omnidirectional':['H-OV-3'],
        'competition':['H-CR-1','H-CR-2','H-CR-3','H-CR-4','H-CR-5'],
        'gps_denied':['H-CR-1','H-CR-5'],
        'density_alt':['H-DA-1','H-DA-2','H-DA-3','H-DA-4',
                        'H-DA-5','H-DA-6','H-DA-7'],
        'pigeon':['H-FD-1','H-FD-2','H-FD-3','H-FD-4','H-FD-5'],
        'flat_descent':['H-FD-1','H-FD-2','H-FD-3','H-FD-5'],
        'steep_descent':['H-FD-4','H-AQ-3','H-FD-3'],
        '3d_approach':['H-FD-5'],
        'direction_reversal':['H-EN-3'],
        'cheyenne':['H-EN-3'],
        'reverse':['H-RC-2','H-OV-3','H-EN-3'],
        'backwards':['H-RC-2','H-OV-3','H-EN-3'],
        'energy_transition':['H-EN-1','H-EN-2','H-EN-3'],
        'stoop_lateral':['H-EN-2'],
        'transition':['H-TX-1','H-TR-2','H-PF-3','H-EN-1'],
        'evasive':['H-RC-1','H-RC-2','H-RC-3','H-RC-4','H-OV-3'],
        'raider':['H-RC-1','H-RC-2','H-RC-3','H-RC-4'],
        'resilience':['H-RES-1','H-RES-2','H-RES-3'],
        'fault_tolerance':['H-RES-1','H-RES-2','H-RES-3'],
        'soaring':['H-SOR-1','H-SOR-2','H-SOR-3','H-SOR-4','H-SOR-5','H-SOR-6'],
        'thermal':['H-SOR-4','H-SOR-6'],
        'endurance':['H-SOR-3','H-CR-3','H-CR-4','H-HL-3'],
        'glide':['H-SOR-1','H-SOR-2','H-CE-1','H-KW-1'],
        'kestrel':['H-KW-1','H-KW-2','H-KW-3','H-KW-4'],
        'gust':['H-GS-1','H-STORM-1','H-STORM-3'],
        'turbulence':['H-GS-1','H-STORM-1','H-STORM-2'],
        'comfort':['H-GS-1','H-PDW-1','H-ST-1'],
        'high_speed':['H-STOOP-1','H-PERF-1','H-OV-1','H-HS-1'],
        'top_speed':['H-PERF-1','H-STOOP-1','H-OV-1','H-HS-1'],
        'hover':['H-PERF-3','H-OV-2','H-OV-3','H-SP-1','H-MO-1'],
        'knife_edge':['H-PULL-1'],
        'pullout':['H-PULL-1'],
        'lateral':['H-OV-2','H-OV-3','H-FD-5'],
        'sideward':['H-OV-2','H-OV-3'],
        'morphing':['H-33','H-34','H-35','H-36'],
        'osprey':['H-OV-1','H-OV-2','H-OV-3'],
        'jump80':['H-OV-1'],
        'performance':['H-PERF-1','H-PERF-2','H-PERF-3','H-PERF-4','H-PERF-5'],
        'efficiency':['H-PERF-2','H-PERF-3'],
        'precision':['H-PF-1','H-PF-2','H-CR-1','H-PREC-1','H-FD-5','H-EN-1'],
        'pilot_feel':['H-PF-1','H-PF-2','H-PF-3','H-PF-4','H-PF-5','H-PF-6'],
        'smooth_flight':['H-PDW-1','H-DIH-1','H-TX-1','H-PF-3','H-ST-1'],
        'range':['H-SOR-2','H-AQ-1','H-CR-3','H-35','H-36'],
        'sar':['H-SP-1','H-SP-2','H-PF-5','H-PF-6','H-SOR-6','H-BS-5',
               'H-FD-5','H-AQ-3'],
        'stability':['H-PDW-1','H-PDW-2','H-PDW-3','H-DIH-1','H-DIH-2','H-DIH-3'],
        'stoop':['H-STOOP-1','H-PULL-1','H-EN-2'],
        'dart':['H-STOOP-1'],
        'storm':['H-STORM-1','H-STORM-2','H-STORM-3','H-STORM-4',
                  'H-STORM-5','H-STORM-6','H-STORM-7'],
        'water':['H-WD-1','H-WD-2','H-WD-3'],
        'whisper_pigeon':['H-AQ-3'],
        'cross_mode':['H-PERF-2','H-PERF-3','H-AQ-1','H-OV-1'],
        'speed':['H-PERF-1','H-STOOP-1','H-OV-1'],
        'noe':['H-BS-5'],
        'sensor_pointing':['H-SP-1','H-SP-2','H-RC-4'],
    }

    if focus in FOCUS:
        h = _first(FOCUS[focus])
        if h: return h

    # ── Lever zone routing ────────────────────────────────────────────────────
    if LV_DESCENT_LO <= lever <= LV_GLIDE_LO and h_agl > 0.5:
        for (lo,hi),hid in [
            ((PD_NEW_SHALLOW_LO,PD_NEW_SHALLOW_HI), 'H-FD-2'),
            ((PD_NEW_MODERATE_LO,PD_NEW_MODERATE_HI),'H-FD-1'),
            ((PD_NEW_STEEP_LO, PD_NEW_STEEP_HI),   'H-FD-3'),
        ]:
            if lo <= lever <= hi:
                h = _ready(hid)
                if h: return h
                break

    if LV_BRAKE_LO <= lever <= LV_DESCENT_LO:
        h = _ready('H-RC-3' if abs(pitch)<=RC_HARD_BRAKE_PITCH_DEAD else 'H-FD-4')
        if h: return h

    if lever < LV_BRAKE_LO:
        h = _ready('H-LB-3')
        if h: return h

    if lever >= LV_SPRINT_LO:
        h = _first(['H-CLB-3','H-HL-4','H-STOOP-1','H-OV-1'])
        if h: return h

    if payload > 0.3:
        h = _first(['H-HL-2','H-HL-3','H-HL-5','H-CR-2'])
        if h: return h

    if (_water_phase_state.get('phase','') in ('water_planing','water_departure')
            or surface_is_water()):
        h = _first(['H-WD-1','H-WD-2','H-WD-3'])
        if h: return h

    # Weakest H-PERF
    ps2 = _PERF_STATE; ref = _PERF_REFERENCE
    _ps = {
        'H-PERF-1': min(1.0, ps2['v_max_ms']/ref['v_max_target_ms']),
        'H-PERF-2': max(0.0,1.0-ps2['wh_per_km_current']/ref['wh_per_km_target'])
                    if ps2['wh_per_km_current']>0 else 0.0,
        'H-PERF-3': min(1.0,ps2['n_per_w_current']/ref['n_per_w_target'])
                    if ps2['n_per_w_current']>0 else 0.0,
        'H-PERF-4': max(0.0,1.0-ps2['latency_ms_current']/ref['latency_ms_target'])
                    if ps2['latency_ms_current']>0 else 0.0,
        'H-PERF-5': max(0.0,1.0-ps2['precision_rms_current']/ref['precision_rms_target'])
                    if ps2['precision_rms_current']>0 else 0.0,
    }
    h = _ready(min(_ps, key=_ps.get))
    if h: return h

    for hyp in _hypothesis_queue:
        if now-_hypothesis_results.get(hyp['id'],{}).get('last_eval_t',0)>=300.0:
            return hyp
    return _hypothesis_queue[0] if _hypothesis_queue else None


# ── Hook _update_genome_from_trial to also notify ALC ────────────────────────
_orig_update_genome_alc = _update_genome_from_trial

def _update_genome_from_trial(hyp_id, score_delta, sensors):
    """Genome update — ALC session logging and velocity tracking added."""
    _orig_update_genome_alc(hyp_id, score_delta, sensors)
    try:
        _alc_log_evaluation(hyp_id, score_delta, sensors)
        _alc_update_velocity(hyp_id, score_delta)
    except Exception as _e:
        _tick_error_log('alc_genome_hook', _e)


# ── Persist integration ───────────────────────────────────────────────────────
_orig_persist_save_alc = persist_save_all

def persist_save_all(*args, **kwargs):
    """Persist — extended to save ALC session memory."""
    result = _orig_persist_save_alc(*args, **kwargs)
    try:
        alc_data = {
            'session_log':       _ALC_SHARED['session_log'][-500:],  # cap at 500
            'exhausted_regions': _ALC_SHARED['exhausted_regions'],
            'flight_number':     _ALC_SHARED['flight_number'],
            'total_evaluations': _ALC_SHARED['total_evaluations'],
            'metric_bests':      _ALC_SHARED['metric_bests'],
            'pilot_rating_log':  _ALC_SHARED['pilot_rating_log'][-100:],
            'axis_velocity_alert': _ALC_SHARED['axis_velocity_alert'],
        }
        _pl_write(f'{_PL_DIR}/alc_session.json', alc_data)
    except Exception as _e:
        _tick_error_log('alc_persist_save', _e)
    return result

_orig_persist_load_alc = persist_load_all

def persist_load_all(*args, **kwargs):
    """Persist — extended to restore ALC session memory."""
    result = _orig_persist_load_alc(*args, **kwargs)
    try:
        import json, os
        path = f'{_PL_DIR}/alc_session.json'
        if os.path.exists(path):
            with open(path) as f:
                alc_data = json.load(f)
            _ALC_SHARED['session_log']        = alc_data.get('session_log', [])
            _ALC_SHARED['exhausted_regions']  = alc_data.get('exhausted_regions', {})
            _ALC_SHARED['flight_number']      = alc_data.get('flight_number', 0)
            _ALC_SHARED['total_evaluations']  = alc_data.get('total_evaluations', 0)
            _ALC_SHARED['metric_bests']       = alc_data.get('metric_bests', {})
            _ALC_SHARED['pilot_rating_log']   = alc_data.get('pilot_rating_log', [])
            _ALC_SHARED['axis_velocity_alert']= alc_data.get('axis_velocity_alert', {})
    except Exception as _e:
        _tick_error_log('alc_persist_load', _e)
    return result


# ── GS commands ───────────────────────────────────────────────────────────────
def alc_preflight_brief():
    """
    GS: alc_preflight_brief
    Pre-flight briefing — what was learned last session, what is queued,
    what to watch for this flight.
    AI: 'preflight brief' / 'what did you learn' / 'pre-flight' /
        'brief me' / 'what should I know before flying' /
        'learning summary' / 'what happened last flight'
    """
    st  = _ALC_SHARED
    fn  = st['flight_number']
    tot = st['total_evaluations']

    print(f"\n  ═══ ALC PRE-FLIGHT BRIEF — Flight #{fn+1} ═══")
    print(f"\n  SESSION HISTORY:")
    print(f"  Total flights:        {fn}")
    print(f"  Total evaluations:    {tot}")

    # Recent improvements
    if st['metric_bests']:
        print(f"\n  CURRENT BESTS (all time):")
        for metric, val in st['metric_bests'].items():
            print(f"    {metric:<20} {val:.4g}")

    # Exhausted regions
    if st['exhausted_regions']:
        print(f"\n  EXHAUSTED SEARCH REGIONS ({len(st['exhausted_regions'])}):")
        for bucket in list(st['exhausted_regions'].keys())[:5]:
            info = st['exhausted_regions'][bucket]
            print(f"    {bucket}: cascade≈{info['cascade_centre']:.0f}° "
                  f"({info['n_poor']} poor evaluations)")
        print(f"    Discovery will avoid these regions this flight.")

    # Axis velocity alerts
    low_v = [ax for ax, alert in st['axis_velocity_alert'].items() if alert]
    if low_v:
        print(f"\n  SLOW-LEARNING AXES (search radius widened):")
        for ax in low_v:
            print(f"    {ax} — genome not improving, exploring wider")

    # Priority queue
    if st['priority_hyp_queue']:
        print(f"\n  PRIORITY EVALUATIONS THIS FLIGHT:")
        for entry in st['priority_hyp_queue'][:5]:
            hid = entry.get('hyp_id','?')
            rsn = entry.get('reason','?')
            print(f"    {hid}: {rsn}")

    # Genome top mechanisms
    print(f"\n  GENOME CURRENT TOP MECHANISMS:")
    for ax_name in ['_MW_PERFORMANCE','_MW_STABILITY','_MW_SAR','_MW_RESILIENCE']:
        ax = globals().get(ax_name)
        if ax:
            top = max(ax, key=ax.get)
            print(f"    {ax_name:<22} → {top} ({ax[top]*100:.0f}%)")

    # What to watch
    print(f"\n  WATCH DURING THIS FLIGHT:")
    degraded = [m for m,v in st['metric_degraded'].items() if v]
    if degraded:
        print(f"    ⚠ Degraded metrics: {degraded}")
    print(f"    → Observer will surface tier-1 observations during cruise")
    print(f"    → Tier-3 safety alerts will interrupt any phase")
    print(f"    → Use 'learning_rate good/neutral/poor' to give feedback")
    print(f"\n  STERILE COCKPIT: ALC silent except safety alerts during flight.")
    print(f"  Full debrief available post-flight: alc_debrief")

    # Increment flight number
    st['flight_number'] += 1


def alc_debrief():
    """
    GS: alc_debrief
    Post-flight debrief — full session narrative, all findings,
    confirmation requests, next session priorities.
    AI: 'debrief' / 'post flight debrief' / 'what did you learn today' /
        'session summary' / 'flight summary' / 'learning report' /
        'what improved' / 'debrief me' / 'alc debrief'
    """
    st  = _ALC_SHARED
    now = _alc_time.monotonic()
    session = [e for e in st['session_log'] if e['flight'] == st['flight_number']-1]

    print(f"\n  ═══ ALC POST-FLIGHT DEBRIEF — Flight #{st['flight_number']-1} ═══")

    # Evaluations this flight
    print(f"\n  THIS FLIGHT:")
    print(f"  Hypotheses evaluated: {len(session)}")
    if session:
        best = max(session, key=lambda e: e['score'])
        worst= min(session, key=lambda e: e['score'])
        print(f"  Best result:  {best['hyp_id']} (Δ{best['score']:+.4f})")
        print(f"  Worst result: {worst['hyp_id']} (Δ{worst['score']:+.4f})")

    # Genome shifts
    shifts = st.get('_genome_shifts_this_session', [])
    if shifts:
        print(f"\n  GENOME SHIFTS THIS FLIGHT ({len(shifts)}):")
        for s in shifts[-5:]:
            for ax, info in s['shifts'].items():
                print(f"    {ax}: {info['from']} → {info['to']} "
                      f"({info['weight']*100:.0f}%)")
        st['_genome_shifts_this_session'] = []

    # CMTS activity
    new_silent   = len(_CMTS_TRANSFERS['silent'])
    new_pending  = len(_CMTS_TRANSFERS['pending'])
    print(f"\n  CROSS-MODE TRANSFERS:")
    print(f"  Silent promotions:  {new_silent}")
    print(f"  Pending (need you): {new_pending}")
    if _CMTS_TRANSFERS['pending']:
        best_t = max(_CMTS_TRANSFERS['pending'], key=lambda t: t['improvement'])
        print(f"  Highest priority:   {best_t['source_hyp']} → "
              f"{best_t['target_context']} "
              f"(+{best_t['improvement']:.1f}% {best_t['primary_metric']})")
        print(f"  Say 'cmts_confirm' or 'cmts_reject' to decide.")

    # Pilot rating summary
    ratings = st['pilot_rating_log']
    if ratings:
        good  = sum(1 for r in ratings if r['rating']=='good')
        poor  = sum(1 for r in ratings if r['rating']=='poor')
        print(f"\n  PILOT RATINGS THIS FLIGHT:")
        print(f"  Good: {good}  Neutral: {len(ratings)-good-poor}  Poor: {poor}")

    # Alert log
    alerts = [a for a in st['alert_log'] if a.get('t',0) > now - 7200]
    if alerts:
        print(f"\n  ALERTS THIS FLIGHT ({len(alerts)}):")
        for a in alerts[-5:]:
            tier = a['tier']
            print(f"  Tier {tier}: {a['text'][:70]}")

    # Metric bests update
    print(f"\n  PERFORMANCE BESTS (all time):")
    for metric, val in st['metric_bests'].items():
        print(f"    {metric:<22} {val:.4g}")

    # Axis velocity
    low_v = [ax for ax, alert in st['axis_velocity_alert'].items() if alert]
    if low_v:
        print(f"\n  SLOW-LEARNING AXES (will widen search next flight):")
        for ax in low_v: print(f"    {ax}")

    # Priorities for next flight
    print(f"\n  PRIORITIES FOR NEXT FLIGHT:")
    pq = st['priority_hyp_queue']
    if pq:
        for e in pq[:3]:
            print(f"    {e.get('hyp_id','?')}: {e.get('reason','?')[:50]}")
    else:
        print(f"    No specific priorities — normal discovery rotation")
    print(f"\n  Total evaluations all time: {st['total_evaluations']}")
    print(f"  Say 'persist_save_all' to save all learning to disk.")


