def alc_set_flight_phase(phase):
    """
    GS: alc_set_flight_phase
    Manually set flight phase for sterile cockpit protocol.
    AI: 'set phase cruise' / 'set phase manoeuvre' / 'set phase approach' /
        'we are in cruise' / 'starting approach' / 'pre-flight phase' /
        'post flight' / 'we landed'
    """
    valid = ['pre_flight','launch_prep','takeoff','climb','cruise',
             'hover_patrol','transit','manoeuvre','approach',
             'landing','recovery','post_flight']
    if phase not in valid:
        # Try partial match
        matches = [p for p in valid if phase.lower() in p]
        if matches:
            phase = matches[0]
        else:
            print(f"Unknown phase '{phase}'. Valid: {valid}")
            return
    alc_set_phase(phase)
    sterile = phase in _ALC_PHASE_STERILE
    print(f"\n  Phase set: {phase}")
    print(f"  {'STERILE COCKPIT — ALC silent except safety alerts' if sterile else 'ALC observations permitted'}")

