# ── Genome routing ────────────────────────────────────────────────────────────
def _update_genome_from_trial(hyp_id, score_delta, sensors):
    """Extends genome update with H-REGEN routing."""
    if score_delta <= 0:
        return
    boost = min(0.08, score_delta * 0.5)
    def _R(axis, mech):
        if mech not in axis: return
        axis[mech] = min(0.60, axis[mech] + boost)
        t = sum(axis.values())
        if t > 0:
            for k in axis: axis[k] /= t

    if hyp_id == 'H-REGEN-1':
        # Descent regen reinforces glide efficiency + endurance
        _R(_MW_GLIDE,     'drag_minimise')
        _R(_MW_ENDURANCE, 'sustained_wh_per_km')
        _R(_MW_ENDURANCE, 'thermal_budget')  # motor temp stays low in regen
    elif hyp_id == 'H-REGEN-2':
        # Braking regen reinforces pitch authority + endurance
        _R(_MW_PITCH,     'pitch_phase')     # cascade reversal = pitch mechanism
        _R(_MW_ENDURANCE, 'sustained_wh_per_km')

    # CMTS cross-mode scoring
    try:
        _h = next((h for h in AERO_HYPOTHESES if h['id']==hyp_id), None)
        if _h:
            _cmts_evaluate(hyp_id, _h['config'], sensors, {}, score_delta)
    except Exception:
        pass

    _pl_append_log({'event':'genome_update','hyp_id':hyp_id,
                    'boost':round(boost,4)})

    for _ax in _ALL_MW_AXES:
        _t = sum(_ax.values())
        if _t > 0 and abs(_t-1.0) > 0.001:
            for _k in _ax: _ax[_k] /= _t


# ── MAP-Elites ────────────────────────────────────────────────────────────────
def _me_niche_label(sensors, result, intent=None):
    """Adds regen niches."""
    if isinstance(sensors, dict):
        V_ms = sensors.get('V_ms', 7.0)
        speed_bin = 0 if V_ms<4 else 1 if V_ms<8 else 2 if V_ms<12 else 3
        wind_bin  = 0
    else:
        speed_bin = int(sensors) if isinstance(sensors,int) else 2
        wind_bin  = int(result)  if isinstance(result,int)  else 0

    if isinstance(result, dict):
        if result.get('regen_active') and result.get('regen_context'):
            return speed_bin, wind_bin, f"regen_{result['regen_context']}"
    if intent in ('regen_descent','regen_brake','regen_glide','regen_emerg'):
        return speed_bin, wind_bin, str(intent)
    return speed_bin, wind_bin, 'general'


