def _regen_mod_observe(sensors, result):
    """Observe regen state from tick output."""
    return {
        'active':    result.get('regen_active', False)   if isinstance(result,dict) else False,
        'context':   result.get('regen_context', None)   if isinstance(result,dict) else None,
        'P_W':       result.get('regen_P_W', 0.0)        if isinstance(result,dict) else 0.0,
        'I_A':       result.get('regen_I_A', 0.0)        if isinstance(result,dict) else 0.0,
        'wh_sess':   result.get('regen_wh_session', 0.0) if isinstance(result,dict) else 0.0,
        'soc':       result.get('regen_soc_est', 0.5)    if isinstance(result,dict) else 0.5,
    }


def _regen_mod_learn(findings):
    """
    Track regen improvement and issue cruise-phase observations.
    Tier-1 (cruise-only) when regen significantly exceeds expected.
    """
    st = _REGEN_STATE
    P  = findings.get('P_W', 0.0)
    ctx= findings.get('context')

    # If regen power is notably better than recent best, note it
    if P > st['best_regen_rate_W'] * 1.2 and P > 3.0:
        # This is handled in _regen_tick; nothing additional needed here
        pass

    # Cruise observation when regen is substantial
    if findings.get('active') and P > 8.0:
        now = _rg_time.monotonic()
        last = _ALC_SHARED.get('_regen_last_obs_t', 0.0)
        if now - last > 60.0:   # at most once per minute
            txt = (f"Regenerating {P:.1f}W in {ctx} zone. "
                   f"Session total: {st['energy_regen_wh']*1000:.0f} mWh.")
            _alc_alert(1, txt, metric='regen_P_W', value=P)
            _ALC_SHARED['_regen_last_obs_t'] = now


def _regen_mod_share():
    """Share regen state into ALC shared state."""
    st = _REGEN_STATE
    return {
        'regen_active':    st['active'],
        'regen_context':   st['context'],
        'regen_P_W':       st['P_regen_W'],
        'regen_wh_session':round(st['energy_regen_wh'], 4),
        'regen_wh_total':  round(st['total_regen_wh'], 4),
        'regen_soc_derate':st['soc_derate_active'],
    }


def _regen_mod_explain():
    """Plain-language regen summary for post-flight debrief."""
    st = _REGEN_STATE
    total = st['energy_regen_wh']
    if total < 0.001:
        return "Regeneration: no regen events this flight."

    # Express as percentage of typical flight energy
    pct = total / BATT_CAPACITY_WH * 100.0
    # Express as equivalent hover time
    hover_min = total / (45.0 / 60.0)   # 45W hover power

    lines = [
        f"Regeneration: {total*1000:.0f} mWh recovered this flight "
        f"({pct:.2f}% of battery capacity, "
        f"≈{hover_min:.1f}s additional hover time)."
    ]

    breakdown = []
    if st['energy_brake_wh'] > 0.0001:
        breakdown.append(f"brake zone {st['energy_brake_wh']*1000:.0f}mWh")
    if st['energy_descent_wh'] > 0.0001:
        breakdown.append(f"descent {st['energy_descent_wh']*1000:.0f}mWh")
    if st['energy_glide_wh'] > 0.0001:
        breakdown.append(f"glide {st['energy_glide_wh']*1000:.0f}mWh")
    if st['energy_emerg_wh'] > 0.0001:
        breakdown.append(f"emergency stop {st['energy_emerg_wh']*1000:.0f}mWh")

    if breakdown:
        lines.append(f"  By zone: {', '.join(breakdown)}.")

    if st['best_regen_config']:
        cfg = st['best_regen_config']
        lines.append(
            f"  Best rate: {st['best_regen_rate_W']:.1f}W at "
            f"freq={cfg['freq_hz']:.2f}Hz "
            f"cascade={cfg['cascade_deg']:.0f}° "
            f"({cfg['context']}).")

    lines.append(
        f"  All-time recovered: {st['total_regen_wh']*1000:.0f} mWh "
        f"across {st['total_flights_with_regen']} flights.")

    return ' '.join(lines)


# Register regen modality
_alc_register_modality(
    'regen_recovery',
    _regen_mod_observe,
    _regen_mod_learn,
    _regen_mod_share,
    _regen_mod_explain,
)


