_orig_persist_save_regen = persist_save_all

def persist_save_all(*args, **kwargs):
    """Persist — extended to save regen state."""
    result = _orig_persist_save_regen(*args, **kwargs)
    try:
        regen_data = {
            'total_regen_wh':          _REGEN_STATE['total_regen_wh'],
            'total_regen_wh_brake':    _REGEN_STATE['total_regen_wh_brake'],
            'total_regen_wh_descent':  _REGEN_STATE['total_regen_wh_descent'],
            'total_regen_wh_glide':    _REGEN_STATE['total_regen_wh_glide'],
            'total_flights_with_regen':_REGEN_STATE['total_flights_with_regen'],
            'best_regen_rate_W':       _REGEN_STATE['best_regen_rate_W'],
            'best_regen_config':       _REGEN_STATE['best_regen_config'],
        }
        _pl_write(f'{_PL_DIR}/regen_state.json', regen_data)
    except Exception as _e:
        _tick_error_log('regen_persist_save', _e)
    return result

_orig_persist_load_regen = persist_load_all

def persist_load_all(*args, **kwargs):
    """Persist — extended to restore regen state."""
    result = _orig_persist_load_regen(*args, **kwargs)
    try:
        import json, os
        path = f'{_PL_DIR}/regen_state.json'
        if os.path.exists(path):
            with open(path) as f:
                d = json.load(f)
            _REGEN_STATE['total_regen_wh']           = d.get('total_regen_wh', 0.0)
            _REGEN_STATE['total_regen_wh_brake']     = d.get('total_regen_wh_brake', 0.0)
            _REGEN_STATE['total_regen_wh_descent']   = d.get('total_regen_wh_descent', 0.0)
            _REGEN_STATE['total_regen_wh_glide']     = d.get('total_regen_wh_glide', 0.0)
            _REGEN_STATE['total_flights_with_regen'] = d.get('total_flights_with_regen', 0)
            _REGEN_STATE['best_regen_rate_W']        = d.get('best_regen_rate_W', 0.0)
            _REGEN_STATE['best_regen_config']        = d.get('best_regen_config', None)
    except Exception as _e:
        _tick_error_log('regen_persist_load', _e)
    return result


# ── Hook into alc_debrief ─────────────────────────────────────────────────────
_orig_alc_debrief_regen = alc_debrief

def alc_debrief():
    """ALC debrief — extended with regen summary."""
    _orig_alc_debrief_regen()
    try:
        st = _REGEN_STATE
        # Increment flight counter if any regen occurred
        if st['energy_regen_wh'] > 0.001:
            st['total_flights_with_regen'] += 1

        # Print regen section in debrief
        total = st['energy_regen_wh']
        print(f"\n  REGENERATIVE RECOVERY THIS FLIGHT:")
        if total < 0.001:
            print(f"  None — no braking or descent zones entered.")
        else:
            pct = total / BATT_CAPACITY_WH * 100.0
            hover_s = total / (45.0 / 3600.0)
            print(f"  Total recovered:  {total*1000:.1f} mWh  "
                  f"({pct:.3f}% of battery)")
            print(f"  Equiv. hover:     {hover_s:.0f}s additional endurance")
            if st['energy_brake_wh'] > 0.0001:
                print(f"  Brake zone:       {st['energy_brake_wh']*1000:.1f} mWh")
            if st['energy_descent_wh'] > 0.0001:
                print(f"  Descent zone:     {st['energy_descent_wh']*1000:.1f} mWh")
            if st['energy_glide_wh'] > 0.0001:
                print(f"  Glide zone:       {st['energy_glide_wh']*1000:.1f} mWh")
            if st['energy_emerg_wh'] > 0.0001:
                print(f"  Emergency stop:   {st['energy_emerg_wh']*1000:.1f} mWh")
            print(f"  Best regen rate:  {st['best_regen_rate_W']:.1f} W")
            print(f"  All-time total:   {st['total_regen_wh']*1000:.0f} mWh "
                  f"({st['total_regen_wh']/BATT_CAPACITY_WH*100:.2f}% battery equiv.)")

        # Reset session accumulators
        st['energy_regen_wh']   = 0.0
        st['energy_brake_wh']   = 0.0
        st['energy_descent_wh'] = 0.0
        st['energy_glide_wh']   = 0.0
        st['energy_emerg_wh']   = 0.0
        st['n_regen_events']    = 0
        st['best_regen_rate_W'] = 0.0

    except Exception as _e:
        _tick_error_log('alc_debrief_regen', _e)


