# ── Queue all new hypotheses ───────────────────────────────────────────────────
_ff_new_ids = {'H-PERF-6','H-PERF-7','H-PREC-2',
               'H-SAR-FF-1','H-SAR-FF-2','H-SAR-FF-3','H-SAR-FF-4'}
for _fh in AERO_HYPOTHESES:
    if _fh['id'] in _ff_new_ids and _fh not in _hypothesis_queue:
        # H-PERF-6 goes to front of queue — it must run first
        if _fh['id'] == 'H-PERF-6':
            _hypothesis_queue.insert(0, _fh)
        else:
            _hypothesis_queue.append(_fh)


# ── Envelope tick — monitors V_min attempts during characterisation ────────────
_ENVELOPE_TICK_LAST = 0.0

def _envelope_tick(sensors, result):
    """
    Monitors flight state during the characterisation phase.
    Updates _ENVELOPE when characterisation data is available.
    Silent background operation — no pilot communication during flight.
    """
    global _ENVELOPE_TICK_LAST
    now = _ff_time.monotonic()
    if now - _ENVELOPE_TICK_LAST < 1.0:   # 1 Hz — low overhead
        return result
    _ENVELOPE_TICK_LAST = now

    env = _ENVELOPE
    if env['char_complete']:
        return result

    V_ms  = sensors.get('V_ms', 7.0)   if isinstance(sensors,dict) else 7.0
    vsi   = sensors.get('vsi_smooth_ms',0.0) if isinstance(sensors,dict) else 0.0
    lever = sensors.get('lever_pct',50.0)    if isinstance(sensors,dict) else 50.0
    I_A   = sensors.get('motor_I_A',0.0)     if isinstance(sensors,dict) else 0.0
    V_bus = sensors.get('bus_voltage', BATT_NOMINAL_V) \
            if isinstance(sensors,dict) else BATT_NOMINAL_V

    # Detect sustained slow flight attempts
    if V_ms < 5.0 and abs(vsi) < 0.5 and lever > LV_DETENT_LO:
        # Aircraft is flying slowly and maintaining altitude
        log_entry = {
            't': round(now, 1), 'V_ms': round(V_ms, 2),
            'vsi': round(vsi, 3), 'lever': round(lever, 1),
            'I_A': round(I_A, 2),
        }
        env['char_log'].append(log_entry)

        # Update V_min if this is the slowest sustained level flight seen
        if (env['V_MIN_MS'] is None or V_ms < env['V_MIN_MS']):
            env['V_MIN_MS'] = round(V_ms, 2)
            env['V_MIN_MEASURED'] = True
            # Recompute orbit geometry
            env['orbit_radius_m'] = _compute_orbit_geometry(
                V_ms, env['orbit_bank_deg'])

    # Detect hover (V < 1.0 m/s maintained)
    if V_ms < 1.0 and abs(vsi) < 0.3:
        if env['HOVER_CAPABLE'] is None:
            env['HOVER_CAPABLE']     = True
            env['HOVER_ENDURANCE_S'] += 1.0
        elif env['HOVER_CAPABLE']:
            env['HOVER_ENDURANCE_S'] += 1.0

    # Compute T/W ratio from current and motor model
    if I_A > 0.5 and V_ms < 2.0:
        P_W = I_A * V_bus
        T_est = P_W * 0.7 / max(V_ms + 0.5, 0.5)
        W = M_AIRFRAME_KG * 9.81
        tw = T_est / W
        if env['T_W_RATIO'] is None or tw > env['T_W_RATIO']:
            env['T_W_RATIO'] = round(tw, 3)

    result['envelope_V_min']      = env['V_MIN_MS']
    result['envelope_hover_cap']  = env['HOVER_CAPABLE']
    result['envelope_orbit_r']    = env['orbit_radius_m']
    return result


# Wire envelope tick
_orig_stroke_sm_ff = stroke_smoothing_tick

def stroke_smoothing_tick(sensors, result):
    """Stroke smoothing — extended with flight envelope monitoring."""
    result = _orig_stroke_sm_ff(sensors, result)
    try:
        _envelope_tick(sensors, result)
    except Exception as _e:
        _tick_error_log('envelope_tick', _e)
    return result


# ── Discovery: H-PERF-6 always first if not yet characterised ────────────────
def discovery_hypothesis_select():
    """
    DEFINITIVE discovery with envelope gate and H-PERF-6 priority.
    H-PERF-6 runs before any other hypothesis on first flight.
    Hover-dependent hypotheses skip when HOVER_CAPABLE is False.
    """
    env    = _ENVELOPE
    st     = _ALC_SHARED
    focus  = _focus_state.get('active','')
    now    = _ff_time.monotonic()
    lever  = _flight_state.get('lever_pct', 50.0)
    h_agl  = _flight_state.get('h_agl_m',  100.0)
    V_ms   = _flight_state.get('V_ms',       7.0)
    pitch  = _flight_state.get('pitch_stick', 0.0)
    payload= _flight_state.get('payload_kg',  0.0)

    def _ready(hid):
        if not _envelope_gate(hid):
            return None   # hover-dependent and HOVER_CAPABLE = False
        hyp = next((h for h in _hypothesis_queue if h['id']==hid), None)
        if hyp:
            # Skip exhausted regions
            fam = '-'.join(hid.split('-')[:2])
            cfg = hyp.get('config',{})
            casc = cfg.get('cascade_phase_deg', 28.0)
            bucket = f"{fam}_cascade_{int(casc//20)*20}"
            if bucket in st.get('exhausted_regions',{}):
                return None
            if now-_hypothesis_results.get(hid,{}).get('last_eval_t',0)>=300:
                return hyp
        return None

    def _first(ids):
        for hid in ids:
            h = _ready(hid)
            if h: return h
        return None

    # ── H-PERF-6 always runs first if not yet characterised ──────────────────
    if not env['char_complete'] and not env['V_MIN_MEASURED']:
        h = _ready('H-PERF-6')
        if h: return h

    # ── ALC priority queue ────────────────────────────────────────────────────
    for entry in st.get('priority_hyp_queue',[]):
        hid = entry.get('hyp_id')
        if hid:
            h = _ready(hid)
            if h:
                st['priority_hyp_queue'].remove(entry)
                return h

    # ── Auto state routing ────────────────────────────────────────────────────
    if _RES_STATE.get('degraded_mode'):
        h = _first(['H-RES-1','H-RES-2'] if
                   len(_RES_STATE.get('failed_pairs',[]))>=2 else ['H-RES-1'])
        if h: return h

    if _WHISPER_STATE.get('active') and LV_DESCENT_LO<=lever<=LV_GLIDE_LO:
        h = _ready('H-AQ-3')
        if h: return h

    if payload > 0.3 and _OV_STATE.get('lat_active'):
        target = 'H-HL-5' if env['HOVER_CAPABLE'] else 'H-SAR-FF-4'
        h = _ready(target)
        if h: return h

    if _OV3_STATE.get('active') and h_agl > 0.3:
        if env['HOVER_CAPABLE'] is not False:
            h = _ready('H-OV-3')
            if h: return h

    if LV_CLIMB_LO <= lever <= LV_SPRINT_LO and V_ms > 3.0:
        h = _ready('H-OV-1')
        if h: return h

    if _OV_STATE.get('lat_active') and h_agl > 0.3:
        if env['HOVER_CAPABLE'] is not False:
            h = _ready('H-OV-2')
            if h: return h

    # ── FF SAR routing when hover not capable ─────────────────────────────────
    if env['HOVER_CAPABLE'] is False:
        # Forward-flight SAR is primary mode
        if V_ms <= (env['V_MIN_MS'] or 5.0) + 2.0:
            h = _first(['H-SAR-FF-1','H-SAR-FF-2','H-SAR-FF-3','H-SAR-FF-4'])
            if h: return h
        # V_min refinement — try to reduce minimum speed
        h = _ready('H-PERF-7')
        if h: return h
        # Short-field landing refinement
        if lever < LV_DESCENT_LO:
            h = _ready('H-PREC-2')
            if h: return h

    # ── Focus keyword routing ─────────────────────────────────────────────────
    FOCUS = {
        # Envelope and performance
        'characterisation':   ['H-PERF-6','H-PERF-7'],
        'envelope':           ['H-PERF-6','H-PERF-7'],
        'v_min':              ['H-PERF-7'],
        'minimum_speed':      ['H-PERF-7'],
        'short_field':        ['H-PREC-2'],
        'landing':            ['H-PREC-2','H-FD-4','H-FD-1'],
        # FF SAR
        'sar_orbit':          ['H-SAR-FF-1'],
        'orbit':              ['H-SAR-FF-1'],
        'lawnmower':          ['H-SAR-FF-2'],
        'area_search':        ['H-SAR-FF-2'],
        'sar_approach':       ['H-SAR-FF-3'],
        'payload_drop':       ['H-SAR-FF-4','H-CR-2'],
        'ff_sar':             ['H-SAR-FF-1','H-SAR-FF-2',
                               'H-SAR-FF-3','H-SAR-FF-4'],
        'forward_flight_sar': ['H-SAR-FF-1','H-SAR-FF-2',
                               'H-SAR-FF-3','H-SAR-FF-4'],
        # Energy management
        'energy_transition':  ['H-EN-1','H-EN-2','H-EN-3'],
        'sprint_stop':        ['H-EN-1'],
        'regen_descent':      ['H-REGEN-1'],
        'regen_brake':        ['H-REGEN-2'],
        # Resilience
        'resilience':         ['H-RES-1','H-RES-2','H-RES-3'],
        'fault_tolerance':    ['H-RES-1','H-RES-2','H-RES-3'],
        # Acoustics
        'whisper':            ['H-AQ-1','H-AQ-2','H-AQ-3','H-EV-2'],
        'quiet_approach':     ['H-AQ-3','H-SAR-FF-3'],
        # Soaring
        'soaring':            ['H-SOR-1','H-SOR-2','H-SOR-3',
                               'H-SOR-4','H-SOR-5','H-SOR-6'],
        'thermal':            ['H-SOR-4','H-SOR-6'],
        'endurance':          ['H-SOR-3','H-CR-3','H-CR-4'],
        # Stability
        'stability':          ['H-PDW-1','H-PDW-2','H-PDW-3',
                               'H-DIH-1','H-DIH-2','H-DIH-3'],
        'gust':               ['H-GS-1','H-STORM-1'],
        'turbulence':         ['H-GS-1','H-STORM-1','H-STORM-2'],
        # Aerobatics
        'agility':            ['H-PULL-1','H-RC-1','H-HB-1','H-OV-3'],
        'raider':             ['H-RC-1','H-RC-2','H-RC-3','H-RC-4'],
        'stoop':              ['H-STOOP-1','H-PULL-1','H-EN-2'],
        # Performance
        'performance':        ['H-PERF-1','H-PERF-2','H-PERF-3',
                               'H-PERF-4','H-PERF-5','H-PERF-6','H-PERF-7'],
        'top_speed':          ['H-PERF-1','H-STOOP-1'],
        'efficiency':         ['H-PERF-2','H-PERF-3'],
        # SAR general
        'sar':                ['H-SP-1','H-SP-2','H-PF-5','H-PF-6',
                               'H-SAR-FF-1','H-SAR-FF-2','H-SAR-FF-3',
                               'H-SAR-FF-4','H-SOR-6','H-BS-5'],
        # Descent
        'pigeon':             ['H-FD-1','H-FD-2','H-FD-3','H-FD-4','H-FD-5'],
        'steep_descent':      ['H-FD-4','H-AQ-3','H-FD-3'],
        # Water
        'water':              ['H-WD-1','H-WD-2','H-WD-3'],
        # Cargo
        'cargo':              ['H-HL-1','H-HL-2','H-HL-3','H-HL-5',
                               'H-CR-2','H-SAR-FF-4'],
        # Competition
        'competition':        ['H-CR-1','H-CR-2','H-CR-3','H-CR-4','H-CR-5'],
        # Climb
        'climb':              ['H-OV-1','H-CLB-1','H-CLB-2','H-CLB-3'],
        # Density altitude
        'density_alt':        ['H-DA-1','H-DA-2','H-DA-3','H-DA-4',
                               'H-DA-5','H-DA-6','H-DA-7'],
    }

    if focus in FOCUS:
        h = _first(FOCUS[focus])
        if h: return h

    # ── Lever zone routing ────────────────────────────────────────────────────
    if LV_DESCENT_LO <= lever <= LV_GLIDE_LO and h_agl > 0.5:
        for (lo,hi),hid in [
            ((PD_NEW_SHALLOW_LO,PD_NEW_SHALLOW_HI), 'H-FD-2'),
            ((PD_NEW_MODERATE_LO,PD_NEW_MODERATE_HI),'H-FD-1'),
            ((PD_NEW_STEEP_LO, PD_NEW_STEEP_HI),   'H-FD-3'),
        ]:
            if lo <= lever <= hi:
                h = _ready(hid)
                if h: return h
                break

    if LV_BRAKE_LO <= lever <= LV_DESCENT_LO:
        h = _ready('H-RC-3' if abs(pitch)<=RC_HARD_BRAKE_PITCH_DEAD else 'H-FD-4')
        if h: return h

    if lever < LV_BRAKE_LO:
        h = _ready('H-LB-3')
        if h: return h

    if lever >= LV_SPRINT_LO:
        h = _first(['H-CLB-3','H-HL-4','H-STOOP-1','H-OV-1'])
        if h: return h

    if payload > 0.3:
        h = _first(['H-HL-2','H-HL-3','H-HL-5','H-CR-2'])
        if h: return h

    if (_water_phase_state.get('phase','') in ('water_planing','water_departure')
            or surface_is_water()):
        h = _first(['H-WD-1','H-WD-2','H-WD-3'])
        if h: return h

    # Weakest H-PERF
    ps2 = _PERF_STATE; ref = _PERF_REFERENCE
    _ps = {
        'H-PERF-1': min(1.0, ps2['v_max_ms']/ref['v_max_target_ms']),
        'H-PERF-2': max(0.0,1.0-ps2['wh_per_km_current']/ref['wh_per_km_target'])
                    if ps2['wh_per_km_current']>0 else 0.0,
        'H-PERF-3': min(1.0,ps2['n_per_w_current']/ref['n_per_w_target'])
                    if ps2['n_per_w_current']>0 else 0.0,
        'H-PERF-4': max(0.0,1.0-ps2['latency_ms_current']/ref['latency_ms_target'])
                    if ps2['latency_ms_current']>0 else 0.0,
        'H-PERF-5': max(0.0,1.0-ps2['precision_rms_current']/ref['precision_rms_target'])
                    if ps2['precision_rms_current']>0 else 0.0,
    }
    h = _ready(min(_ps, key=_ps.get))
    if h: return h

    for hyp in _hypothesis_queue:
        if (_envelope_gate(hyp['id']) and
                now-_hypothesis_results.get(hyp['id'],{}).get('last_eval_t',0)>=300.0):
            return hyp
    return next((h for h in _hypothesis_queue if _envelope_gate(h['id'])),
                _hypothesis_queue[0] if _hypothesis_queue else None)


