# ── Genome routing ─────────────────────────────────────────────────────────────
def _update_genome_from_trial(hyp_id, score_delta, sensors):
    """Extends genome update with FF SAR and envelope hypotheses."""
    if score_delta <= 0:
        return
    boost = min(0.08, score_delta * 0.5)
    def _R(axis, mech):
        if mech not in axis: return
        axis[mech] = min(0.60, axis[mech] + boost)
        t = sum(axis.values())
        if t > 0:
            for k in axis: axis[k] /= t

    if hyp_id in ('H-PERF-6','H-PERF-7'):
        _R(_MW_PITCH,      'pitch_freq')     # frequency drives V_min
        _R(_MW_PITCH,      'pitch_aoa')      # high AoA for slow flight
        _R(_MW_PERFORMANCE,'precision_hold')
        _R(_MW_TRANSITION, 'blend_smoothness')
    elif hyp_id == 'H-PREC-2':
        _R(_MW_PITCH,      'pitch_dih')      # dihedral braking in flare
        _R(_MW_STABILITY,  'geom_dihedral')
        _R(_MW_PERFORMANCE,'precision_hold')
    elif hyp_id == 'H-SAR-FF-1':
        _R(_MW_TURN,       'inner_outer_asymm')  # bank differential
        _R(_MW_PITCH,      'pitch_aoa')
        _R(_MW_SAR,        'precision_hover')    # orbit = hover equivalent
    elif hyp_id == 'H-SAR-FF-2':
        _R(_MW_SAR,        'area_coverage_rate')
        _R(_MW_ENDURANCE,  'sustained_wh_per_km')
        _R(_MW_TURN,       'per_stroke_vector')  # tight turn at V_min
    elif hyp_id == 'H-SAR-FF-3':
        _R(_MW_SAR,        'precision_hover')
        _R(_MW_GLIDE,      'min_sink_aoa')
        _R(_MW_STABILITY,  'stroke_dihedral')
    elif hyp_id == 'H-SAR-FF-4':
        _R(_MW_SAR,        'payload_delivery')
        _R(_MW_CARGO,      'release_smooth')
        _R(_MW_PERFORMANCE,'precision_hold')

    try:
        _h = next((h for h in AERO_HYPOTHESES if h['id']==hyp_id), None)
        if _h:
            _cmts_evaluate(hyp_id, _h['config'], sensors, {}, score_delta)
    except Exception:
        pass

    _pl_append_log({'event':'genome_update','hyp_id':hyp_id,
                    'boost':round(boost,4)})
    for _ax in _ALL_MW_AXES:
        _t = sum(_ax.values())
        if _t > 0 and abs(_t-1.0) > 0.001:
            for _k in _ax: _ax[_k] /= _t


# ── Persist envelope state ────────────────────────────────────────────────────
_orig_persist_save_ff = persist_save_all

def persist_save_all(*args, **kwargs):
    """Persist — extended to save flight envelope characterisation."""
    result = _orig_persist_save_ff(*args, **kwargs)
    try:
        env_data = {
            'HOVER_CAPABLE':       _ENVELOPE['HOVER_CAPABLE'],
            'V_MIN_MS':            _ENVELOPE['V_MIN_MS'],
            'V_MIN_MEASURED':      _ENVELOPE['V_MIN_MEASURED'],
            'HOVER_ENDURANCE_S':   _ENVELOPE['HOVER_ENDURANCE_S'],
            'T_W_RATIO':           _ENVELOPE['T_W_RATIO'],
            'orbit_radius_m':      _ENVELOPE['orbit_radius_m'],
            'sf_best_touchdown_Vms': _ENVELOPE['sf_best_touchdown_Vms'],
            'char_complete':       _ENVELOPE['char_complete'],
            'char_V_levels':       _ENVELOPE['char_V_levels'],
            'char_log':            _ENVELOPE['char_log'][-100:],
        }
        _pl_write(f'{_PL_DIR}/envelope.json', env_data)
    except Exception as _e:
        _tick_error_log('envelope_persist_save', _e)
    return result

_orig_persist_load_ff = persist_load_all

def persist_load_all(*args, **kwargs):
    """Persist — extended to restore flight envelope."""
    result = _orig_persist_load_ff(*args, **kwargs)
    try:
        import json, os
        path = f'{_PL_DIR}/envelope.json'
        if os.path.exists(path):
            with open(path) as f:
                d = json.load(f)
            _ENVELOPE['HOVER_CAPABLE']     = d.get('HOVER_CAPABLE')
            _ENVELOPE['V_MIN_MS']          = d.get('V_MIN_MS')
            _ENVELOPE['V_MIN_MEASURED']    = d.get('V_MIN_MEASURED', False)
            _ENVELOPE['HOVER_ENDURANCE_S'] = d.get('HOVER_ENDURANCE_S', 0.0)
            _ENVELOPE['T_W_RATIO']         = d.get('T_W_RATIO')
            _ENVELOPE['orbit_radius_m']    = d.get('orbit_radius_m')
            _ENVELOPE['sf_best_touchdown_Vms'] = d.get('sf_best_touchdown_Vms')
            _ENVELOPE['char_complete']     = d.get('char_complete', False)
            _ENVELOPE['char_V_levels']     = d.get('char_V_levels', [])
            _ENVELOPE['char_log']          = d.get('char_log', [])
    except Exception as _e:
        _tick_error_log('envelope_persist_load', _e)
    return result


# ── ALC debrief extension ─────────────────────────────────────────────────────
_orig_alc_debrief_ff = alc_debrief

def alc_debrief():
    """ALC debrief — extended with flight envelope summary."""
    _orig_alc_debrief_ff()
    try:
        env = _ENVELOPE
        print(f"\n  FLIGHT ENVELOPE:")
        hc = env['HOVER_CAPABLE']
        print(f"  Hover capable:    "
              f"{'YES' if hc is True else 'NO' if hc is False else 'NOT YET MEASURED'}")
        if hc is True:
            print(f"  Hover endurance:  {env['HOVER_ENDURANCE_S']:.0f}s sustained")
        if env['V_MIN_MS'] is not None:
            print(f"  V_min measured:   {env['V_MIN_MS']:.1f} m/s")
            print(f"  SAR orbit radius: {env['orbit_radius_m']:.1f}m "
                  f"at {env['orbit_bank_deg']:.0f}° bank")
        else:
            print(f"  V_min:            Not yet measured — run H-PERF-6")
        if env['T_W_RATIO'] is not None:
            print(f"  T/W ratio est:    {env['T_W_RATIO']:.3f}")
        if hc is False:
            print(f"\n  FORWARD-FLIGHT SAR MODE ACTIVE:")
            print(f"  Primary mode:     H-SAR-FF-1 slow orbit")
            print(f"  Area search:      H-SAR-FF-2 lawnmower")
            print(f"  Approach:         H-SAR-FF-3 sensor orbit descent")
            print(f"  Payload:          H-SAR-FF-4 minimum-speed pass")
            print(f"  Landing:          H-PREC-2 short-field")
            print(f"  All hover-dependent hypotheses: gated off")
    except Exception as _e:
        _tick_error_log('alc_debrief_ff', _e)


# ── GS commands ───────────────────────────────────────────────────────────────
def envelope_status():
    """
    GS: envelope_status
    Flight envelope characterisation results.
    AI: 'envelope status' / 'can we hover' / 'what is V_min' /
        'flight envelope' / 'hover capable' / 'minimum speed' /
        'what did we learn first flight' / 'sar orbit radius'
    """
    env = _ENVELOPE
    print(f"\n  FLIGHT ENVELOPE STATUS")
    print(f"  ─────────────────────────────────────────────")
    hc = env['HOVER_CAPABLE']
    print(f"  Hover capable:    "
          f"{'YES ✓' if hc is True else 'NO ✗ — forward-flight SAR active' if hc is False else 'NOT YET MEASURED — run H-PERF-6'}")
    if hc is True:
        print(f"  Hover endurance:  {env['HOVER_ENDURANCE_S']:.0f}s best sustained")
    if env['V_MIN_MS'] is not None:
        print(f"  V_min (measured): {env['V_MIN_MS']:.2f} m/s")
        print(f"  V_min measured:   {'YES' if env['V_MIN_MEASURED'] else 'estimated'}")
        if env['orbit_radius_m']:
            print(f"  SAR orbit radius: {env['orbit_radius_m']:.1f}m "
                  f"at {env['orbit_bank_deg']:.0f}° bank")
            cov = _ff_sar_coverage_rate(env['V_MIN_MS'], 30.0)
            print(f"  Coverage rate:    {cov:.0f} m²/s at 30m AGL, 60° FOV")
    else:
        print(f"  V_min:            Not yet measured")
        print(f"  ACTION:           Run H-PERF-6 on first flight")
    if env['T_W_RATIO'] is not None:
        print(f"  T/W ratio est:    {env['T_W_RATIO']:.3f} "
              f"({'>1.0 hover margin' if env['T_W_RATIO']>1.0 else '<1.0 forward-flight only'})")
    if env['sf_best_touchdown_Vms'] is not None:
        print(f"  Best touchdown V: {env['sf_best_touchdown_Vms']:.2f} m/s")
    print(f"\n  HYPOTHESIS GATE:")
    if hc is False:
        print(f"  Hover-dependent hypotheses: GATED OFF")
        print(f"  Active SAR mode: H-SAR-FF-1/2/3/4")
    elif hc is True:
        print(f"  All hypotheses:  ACTIVE (hover + forward-flight)")
    else:
        print(f"  Gate status:     OPEN (measuring — both modes active)")
    if env['char_log']:
        print(f"\n  CHARACTERISATION LOG: {len(env['char_log'])} entries")
        slowest = min(env['char_log'], key=lambda e: e['V_ms'])
        print(f"  Slowest sustained: {slowest['V_ms']:.2f} m/s "
              f"(VSI {slowest['vsi']:+.2f} m/s)")


def set_hover_capable(capable: bool):
    """
    GS: set_hover_capable
    Manually set hover capability from pilot observation.
    Use when H-PERF-6 result is clear from flying but not yet auto-detected.
    AI: 'set hover capable true' / 'set hover capable false' /
        'confirm hover' / 'no hover capability' / 'aircraft can hover' /
        'aircraft cannot hover'
    """
    _ENVELOPE['HOVER_CAPABLE'] = capable
    _ENVELOPE['V_MIN_MEASURED'] = True
    status = 'HOVER CAPABLE — all hypotheses active' if capable \
             else 'NO HOVER — forward-flight SAR mode active'
    print(f"\n  HOVER CAPABILITY SET: {status}")
    if not capable:
        print(f"  Hover-dependent hypotheses now gated off.")
        print(f"  H-SAR-FF-1/2/3/4 now primary SAR mode.")
        print(f"  H-PREC-2 short-field landing now primary approach.")
    _pl_append_log({'event': 'set_hover_capable', 'value': capable})

_GS_ALLOWED_CMDS.update({'envelope_status', 'set_hover_capable'})


# ── Genome axis normalisation ─────────────────────────────────────────────────
for _ax in _ALL_MW_AXES:
    _t = sum(_ax.values())
    if _t > 0 and abs(_t-1.0) > 0.001:
        for _k in _ax: _ax[_k] /= _t


